def _get_app_settings():
    payload = _load_json(SETTINGS_STORE, _app_settings_default())
    if not isinstance(payload, dict):
        payload = _app_settings_default()
    base = _app_settings_default()
    base.update({k: v for k, v in payload.items() if k in base})
    for section in ['intelligence', 'dataCollection', 'apiConfig', 'performance']:
        if section in base and section in payload:
            base[section].update({k: v for k, v in payload[section].items() if k in base[section]})
    return base


def _save_app_settings(payload):
    if not isinstance(payload, dict):
        return _get_app_settings()
    current = _get_app_settings()
    current['updatedAt'] = datetime.now(timezone.utc).isoformat()
    for section in ['intelligence', 'dataCollection', 'apiConfig', 'performance']:
        if section in payload and isinstance(payload[section], dict):
            for key, val in payload[section].items():
                if key in current.get(section, {}):
                    current[section][key] = val
    _save_json(SETTINGS_STORE, current)
    return current


def _mlb_memory_store_default():
    return {
        "latest": None,
        "snapshots": [],
        "updatedAt": None,
    }


_MLB_MEMORY_READ_CACHE = {
    "sig": None,
    "payload": None,
    "snapshot_pickles": None,
    "snapshot_jsons": None,
    "snapshot_modes": None,
    "updated_at": None,
    "latest": None,
    "latest_summary": None,
    "latest_response": None,
    "latest_summary_response": None,
    "status": None,
}
_MLB_MEMORY_READ_LOCK = threading.Lock()


def _normalize_mlb_memory_store(payload):
    if not isinstance(payload, dict):
        payload = _mlb_memory_store_default()
    else:
        payload.setdefault("latest", None)
        payload.setdefault("snapshots", [])
        payload.setdefault("updatedAt", None)
    if not isinstance(payload.get("snapshots"), list):
        payload["snapshots"] = []
    return payload


def _mlb_memory_file_signature(stat):
    return (
        stat.st_dev,
        stat.st_ino,
        stat.st_mtime_ns,
        stat.st_size,
    )


def _mlb_memory_snapshot_mode(snapshot):
    """Return the canonical stored mode, or None when compaction is still needed."""
    if not isinstance(snapshot, dict):
        return None
    games = snapshot.get("games")
    players = snapshot.get("players")
    if not isinstance(games, dict) or not isinstance(players, dict):
        return None

    compact = snapshot.get("compact")
    if compact is False:
        return "detail"
    if compact is not True:
        return None
    if len(games.get("boxscores") or []) > 6:
        return None
    if len(players.get("featured") or []) > 40:
        return None
    return "compact"


def _build_mlb_memory_cached_views(
    payload,
    stat,
    *,
    snapshot_pickles=None,
    snapshot_jsons=None,
    snapshot_modes=None,
    payload_blob=None,
):
    """Build immutable full/lightweight views for one persisted store version."""
    import pickle

    payload = _normalize_mlb_memory_store(payload)
    snapshots = payload.get("snapshots") or []
    latest = (
        payload.get("latest")
        if isinstance(payload.get("latest"), dict)
        else None
    )
    if snapshot_pickles is None:
        snapshot_pickles = tuple(
            pickle.dumps(item, protocol=pickle.HIGHEST_PROTOCOL)
            for item in snapshots
        )
    else:
        snapshot_pickles = tuple(snapshot_pickles)
    if snapshot_jsons is not None:
        snapshot_jsons = tuple(snapshot_jsons)
    if snapshot_modes is None:
        snapshot_modes = tuple(
            _mlb_memory_snapshot_mode(item)
            for item in snapshots
        )
    else:
        snapshot_modes = tuple(snapshot_modes)
    latest_summary = None
    if latest is not None:
        latest_summary = {
            "createdAt": latest.get("createdAt"),
            "targetDateET": latest.get("targetDateET"),
            "meta": latest.get("meta") or {},
        }
    latest_meta = (latest or {}).get("meta") or {}
    status = {
        "snapshotCount": len(snapshot_pickles),
        "latest": {
            "createdAt": (latest or {}).get("createdAt"),
            "targetDateET": (latest or {}).get("targetDateET"),
            "teamCount": latest_meta.get("teamCount"),
            "gameCount": latest_meta.get("gameCount"),
            "featuredPlayers": latest_meta.get("featuredPlayers"),
            "mode": latest_meta.get("mode"),
        },
        "file": {
            "exists": True,
            "path": MLB_MEMORY_STORE,
            "sizeBytes": stat.st_size,
            "modifiedAt": datetime.fromtimestamp(
                stat.st_mtime, tz=timezone.utc
            ).isoformat(),
        },
        "updatedAt": payload.get("updatedAt"),
    }
    return {
        "sig": _mlb_memory_file_signature(stat),
        "payload": payload_blob,
        "snapshot_pickles": snapshot_pickles,
        "snapshot_jsons": snapshot_jsons,
        "snapshot_modes": snapshot_modes,
        "updated_at": payload.get("updatedAt"),
        "latest": (
            pickle.dumps(latest, protocol=pickle.HIGHEST_PROTOCOL)
            if latest is not None
            else None
        ),
        "latest_summary": (
            pickle.dumps(latest_summary, protocol=pickle.HIGHEST_PROTOCOL)
            if latest_summary is not None
            else None
        ),
        "latest_response": None,
        "latest_summary_response": None,
        "status": pickle.dumps(status, protocol=pickle.HIGHEST_PROTOCOL),
    }


def _publish_mlb_memory_cached_views(
    payload,
    stat,
    *,
    snapshot_pickles=None,
    snapshot_jsons=None,
    snapshot_modes=None,
):
    """Advance read views after an atomic write without reparsing the file."""
    cached = _build_mlb_memory_cached_views(
        payload,
        stat,
        snapshot_pickles=snapshot_pickles,
        snapshot_jsons=snapshot_jsons,
        snapshot_modes=snapshot_modes,
    )
    with _MLB_MEMORY_READ_LOCK:
        try:
            current = os.stat(MLB_MEMORY_STORE)
        except OSError:
            return
        if _mlb_memory_file_signature(current) == cached["sig"]:
            _MLB_MEMORY_READ_CACHE.update(cached)


def _mlb_memory_cached_views():
    """Parse the large seasonal memory store once per atomic file version.

    The store is already roughly 12 MB and keeps growing through the season.
    Status and summary-only requests need only a few metadata fields, while
    writers need retained snapshots. Cache immutable per-snapshot blobs so
    lightweight reads and warm appends never clone the full store. The full
    mutable payload is materialized lazily only when a caller requests it.
    """
    import pickle

    try:
        with _MLB_MEMORY_READ_LOCK:
            with open(MLB_MEMORY_STORE, "rb") as handle:
                stat = os.fstat(handle.fileno())
                sig = _mlb_memory_file_signature(stat)
                if (
                    _MLB_MEMORY_READ_CACHE["sig"] == sig
                    and _MLB_MEMORY_READ_CACHE["snapshot_pickles"] is not None
                ):
                    return dict(_MLB_MEMORY_READ_CACHE)

                payload = _normalize_mlb_memory_store(json.load(handle))
                _MLB_MEMORY_READ_CACHE.update(
                    _build_mlb_memory_cached_views(payload, stat)
                )
                return dict(_MLB_MEMORY_READ_CACHE)
    except Exception:
        empty = _normalize_mlb_memory_store(_mlb_memory_store_default())
        try:
            fallback_stat = os.stat(MLB_MEMORY_STORE)
            file_exists = True
            file_size = fallback_stat.st_size
            modified_at = datetime.fromtimestamp(
                fallback_stat.st_mtime, tz=timezone.utc
            ).isoformat()
        except OSError:
            file_exists = False
            file_size = 0
            modified_at = None
        status = {
            "snapshotCount": 0,
            "latest": {
                "createdAt": None,
                "targetDateET": None,
                "teamCount": None,
                "gameCount": None,
                "featuredPlayers": None,
                "mode": None,
            },
            "file": {
                "exists": file_exists,
                "path": MLB_MEMORY_STORE,
                "sizeBytes": file_size,
                "modifiedAt": modified_at,
            },
            "updatedAt": None,
        }
        return {
            "sig": None,
            "payload": None,
            "snapshot_pickles": (),
            "snapshot_jsons": (),
            "snapshot_modes": (),
            "updated_at": None,
            "latest": None,
            "latest_summary": None,
            "latest_response": None,
            "latest_summary_response": None,
            "status": pickle.dumps(status, protocol=pickle.HIGHEST_PROTOCOL),
        }


def _mlb_memory_store_payload():
    import pickle

    while True:
        cached = _mlb_memory_cached_views()
        if cached["sig"] is None:
            latest_blob = cached["latest"]
            snapshots = [
                pickle.loads(item)
                for item in (cached["snapshot_pickles"] or ())
            ]
            latest = (
                pickle.loads(latest_blob)
                if latest_blob is not None
                else None
            )
            if snapshots and latest == snapshots[-1]:
                latest = snapshots[-1]
            return {
                "latest": latest,
                "snapshots": snapshots,
                "updatedAt": cached["updated_at"],
            }
        blob = cached["payload"]
        if blob is not None:
            return pickle.loads(blob)

        with _MLB_MEMORY_READ_LOCK:
            if _MLB_MEMORY_READ_CACHE["sig"] != cached["sig"]:
                continue
            try:
                current_sig = _mlb_memory_file_signature(
                    os.stat(MLB_MEMORY_STORE)
                )
            except OSError:
                current_sig = None
            if current_sig != cached["sig"]:
                continue

            blob = _MLB_MEMORY_READ_CACHE["payload"]
            if blob is None:
                latest_blob = _MLB_MEMORY_READ_CACHE["latest"]
                snapshots = [
                    pickle.loads(item)
                    for item in (
                        _MLB_MEMORY_READ_CACHE["snapshot_pickles"] or ()
                    )
                ]
                latest = (
                    pickle.loads(latest_blob)
                    if latest_blob is not None
                    else None
                )
                if snapshots and latest == snapshots[-1]:
                    latest = snapshots[-1]
                payload = {
                    "latest": latest,
                    "snapshots": snapshots,
                    "updatedAt": _MLB_MEMORY_READ_CACHE["updated_at"],
                }
                blob = pickle.dumps(
                    payload,
                    protocol=pickle.HIGHEST_PROTOCOL,
                )
                _MLB_MEMORY_READ_CACHE["payload"] = blob
        return pickle.loads(blob)


def _mlb_memory_latest_snapshot(summary_only=False):
    import pickle

    key = "latest_summary" if summary_only else "latest"
    blob = _mlb_memory_cached_views()[key]
    return pickle.loads(blob) if blob is not None else None


def _mlb_memory_latest_representation(summary_only=False):
    """Build one immutable JSON/gzip representation per store file version."""
    import gzip
    import hashlib
    import pickle

    view_key = "latest_summary" if summary_only else "latest"
    response_key = (
        "latest_summary_response" if summary_only else "latest_response"
    )

    while True:
        cached = _mlb_memory_cached_views()
        if cached[view_key] is None:
            return None
        representation = cached[response_key]
        if representation is not None:
            return representation

        with _MLB_MEMORY_READ_LOCK:
            if _MLB_MEMORY_READ_CACHE["sig"] != cached["sig"]:
                continue
            try:
                current_sig = _mlb_memory_file_signature(
                    os.stat(MLB_MEMORY_STORE)
                )
            except OSError:
                current_sig = None
            if current_sig != cached["sig"]:
                continue

            representation = _MLB_MEMORY_READ_CACHE[response_key]
            if representation is None:
                latest = pickle.loads(_MLB_MEMORY_READ_CACHE[view_key])
                if not latest:
                    return None
                body = (
                    app.json.dumps(
                        {"success": True, "snapshot": latest},
                        separators=(",", ":"),
                    )
                    + "\n"
                ).encode("utf-8")
                compressed = (
                    gzip.compress(body, compresslevel=5)
                    if len(body) >= 4096
                    else None
                )
                representation = {
                    "body": body,
                    "gzip": compressed,
                    "etag": hashlib.sha256(body).hexdigest(),
                    "gzip_etag": (
                        hashlib.sha256(compressed).hexdigest()
                        if compressed is not None
                        else None
                    ),
                }
                _MLB_MEMORY_READ_CACHE[response_key] = representation
        return representation


def _mlb_memory_latest_response(summary_only=False):
    """Serve cached latest-memory bytes with variant-safe revalidation."""
    representation = _mlb_memory_latest_representation(
        summary_only=summary_only
    )
    if representation is None:
        return None

    use_gzip = (
        representation["gzip"] is not None
        and "gzip" in (request.headers.get("Accept-Encoding") or "")
    )
    if use_gzip:
        body = representation["gzip"]
        etag = representation["gzip_etag"]
    else:
        body = representation["body"]
        etag = representation["etag"]

    headers = {
        "Cache-Control": "no-cache",
        "ETag": f'"{etag}"',
        "Vary": "Accept-Encoding",
    }
    if use_gzip:
        headers["Content-Encoding"] = "gzip"
    try:
        if request.if_none_match.contains(etag):
            return Response(status=304, headers=headers)
    except Exception:
        pass
    return Response(body, mimetype="application/json", headers=headers)


def _mlb_memory_store_status_view():
    import pickle

    return pickle.loads(_mlb_memory_cached_views()["status"])


def _write_mlb_memory_store(encoded):
    """Atomically persist already-encoded JSON and return the new file stat."""
    tmp = (
        f"{MLB_MEMORY_STORE}.{os.getpid()}."
        f"{threading.get_ident()}.tmp"
    )
    try:
        parent = os.path.dirname(MLB_MEMORY_STORE)
        if parent:
            os.makedirs(parent, exist_ok=True)
        with open(tmp, "w", encoding="utf-8") as handle:
            handle.write(encoded)
            handle.flush()
            try:
                os.fsync(handle.fileno())
            except OSError:
                pass
        os.replace(tmp, MLB_MEMORY_STORE)
        return os.stat(MLB_MEMORY_STORE)
    except Exception as ex:
        try:
            if os.path.exists(tmp):
                os.unlink(tmp)
        except OSError:
            pass
        print(f"[_write_mlb_memory_store] FAILED: {ex}")
        return None


def _append_mlb_memory_snapshot(snapshot, keep=30, return_payload=True):
    import pickle

    cached = _mlb_memory_cached_views()
    snapshot_pickles = list(cached["snapshot_pickles"] or ())
    snapshot_jsons = list(
        cached["snapshot_jsons"]
        if cached["snapshot_jsons"] is not None
        else [None] * len(snapshot_pickles)
    )
    snapshot_modes = list(
        cached["snapshot_modes"]
        if cached["snapshot_modes"] is not None
        else [None] * len(snapshot_pickles)
    )

    keep = max(6, int(keep or _MLB_MEMORY_KEEP_SNAPSHOTS))
    retain = max(0, keep - 1)
    if len(snapshot_pickles) > retain:
        snapshot_pickles = snapshot_pickles[-retain:]
        snapshot_jsons = snapshot_jsons[-retain:]
        snapshot_modes = snapshot_modes[-retain:]

    snapshot_pickles.append(
        pickle.dumps(snapshot, protocol=pickle.HIGHEST_PROTOCOL)
    )
    snapshot_jsons.append(None)
    snapshot_modes.append(None)

    # Reuse canonical immutable blobs. Only a snapshot whose storage mode
    # changes (plus the new snapshot) needs compaction and JSON serialization.
    stored_pickles = []
    stored_jsons = []
    stored_modes = []
    recent_start = max(0, len(snapshot_pickles) - 3)
    for idx, (item_blob, encoded_item, stored_mode) in enumerate(
        zip(snapshot_pickles, snapshot_jsons, snapshot_modes)
    ):
        desired_mode = "detail" if idx >= recent_start else "compact"
        if encoded_item is not None and stored_mode == desired_mode:
            stored_pickles.append(item_blob)
            stored_jsons.append(encoded_item)
            stored_modes.append(stored_mode)
            continue

        item = _compact_mlb_memory_snapshot(
            pickle.loads(item_blob),
            keep_detail=(desired_mode == "detail"),
        )
        stored_pickles.append(
            pickle.dumps(item, protocol=pickle.HIGHEST_PROTOCOL)
        )
        stored_jsons.append(
            json.dumps(
                item,
                ensure_ascii=False,
                separators=(",", ":"),
            )
        )
        stored_modes.append(desired_mode)

    # Prune oldest snapshots until file size target is respected.
    updated_at = datetime.now(timezone.utc).isoformat()
    updated_json = json.dumps(
        updated_at,
        ensure_ascii=False,
        separators=(",", ":"),
    )

    def _encoded_store(items):
        latest_json = items[-1]
        return (
            '{"latest":'
            + latest_json
            + ',"snapshots":['
            + ",".join(items)
            + '],"updatedAt":'
            + updated_json
            + "}"
        )

    encoded = _encoded_store(stored_jsons)
    while stored_jsons:
        encoded_size = len(encoded.encode("utf-8"))
        if encoded_size <= _MLB_MEMORY_MAX_BYTES or len(stored_jsons) <= 6:
            break
        stored_pickles = stored_pickles[1:]
        stored_jsons = stored_jsons[1:]
        stored_modes = stored_modes[1:]
        encoded = _encoded_store(stored_jsons)

    stat = _write_mlb_memory_store(encoded)
    if stat is None:
        raise OSError("Unable to persist MLB memory store")

    latest = pickle.loads(stored_pickles[-1])
    payload = {
        "latest": latest,
        "snapshots": [],
        "updatedAt": updated_at,
    }
    _publish_mlb_memory_cached_views(
        payload,
        stat,
        snapshot_pickles=stored_pickles,
        snapshot_jsons=stored_jsons,
        snapshot_modes=stored_modes,
    )
    if return_payload:
        return _mlb_memory_store_payload()
    return None


def _compact_mlb_memory_snapshot(snapshot, keep_detail=False):
    if not isinstance(snapshot, dict):
        return {}
    out = dict(snapshot)
    out["compact"] = not bool(keep_detail)

    games = dict(out.get("games") or {})
    boxscores = list(games.get("boxscores") or [])
    if not keep_detail and len(boxscores) > 6:
        games["boxscoresSample"] = boxscores[:6]
        games["boxscoreCount"] = len(boxscores)
        games.pop("boxscores", None)
    out["games"] = games

    players = dict(out.get("players") or {})
    featured = list(players.get("featured") or [])
    if not keep_detail and len(featured) > 40:
        players["featuredSample"] = featured[:40]
        players["featuredCount"] = len(featured)
        players.pop("featured", None)
    out["players"] = players

    schedule = list(out.get("schedule") or [])
    if not keep_detail and len(schedule) > 3:
        out["schedule"] = schedule[:3]
        out["scheduleTruncated"] = True

    return out

