@app.route("/api/status")
def api_status():
    t0 = time.time()
    with _fg_lock:
        fgl, fgd, fgb, fgp = _fg_loaded, _fg_load_date, len(_fg_bat), len(_fg_pit)
    with _sv_lock:
        svl, svd = _sv_loaded, _sv_load_date
        svpi, svbi, svsc, svar = len(_sv_pit_xstats), len(_sv_bat_xstats), len(_sv_bat_statcast), len(_sv_arsenal_pct)
    with _pitcher_name_to_mlbam_lock:
        nm_count = len(_pitcher_name_to_mlbam)
    with _batter_profiles_lock:
        bp_count = len(_batter_profiles)
    with _batter_statcast_lock:
        bs_count = sum(1 for v in _batter_statcast_cache.values() if v is not None)
    with _pitcher_statcast_lock:
        ps_count = sum(1 for v in _pitcher_statcast_cache.values() if v is not None)

    resp = jsonify({
        "fangraphs": {"loaded":fgl,"date":str(fgd),"batters":fgb,"pitchers":fgp},
        "savant":    {"loaded":svl,"date":str(svd),"pit_xstats":svpi,"bat_xstats":svbi,"statcast":svsc,"arsenals":svar},
        "referenceSnapshot": _reference_snapshot_status_payload(),
        "mlbMemory": _mlb_memory_status_payload(),
        "ai": {
            "gemini": {
                "available":       _gemini_available,
                "fast_model":      VERTEX_MODELS["fast"],
                "reasoning_model": VERTEX_MODELS["reasoning"],
                "narrative_model": VERTEX_MODELS["narrative"],
                "premium_model":   VERTEX_MODELS["premium"],
            },
            "bigquery": {"available": _bigquery_available},
        },
        "arsenalPrior": {
            "name_to_mlbam":   nm_count,
            "batter_profiles": bp_count,
            "batter_statcast_hot":  bs_count,
            "pitcher_statcast_hot": ps_count,
        },
    })
    logging.info(f"[API] /api/status took {time.time() - t0:.3f}s")
    return resp


@app.route("/api/cache/status")
def api_cache_status():
    """Aggregated readiness for every background loader the sim depends on.
    Used by the Cache Status panel in Admin Settings."""
    today = datetime.now().date()
    with _fg_lock:
        fg_state = {
            "loaded":   bool(_fg_loaded and _fg_load_date == today),
            "loading":  bool(_fg_loading),
            "date":     str(_fg_load_date) if _fg_load_date else None,
            "batters":  len(_fg_bat),
            "pitchers": len(_fg_pit),
        }
    with _sv_lock:
        sv_state = {
            "loaded":     bool(_sv_loaded and _sv_load_date == today),
            "loading":    bool(_sv_loading),
            "date":       str(_sv_load_date) if _sv_load_date else None,
            "pit_xstats": len(_sv_pit_xstats),
            "bat_xstats": len(_sv_bat_xstats),
            "statcast":   len(_sv_bat_statcast),
            "arsenals":   len(_sv_arsenal_pct),
        }
    with _local_arsenal_lock:
        ars = _local_arsenal_cache
    with _sv_lock:
        shared_arsenal_count = len(_sv_arsenal_pct)
    arsenal_state = {
        "loaded":   bool(shared_arsenal_count or ars is not None),
        "pitchers": shared_arsenal_count or (len(ars[0]) if ars else 0),
        "source":   "shared_snapshot" if shared_arsenal_count else "local_fallback",
    }
    pipeline_state = None
    if _PIPELINE_AVAILABLE:
        try:
            pipeline_state = get_pipeline_status() or {"status": "idle"}
            with _pipeline_run_lock:
                started = _pipeline_run_started_at
            # Only surface app-side started_at while the pipeline is actually
            # running; once it's done/idle the timestamp is stale.
            if started and pipeline_state.get("status") == "running":
                pipeline_state["started_at"] = datetime.fromtimestamp(started).isoformat()
        except Exception as ex:
            pipeline_state = {"status": "error", "error": str(ex)[:200]}

    pipeline_ok = (pipeline_state is None) or (pipeline_state.get("status") == "done")
    ready = bool(
        fg_state["loaded"] and sv_state["loaded"]
        and arsenal_state["loaded"] and pipeline_ok
    )
    return jsonify({
        "ready":    ready,
        "fg":       fg_state,
        "savant":   sv_state,
        "referenceSnapshot": _reference_snapshot_status_payload(),
        "arsenal":  arsenal_state,
        "pipeline": pipeline_state,
    })


@app.route("/api/cache/warm", methods=["POST"])
def api_cache_warm():
    """Re-trigger every background loader. Non-blocking — returns immediately
    with the list of loaders that were started. Safe to call repeatedly: each
    loader skips work that's already in progress or up-to-date.

    Query params:
        force=1   — force-restart the matchup pipeline even if status is
                    'running'. Useful when a previous run has stalled on
                    slow MLB API responses. The orphan thread keeps
                    blocking on its I/O call but its result is overwritten
                    when the new run finishes.
        date=YYYY-MM-DD — warm the lineup pipeline for a specific slate
                    instead of today. Defaults to today in ET.
    """
    global _pipeline_run_started_at
    force = str(request.args.get("force", "")).strip().lower() in ("1", "true", "yes")
    target_date = (request.args.get("date") or "").strip() or None
    if settings.process_role != 'worker':
        try:
            job = enqueue_job(
                'cache_warm',
                {'force': force, 'date': target_date},
                dedupe_key=f'cache-warm:{target_date or "today"}',
                timeout_seconds=600,
                max_attempts=1,
            )
            return jsonify({'success': True, 'queued': True, 'jobId': job['id']}), 202
        except JobQueueUnavailable:
            return jsonify({'success': False, 'error': 'Worker unavailable'}), 503
    triggered = []
    skipped = []

    try:
        with _fg_lock:
            fg_busy = _fg_loading or (
                _fg_loaded and _fg_load_date == datetime.now().date()
            )
        if fg_busy:
            skipped.append("fg")
        else:
            _maybe_refresh_fg()
            triggered.append("fg")
    except Exception as ex:
        logging.warning(f"[cache/warm] fg trigger failed: {ex}")

    try:
        with _sv_lock:
            sv_busy = _sv_loading or (
                _sv_loaded and _sv_load_date == datetime.now().date()
            )
        if sv_busy:
            skipped.append("savant")
        else:
            _maybe_refresh_savant()
            triggered.append("savant")
    except Exception as ex:
        logging.warning(f"[cache/warm] savant trigger failed: {ex}")

    with _local_arsenal_lock:
        arsenal_loaded = _local_arsenal_cache is not None
    if arsenal_loaded:
        skipped.append("arsenal")
    else:
        def _warm_arsenal():
            global _local_arsenal_cache
            try:
                with _local_arsenal_lock:
                    if _local_arsenal_cache is None:
                        _local_arsenal_cache = _load_local_pitcher_arsenal()
            except Exception as ex:
                logging.warning(f"[cache/warm] arsenal load failed: {ex}")
        threading.Thread(target=_warm_arsenal, daemon=True).start()
        triggered.append("arsenal")

    if _PIPELINE_AVAILABLE:
        try:
            ps = get_pipeline_status() or {}
            if ps.get("status") == "running" and not force:
                skipped.append("pipeline")
            else:
                with _pipeline_run_lock:
                    _pipeline_run_started_at = time.time()
                threading.Thread(
                    target=run_pipeline,
                    kwargs={"target_date": target_date},
                    daemon=True,
                ).start()
                triggered.append("pipeline" + (" (force)" if force else ""))
        except Exception as ex:
            logging.warning(f"[cache/warm] pipeline trigger failed: {ex}")

    return jsonify({
        "success":     True,
        "triggered":   triggered,
        "skipped":     skipped,
        "target_date": target_date,
    })


# Commit marker (baked in by the Docker build via GIT_SHA) + process boot time,
# so a deploy can be verified live: GET /health → {"version": "<sha>", ...}.
_APP_VERSION = os.getenv('GIT_SHA') or 'dev'
_APP_BOOT_ISO = datetime.now().isoformat()


@app.route('/health')
@limiter.exempt
def health_check():
    """Constant-time liveness probe; never touches Redis, files, or loaders."""
    return {
        'status': 'ok',
        'version': _APP_VERSION,
        'bootedAt': _APP_BOOT_ISO,
        'process': settings.process_role,
    }, 200


@app.route('/ready')
@limiter.exempt
def readiness_check():
    """Dependency readiness for deployment smoke tests and traffic gating."""
    started = time.perf_counter()
    jobs = queue_health()
    ready = bool(jobs.get('connected') and jobs.get('workerReady'))
    return {
        'status': 'ready' if ready else 'not_ready',
        'version': _APP_VERSION,
        'jobs': jobs,
        'latencyMs': round((time.perf_counter() - started) * 1000, 2),
    }, 200 if ready else 503


@app.route('/api/jobs/<job_id>')
def api_job_status(job_id):
    """Return a secret-safe durable job status for UI polling."""
    if not re.fullmatch(r'[0-9a-f]{32}', job_id or ''):
        return jsonify({'success': False, 'error': 'Invalid job id'}), 400
    try:
        queue = get_job_queue()
        job = queue.get(job_id)
    except JobQueueUnavailable:
        return jsonify({'success': False, 'error': 'Worker unavailable'}), 503
    if not job:
        return jsonify({'success': False, 'error': 'Job not found'}), 404
    return jsonify({'success': True, 'job': queue.snapshot(job)})


