@app.route('/api/tracker/blend-debug')
def api_tracker_blend_debug():
    """QA endpoint: returns per-row rawProb, rawMultProb, marketImplied, adjProb, edge for a game."""
    t0 = time.time()
    game_pk = request.args.get('gamePk') or request.args.get('game_pk')
    if not game_pk:
        logging.info(f"[API] /api/tracker/blend-debug took {time.time() - t0:.3f}s (missing gamePk)")
        return jsonify({"error": "gamePk required"}), 400
    try:
        game_pk = int(game_pk)
    except Exception:
        logging.info(f"[API] /api/tracker/blend-debug took {time.time() - t0:.3f}s (bad gamePk)")
        return jsonify({"error": "gamePk must be an integer"}), 400
    adjustments = _get_adjustments()
    _maybe_refresh_fg()
    game_obj = fetch_schedule_game(game_pk)
    if not game_obj:
        logging.info(f"[API] /api/tracker/blend-debug took {time.time() - t0:.3f}s (game not found)")
        return jsonify({"error": "game not found"}), 404
    game_date = ((game_obj.get('gameDate') or '').split('T')[0] or
                 datetime.now(ET).strftime('%Y-%m-%d'))
    rows = _build_tracker_rows_for_game(game_pk, game_date, adjustments=adjustments, _sched=[game_obj], include_odds=True)
    debug_rows = []
    for r in rows:
        market_implied = r.get('marketImplied')
        under_implied = _american_to_implied(r.get('bestUnderPrice'))
        fair_over = None
        fair_under = None
        if market_implied and under_implied:
            fair_over, fair_under = devig_power(market_implied, under_implied)
        debug_rows.append({
            "player": r.get('player'),
            "team": r.get('team'),
            "marketKey": r.get('marketKey'),
            "line": r.get('line'),
            "rawProb": r.get('rawProb'),
            "rawMultProb": r.get('rawMultProb'),
            "marketImplied": market_implied,
            "underImplied": under_implied,
            "fairOver": fair_over,
            "fairUnder": fair_under,
            "adjProb": r.get('adjProb'),
            "edge": r.get('edge'),
            "hubRating": r.get('hubRating'),
            "evPct": r.get('evPct'),
            "blended": r.get('marketImplied') is not None and r.get('marketImplied', 0) > 0,
        })
    blended_count = sum(1 for r in debug_rows if r['blended'])
    return jsonify({
        "gamePk": game_pk,
        "gameDate": game_date,
        "totalRows": len(debug_rows),
        "blendedRows": blended_count,
        "multiplicativeOnlyRows": len(debug_rows) - blended_count,
        "rows": debug_rows,
    })


# ──────────────────────────────────────────────────────────────────────────
# Best-prop recommender — click a game, get the top player-prop target.
#
# Reuses the full per-prop engine (_build_tracker_rows_for_game) that already
# produces hubRating / edge / EV / adjProb / confidenceTier / bvpGrade / MC
# percentiles for every batter market + pitcher-K line, then ranks those rows
# to surface THE recommended pick (plus the best batter prop and best pitcher-K
# prop) with auto-generated reasoning. Cached per game for a few minutes so a
# repeat click is instant.
# ──────────────────────────────────────────────────────────────────────────
_PROP_MARKET_LABEL = {
    'batter_hits':        'Hits',
    'batter_total_bases': 'Total Bases',
    'batter_home_runs':   'Home Run',
    'batter_rbis':        'RBIs',
    'pitcher_strikeouts': 'Strikeouts',
}
_PLAYER_PROP_MARKETS = set(_PROP_MARKET_LABEL)

_best_prop_cache: dict = {}
_best_prop_lock = threading.Lock()
_BEST_PROP_TTL = 600  # seconds


def _odds_str(price):
    try:
        p = int(round(float(price)))
    except (TypeError, ValueError):
        return None
    return f"+{p}" if p > 0 else str(p)


def _best_prop_rank_key(r):
    """Sort key (desc): positive-edge rows first by edge, else by model conviction."""
    edge = r.get('edge')
    has_edge = edge is not None
    return (
        1 if (has_edge and edge > 0) else 0,
        (float(edge) if has_edge else -1.0),
        float(r.get('hubRating') or 0),
        float(r.get('adjProb') or 0),
    )


def _best_prop_reasoning(r):
    """Auto-generate a recommendation summary + driver chips from a prop row."""
    mk = r.get('marketKey')
    label = _PROP_MARKET_LABEL.get(mk, (mk or '').replace('_', ' ').title())
    player = r.get('player')
    line = r.get('line')
    side = r.get('recommendedSide', 'Over')
    adj = r.get('adjProb')
    edge = r.get('edge')
    ev = r.get('evPct')
    tier = r.get('confidenceTier')
    bvp = r.get('bvpGrade')
    mean = r.get('modelMean')
    mi = r.get('marketImplied')
    price = r.get('bestOverPrice')
    book = r.get('bestOverBook')
    mc_over = r.get('mc_prob_over')

    drivers = []
    if adj is not None:
        drivers.append(f"Model {adj * 100:.0f}% to cash the {side}")
    if mean is not None:
        drivers.append(f"Projects {mean:g} {label.lower()} into a {line} line")
    if edge is not None and mi:
        drivers.append(f"+{edge * 100:.1f}-pt edge over market implied {mi * 100:.0f}%")
    if ev is not None:
        tail = f" at {_odds_str(price)} ({book})" if (price and book) else ""
        drivers.append(f"+{ev * 100:.1f}% expected value{tail}")
    if mc_over is not None:
        drivers.append(f"Sims clear the line {mc_over * 100:.0f}% of the time")
    if bvp in ('A', 'B'):
        drivers.append(f"Favorable matchup history (BvP grade {bvp})")
    if tier:
        drivers.append(f"{tier}-tier confidence")

    parts = [f"Take {player} {side} {line} {label}."]
    if adj is not None:
        s = f" Model gives it {adj * 100:.0f}%"
        if edge is not None and edge > 0:
            s += f" — a +{edge * 100:.1f}-pt edge on the market"
        s += "."
        parts.append(s)
    if price and book:
        parts.append(f" Best price {_odds_str(price)} at {book}.")
    return {'summary': ''.join(parts), 'drivers': drivers}


def _best_prop_pack(r):
    rsn = _best_prop_reasoning(r)
    return {
        'player':          r.get('player'),
        'playerId':        r.get('playerId'),
        'team':            r.get('team'),
        'marketKey':       r.get('marketKey'),
        'marketLabel':     _PROP_MARKET_LABEL.get(r.get('marketKey'), r.get('marketKey')),
        'line':            r.get('line'),
        'side':            r.get('recommendedSide', 'Over'),
        'adjProb':         r.get('adjProb'),
        'edge':            r.get('edge'),
        'evPct':           r.get('evPct'),
        'hubRating':       r.get('hubRating'),
        'confidenceTier':  r.get('confidenceTier'),
        'bvpGrade':        r.get('bvpGrade'),
        'modelMean':       r.get('modelMean'),
        'marketImplied':   r.get('marketImplied'),
        'bestOverPrice':   r.get('bestOverPrice'),
        'bestOverBook':    r.get('bestOverBook'),
        'opp':             r.get('opp'),
        'summary':         rsn['summary'],
        'drivers':         rsn['drivers'],
    }


@app.route('/api/best-prop/<int:game_pk>')
def api_best_prop(game_pk):
    """Rank every batter/pitcher prop for a game and recommend the top target(s)."""
    t0 = time.time()
    use_odds = (request.args.get('odds', '1') not in ('0', 'false', 'no'))
    now = time.time()
    ck = (game_pk, bool(use_odds))
    with _best_prop_lock:
        hit = _best_prop_cache.get(ck)
        if hit and (now - hit[0]) < _BEST_PROP_TTL:
            return jsonify(hit[1])

    try:
        game_obj = fetch_schedule_game(game_pk)
    except Exception as ex:
        return jsonify({'success': False, 'error': f'schedule fetch failed: {ex}'}), 502
    if not game_obj:
        return jsonify({'success': False, 'error': 'game not found'}), 404
    game_date = ((game_obj.get('gameDate') or '').split('T')[0] or
                 datetime.now(ET).strftime('%Y-%m-%d'))
    teams = game_obj.get('teams', {})
    away_t = (teams.get('away', {}) or {}).get('team', {}) or {}
    home_t = (teams.get('home', {}) or {}).get('team', {}) or {}
    away_abbr = away_t.get('abbreviation') or away_t.get('name') or 'AWAY'
    home_abbr = home_t.get('abbreviation') or home_t.get('name') or 'HOME'

    try:
        _maybe_refresh_fg()
        rows = _build_tracker_rows_for_game(
            game_pk, game_date, _sched=[game_obj], include_odds=use_odds) or []
    except Exception as ex:
        logging.error(f"[best-prop] {game_pk} {ex}")
        return jsonify({'success': False, 'error': str(ex)}), 500

    cand = [r for r in rows
            if r.get('marketKey') in _PLAYER_PROP_MARKETS and (r.get('adjProb') or 0) > 0]
    cand.sort(key=_best_prop_rank_key, reverse=True)

    qual = [r for r in cand if (r.get('adjProb') or 0) >= 0.50]
    headline = qual[0] if qual else (cand[0] if cand else None)
    top_batter = next((r for r in cand if str(r.get('marketKey')).startswith('batter_')), None)
    top_pitcher = next((r for r in cand if r.get('marketKey') == 'pitcher_strikeouts'), None)

    payload = {
        'success': True,
        'gamePk': game_pk,
        'gameDate': game_date,
        'matchup': f"{away_abbr} @ {home_abbr}",
        'recommendation': _best_prop_pack(headline) if headline else None,
        'topBatter': _best_prop_pack(top_batter) if top_batter else None,
        'topPitcherK': _best_prop_pack(top_pitcher) if top_pitcher else None,
        'board': [_best_prop_pack(r) for r in cand[:6]],
        'oddsUsed': bool(use_odds and any(r.get('marketImplied') for r in cand)),
        'candidateCount': len(cand),
        'tookSec': round(time.time() - t0, 2),
    }
    with _best_prop_lock:
        _best_prop_cache[ck] = (now, payload)
    return jsonify(payload)


def _mlb_memory_status_payload():
    status = _mlb_memory_store_status_view()
    with _mlb_memory_lock:
        collecting = bool(_mlb_memory_collecting)
        last_collect = _mlb_memory_last_collect
        last_error = _mlb_memory_last_error
    return {
        "collecting": collecting,
        "lastCollectAt": last_collect,
        "lastError": last_error,
        "nextMode": _memory_mode_for_now('auto'),
        "snapshotCount": status.get("snapshotCount", 0),
        "latest": status.get("latest") or {},
        "file": status.get("file") or {},
        "updatedAt": status.get("updatedAt"),
    }


def _run_mlb_memory_collect(date_str=None, days_back=2, max_games_per_day=30, include_boxscores=True, max_players=160, mode=None, pace_sec=0.0):
    global _mlb_memory_collecting, _mlb_memory_last_collect, _mlb_memory_last_error
    with _mlb_memory_lock:
        if _mlb_memory_collecting:
            return None, "Collect already in progress"
        _mlb_memory_collecting = True
        _mlb_memory_last_error = None
    try:
        defaults = _memory_mode_defaults(mode)
        eff_mode = defaults.get('mode')
        snapshot = _collect_mlb_memory_snapshot(
            date_str=date_str,
            days_back=int(defaults.get('days_back', days_back) if mode else days_back),
            max_games_per_day=int(defaults.get('max_games_per_day', max_games_per_day) if mode else max_games_per_day),
            include_boxscores=bool(defaults.get('include_boxscores', include_boxscores) if mode else include_boxscores),
            max_players=int(defaults.get('max_players', max_players) if mode else max_players),
            mode=eff_mode if mode else 'manual',
            include_team_rosters=bool(defaults.get('include_team_rosters', False) if mode else False),
            transactions_days=int(defaults.get('transactions_days', 2) if mode else 2),
            pace_sec=pace_sec,
        )
        _append_mlb_memory_snapshot(
            snapshot,
            keep=_MLB_MEMORY_KEEP_SNAPSHOTS,
            return_payload=False,
        )
        _mlb_memory_last_collect = datetime.now(timezone.utc).isoformat()
        return snapshot, None
    except Exception as ex:
        _mlb_memory_last_error = str(ex)
        return None, str(ex)
    finally:
        with _mlb_memory_lock:
            _mlb_memory_collecting = False


_mlb_memory_worker_started = False


def _start_mlb_memory_worker(interval_sec=3 * 60 * 60):
    global _mlb_memory_worker_started
    with _mlb_memory_lock:
        if _mlb_memory_worker_started:
            return
        _mlb_memory_worker_started = True

    def _runner():
        # Don't collect at boot: the first run used to fire immediately, right
        # while the FG/Savant preload and the projections prewarm are competing
        # for CPU and the HTTP pool. The store persists across restarts, so a
        # 15-minute-old snapshot at boot is fine.
        time.sleep(900)
        while True:
            try:
                _run_mlb_memory_collect(
                    date_str=datetime.now(ET).strftime('%Y-%m-%d'),
                    mode='auto',
                    pace_sec=0.05,
                )
            except Exception as ex:
                print(f'[mlb_memory_worker] {ex}')
            time.sleep(max(1800, int(interval_sec)))

    threading.Thread(target=_runner, daemon=True).start()


