@app.route("/api/game-projection/<int:game_pk>")
def api_game_projection(game_pk):
    _maybe_refresh_fg()
    _maybe_refresh_savant()
    try:
        gdata = fetch_schedule_game(game_pk)
        if not gdata:
            return jsonify({"success": False, "error": "Game not found"})
        away_t = gdata.get("teams",{}).get("away",{})
        home_t = gdata.get("teams",{}).get("home",{})
        ap = away_t.get("probablePitcher",{}); hp = home_t.get("probablePitcher",{})
        ap_n = ap.get("fullName","TBD"); hp_n = hp.get("fullName","TBD")
        hid = home_t.get("team",{}).get("id")
        pf = PARK_FACTORS.get(hid, 1.0)
        ap_mlb = pitcher_stats_mlb(ap.get("id")) if ap.get("id") else {}
        hp_mlb = pitcher_stats_mlb(hp.get("id")) if hp.get("id") else {}
        ap_fg = fg_pitcher(ap_n); hp_fg = fg_pitcher(hp_n)
        ap_sv = sv_pitcher(ap_n); hp_sv = sv_pitcher(hp_n)
        def best_era(sv, fg, mlb):
            # FIX: Require min 15 IP before trusting xERA (avoids April small-sample noise)
            xera = sv.get("sv_xera")
            ip = fg.get("fg_ip", 0) or 0
            if xera and float(ip or 0) >= 15:
                try:
                    f = float(xera)
                    if 0 < f < 12: return f
                except Exception: pass
            for v in [fg.get("fg_era"), mlb.get("era")]:
                try:
                    f = float(v)
                    if 0 < f < 12: return f
                except Exception: pass
            return 4.50
        def best_fip(fg, fallback):
            try:
                f = float(fg.get("fg_fip",0))
                if 0 < f < 12: return f
            except Exception: pass
            return fallback
        # home pitcher faces away lineup, away pitcher faces home lineup
        away_pit_era = best_era(hp_sv, hp_fg, hp_mlb)
        home_pit_era = best_era(ap_sv, ap_fg, ap_mlb)
        away_pit_fip = best_fip(hp_fg, away_pit_era)
        home_pit_fip = best_fip(ap_fg, home_pit_era)
        # Try to get lineup xwOBA
        try:
            r = requests.get(f"{MLB_API}/game/{game_pk}/boxscore", timeout=10)
            r.raise_for_status()
            box = r.json().get("teams",{})
            away_bats = get_batters_from_boxscore(box.get("away",{}), "away")
            home_bats = get_batters_from_boxscore(box.get("home",{}), "home")
        except Exception as ex:
            print(f'[api_game_projection] boxscore fetch failed for {game_pk}: {ex}')
            away_bats = []; home_bats = []
        def lineup_xwoba(bats):
            vals = []
            for b in bats:
                for k in ["sv_xwoba","fg_woba"]:
                    try:
                        f = float(b.get(k,0))
                        if 0.1 < f < 0.6: vals.append(f); break
                    except Exception: pass
                else:
                    vals.append(0.320)
            return round(sum(vals)/len(vals), 3) if vals else 0.320
        away_xwoba = lineup_xwoba(away_bats)
        home_xwoba = lineup_xwoba(home_bats)
        # Blended ERA: 60% xERA/ERA + 40% FIP
        away_blend = 0.6*away_pit_era + 0.4*away_pit_fip
        home_blend = 0.6*home_pit_era + 0.4*home_pit_fip
        # Base runs model (empirical: 4.5 R/G MLB avg)
        away_runs = 4.50 * (away_blend/4.50) * (away_xwoba/0.320) * pf  # FIX: corrected ERA direction (lower ERA = fewer runs allowed)
        home_runs = 4.50 * (home_blend/4.50) * (home_xwoba/0.320) * pf  # FIX: corrected ERA direction
        # Weather adjustment
        ven = gdata.get("venue", {})
        venue_id_wx = ven.get("id")
        vloc = ven.get("location", {}) or {}
        coords = vloc.get("defaultCoordinates", {}) or {}
        lat = coords.get("latitude")
        lon = coords.get("longitude")
        try:
            dt_utc_wx = datetime.fromisoformat(gdata.get("gameDate","").replace("Z","+00:00"))
            proj_hour = dt_utc_wx.astimezone(ET).hour
        except Exception:
            proj_hour = 13
        wx = get_weather(lat, lon, proj_hour, venue_id=venue_id_wx)
        # Fallback: use MLB schedule weather for projections when Open-Meteo is unavailable.
        if (wx.get("temp") in (None, "N/A") or wx.get("condition") in (None, "", "N/A")):
            raw_weather = gdata.get("weather", {}) or {}
            if raw_weather:
                print(f"[weather_fallback] using MLB weather for projection gamePk={game_pk} venue={venue_id_wx}")
                wx = {
                    "temp": raw_weather.get("temp", "N/A"),
                    "condition": raw_weather.get("condition", "N/A"),
                    "wind": raw_weather.get("wind", "N/A"),
                    "wind_speed": raw_weather.get("wind", "N/A"),
                    "wind_dir": "",
                    "rain_chance": raw_weather.get("precipitationChance", raw_weather.get("precipChance", "N/A")),
                }
        wx_adj = 0.0
        if not wx.get("dome"):
            try:
                t = float(wx.get("temp","70"))
                if t > 82: wx_adj = 0.20
                elif t > 76: wx_adj = 0.10
                elif t < 48: wx_adj = -0.20
                elif t < 56: wx_adj = -0.10
            except Exception: pass
        wind_adj = _wind_run_adj(wx)
        # Bullpen fatigue: each team scores extra against the OTHER team's tired
        # pen (day-cached, non-blocking — 0 until warm). Affects late innings, so
        # it belongs in the full-game total, not F5.
        aid = away_t.get("team", {}).get("id")
        away_bp = _bullpen_run_boost(_relief_fatigue_penalty_cached(hid))
        home_bp = _bullpen_run_boost(_relief_fatigue_penalty_cached(aid))
        away_runs = round(away_runs + wx_adj + wind_adj + away_bp, 1)
        home_runs = round(home_runs + wx_adj + wind_adj + home_bp, 1)
        total = round(away_runs + home_runs, 1)
        run_env = "HIGH" if total > 9.5 else ("LOW" if total < 7.5 else "NEUTRAL")
        at_abbr = away_t.get("team",{}).get("abbreviation","AWAY")
        ht_abbr = home_t.get("team",{}).get("abbreviation","HOME")
        diff = abs(home_runs - away_runs)
        if diff > 0.7:
            fav = ht_abbr if home_runs > away_runs else at_abbr
        else:
            fav = "EVEN"

        # Build lightweight BvP context from top lineup spots when available.
        bvp_highlights = []
        try:
            def _bvp_lineup_highlights(lineup, opp_pitcher_id, opp_pitcher_name):
                rows = []
                if not opp_pitcher_id:
                    return rows
                for b in (lineup or [])[:6]:
                    bid = b.get("id")
                    if not bid:
                        continue
                    bp = _fetch_bvp(bid, opp_pitcher_id)
                    if not bp or not bp.get("success"):
                        continue
                    pa = int(bp.get("pa", 0) or 0)
                    avg = bp.get("avg")
                    hr = int(bp.get("hr", 0) or 0)
                    if pa < 6 or avg is None:
                        continue
                    rows.append(
                        f"{b.get('name','Hitter')} vs {opp_pitcher_name}: {pa} PA, AVG {avg:.3f}, HR {hr}"
                    )
                    if len(rows) >= 2:
                        break
                return rows

            bvp_highlights.extend(_bvp_lineup_highlights(away_bats, hp.get("id"), hp_n))
            bvp_highlights.extend(_bvp_lineup_highlights(home_bats, ap.get("id"), ap_n))
        except Exception:
            bvp_highlights = []

        story_context = {
            "game_pk": game_pk,
            "away_team": at_abbr,
            "home_team": ht_abbr,
            "favorite": fav,
            "projected_total_runs": total,
            "run_environment": run_env,
            "weather": {
                "temp": wx.get("temp", "N/A"),
                "condition": wx.get("condition", "N/A"),
                "wind": wx.get("wind", "N/A"),
                "wind_dir": wx.get("wind_dir", ""),
                "wind_to_field": wx.get("wind_field"),
                "wind_out_mph": wx.get("wind_out"),
            },
            "series": {
                "game": gdata.get("seriesGame"),
                "total": gdata.get("seriesTotal"),
            },
            "umpire_tendency": "Unknown",
            "pitcher_form": {
                "away_pitcher": {
                    "name": ap_n,
                    "era": round(home_pit_era, 2),
                    "fip": round(home_pit_fip, 2),
                },
                "home_pitcher": {
                    "name": hp_n,
                    "era": round(away_pit_era, 2),
                    "fip": round(away_pit_fip, 2),
                },
            },
            "bvp_highlights": bvp_highlights,
            "lineup_xwoba": {
                "away": away_xwoba,
                "home": home_xwoba,
            },
        }

        matchup_insights, storyline_source = _claude_matchup_insights(story_context)
        if not matchup_insights:
            matchup_insights = _fallback_matchup_insights(
                gdata,
                at_abbr,
                ht_abbr,
                total,
                run_env,
                fav,
                ap_n,
                hp_n,
                home_pit_era,
                away_pit_era,
                wx,
            )
            storyline_source = f"fallback: {storyline_source or 'claude unavailable'}"

        return jsonify({
            "success": True,
            "awayAbbr": at_abbr, "homeAbbr": ht_abbr,
            "awayRuns": away_runs, "homeRuns": home_runs,
            "total": total, "runEnv": run_env, "favorite": fav,
            "awayXwoba": away_xwoba, "homeXwoba": home_xwoba,
            "awayPitcherEra": round(away_pit_era,2),
            "homePitcherEra": round(home_pit_era,2),
            "awayPitcherFip": round(away_pit_fip,2),
            "homePitcherFip": round(home_pit_fip,2),
            "parkFactor": pf, "wxAdj": wx_adj, "windAdj": wind_adj,
            "windField": wx.get("wind_field"), "windOut": wx.get("wind_out"),
            "awayBullpenAdj": away_bp, "homeBullpenAdj": home_bp,
            "matchup_insights": matchup_insights[:5],
            "storylineSource": storyline_source,
        })
    except Exception as ex:
        print("[api_game_projection]", traceback.format_exc())
        return jsonify({"success":False,"error":str(ex)}), 500


def _compute_form(logs, is_pitcher):
    """Compute rolling form windows from game log entries (newest-last order)."""
    def _hitter_window(games):
        if not games:
            return None
        ab = h = hr = bb = k = tb = 0
        pa = 0
        for g in games:
            ab += g.get("ab", 0)
            h  += g.get("h", 0)
            hr += g.get("hr", 0)
            bb += g.get("bb", 0)
            k  += g.get("k", 0)
            tb += g.get("tb", 0)
            pa += g.get("ab", 0) + g.get("bb", 0)
        avg  = round(h / ab, 3) if ab else None
        obp  = round((h + bb) / pa, 3) if pa else None
        slg  = round(tb / ab, 3) if ab else None
        ops  = round((obp or 0) + (slg or 0), 3) if (obp and slg) else None
        iso  = round((slg or 0) - (avg or 0), 3) if (slg and avg) else None
        kpct = round(k / pa, 4) if pa else None
        return {
            "games": len(games), "ab": ab, "hr": hr,
            "avg":  f".{int(round((avg or 0)*1000)):03d}" if avg is not None else "---",
            "obp":  f".{int(round((obp or 0)*1000)):03d}" if obp is not None else "---",
            "slg":  f".{int(round((slg or 0)*1000)):03d}" if slg is not None else "---",
            "ops":  f".{int(round((ops or 0)*1000)):03d}" if ops is not None else "---",
            "iso":  f".{int(round((iso or 0)*1000)):03d}" if iso is not None else "---",
            "kpct": round(kpct, 4) if kpct is not None else None,
        }

    def _pitcher_window(games):
        if not games:
            return None
        ip_total = 0.0; er = 0; pk = 0; bb = 0; qs = 0
        for g in games:
            ip_val = float(g.get("ip", 0) or 0)
            ip_total += ip_val
            er  += g.get("er", 0)
            pk  += g.get("k", 0)
            bb  += g.get("bb", 0)
            if ip_val >= 6 and g.get("er", 0) <= 3:
                qs += 1
        era  = round(er / ip_total * 9, 2) if ip_total else None
        k9   = round(pk / ip_total * 9, 2) if ip_total else None
        bb9  = round(bb / ip_total * 9, 2) if ip_total else None
        whip = None  # hits not stored in current game log schema
        return {
            "games": len(games), "ip": round(ip_total, 1), "qs": qs,
            "era":  era, "whip": whip, "k9": k9, "bb9": bb9,
        }

    recent = list(reversed(logs))  # newest first
    if not is_pitcher:
        l7  = _hitter_window(recent[:7])
        l14 = _hitter_window(recent[:14])
        l30 = _hitter_window(recent[:30])
        # Flag based on L7 OPS / AVG
        flag = "neutral"; flag_note = ""; trend = "stable"
        if l7:
            avg7 = float(l7["avg"].replace(".", "0.")) if l7["avg"] != "---" else None
            if avg7 is not None:
                if avg7 >= 0.350:   flag = "hot";     flag_note = f"Batting {l7['avg']} over last 7 games"
                elif avg7 >= 0.280: flag = "warm";    flag_note = f"Solid {l7['avg']} over last 7 games"
                elif avg7 < 0.150:  flag = "cold";    flag_note = f"Struggling at {l7['avg']} over last 7 games"
                elif avg7 < 0.210:  flag = "chilly";  flag_note = f"Below average {l7['avg']} over last 7 games"
            if l14:
                avg14 = float(l14["avg"].replace(".", "0.")) if l14["avg"] != "---" else None
                if avg7 is not None and avg14 is not None:
                    if avg7 > avg14 + 0.040:   trend = "improving"
                    elif avg7 < avg14 - 0.040: trend = "declining"
        return {"kind": "hitter", "flag": flag, "flag_note": flag_note, "trend": trend,
                "l7": l7, "l14": l14, "l30": l30}
    else:
        l3  = _pitcher_window(recent[:3])
        l5  = _pitcher_window(recent[:5])
        l10 = _pitcher_window(recent[:10])
        flag = "neutral"; flag_note = ""; trend = "stable"
        if l3 and l3["era"] is not None:
            era3 = l3["era"]
            if era3 < 2.0:   flag = "dealing";     flag_note = f"{era3:.2f} ERA over last 3 starts"
            elif era3 < 3.5: flag = "hot";         flag_note = f"{era3:.2f} ERA over last 3 starts"
            elif era3 < 4.5: flag = "neutral";     flag_note = f"{era3:.2f} ERA over last 3 starts"
            elif era3 < 6.0: flag = "chilly";      flag_note = f"{era3:.2f} ERA over last 3 starts"
            else:            flag = "struggling";  flag_note = f"{era3:.2f} ERA over last 3 starts"
            if l5 and l5["era"] is not None:
                if era3 < l5["era"] - 0.75:    trend = "improving"
                elif era3 > l5["era"] + 0.75:  trend = "declining"
        return {"kind": "pitcher", "flag": flag, "flag_note": flag_note, "trend": trend,
                "l3": l3, "l5": l5, "l10": l10}


def _build_ai_lines(name, is_pitcher, season, fg, sv, logs):
    """Generate 3-5 plain-text AI scouting sentences from cached + live stats."""
    lines = []
    try:
        first = name.split()[0] if name else "Player"
        if not is_pitcher:
            avg  = _safe_f(fg.get("fg_avg")     or season.get("avg"),  0.0)
            woba = _safe_f(fg.get("fg_woba"),  0.0)
            wrc  = int(_safe_f(fg.get("fg_wrc"), 0))
            xba  = _safe_f(sv.get("sv_xba"),   0.0)
            ev   = _safe_f(sv.get("sv_ev"),    0.0)
            brl  = _safe_f(sv.get("sv_brl_pct"), 0.0)
            hh   = _safe_f(sv.get("sv_hh_pct"),  0.0)
            r_ab = sum(g.get("ab", 0) for g in logs[-7:])
            r_h  = sum(g.get("h",  0) for g in logs[-7:])
            r_avg = round(r_h / r_ab, 3) if r_ab > 0 else None
            if avg > 0:
                tier = "elite" if avg >= 0.310 else "above-avg" if avg >= 0.280 else "below-avg"
                lines.append(
                    f"Batting {avg:.3f} this season ({tier}). wOBA {woba:.3f} ranks in the "
                    f"{'top third' if woba >= 0.340 else 'middle third' if woba >= 0.310 else 'bottom third'} of the league."
                )
            if wrc > 0:
                desc = "elite (well above avg)" if wrc >= 130 else "above avg" if wrc >= 110 else "roughly avg" if wrc >= 95 else "below avg"
                lines.append(f"wRC+ of {wrc} — {first} is {desc} in total offensive production (100 = league avg).")
            if ev > 0:
                quality = "Elite contact — target power props." if ev >= 91 and brl >= 8 else "Solid contact." if ev >= 88 else "Soft contact profile — fade power markets."
                lines.append(f"Avg exit velocity {ev} mph · Barrel% {brl:.1f} · Hard Hit% {hh:.1f}. {quality}")
            if xba > 0 and avg > 0:
                diff = round(xba - avg, 3)
                if abs(diff) >= 0.015:
                    direction = "unlucky — regression upward likely" if diff > 0 else "running hot — may regress"
                    lines.append(f"xBA ({xba:.3f}) vs AVG ({avg:.3f}), gap of {diff:+.3f} — {first} appears {direction}.")
            if r_avg is not None and r_ab >= 10:
                note = "Hot streak — elevated prop target." if r_avg >= 0.300 else "Cold stretch — consider fading hit props." if r_avg < 0.160 else "Normal recent form."
                lines.append(f"Last 7 games: {r_h}-for-{r_ab} ({r_avg:.3f}). {note}")
        else:
            era  = _safe_f(fg.get("fg_era")  or season.get("era"),  0.0)
            fip  = _safe_f(fg.get("fg_fip"),  0.0)
            kpct = _safe_f(fg.get("fg_kpct"), 0.0)
            xera = _safe_f(sv.get("sv_xera"), 0.0)
            if era > 0:
                fip_note = f"FIP {fip:.2f} signals sustainable success." if fip <= era else f"FIP {fip:.2f} suggests ERA may climb."
                lines.append(f"ERA of {era:.2f} this season. {fip_note}")
            if xera > 0:
                if era < xera - 0.30:
                    lines.append(f"xERA {xera:.2f} — outperforming expected metrics, regression risk.")
                elif era > xera + 0.30:
                    lines.append(f"xERA {xera:.2f} — underperforming expected metrics, positive regression candidate.")
                else:
                    lines.append(f"xERA {xera:.2f} aligns closely with ERA — sustainable performance.")
            if kpct > 0:
                k_desc = "elite strikeout arm — target K prop overs" if kpct >= 0.27 else "above-avg swing-and-miss" if kpct >= 0.22 else "below-avg K rate — fade K overs"
                lines.append(f"K% of {kpct*100:.1f}% — {k_desc}.")
            r_starts = [g for g in logs[-5:] if float(g.get("ip", 0) or 0) >= 3.0]
            if r_starts:
                r_k = sum(g.get("k", 0) for g in r_starts)
                lines.append(f"Last {len(r_starts)} starts: {r_k} total Ks ({round(r_k / len(r_starts), 1)} K/start avg).")
    except Exception:
        pass
    if not lines:
        lines.append(f"Insufficient data for a full AI report on {name} this early in the season.")
    return lines


@app.route("/api/player/<int:player_id>")
def api_player_profile(player_id):
    """Full player profile: identity + season stats + FG/Savant cache + game log + platoon + AI."""
    _maybe_refresh_fg()
    _maybe_refresh_savant()
    include_form = request.args.get("includeForm") == "1"
    try:
        year = datetime.now().year

        # 1. Player identity + season stats
        pr = requests.get(
            f"{MLB_API}/people/{player_id}",
            params={"hydrate": f"stats(group=[hitting,pitching],type=season,season={year}),currentTeam"},
            timeout=10
        )
        pr.raise_for_status()
        people = pr.json().get("people", [])
        if not people:
            return jsonify({"success": False, "error": "Player not found"}), 404
        p = people[0]

        name       = p.get("fullName", "Unknown")
        pos_code   = p.get("primaryPosition", {}).get("abbreviation", "?")
        team_obj   = (p.get("currentTeam") or {})
        team_abbr  = team_obj.get("abbreviation", "?")
        team_id    = team_obj.get("id")
        throws     = (p.get("pitchHand")   or {}).get("code", "?")
        bats_side  = (p.get("batSide")     or {}).get("code", "?")
        is_pitcher = pos_code in ("P", "SP", "RP", "CP")

        season = {}
        for sg in p.get("stats", []):
            grp    = (sg.get("group") or {}).get("displayName", "")
            splits = sg.get("splits", [])
            if splits:
                s = splits[0].get("stat", {})
                if grp == "hitting" and not is_pitcher:
                    season = {
                        "avg": s.get("avg"), "obp": s.get("obp"),
                        "slg": s.get("slg"), "ops": s.get("ops"),
                        "homeRuns": s.get("homeRuns", 0), "rbi": s.get("rbi", 0),
                        "runs": s.get("runs", 0), "stolenBases": s.get("stolenBases", 0),
                    }
                elif grp == "pitching" and is_pitcher:
                    season = {
                        "era": s.get("era"), "whip": s.get("whip"),
                        "inningsPitched": s.get("inningsPitched"),
                        "wins": s.get("wins", 0), "losses": s.get("losses", 0),
                    }

        # 2. Cached FG + Savant — zero extra HTTP calls
        fgr = (fg_pitcher(name) if is_pitcher else fg_batter(name)) or {}
        svr = (sv_pitcher(name) if is_pitcher else sv_batter(name)) or {}
        # Keep original keys (e.g. fg_avg, sv_arsenal_pct) so JS can access them directly
        fg_out = dict(fgr)
        sv_out = dict(svr)

        # 3. Game log — last 10 games
        group     = "pitching" if is_pitcher else "hitting"
        game_logs = []
        try:
            lr = requests.get(
                f"{MLB_API}/people/{player_id}/stats",
                params={"stats": "gameLog", "group": group, "season": year},
                timeout=8
            )
            if lr.ok:
                for sp in (lr.json().get("stats", [{}])[0].get("splits", []))[-30 if include_form else -10:]:
                    s   = sp.get("stat", {})
                    opp = (sp.get("opponent") or {}).get("abbreviation", "?")
                    dt  = sp.get("date", "")[:10]
                    if not is_pitcher:
                        game_logs.append({
                            "date": dt, "opp": opp,
                            "ab":  s.get("atBats", 0),     "h":   s.get("hits", 0),
                            "hr":  s.get("homeRuns", 0),   "rbi": s.get("rbi", 0),
                            "k":   s.get("strikeOuts", 0), "bb":  s.get("baseOnBalls", 0),
                            "tb":  s.get("totalBases", 0), "avg": s.get("avg", "---"),
                        })
                    else:
                        game_logs.append({
                            "date": dt, "opp": opp,
                            "ip":  s.get("inningsPitched", "0"), "h":  s.get("hits", 0),
                            "er":  s.get("earnedRuns", 0),
                            "k":   s.get("strikeOuts", 0),       "bb": s.get("baseOnBalls", 0),
                            "era": s.get("era", "---"),
                        })
        except Exception:
            pass

        # 4. Platoon splits vs LHP / RHP
        platoon = {}
        try:
            plr = requests.get(
                f"{MLB_API}/people/{player_id}/stats",
                params={"stats": "statSplits", "group": group, "season": year, "sitCodes": "vl,vr"},
                timeout=8
            )
            if plr.ok:
                for sp in plr.json().get("stats", [{}])[0].get("splits", []):
                    code = (sp.get("split") or {}).get("code", "")
                    s    = sp.get("stat", {})
                    if code in ("vl", "vr"):
                        platoon[code] = {
                            "avg":  s.get("avg",  "---"), "obp": s.get("obp", "---"),
                            "slg":  s.get("slg",  "---"), "ops": s.get("ops", "---"),
                            "pa":   s.get("plateAppearances", 0),
                            "hr":   s.get("homeRuns", 0),
                            "woba": s.get("woba", "---"),
                        }
        except Exception:
            pass

        # 5. AI Scout lines
        ai_lines = _build_ai_lines(name, is_pitcher, season, fgr, svr, game_logs)

        # 6. Form — use the richer _fetch_rolling_form (cached, wOBA-based) when requested
        form = _fetch_rolling_form(player_id, is_pitcher) if include_form else None

        opp_pitcher = None
        try:
            today_raw = fetch_schedule(datetime.now(ET).strftime("%Y-%m-%d"))
            for g in today_raw or []:
                teams = g.get("teams", {})
                away = teams.get("away", {})
                home = teams.get("home", {})
                away_id = (away.get("team") or {}).get("id")
                home_id = (home.get("team") or {}).get("id")
                if team_id not in (away_id, home_id):
                    continue
                if team_id == away_id:
                    opp = home
                else:
                    opp = away
                opp_team = opp.get("team", {})
                opp_pp = opp.get("probablePitcher") or {}
                opp_pitcher = {
                    "id": opp_pp.get("id"),
                    "name": opp_pp.get("fullName", "TBD"),
                    "team": opp_team.get("abbreviation", "?"),
                    "gamePk": g.get("gamePk"),
                }
                break
        except Exception:
            opp_pitcher = None

        return jsonify({
            "success":   True,
            "id":        player_id,
            "name":      name,
            "pos":       pos_code,
            "team":      team_abbr,
            "isPitcher": is_pitcher,
            "throws":    throws,
            "bats":      bats_side,
            "season":    season,
            "fg":        fg_out,
            "sv":        sv_out,
            "gameLogs":  game_logs,
            "platoon":   platoon,
            "aiLines":   ai_lines,
            "form":      form,
            "oppPitcher": opp_pitcher,
        })
        
    except Exception as ex:
        traceback.print_exc()
        return jsonify({"success": False, "error": str(ex)}), 500


@app.route("/api/bvp/<int:batter_id>/<int:pitcher_id>")
def api_bvp(batter_id, pitcher_id):
    """Batter-vs-Pitcher grade and sample detail for props surfaces."""
    result = _fetch_bvp(batter_id, pitcher_id)
    if not result or not result.get("success"):
        return jsonify({
            "success": False,
            "grade": "D",
            "ops": None,
            "avg": None,
            "hr": 0,
            "pa": 0,
            "sample_note": "No BvP data available",
        })
    return jsonify({
        "success": True,
        "grade": result.get("grade", "D"),
        "grade_basis": result.get("grade_basis", "h2h"),
        "pitcher_hand": result.get("pitcher_hand"),
        "platoon_ops": result.get("platoon_ops"),
        "ops": result.get("ops"),
        "avg": result.get("avg"),
        "hr": result.get("hr", 0),
        "pa": result.get("pa", 0),
        "ops_ratio": result.get("ops_ratio"),
        "sample_note": result.get("sample_note") or result.get("note") or "",
        "tooltip": result.get("tooltip") or "",
    })


@app.route("/api/bvp/<int:batter_id>/<int:pitcher_id>/projection")
def api_bvp_projection(batter_id, pitcher_id):
    """
    Full BATX matchup projection + xStats for the BvP detail panel.
    Returns projected game probs (hit1/tb2/hr/rbi1), expected values,
    Statcast quality metrics (xBA, xSLG, xwOBA, EV, barrel%, HH%),
    and pitcher resistance profile.
    Query params: game_pk (int) — enriches park factor + dome flag.
                  slot (int, 1-9) — batter's lineup slot, defaults to 5.
    """
    game_pk     = request.args.get("game_pk",  type=int)
    lineup_slot = request.args.get("slot",     type=int, default=5)

    try:
        _wait_for_fg_data(timeout_sec=3)
        _wait_for_savant_data(timeout_sec=3)

        # ── 1. Resolve player names + handedness ────────────────────────────
        batter_name  = pitcher_name = ""
        bats_code    = "S"
        pitcher_hand = "R"

        with ThreadPoolExecutor(max_workers=2) as ex:
            b_fut = ex.submit(requests.get, f"{MLB_API}/people/{batter_id}",  timeout=6)
            p_fut = ex.submit(requests.get, f"{MLB_API}/people/{pitcher_id}", timeout=6)
            br = b_fut.result(timeout=8)
            pr = p_fut.result(timeout=8)

        if br.ok:
            bp = (br.json().get("people") or [{}])[0]
            batter_name = bp.get("fullName", "")
            bats_code   = (bp.get("batSide")  or {}).get("code", "S") or "S"
        if pr.ok:
            pp = (pr.json().get("people") or [{}])[0]
            pitcher_name = pp.get("fullName", "")
            pitcher_hand = (pp.get("pitchHand") or {}).get("code", "R") or "R"

        # ── 2. Load FG + Savant stats ────────────────────────────────────────
        fg_bat = fg_batter(batter_name)  or {}
        sv_bat = sv_batter(batter_name)  or {}
        fg_pit = fg_pitcher(pitcher_name) or {}
        sv_pit = sv_pitcher(pitcher_name) or {}

        # Tier-2 fallback: direct per-player Savant CSV when bulk cache misses
        _sv_key_fields = ("sv_xba", "sv_ev", "sv_brl_pct")
        if not any(_safe_f(sv_bat.get(k), None) for k in _sv_key_fields):
            _direct = _fetch_savant_player_batter(batter_id, datetime.now().year)
            if _direct:
                sv_bat = dict(sv_bat)
                sv_bat.update({k: v for k, v in _direct.items() if v not in (None, "N/A")})

        # ── 3. Build batter object with platoon splits ───────────────────────
        splits = hitter_split_profile(batter_id)
        vl = splits.get("vl", {})
        vr = splits.get("vr", {})

        batter_obj = {
            "name":     batter_name,
            "id":       batter_id,
            "bats":     bats_code,
            "slot":     lineup_slot,
            "avg":      _safe_f(fg_bat.get("fg_avg"),  0.245),
            "obp":      _safe_f(fg_bat.get("fg_obp"),  0.315),
            "slg":      _safe_f(fg_bat.get("fg_slg"),  0.390),
            "ops":      _safe_f(fg_bat.get("fg_ops"),  0.705),
            "vs_l_avg": vl.get("avg", 0), "vs_l_ops": vl.get("ops", 0),
            "vs_l_obp": vl.get("obp", 0), "vs_l_slg": vl.get("slg", 0),
            "vs_l_pa":  vl.get("pa",  0),
            "vs_r_avg": vr.get("avg", 0), "vs_r_ops": vr.get("ops", 0),
            "vs_r_obp": vr.get("obp", 0), "vs_r_slg": vr.get("slg", 0),
            "vs_r_pa":  vr.get("pa",  0),
        }

        # ── 4. Game context: park factor + dome + live weather ────────────────
        park_factor = 1.0
        _park_home_id = None   # home team id for hand-aware park_hr (power models)
        weather     = {}
        if game_pk:
            try:
                sr = requests.get(
                    f"{MLB_API}/schedule",
                    params={"gamePk": game_pk, "hydrate": "team,venue(location)", "sportId": 1},
                    timeout=6,
                )
                if sr.ok:
                    dates = sr.json().get("dates", [])
                    if dates and dates[0].get("games"):
                        gm      = dates[0]["games"][0]
                        home_id = (((gm.get("teams") or {}).get("home") or {}).get("team") or {}).get("id")
                        if home_id:
                            park_factor = PARK_FACTORS.get(home_id, 1.0)
                            _park_home_id = home_id
                        venue   = gm.get("venue") or {}
                        venue_id = venue.get("id")
                        # Pull lat/lon and game hour for live weather lookup
                        loc      = venue.get("location") or {}
                        lat      = loc.get("latitude")
                        lon      = loc.get("longitude")
                        game_hour = 19  # default 7pm ET
                        try:
                            gd_utc = datetime.fromisoformat(gm.get("gameDate","").replace("Z","+00:00"))
                            game_hour = gd_utc.astimezone(ET).hour
                        except Exception:
                            pass
                        if venue_id and venue_id in DOME_VENUES:
                            weather = {"dome": True, "temp": 72, "wind_speed": 0, "condition": "Dome"}
                        else:
                            try:
                                weather = get_weather(lat, lon, game_hour, venue_id=venue_id) or {}
                            except Exception:
                                weather = {}
            except Exception:
                pass

        # ── 5. BvP component (already cached) ───────────────────────────────
        bvp_data = _fetch_bvp(batter_id, pitcher_id)

        # ── 5a. Pitch-mix matchup scores (Statcast SLG + FG RV/100 blended)
        try:
            sv_mix_score, _mix_rows = _compute_pitch_mix_score(str(pitcher_id), str(batter_id))
        except Exception:
            sv_mix_score, _mix_rows = 1.0, []
        try:
            fg_mix_score, fg_mix_rows = _fg_pitch_matchup_score(batter_id, pitcher_id)
        except Exception:
            fg_mix_score, fg_mix_rows = 1.0, []
        # Blend: FG RV/100 (more direct) + Statcast SLG ratio
        _fg_has = (fg_mix_score != 1.0)
        _sv_has = (sv_mix_score != 1.0)
        if _fg_has and _sv_has:
            mix_score = fg_mix_score * 0.60 + sv_mix_score * 0.40
        elif _fg_has:
            mix_score = fg_mix_score
        else:
            mix_score = sv_mix_score

        # ── 5b. Rolling form for batter (daily-cached) ──────────────────────
        batter_form = _fetch_rolling_form(batter_id, False)

        # ── 6. BATX projection (most complete model) ─────────────────────────
        batx = _project_batter_batx(
            batter_obj, pitcher_name, fg_pit, sv_pit,
            park_factor, weather, pitcher_hand,
            opp_pitcher_id=pitcher_id, bvp=bvp_data, form=batter_form,
            def_factor=_def_factor_for_pitcher(pitcher_id),
        )

        # ── 7. Calibrated game probs via _project_batter_vs_pitcher ─────────
        bstats = {
            "sv_xba":    _safe_f(sv_bat.get("sv_xba"),     0.250),
            "sv_xwoba":  _safe_f(sv_bat.get("sv_xwoba"),   0.310),
            "fg_iso":    _safe_f(fg_bat.get("fg_iso"),     0.145),
            "sv_brl_pct":_safe_f(sv_bat.get("sv_brl_pct"), 6.0),
            "fg_pa":     _safe_f(fg_bat.get("fg_pa"),      200),
            "fg_avg":    _safe_f(fg_bat.get("fg_avg"),     0.245),
            "fg_woba":   _safe_f(fg_bat.get("fg_woba"),    0.310),
        }
        pstats = {
            "fg_fip":  _safe_f(fg_pit.get("fg_xfip") or fg_pit.get("fg_era"), 4.20),
            "fg_hr9":  _safe_f(fg_pit.get("fg_hr9"),  1.10),
            "fg_kpct": _safe_f(fg_pit.get("fg_kpct"), 0.22),
        }
        _full_bstats = {
            **bstats,
            **fg_bat,        # brings fgId, fgkpct, fgbbpct, etc.
            **sv_bat,        # brings svxba, svev, svhhpct, svsspct, svbrlpct, svla
            "name":   batter_name,
            "bats":   bats_code,
            # rolling form
            "l7Hits":    batter_form.get("l7Hits")    if batter_form else None,
            "l14Hits":   batter_form.get("l14Hits")   if batter_form else None,
            "l7HitRate": batter_form.get("l7HitRate") if batter_form else None,
            "parkFactor": park_factor,
        }
        _full_pstats = {
            **pstats,
            **fg_pit,
            **sv_pit,
            "name":      pitcher_name,
            "pitchHand": pitcher_hand,
        }
        gp = _project_batter_vs_pitcher(_full_bstats, _full_pstats)

        # BATX expected → Poisson probs; blend with calibrated probs (60/40)
        hits_m = float(batx.get("hits", 0) or 0)
        tb_m   = float(batx.get("tb",   0) or 0)
        hr_m   = float(batx.get("hr",   0) or 0)
        rbi_m  = float(batx.get("rbi",  0) or 0)
        r_m    = float(batx.get("r",    0) or 0)

        def _blend_prob(cal, batx_p):
            return round(max(0.01, min(0.99, 0.60 * cal + 0.40 * batx_p)), 3)

        # XGB supplemental probs (auto-active when models loaded; None otherwise).
        # Used to surface model agreement and improve calibration once trained.
        _xgb_extras = {}
        try:
            # Heater momentum (recent EV/barrel) for the power batter models —
            # only pulled when at least one is live, since it costs a Statcast
            # lookup. Shared by the HR/TB/RBI scorers via _bdict.
            _mom = (_batter_momentum_features(batter_id)
                    if (batter_id and (xgb_ready("hr") or xgb_ready("tb") or xgb_ready("rbi")))
                    else {})
            _bform = batter_form or {}
            _bdict = {**bstats, **fg_bat, **sv_bat, "name": batter_name, "bats": bats_code,
                      "l7Hits": _bform.get("l7Hits"), "l14Hits": _bform.get("l14Hits"),
                      "l7HitRate": _bform.get("l7HitRate"),
                      # Venue context for the power models' park features
                      # (learned season-specific level when available).
                      "parkFactor": (_park_factor_for(_park_home_id)
                                     if _park_home_id else park_factor),
                      "parkHr": (_hr_park_factor_hand(_park_home_id, bats_code)
                                 if _park_home_id else 1.0),
                      **_mom}
            _pdict = {**pstats, **fg_pit, **sv_pit, "name": pitcher_name, "pitchHand": pitcher_hand}
            _maybe_opp_stuff(_pdict, pitcher_id)
            if xgb_ready("hr"):
                _xgb_extras["xgbHrProb"]  = xgb_hr_prob(_bdict, _pdict)
            if xgb_ready("tb"):
                _xgb_extras["xgbTbProb"]  = xgb_tb_prob(_bdict, _pdict)
            if xgb_ready("rbi"):
                _xgb_extras["xgbRbiProb"] = xgb_rbi_prob(_bdict, _pdict)
        except Exception:
            pass

        def _blend_with_xgb(blended, xgb_p):
            if xgb_p is None:
                return blended
            return round(max(0.01, min(0.99, 0.6 * xgb_p + 0.4 * blended)), 3)

        # 1+ hit uses binomial across expected PAs (Poisson over-states for
        # high-λ batters and under-states for low-λ ones — that mismatch was
        # the dominant source of false "HIGH UNCERTAINTY" flags between XGB
        # and BATX).
        _exp_pa_for_hit = float(batx.get("expected_pa") or 4.2)
        batx_hit1_p     = _binomial_over_zero(hits_m, _exp_pa_for_hit)

        probs = {
            "hit1": _blend_prob(gp["hitProb"], batx_hit1_p),
            "tb2":  _blend_with_xgb(_blend_prob(gp["tbProb"],  _poisson_over_prob(tb_m,   1.5)), _xgb_extras.get("xgbTbProb")),
            "hr":   _blend_with_xgb(_blend_prob(gp["hrProb"],  _poisson_over_prob(hr_m,   0.5)), _xgb_extras.get("xgbHrProb")),
            "rbi1": _blend_with_xgb(_blend_prob(gp["rbiProb"], _poisson_over_prob(rbi_m,  0.5)), _xgb_extras.get("xgbRbiProb")),
            "r1":   round(_poisson_over_prob(r_m, 0.5), 3),
            "xgbHitProb":     gp.get("xgbHitProb"),
            "xgbHitCoverage": gp.get("xgbHitCoverage"),
            "xgbHrProb":      _xgb_extras.get("xgbHrProb"),
            "xgbTbProb":      _xgb_extras.get("xgbTbProb"),
            "xgbRbiProb":     _xgb_extras.get("xgbRbiProb"),
        }

        # Apply shrink-to-prior to hit1 BEFORE verdicts, so the per-market tile
        # and the divergence bar marker stay in sync.
        _bvp_pa_n = 0
        try:
            _bvp_pa_n = int((bvp_data or {}).get("pa") or 0)
        except (TypeError, ValueError):
            _bvp_pa_n = 0
        _early_div = _model_divergence(
            probs, gp, batx, _exp_pa_for_hit,
            bvp_pa=_bvp_pa_n, park_factor=park_factor,
        )
        if _early_div.get("available") and _early_div.get("blended") is not None:
            probs["hit1"] = _early_div["blended"]

        # ── 8. xStats + Statcast quality metrics ─────────────────────────────
        sv_xba   = _safe_f(sv_bat.get("sv_xba"),    None)
        sv_xslg  = _safe_f(sv_bat.get("sv_xslg"),   None)
        sv_xwoba = _safe_f(sv_bat.get("sv_xwoba"),  None)
        sv_ev    = _safe_f(sv_bat.get("sv_ev"),      None)
        sv_brl   = _safe_f(sv_bat.get("sv_brl_pct"),None)
        sv_hh    = _safe_f(sv_bat.get("sv_hh_pct"), None)

        # Percentile ranks across all Savant batters
        with _sv_lock:
            _sc = dict(_sv_bat_statcast)
            _xs = dict(_sv_bat_xstats)

        def _pct(cache, field, val):
            if val is None:
                return None
            vals = [_safe_f(v.get(field), None) for v in cache.values()]
            vals = [x for x in vals if x is not None and x > 0]
            return _pct_rank(vals, val)

        # FanGraphs tier-3 fallback (always available from MLB API bulk cache)
        fg_woba  = _safe_f(fg_bat.get("fg_woba"),  None)
        fg_iso   = _safe_f(fg_bat.get("fg_iso"),   None)
        fg_kpct  = _safe_f(fg_bat.get("fg_kpct"),  None)
        fg_bbpct = _safe_f(fg_bat.get("fg_bbpct"), None)
        fg_ops   = _safe_f(fg_bat.get("fg_ops"),   None)

        _has_savant = sv_ev is not None or sv_xba is not None
        batter_quality = {
            # Savant metrics (may be None if unavailable even after direct fetch)
            "xba":      round(sv_xba,  3) if sv_xba  is not None else None,
            "xslg":     round(sv_xslg, 3) if sv_xslg is not None else None,
            "xwoba":    round(sv_xwoba,3) if sv_xwoba is not None else None,
            "ev":       round(sv_ev,   1) if sv_ev    is not None else None,
            "brl_pct":  round(sv_brl,  1) if sv_brl   is not None else None,
            "hh_pct":   round(sv_hh,   1) if sv_hh    is not None else None,
            "ev_pct":       _pct(_sc, "sv_ev",      sv_ev),
            "brl_pct_rank": _pct(_sc, "sv_brl_pct", sv_brl),
            "hh_pct_rank":  _pct(_sc, "sv_hh_pct",  sv_hh),
            "xba_pct":      _pct(_xs, "sv_xba",     sv_xba),
            "xwoba_pct":    _pct(_xs, "sv_xwoba",   sv_xwoba),
            # FanGraphs metrics (always present as fallback)
            "fg_woba":  round(fg_woba,  3) if fg_woba  is not None else None,
            "fg_iso":   round(fg_iso,   3) if fg_iso   is not None else None,
            "fg_kpct":  round(fg_kpct,  3) if fg_kpct  is not None else None,
            "fg_bbpct": round(fg_bbpct, 3) if fg_bbpct is not None else None,
            "fg_ops":   round(fg_ops,   3) if fg_ops   is not None else None,
            "source":   "savant" if _has_savant else "fg",
        }

        pitcher_profile = {
            "xera":      _safe_f(sv_pit.get("sv_xera"),    None),
            "xwoba_against": _safe_f(sv_pit.get("sv_xwoba_p"), None),
            "whiff_pct": _safe_f(sv_pit.get("sv_whiff"),   None),
            "k_pct":     _safe_f(sv_pit.get("sv_k_pct"),   None),
            "bb_pct":    _safe_f(sv_pit.get("sv_bb_pct"),  None),
            "era":       _safe_f(fg_pit.get("fg_era"),      None),
            "k9":        _safe_f(fg_pit.get("fg_k9"),       None),
        }

        # ── 9. vs-Starter projection: re-scale game-level expecteds to the
        #     PAs the batter actually sees vs the SP. Apply BET/LEAN/FADE
        #     verdicts so the user sees a clear directional call.
        exp_pa_total = float(batx.get("expected_pa") or 4.35)
        # Try to use the starter's recent TBF for a sharper PA-vs-SP estimate;
        # otherwise default to 22 (league-average SP workload).
        starter_tbf = 22.0
        try:
            _pit_form = _pitcher_recent_form(pitcher_id) if pitcher_id else None
            if _pit_form:
                # _pitcher_recent_form returns {total_ip, n_starts, ...}. The
                # old code read l5/l3->ip/games (keys that never exist here), so
                # _avg_ip was always None and every starter was pinned to the
                # league-average 22.0 TBF — the workload estimate was dead code.
                _total_ip = _safe_f(_pit_form.get("total_ip"), None)
                _n_starts = _safe_f(_pit_form.get("n_starts"), 0)
                # Require >= 2 recent starts; a single start is too noisy a
                # workload signal, so fall back to the league-average default.
                if _total_ip and _total_ip > 0 and _n_starts and _n_starts >= 2:
                    # IP per start × ~4.3 batters per inning ≈ TBF/start
                    starter_tbf = max(15.0, min(28.0, (_total_ip / _n_starts) * 4.3))
        except Exception:
            pass

        pa_vs_sp = _starter_pa_for_slot(lineup_slot, exp_pa_total, starter_tbf)

        # Umpire K-zone tendency: scales the pitcher K projection AND the
        # batter's K-risk in the vs-SP simulation. 1.0 = neutral.
        ump_k_mult, ump_meta = _umpire_k_multiplier(game_pk)

        # TTOP boost for the batter (averages multiplier across vs-SP PAs).
        ttop_batter = _ttop_avg_batter_mult(pa_vs_sp)
        vs_sp = _vs_sp_projections(batx, exp_pa_total, pa_vs_sp, ttop_boost=ttop_batter)

        def _verdict_block(prob_dict):
            out = {}
            for mk in ("hit1", "tb2", "hr", "rbi1"):
                key, label, cls = _verdict_for(mk, prob_dict.get(mk))
                out[mk] = {"key": key, "label": label, "cls": cls}
            return out

        def _verdict_edge_block(prob_dict, neutral):
            out = {}
            for mk in ("hit1", "tb2", "hr", "rbi1"):
                key, label, cls = _verdict_edge(prob_dict.get(mk), (neutral or {}).get(mk))
                edge = (prob_dict.get(mk) or 0) - ((neutral or {}).get(mk) or 0)
                out[mk] = {"key": key, "label": label, "cls": cls, "edge": round(edge, 3)}
            return out

        verdicts_game = _verdict_block(probs)
        verdicts_sp   = _verdict_edge_block(vs_sp, vs_sp.get("neutral"))

        # When the stacked calibrator demoted to PASS (wide CI / straddles 50%),
        # force the per-market verdict tile to PASS too — otherwise the
        # headline verdict and the per-market chip contradict each other
        # (the dual-model UX problem we're trying to eliminate).
        _v = (_early_div or {}).get("verdict") or {}
        if _v.get("tier") == "PASS" and "hit1" in verdicts_game:
            verdicts_game["hit1"] = {"key": "pass", "label": "PASS", "cls": "v-pass"}

        # ── 10. Pitcher K projection vs the opposing lineup (game-context).
        #     Lineup is fetched from the boxscore when game_pk is provided.
        pitcher_k = None
        if game_pk:
            try:
                box = requests.get(f"{MLB_API}/game/{game_pk}/boxscore", timeout=6).json().get("teams", {})
                # Determine which side this pitcher belongs to so we use the
                # OPPOSING lineup (the one he's actually facing).
                away_team_id = (((box.get("away") or {}).get("team") or {}).get("id"))
                home_team_id = (((box.get("home") or {}).get("team") or {}).get("id"))
                pit_team_id = None
                for side_key in ("away", "home"):
                    pmap = ((box.get(side_key) or {}).get("players") or {})
                    if any(int((p.get("person") or {}).get("id") or 0) == int(pitcher_id) for p in pmap.values()):
                        pit_team_id = away_team_id if side_key == "away" else home_team_id
                        break
                opposing_side = "home" if pit_team_id == away_team_id else "away"
                opposing_lineup = get_batters_from_boxscore(box.get(opposing_side, {}), opposing_side)
                pitcher_k = _pitcher_k_projection_vs_lineup(
                    pitcher_id, pitcher_name, opposing_lineup,
                    starter_tbf=starter_tbf, ump_k_mult=ump_k_mult,
                )
            except Exception as _kex:
                print(f"[bvp pitcher_k] {_kex}")
                pitcher_k = None

        # ── 11. Why-this-projection: top BATX drivers (sign + magnitude).
        drivers = _projection_drivers(batx.get("adjustments") or {})

        # ── 12. XGB-vs-BATX divergence (computed above on raw blend, before
        # shrink was applied to probs["hit1"]).
        divergence = _early_div

        # ── 13. Monte Carlo distribution over vs-SP PAs (5k sims).
        try:
            per_pa = _per_pa_rates_from_batx(batx, fg_bat, exp_pa_total, ttop_boost=ttop_batter)
            # Bake umpire K factor into the batter's K rate per PA for the sim.
            per_pa = dict(per_pa)
            per_pa["k"] = max(0.04, min(0.55, per_pa["k"] * ump_k_mult))
            mc = _monte_carlo_vs_sp(per_pa, pa_vs_sp, n_sims=4000, rng_seed=batter_id)
        except Exception as _mcex:
            print(f"[bvp monte_carlo] {_mcex}")
            mc = None

        # ── 14. Bullpen-aware slice: PAs vs the relievers after SP exits.
        try:
            vs_rp = _vs_rp_projections(batx, exp_pa_total, pa_vs_sp)
        except Exception:
            vs_rp = None

        return jsonify({
            "success":      True,
            "batterName":   batter_name,
            "pitcherName":  pitcher_name,
            "pitcherHand":  pitcher_hand,
            "parkFactor":   park_factor,
            "projectedProbs": probs,
            "expectedValues": {
                "hits": round(hits_m, 3),
                "tb":   round(tb_m,   3),
                "hr":   round(hr_m,   4),
                "rbi":  round(rbi_m,  3),
                "r":    round(r_m,    3),
            },
            "matchupContext": {
                "platoonNote": batx.get("platoon_note", ""),
                "splitOps":    round(float(batx.get("split_ops") or 0), 3),
                "splitAvg":    round(float(batx.get("split_avg") or 0), 3),
                "expPA":       batx.get("expected_pa", 4.0),
                "bvpGrade":    (bvp_data or {}).get("grade", "?"),
                "bvpPA":       (bvp_data or {}).get("pa", 0),
                "bvpFirstSeason": (bvp_data or {}).get("first_season"),
                "bvpLastSeason":  (bvp_data or {}).get("last_season"),
                "bvpSeasons":     (bvp_data or {}).get("seasons", []),
                "bvpReliability": (bvp_data or {}).get("reliability", 0.0),
                "bvpWobaEdge":    (bvp_data or {}).get("woba_edge", 0.0),
                "mixScore":       mix_score,
                "mixScoreFg":     fg_mix_score,
                "mixScoreSv":     sv_mix_score,
                "mixRowsFg":      fg_mix_rows,
                # Composite confidence (0–100): blends BvP sample reliability,
                # platoon split sample, and pitch-mix data availability.
                "confidence": _compute_bvp_confidence(
                    bvp_data, batter_obj, pitcher_hand, mix_score, _mix_rows,
                ),
            },
            "batterQuality":  batter_quality,
            "pitcherProfile": pitcher_profile,
            "adjustments":    batx.get("adjustments", {}),
            # Per-PA-vs-starter projection (NEW). Tells the user how the matchup
            # plays out specifically over the PAs vs THIS pitcher, not the full
            # game including reliever PAs.
            "vsStarter": {
                "paVsSp":   pa_vs_sp,
                "starterTBF": round(starter_tbf, 1),
                "probs":    {k: vs_sp[k] for k in ("hit1", "tb2", "hr", "rbi1")},
                "neutral":  vs_sp.get("neutral", {}),
                "expected": vs_sp["expected"],
                "verdicts": verdicts_sp,
            },
            # Verdicts on the GAME-level probs too, since prop bets clear on
            # full-game stats. Frontend can color-code accordingly.
            "verdicts": verdicts_game,
            "pitcherKProjection": pitcher_k,
            # Why this projection? Top BATX components (signed contributions).
            "drivers": drivers,
            # Cross-model agreement check (XGB vs rule). Surface uncertainty.
            "modelDivergence": divergence,
            # Monte Carlo distribution over vs-SP PAs (P25/P50/P75/P90).
            "monteCarlo": mc,
            # PAs vs the bullpen (after SP exits) — useful for spotting late-game
            # damage opportunities or fades when facing a dominant pen.
            "vsBullpen": vs_rp,
            # Game context that shifts the projection.
            "gameContext": {
                "ttopBatterMult": round(ttop_batter, 3),
                "umpireKMult":    ump_k_mult,
                "umpire":         ump_meta,
                "weather":        weather or {},
                "parkFactor":     round(float(park_factor), 3),
            },
        })

    except Exception as ex:
        print(f"[api_bvp_projection] {traceback.format_exc()}")
        # Partial fallback: return FG-based quality metrics so the card never shows "Stats loading…"
        try:
            _fb = fg_batter(batter_name) if batter_name else {}
            _fallback_quality = {
                "fg_woba":  round(_safe_f(_fb.get("fg_woba"), None), 3) if _safe_f(_fb.get("fg_woba"), None) is not None else None,
                "fg_iso":   round(_safe_f(_fb.get("fg_iso"),  None), 3) if _safe_f(_fb.get("fg_iso"),  None) is not None else None,
                "fg_kpct":  round(_safe_f(_fb.get("fg_kpct"), None), 3) if _safe_f(_fb.get("fg_kpct"), None) is not None else None,
                "fg_bbpct": round(_safe_f(_fb.get("fg_bbpct"),None), 3) if _safe_f(_fb.get("fg_bbpct"),None) is not None else None,
                "fg_ops":   round(_safe_f(_fb.get("fg_ops"),  None), 3) if _safe_f(_fb.get("fg_ops"),  None) is not None else None,
                "source": "fg",
            }
            return jsonify({"success": False, "error": str(ex), "batterQuality": _fallback_quality})
        except Exception:
            return jsonify({"success": False, "error": str(ex)}), 500


@app.route("/api/bvp/<int:batter_id>/<int:pitcher_id>/arsenal")
def api_bvp_arsenal(batter_id, pitcher_id):
    """Pitch arsenal breakdown for batter vs pitcher matchup."""
    try:
        _maybe_refresh_fg()
        _maybe_refresh_savant()

        # Resolve pitcher name + hand
        pitcher_name = ""
        pitcher_hand = "R"
        try:
            rp = requests.get(f"{MLB_API}/people/{pitcher_id}", timeout=8)
            if rp.ok:
                ppl = rp.json().get("people") or [{}]
                pitcher_name = (ppl[0].get("fullName") or "").strip()
                pitcher_hand = ((ppl[0].get("pitchHand") or {}).get("code") or "R").upper()
        except Exception:
            pass

        pit_pid_str = str(pitcher_id)
        bat_pid_str = str(batter_id)

        # Pitch-mix matchup score + per-pitch table
        mix_score, table_rows = _compute_pitch_mix_score(pit_pid_str, bat_pid_str)

        # Pitcher's raw arsenal pct + velo from Savant
        svp = sv_pitcher(pitcher_name) if pitcher_name else {}
        raw_pct  = (svp.get("sv_arsenal_pct")  or {}) if isinstance(svp, dict) else {}
        raw_velo = (svp.get("sv_arsenal_velo") or {}) if isinstance(svp, dict) else {}

        # Build enriched pitch list (merge table_rows with pct/velo)
        pitches = []
        for row in table_rows:
            code = (row.get("pitch") or "").lower()
            label = PITCH_LABELS.get(code, code.upper())
            pct  = raw_pct.get(code)
            velo = raw_velo.get(code)
            # _sv_arsenal_pct already stores % values (e.g. 35.0 = 35%); fall back to pitch_usage from table_rows
            usage_pct = round(float(pct), 1) if pct is not None else row.get("usage")
            pitches.append({
                "code":       code,
                "label":      label,
                "usage":      usage_pct,
                "velo":       round(float(velo), 1) if velo is not None else None,
                "pit_ba":     row.get("pit_ba"),
                "pit_slg":    row.get("pit_slg"),
                "pit_woba":   row.get("pit_woba"),
                "pit_whiff":  row.get("pit_whiff"),
                "bat_slg":    row.get("bat_slg"),
                "bat_woba":   row.get("bat_woba"),
                "bat_whiff":  row.get("bat_whiff"),
                "bat_hh":     row.get("bat_hh"),
                "ratio":      row.get("ratio"),
            })

        # If no pit_arsenal data, fall back to pct-only list (no batter breakdown)
        if not pitches and raw_pct:
            for code, pct_val in sorted(raw_pct.items(), key=lambda kv: kv[1], reverse=True):
                label = PITCH_LABELS.get(code, code.upper())
                velo  = raw_velo.get(code)
                pitches.append({
                    "code":    code,
                    "label":   label,
                    "usage":   round(float(pct_val), 1) if pct_val is not None else None,
                    "velo":    round(float(velo), 1) if velo is not None else None,
                })

        primary_pitch = pitches[0]["label"] if pitches else None

        return jsonify({
            "success":      True,
            "pitcherName":  pitcher_name,
            "pitcherHand":  pitcher_hand,
            "mixScore":     mix_score,
            "primaryPitch": primary_pitch,
            "pitches":      pitches,
        })

    except Exception as ex:
        import traceback as _tb
        print(f"[api_bvp_arsenal] {_tb.format_exc()}")
        return jsonify({"success": False, "error": str(ex)}), 500


@app.route("/api/player/<int:player_id>/bvp/<int:pitcher_id>")
def api_player_bvp_games(player_id, pitcher_id):
    """Opponent-specific game logs: summary + latest matchup games."""
    try:
        bvp = _fetch_bvp(player_id, pitcher_id)
        if not bvp or not bvp.get("success"):
            return jsonify({"success": False, "error": "No BvP data available"}), 404

        year = datetime.now().year
        games = []
        score_cache = {}

        def _game_info(game_pk, batter_team_id=None):
            """Return (score_txt, win_loss, opp_pitcher_name, opp_team_abbr) from boxscore."""
            if not game_pk:
                return "—", "", "—", ""
            if game_pk in score_cache:
                return score_cache[game_pk]
            score_txt = "—"
            win_loss = ""
            opp_pitcher = "—"
            opp_team = ""
            try:
                br = requests.get(f"{MLB_API}/game/{game_pk}/boxscore", timeout=8)
                if br.ok:
                    bj = br.json()
                    t = bj.get("teams", {})
                    away = t.get("away", {})
                    home = t.get("home", {})
                    away_runs = int((((away.get("teamStats") or {}).get("batting") or {}).get("runs") or 0))
                    home_runs = int((((home.get("teamStats") or {}).get("batting") or {}).get("runs") or 0))
                    away_id = ((away.get("team") or {}).get("id"))
                    home_id = ((home.get("team") or {}).get("id"))
                    # Determine which side the batter is on to set score perspective + opp side
                    if batter_team_id and batter_team_id == away_id:
                        score_txt = f"{away_runs}-{home_runs}"
                        win_loss = "W" if away_runs > home_runs else ("L" if away_runs < home_runs else "T")
                        opp_side = home
                    elif batter_team_id and batter_team_id == home_id:
                        score_txt = f"{home_runs}-{away_runs}"
                        win_loss = "W" if home_runs > away_runs else ("L" if home_runs < away_runs else "T")
                        opp_side = away
                    else:
                        score_txt = f"{away_runs}-{home_runs}"
                        opp_side = home
                    # Extract opposing team abbreviation
                    opp_team = ((opp_side.get("team") or {}).get("abbreviation") or
                                (opp_side.get("team") or {}).get("teamName") or "")
                    # Extract opposing starting pitcher (first in pitchers list)
                    opp_pitchers = opp_side.get("pitchers", [])
                    opp_players = opp_side.get("players", {})
                    if opp_pitchers:
                        starter_key = f"ID{opp_pitchers[0]}"
                        starter = opp_players.get(starter_key, {})
                        opp_pitcher = ((starter.get("person") or {}).get("fullName") or
                                       (starter.get("person") or {}).get("lastName") or "—")
            except Exception:
                pass
            score_cache[game_pk] = (score_txt, win_loss, opp_pitcher, opp_team)
            return score_cache[game_pk]

        # Resolve today's pitcher name for summary line
        pitcher_name = "Pitcher"
        try:
            pr = requests.get(f"{MLB_API}/people/{pitcher_id}", timeout=6)
            if pr.ok:
                pitcher_name = ((pr.json().get("people") or [{}])[0].get("fullName") or "Pitcher")
        except Exception:
            pass

        # Fetch recent game log (no opposingPlayerId filter — that param unreliable)
        # and extract the actual pitcher faced from each game's boxscore.
        try:
            gr = requests.get(
                f"{MLB_API}/people/{player_id}/stats",
                params={"stats": "gameLog", "group": "hitting", "season": year, "sportId": 1},
                timeout=10,
            )
            if gr.ok:
                all_splits = (gr.json().get("stats") or [{}])[0].get("splits", [])
                for sp in reversed(all_splits):
                    if len(games) >= 5:
                        break
                    st = sp.get("stat", {})
                    gm = sp.get("game") or {}
                    game_pk = gm.get("gamePk")
                    team_id = ((sp.get("team") or {}).get("id"))
                    score_txt, win_loss, opp_pitcher, opp_team = _game_info(game_pk, batter_team_id=team_id)
                    games.append({
                        "date": (sp.get("date") or "")[:10],
                        "score": score_txt,
                        "pitcher": opp_pitcher,
                        "team": opp_team,
                        "ab": int(st.get("atBats", 0) or 0),
                        "hits": int(st.get("hits", 0) or 0),
                        "hr": int(st.get("homeRuns", 0) or 0),
                        "rbi": int(st.get("rbi", 0) or 0),
                        "k": int(st.get("strikeOuts", 0) or 0),
                        "bb": int(st.get("baseOnBalls", 0) or 0),
                        "result": win_loss,
                    })
        except Exception:
            pass

        # Ensure latest first.
        games = sorted(games, key=lambda x: x.get("date", ""), reverse=True)[:5]

        # ── Enrich with Statcast per-PA metrics (EV / launch_angle / dist / trajectory).
        # The MLB Stats API gameLog has no Statcast detail; pull from Savant via pybaseball.
        try:
            sc_rows = _recent_statcast_for_batter(player_id, pitcher_id=None, n=40, seasons=1)
            by_date = {}
            for r in (sc_rows or []):
                d = r.get("date")
                if not d:
                    continue
                # Keep the hardest-hit batted ball per date (often only 1 batted ball anyway).
                cur = by_date.get(d)
                cur_ev = (cur or {}).get("exit_velocity") or -1
                new_ev = r.get("exit_velocity") or -1
                if cur is None or new_ev > cur_ev:
                    by_date[d] = r
            for g in games:
                sc = by_date.get(g.get("date"))
                if sc:
                    g["exit_velocity"] = sc.get("exit_velocity")
                    g["launch_angle"]  = sc.get("launch_angle")
                    g["hit_distance"]  = sc.get("hit_distance")
                    g["trajectory"]    = sc.get("trajectory")
        except Exception as ex:
            logging.warning(f"[api_player_bvp_games] statcast enrich failed bid={player_id}: {ex}")

        ab = bvp.get("ab", 0) or 0
        avg = bvp.get("avg")
        hr = bvp.get("hr", 0) or 0
        ops = bvp.get("ops")
        summary_line = f"vs. {pitcher_name}: {ab} AB | {avg if avg is not None else '---'} AVG | {hr} HR | {ops if ops is not None else '---'} OPS"

        return jsonify({
            "success": True,
            "playerId": player_id,
            "pitcherId": pitcher_id,
            "pitcherName": pitcher_name,
            "grade": bvp.get("grade", "D"),
            "ops": bvp.get("ops"),
            "avg": bvp.get("avg"),
            "hr": bvp.get("hr", 0),
            "pa": bvp.get("pa", 0),
            "sample_note": bvp.get("sample_note") or bvp.get("note") or "",
            "summary": summary_line,
            "games": games,
        })
    except Exception as ex:
        print(f"[api_player_bvp_games] {traceback.format_exc()}")
        return jsonify({"success": False, "error": str(ex)}), 500


@app.route("/api/player/form/<int:player_id>")
def api_player_form(player_id):
    """
    Rolling form for a single player — daily cached.
    Query params:
      is_pitcher=1  (default 0)
    Returns same shape as the 'form' key in /api/player/<id>?includeForm=1.
    """
    is_pitcher = request.args.get("is_pitcher") == "1"
    result = _fetch_rolling_form(player_id, is_pitcher)
    if result is None:
        return jsonify({"success": False, "error": "Form data unavailable"}), 404
    return jsonify({"success": True, **result})



@app.route("/api/player-splits/<int:player_id>/<string:group>")
def api_player_splits(player_id, group):
    try:
        year = datetime.now().year
        # Platoon splits (vl = vs lefty, vr = vs righty)
        pr = requests.get(
            f"{MLB_API}/people/{player_id}/stats",
            params={"stats":"statSplits","group":group,"season":year,"sitCodes":"vl,vr"},
            timeout=8
        )
        pr.raise_for_status()
        platoon = {}
        for sp in pr.json().get("stats",[{}])[0].get("splits",[]):
            code = sp.get("split",{}).get("code","")
            s = sp.get("stat",{})
            if code in ("vl","vr"):
                platoon[code] = {
                    "avg":  s.get("avg","---"), "obp": s.get("obp","---"),
                    "slg":  s.get("slg","---"), "ops": s.get("ops","---"),
                    "pa":   s.get("plateAppearances",0),
                    "hr":   s.get("homeRuns",0),
                    "woba": s.get("woba","---"),
                }
        # Game log (recent form)
        lr = requests.get(
            f"{MLB_API}/people/{player_id}/stats",
            params={"stats":"gameLog","group":group,"season":year},
            timeout=8
        )
        lr.raise_for_status()
        all_games = lr.json().get("stats",[{}])[0].get("splits",[])
        last7 = all_games[-7:] if len(all_games) >= 7 else all_games
        recent = []
        if group == "hitting":
            for sp in last7:
                s = sp.get("stat",{})
                recent.append({
                    "date": sp.get("date",""), "opp": sp.get("opponent",{}).get("abbreviation",""),
                    "ab": s.get("atBats",0), "h": s.get("hits",0),
                    "hr": s.get("homeRuns",0), "rbi": s.get("rbi",0),
                    "k":  s.get("strikeOuts",0), "bb": s.get("baseOnBalls",0),
                    "avg": s.get("avg","---"),
                })
            l7_ab  = sum(g["ab"] for g in recent)
            l7_h   = sum(g["h"]  for g in recent)
            l7_hr  = sum(g["hr"] for g in recent)
            l7_rbi = sum(g["rbi"] for g in recent)
            l7_k   = sum(g["k"]  for g in recent)
            l7_avg = round(l7_h/l7_ab,3) if l7_ab > 0 else 0
            is_hot  = l7_avg >= 0.310 or l7_hr >= 2
            is_cold = l7_avg < 0.150 and l7_ab >= 12
            return jsonify({
                "success":True, "group":"hitting",
                "platoon": platoon, "recentGames": recent,
                "l7_avg": l7_avg, "l7_hr": l7_hr, "l7_rbi": l7_rbi, "l7_k": l7_k,
                "isHot": is_hot, "isCold": is_cold,
            })
        else:
            for sp in last7:
                s = sp.get("stat",{})
                recent.append({
                    "date": sp.get("date",""), "opp": sp.get("opponent",{}).get("abbreviation",""),
                    "ip": s.get("inningsPitched","0"), "er": s.get("earnedRuns",0),
                    "k": s.get("strikeOuts",0), "bb": s.get("baseOnBalls",0),
                    "h": s.get("hits",0),
                })
            l7_er = sum(g["er"] for g in recent)
            l7_k  = sum(g["k"]  for g in recent)
            is_hot  = l7_er <= 4 and len(recent) >= 2
            is_cold = l7_er >= 9 and len(recent) >= 2
            return jsonify({
                "success":True, "group":"pitching",
                "platoon": platoon, "recentGames": recent,
                "l7_er": l7_er, "l7_k": l7_k,
                "isHot": is_hot, "isCold": is_cold,
            })
    except Exception as ex:
        print("[api_player_splits]", traceback.format_exc())
        return jsonify({"success":False,"error":str(ex),"platoon":{},"recentGames":[]}), 500


@app.route("/api/player/<int:player_id>/spray")
def api_player_spray(player_id):
    """Spray chart: current season batted ball positions for a batter."""
    try:
        today = datetime.now().strftime("%Y-%m-%d")
        refresh = str(request.args.get('refresh') or '').strip().lower() in ('1', 'true', 'yes')

        # Check cache first (daily TTL)
        cached = _spray_cache.get(player_id)
        if (not refresh) and cached and cached.get("date") == today:
            return jsonify({"success": True, "data": cached.get("data", [])})

        # Fetch player identity and type
        pr = requests.get(f"{MLB_API}/people/{player_id}", timeout=10)
        pr.raise_for_status()
        people = pr.json().get("people", [])
        if not people:
            return jsonify({"success": False, "error": "Player not found"}), 404

        is_pitcher = (people[0].get("primaryPosition", {}).get("abbreviation", "") or "?") in ("P", "SP", "RP", "CP")
        if is_pitcher:
            _spray_cache[player_id] = {"date": today, "data": []}
            return jsonify({"success": True, "data": []})
        
        # Fetch spray chart data from pybaseball
        import pybaseball as pb
        start_dt = f"{datetime.now().year}-03-01"
        end_dt = today
        sc = pb.statcast_batter(start_dt=start_dt, end_dt=end_dt, player_id=int(player_id))
        
        if sc is None or sc.empty:
            _spray_cache[player_id] = {"date": today, "data": []}
            return jsonify({"success": True, "data": []})

        def _to_float(v):
            try:
                if v is None:
                    return None
                if pd.isna(v):
                    return None
                value = float(v)
                if pd.isna(value):
                    return None
                return value
            except Exception:
                return None

        def _to_text(v):
            if v is None:
                return ""
            try:
                if pd.isna(v):
                    return ""
            except Exception:
                pass
            return str(v).strip()

        # Extract batted ball data with key fields
        spray_data = []
        for _, row in sc.iterrows():
            # Skip if no hit coordinates
            hc_x = _to_float(row.get("hc_x"))
            hc_y = _to_float(row.get("hc_y"))
            if hc_x is None or hc_y is None:
                continue

            events = _to_text(row.get("events")).lower()
            result = _to_text(row.get("events")) or _to_text(row.get("des"))
            if events in ("single", "double", "triple"):
                outcome_cat = 'hit'
            elif events == "home_run":
                outcome_cat = 'hr'
            else:
                outcome_cat = 'out'

            ev = _to_float(row.get("launch_speed"))
            la = _to_float(row.get("launch_angle"))
            hit_distance = _to_float(row.get("hit_distance_sc"))

            spray_data.append({
                'hc_x': round(hc_x, 2),
                'hc_y': round(hc_y, 2),
                'events': events or None,
                'hit_distance': hit_distance,
                'launch_angle': la,
                'exit_velocity': ev,
                'pitch_type': row.get('pitch_type', 'UNK') or 'UNK',
                'result': result,
                'outcome': outcome_cat,
                'date': str(row.get('game_date', '')),
                'home_team': row.get('home_team', ''),
                'away_team': row.get('away_team', ''),
                'is_home_game': row.get('inning_topbot') == 'Bot',
                'pitcher_hand': row.get('p_throws', '?') or '?',
            })

        # Cache the result
        _spray_cache[player_id] = {"date": today, "data": spray_data}
        return jsonify({"success": True, "data": spray_data})

    except Exception as ex:
        print(f"[api_player_spray] {player_id}: {traceback.format_exc()}")
        return jsonify({"success": False, "error": str(ex), "data": []}), 500


@app.route("/api/player/<int:player_id>/zonechart")
def api_player_zonechart(player_id):
    """Strike zone chart: 3×3 zone metrics for pitcher or batter."""
    try:
        refresh = str(request.args.get('refresh') or '').strip().lower() in ('1', 'true', 'yes')
        zone_data = _compute_zonechart_data(player_id, force_refresh=refresh)
        return jsonify({"success": True, "data": zone_data})
    
    except ValueError as ex:
        return jsonify({"success": False, "error": str(ex), "data": [None]*9}), 404
    except Exception as ex:
        print(f"[api_player_zonechart] {player_id}: {traceback.format_exc()}")
        return jsonify({"success": False, "error": str(ex), "data": [None]*9}), 500


def _compute_zone_metrics_pitcher(sc, zone_id, is_pitcher=True):
    """Compute metrics for a single zone from statcast data."""
    if sc is None or sc.empty:
        return {
            "zone_id": zone_id,
            "pitch_pct": 0,
            "swing_rate": 0,
            "whiff_rate": 0,
            "ba": 0,
            "slg": 0,
        }
    
    # Map zone_id to plate coordinates (MLB standard: 17" wide × 30" tall strike zone)
    # Zones: top(z > .76), middle(.41 < z < .76), bottom(z < .41)
    # Left(x < -8.5), center(-8.5 < x < 8.5), right(x > 8.5)
    zone_bounds = {
        0: {"x": (-17, -8.5), "z": (0.76, 3.5)},    # Top-left
        1: {"x": (-8.5, 8.5), "z": (0.76, 3.5)},    # Top-center
        2: {"x": (8.5, 17), "z": (0.76, 3.5)},      # Top-right
        3: {"x": (-17, -8.5), "z": (0.41, 0.76)},   # Mid-left
        4: {"x": (-8.5, 8.5), "z": (0.41, 0.76)},   # Heart
        5: {"x": (8.5, 17), "z": (0.41, 0.76)},     # Mid-right
        6: {"x": (-17, -8.5), "z": (-0.5, 0.41)},   # Bot-left
        7: {"x": (-8.5, 8.5), "z": (-0.5, 0.41)},   # Bot-center
        8: {"x": (8.5, 17), "z": (-0.5, 0.41)},     # Bot-right
    }
    
    bounds = zone_bounds.get(zone_id, {})
    x_range = bounds.get("x", (-17, 17))
    z_range = bounds.get("z", (-0.5, 3.5))
    
    # Filter pitches in this zone
    zone_pitches = sc[
        (sc['plate_x'] >= x_range[0]) & (sc['plate_x'] <= x_range[1]) &
        (sc['plate_z'] >= z_range[0]) & (sc['plate_z'] <= z_range[1])
    ]
    
    if len(zone_pitches) == 0:
        return {
            "zone_id": zone_id,
            "pitch_pct": 0,
            "swing_rate": 0,
            "whiff_rate": 0,
            "ba": 0,
            "slg": 0,
        }
    
    total_pitches = len(sc)
    zone_pitch_count = len(zone_pitches)
    pitch_pct = round(zone_pitch_count / total_pitches * 100, 1) if total_pitches > 0 else 0
    
    # Swing rate: % of pitches with a swing
    swings = len(zone_pitches[zone_pitches['description'].str.contains('swinging', case=False, na=False)])
    swing_rate = round(swings / zone_pitch_count * 100, 1) if zone_pitch_count > 0 else 0
    
    # Whiff rate: % of swings that missed
    whiffs = len(zone_pitches[zone_pitches['description'].str.contains('swinging strike', case=False, na=False)])
    whiff_rate = round(whiffs / swings * 100, 1) if swings > 0 else 0
    
    # BA & SLG: only for batted balls
    events = zone_pitches['events'].fillna('') if 'events' in zone_pitches else pd.Series(dtype=object)
    hit_results = ['single', 'double', 'triple', 'home_run']
    normalized_events = events.astype(str).str.strip().str.lower()
    hits = len(zone_pitches[normalized_events.isin(hit_results)])
    home_runs = len(zone_pitches[normalized_events == 'home_run'])
    doubles = len(zone_pitches[normalized_events == 'double'])
    triples = len(zone_pitches[normalized_events == 'triple'])
    singles = hits - home_runs - doubles - triples
    
    batted_balls = len(zone_pitches[zone_pitches['type'] == 'X'])
    ba = round(hits / batted_balls, 3) if batted_balls > 0 else 0
    total_bases = singles + (doubles * 2) + (triples * 3) + (home_runs * 4)
    slg = round(total_bases / batted_balls, 3) if batted_balls > 0 else 0
    
    return {
        "zone_id": zone_id,
        "pitch_pct": pitch_pct,
        "swing_rate": swing_rate,
        "whiff_rate": whiff_rate,
        "ba": ba,
        "slg": slg,
    }


# ── Phase 6 Monte Carlo Simulation ────────────────────────────────────────────
import random, statistics, math

BULLPEN_BASE = {"era":4.05, "whip":1.28, "k9":8.6, "bb9":3.2, "hr9":1.10}
_bio_cache = {}
_hit_split_cache = {}
_team_pitch_cache = {}

# ── Rolling Form Cache (daily per player) ─────────────────────────────────────
_form_cache: dict = {}          # {player_id: (date, form_dict)}
_form_lock  = threading.Lock()

# ── BvP (Batter-vs-Pitcher) Cache ────────────────────────────────────────────
_bvp_cache: dict = {}           # {(batter_id, pitcher_id): (date, bvp_dict)}
_bvp_lock  = threading.Lock()

# ── Pitch-Type Advantage Cache (daily) ───────────────────────────────────────
_pitch_adv_cache: dict = {}            # {(batter_id, pitcher_id): (date, adv_dict)}
_batter_pitch_perf_cache: dict = {}    # {batter_id: (date, perf_dict)}
_pitch_adv_lock = threading.Lock()
_PITCH_ADV_USE_PYBASEBALL = os.getenv("PITCH_ADV_USE_PYBASEBALL", "0") == "1"

# League averages used for Bayesian shrinkage
_LEAGUE_WOBA  = 0.320
_LEAGUE_BABIP = 0.295
_LEAGUE_KPCT  = 0.225
_LEAGUE_BBPCT = 0.082
# wOBA weights (2024 calibrated)
_WOBA_WEIGHTS = {"bb": 0.696, "hbp": 0.726, "single": 0.888,
                 "double": 1.258, "triple": 1.599, "hr": 2.054}
# Shrinkage priors (PA equivalent)
_SHRINK_PA_FORM = 100   # form windows: shrink hard early-season samples
_SHRINK_PA_BVP  = 200   # BvP: even harder, tiny samples


def _woba_from_counts(bb, hbp, singles, doubles, triples, hr, pa):
    """Compute wOBA from raw counting stats."""
    if pa <= 0:
        return None
    w = _WOBA_WEIGHTS
    num = w["bb"]*bb + w["hbp"]*hbp + w["single"]*singles + w["double"]*doubles + w["triple"]*triples + w["hr"]*hr
    return round(num / pa, 3)


def _shrink(observed, n_obs, league_mean, prior_n):
    """Bayesian shrink: blend observed rate with league mean weighted by sample size."""
    if n_obs <= 0:
        return league_mean
    return round((observed * n_obs + league_mean * prior_n) / (n_obs + prior_n), 4)


def parse_ip(ipval):
    """Parse '6.1' style IP where .1 = 1/3 inning, .2 = 2/3 inning."""
    try:
        f = float(ipval or 0)
        whole = int(f)
        outs = round((f - whole) * 10)  # .1→1 out, .2→2 outs
        return whole + outs / 3.0
    except Exception:
        return 0.0


_GAMELOG_SPLITS_CACHE = {}     # (player_id, group, season) -> (date, splits)
_GAMELOG_SPLITS_LOCK = threading.Lock()


def _gamelog_splits_cached(player_id, group, season=None):
    """Raw season game-log `splits` for a player, daily-cached and SHARED across
    every game-log consumer (recent-form, rolling-form, batter/pitcher trends).

    Before this, each consumer issued its own uncached MLB Stats API call, so a
    single game card fetched the same batter's log 2–3× — and a full slate hit
    the endpoint hundreds of times on every cold open. Caching the raw splits
    once per (player, group, season) per day collapses that to one call."""
    if season is None:
        season = datetime.now().year
    today = datetime.now().date()
    try:
        ck = (int(player_id), group, int(season))
    except (TypeError, ValueError):
        return []
    with _GAMELOG_SPLITS_LOCK:
        c = _GAMELOG_SPLITS_CACHE.get(ck)
        if c and c[0] == today:
            return c[1]
    try:
        r = requests.get(
            f"{MLB_API}/people/{player_id}/stats",
            params={"stats": "gameLog", "season": season, "group": group, "gameType": "R"},
            timeout=8,
        )
        if not r.ok:
            return []
        splits = (r.json().get("stats") or [{}])[0].get("splits", []) or []
    except Exception:
        return []
    with _GAMELOG_SPLITS_LOCK:
        _GAMELOG_SPLITS_CACHE[ck] = (today, splits)
    return splits


def _fetch_game_log_raw(player_id, group, n=30):
    """Fetch the last *n* game log entries from MLB Stats API. Returns list of stat dicts."""
    splits = _gamelog_splits_cached(player_id, group)
    return splits[-n:] if n else splits


def _fetch_rolling_form(player_id, is_pitcher):
    """
    Compute L7/L14/L30 rolling form for a player. Daily-cached per player_id.
    For hitters: returns wOBA (shrunk), xwOBA (from Savant cache), K%, BB%,
                 AVG, OBP, SLG, ISO, flag, trend.
    For pitchers: same as existing _compute_form, harmonised.
    """
    today = datetime.now().date()
    with _form_lock:
        cached = _form_cache.get(player_id)
        if cached and cached[0] == today:
            return cached[1]

    try:
        if not is_pitcher:
            splits = _fetch_game_log_raw(player_id, "hitting", 30)
            # Build raw per-game rows newest-first
            rows = []
            for sp in reversed(splits):
                s = sp.get("stat", {})
                ab  = int(s.get("atBats", 0) or 0)
                h   = int(s.get("hits", 0) or 0)
                bb  = int(s.get("baseOnBalls", 0) or 0)
                hbp = int(s.get("hitByPitch", 0) or 0)
                hr  = int(s.get("homeRuns", 0) or 0)
                dbl = int(s.get("doubles", 0) or 0)
                tpl = int(s.get("triples", 0) or 0)
                tb  = int(s.get("totalBases", 0) or 0)
                sf  = int(s.get("sacFlies", 0) or 0)
                so  = int(s.get("strikeOuts", 0) or 0)
                singles = max(0, h - dbl - tpl - hr)
                pa  = ab + bb + hbp + sf
                rows.append({"ab": ab, "h": h, "bb": bb, "hbp": hbp, "hr": hr,
                              "dbl": dbl, "tpl": tpl, "tb": tb, "sf": sf,
                              "so": so, "singles": singles, "pa": pa})

            # Pull Savant xwOBA for season-level anchor
            player_name = ""
            try:
                pr = requests.get(f"{MLB_API}/people/{player_id}", timeout=6)
                player_name = (pr.json().get("people") or [{}])[0].get("fullName", "")
            except Exception:
                pass
            sv = sv_batter(player_name) if player_name else {}
            sv_xwoba = _num(sv.get("sv_xwoba"), 0)

            def _window(n):
                g = rows[:n]
                if not g:
                    return None
                ab  = sum(x["ab"]  for x in g)
                h   = sum(x["h"]   for x in g)
                bb  = sum(x["bb"]  for x in g)
                hbp = sum(x["hbp"] for x in g)
                hr  = sum(x["hr"]  for x in g)
                dbl = sum(x["dbl"] for x in g)
                tpl = sum(x["tpl"] for x in g)
                tb  = sum(x["tb"]  for x in g)
                sf  = sum(x["sf"]  for x in g)
                so  = sum(x["so"]  for x in g)
                singles = sum(x["singles"] for x in g)
                pa  = sum(x["pa"]  for x in g)
                avg  = round(h / ab, 3) if ab else None
                obp  = round((h + bb + hbp) / pa, 3) if pa else None
                slg  = round(tb / ab, 3) if ab else None
                ops  = round((obp or 0) + (slg or 0), 3) if (obp and slg) else None
                iso  = round(max(0, (slg or 0) - (avg or 0)), 3) if slg and avg else None
                raw_woba = _woba_from_counts(bb, hbp, singles, dbl, tpl, hr, pa)
                # Shrink wOBA towards league mean
                shrunk_woba = _shrink(raw_woba or _LEAGUE_WOBA, pa,
                                      _LEAGUE_WOBA, _SHRINK_PA_FORM)
                kpct  = round(so / pa, 4) if pa else None
                bbpct = round(bb / pa, 4) if pa else None
                # xwOBA: blend seasonal Savant number (best proxy we have per-game)
                xwoba = sv_xwoba if sv_xwoba else shrunk_woba

                def fmt3(v):
                    if v is None: return "---"
                    s = int(round(v * 1000))
                    return f".{s:03d}"

                return {
                    "games": len(g), "pa": pa, "ab": ab, "hr": hr,
                    "avg":   fmt3(avg),
                    "obp":   fmt3(obp),
                    "slg":   fmt3(slg),
                    "ops":   fmt3(ops),
                    "iso":   fmt3(iso),
                    "woba":  fmt3(shrunk_woba),
                    "xwoba": fmt3(xwoba),
                    "kpct":  round(kpct, 4) if kpct is not None else None,
                    "bbpct": round(bbpct, 4) if bbpct is not None else None,
                    "raw_woba": round(raw_woba, 3) if raw_woba else None,
                }

            l7  = _window(7)
            l14 = _window(14)
            l30 = _window(30)

            # Flag / trend from L7 wOBA (more stable than AVG)
            flag = "neutral"; flag_note = ""; trend = "stable"
            if l7 and l7["raw_woba"] is not None:
                w7 = l7["raw_woba"]
                if l7["pa"] >= 20:
                    if w7 >= 0.380:   flag = "hot";     flag_note = f"Elite wOBA {l7['woba']} over last 7 games"
                    elif w7 >= 0.340: flag = "warm";    flag_note = f"Solid wOBA {l7['woba']} over last 7 games"
                    elif w7 < 0.270:  flag = "cold";    flag_note = f"Struggling — wOBA {l7['woba']} over last 7 games"
                    elif w7 < 0.310:  flag = "chilly";  flag_note = f"Below avg wOBA {l7['woba']} over last 7 games"
                if l14 and l14["raw_woba"] is not None and l14["pa"] >= 30:
                    w14 = l14["raw_woba"]
                    if w7 > w14 + 0.035:   trend = "improving"
                    elif w7 < w14 - 0.035: trend = "declining"

            result = {"kind": "hitter", "flag": flag, "flag_note": flag_note, "trend": trend,
                      "l7": l7, "l14": l14, "l30": l30}
        else:
            # Pitcher: same logic as before but harmonised
            splits = _fetch_game_log_raw(player_id, "pitching", 10)
            rows = []
            for sp in reversed(splits):
                s = sp.get("stat", {})
                rows.append({
                    "ip":  _parse_ip(s.get("inningsPitched", 0)),
                    "er":  int(s.get("earnedRuns", 0) or 0),
                    "k":   int(s.get("strikeOuts", 0) or 0),
                    "bb":  int(s.get("baseOnBalls", 0) or 0),
                    "h":   int(s.get("hits", 0) or 0),
                    "hr":  int(s.get("homeRuns", 0) or 0),
                    "bf":  int(s.get("battersFaced", 0) or 0),
                })

            def _pit_window(n):
                g = rows[:n]
                if not g: return None
                ip = sum(x["ip"] for x in g)
                er = sum(x["er"] for x in g)
                k  = sum(x["k"]  for x in g)
                bb = sum(x["bb"] for x in g)
                h  = sum(x["h"]  for x in g)
                hr = sum(x["hr"] for x in g)
                bf = sum(x["bf"] for x in g)
                qs = sum(1 for x in g if x["ip"] >= 6 and x["er"] <= 3)
                era  = round(er  / ip * 9, 2) if ip else None
                k9   = round(k   / ip * 9, 2) if ip else None
                bb9  = round(bb  / ip * 9, 2) if ip else None
                whip = round((h + bb) / ip, 3) if ip else None
                kpct  = round(k  / bf, 4) if bf else None
                bbpct = round(bb / bf, 4) if bf else None
                return {
                    "games": len(g), "ip": round(ip, 1), "qs": qs,
                    "era": era, "k9": k9, "bb9": bb9, "whip": whip,
                    "kpct": kpct, "bbpct": bbpct,
                }

            l3  = _pit_window(3)
            l5  = _pit_window(5)
            l10 = _pit_window(10)
            flag = "neutral"; flag_note = ""; trend = "stable"
            if l3 and l3["era"] is not None:
                era3 = l3["era"]
                if era3 < 2.0:   flag = "dealing";    flag_note = f"{era3:.2f} ERA over last 3 starts"
                elif era3 < 3.5: flag = "hot";        flag_note = f"{era3:.2f} ERA over last 3 starts"
                elif era3 < 4.5: flag = "neutral";    flag_note = f"{era3:.2f} ERA over last 3 starts"
                elif era3 < 6.0: flag = "chilly";     flag_note = f"{era3:.2f} ERA over last 3 starts"
                else:            flag = "struggling"; flag_note = f"{era3:.2f} ERA over last 3 starts"
                if l5 and l5["era"] is not None:
                    if era3 < l5["era"] - 0.75:   trend = "improving"
                    elif era3 > l5["era"] + 0.75: trend = "declining"
            result = {"kind": "pitcher", "flag": flag, "flag_note": flag_note, "trend": trend,
                      "l3": l3, "l5": l5, "l10": l10}

    except Exception as ex:
        print(f"[form] player {player_id}:", ex)
        result = None

    with _form_lock:
        _form_cache[player_id] = (today, result)
    return result


_hit_form_cache = {}
_hit_form_lock = threading.Lock()


def _batter_recent_hit_form(batter_id):
    """Flat L7/L14 hit-form features in the EXACT scale the hits XGB model
    trained on (regenerate_models.build_batter_matrix):

      l7Hits / l14Hits — mean hits PER GAME over the last 7 / 14 completed games
      l7HitRate        — mean of per-game (hits / max(AB,1)) over the last 7

    The model's _build_hit_features reads these flat keys, but the only producer
    of rolling form (_fetch_rolling_form) returns *nested* l7/l14 dicts, so every
    call site was silently feeding the empty-input defaults — the train/serve gap
    that flattened the hits model to `no_edge` in production. Sourced from the
    same MLB game-log feed used for training; daily-cached per batter. Returns {}
    when no game log exists so the builder keeps its neutral default (no
    fabricated signal)."""
    if not batter_id:
        return {}
    today = datetime.now().date()
    with _hit_form_lock:
        c = _hit_form_cache.get(batter_id)
        if c and c[0] == today:
            return c[1]
    out = {}
    try:
        # newest-last; 14 games covers both windows. No shift at serve — the most
        # recent completed games ARE the prior-game window training shifted to.
        splits = _fetch_game_log_raw(batter_id, "hitting", 14)
        games = [(int((sp.get("stat", {})).get("hits", 0) or 0),
                  int((sp.get("stat", {})).get("atBats", 0) or 0)) for sp in splits]
        if games:
            last7, last14 = games[-7:], games[-14:]
            out["l7Hits"]    = round(sum(h for h, _ in last7) / len(last7), 4)
            out["l14Hits"]   = round(sum(h for h, _ in last14) / len(last14), 4)
            out["l7HitRate"] = round(sum(h / max(ab, 1) for h, ab in last7) / len(last7), 4)
    except Exception:
        out = {}
    with _hit_form_lock:
        _hit_form_cache[batter_id] = (today, out)
    return out


def _compute_bvp_confidence(bvp_data, batter_obj, pitcher_hand, mix_score, mix_rows):
    """0-100 confidence score for the BvP projection.

    Blends four signals:
      * H2H sample size (saturates at ~30 PA)
      * Platoon split sample size for the pitcher's hand
      * Pitch-mix coverage (how many pitches have batter career data)
      * Whether Statcast pitch arsenal data is available at all
    Designed so a fresh matchup with no H2H still scores well when there's
    strong platoon + arsenal coverage. Returns dict {value, label, basis}.
    """
    pa = int((bvp_data or {}).get("pa", 0) or 0)
    h2h_score = min(1.0, pa / 30.0)                     # 30 PA → fully saturated

    hand = (pitcher_hand or "R").upper()
    split_pa = int((batter_obj.get("vs_l_pa") if hand == "L" else batter_obj.get("vs_r_pa")) or 0)
    plat_score = min(1.0, split_pa / 120.0)             # 120 PA platoon → saturated

    if mix_rows:
        covered = sum(1 for r in mix_rows if r.get("bat_slg") is not None)
        mix_cov = min(1.0, covered / max(1, len(mix_rows)))
    else:
        mix_cov = 0.0

    # Weighted blend; if no data anywhere, falls back to low-but-nonzero score.
    raw = 0.35 * h2h_score + 0.30 * plat_score + 0.25 * mix_cov + 0.10 * (1.0 if mix_rows else 0.0)
    value = round(100 * raw, 1)

    if value >= 70:    label = "STRONG"
    elif value >= 50:  label = "MODERATE"
    elif value >= 30:  label = "LIMITED"
    else:              label = "WEAK"

    basis = []
    if pa > 0:        basis.append(f"{pa} H2H PA")
    if split_pa > 0:  basis.append(f"{split_pa} PA vs {hand}HP")
    if mix_rows:      basis.append(f"{len(mix_rows)}-pitch arsenal")

    return {
        "value":     value,
        "label":     label,
        "h2hScore":  round(h2h_score, 3),
        "platScore": round(plat_score, 3),
        "mixScore":  round(mix_cov, 3),
        "basis":     " · ".join(basis) if basis else "no matchup data",
    }


# Verdict thresholds — calibrated to typical sportsbook prop lines so that
# the model's stated probability is compared against the implied book line.
# Each entry: (bet_threshold, lean_threshold, fade_threshold).
_PROP_VERDICTS = {
    "hit1": (0.70, 0.58, 0.48),   # 1+ Hit  (line ~ -180)
    "tb2":  (0.45, 0.35, 0.27),   # 2+ TB   (line ~ +160)
    "hr":   (0.22, 0.14, 0.09),   # HR      (line ~ +450)
    "rbi1": (0.55, 0.42, 0.33),   # 1+ RBI  (line ~ +110)
}


def _verdict_for(market, prob):
    """Return (key, label, color_class) for prob+market.

    Keys: 'bet' (green), 'lean' (yellow), 'pass' (neutral), 'fade' (red).
    """
    if prob is None:
        return ("pass", "—", "")
    bet_t, lean_t, fade_t = _PROP_VERDICTS.get(market, (0.65, 0.55, 0.40))
    if prob >= bet_t:  return ("bet",  "BET",  "v-bet")
    if prob >= lean_t: return ("lean", "LEAN", "v-lean")
    if prob <= fade_t: return ("fade", "FADE", "v-fade")
    return ("pass", "PASS", "v-pass")


def _starter_pa_for_slot(slot, exp_pa_total=None, starter_tbf=22.0):
    """Expected PAs the batter sees vs the SP only (not full game).

    Heuristic: an SP facing ~22 batters → 22/9 ≈ 2.44 PAs per slot. Top of
    order may pick up an extra trip when the SP works deep. Capped to
    [1.2, 3.4] so the result stays plausible across hook scenarios.
    """
    slot = max(1, min(9, int(slot or 5)))
    base = starter_tbf / 9.0
    # Top of order picks up an extra trip when the SP works past 18 batters.
    extra_slots = max(0, int(starter_tbf - 18))
    pa = base + (1.0 if slot <= extra_slots else 0.0)
    if exp_pa_total is not None:
        pa = min(pa, max(1.0, float(exp_pa_total) - 0.6))
    return round(max(1.2, min(3.4, pa)), 2)


def _vs_sp_projections(batx, exp_pa_total, exp_pa_vs_sp, ttop_boost=None):
    """Convert game-level BATX expected values into vs-SP probabilities.

    Treats expected counts as Poisson(mean = batx_value × pa_vs_sp / pa_total
    × ttop_boost) and returns P(>= line) for each market, plus the rescaled
    expected values AND a league-neutral baseline for the same PA count.

    The TTOP boost (default = average wOBA multiplier across pa_vs_sp PAs)
    captures the "third time through the order" effect: each subsequent PA
    against the starter the batter sees a stale arsenal and performs better.
    """
    pa_total = max(0.5, float(exp_pa_total or 4.35))
    pa_sp    = max(0.5, float(exp_pa_vs_sp or pa_total * 0.6))
    scale    = pa_sp / pa_total
    if ttop_boost is None:
        ttop_boost = _ttop_avg_batter_mult(pa_sp)
    h_lam    = float(batx.get("hits", 0) or 0) * scale * ttop_boost
    tb_lam   = float(batx.get("tb",   0) or 0) * scale * ttop_boost
    hr_lam   = float(batx.get("hr",   0) or 0) * scale * ttop_boost
    rbi_lam  = float(batx.get("rbi",  0) or 0) * scale * ttop_boost

    # Neutral-batter baseline at the same PA count (league rates).
    neutral = {
        "hit1": round(_poisson_over_prob(0.245 * pa_sp, 0.5), 3),
        "tb2":  round(_poisson_over_prob(0.420 * pa_sp, 1.5), 3),
        "hr":   round(_poisson_over_prob(0.032 * pa_sp, 0.5), 3),
        "rbi1": round(_poisson_over_prob(0.115 * pa_sp, 0.5), 3),
    }
    return {
        "hit1": round(_poisson_over_prob(h_lam,   0.5), 3),
        "tb2":  round(_poisson_over_prob(tb_lam,  1.5), 3),
        "hr":   round(_poisson_over_prob(hr_lam,  0.5), 3),
        "rbi1": round(_poisson_over_prob(rbi_lam, 0.5), 3),
        "neutral": neutral,
        "expected": {
            "hits": round(h_lam,  3),
            "tb":   round(tb_lam, 3),
            "hr":   round(hr_lam, 4),
            "rbi":  round(rbi_lam, 3),
        },
    }


def _verdict_edge(prob, neutral):
    """Edge-based verdict for vs-SP probs (compare to league neutral baseline)."""
    if prob is None or neutral is None:
        return ("pass", "—", "")
    edge = prob - neutral
    if edge >= 0.10:  return ("bet",  "STRONG", "v-bet")
    if edge >= 0.04:  return ("lean", "EDGE",   "v-lean")
    if edge <= -0.07: return ("fade", "FADE",   "v-fade")
    return ("pass", "AVG", "v-pass")


def _log5_k_rate(batter_k, pitcher_k, league_k=_LEAGUE_KPCT):
    """Log5 / Bill James formula for K probability per PA in this matchup."""
    b = max(0.05, min(0.55, float(batter_k or league_k)))
    p = max(0.10, min(0.45, float(pitcher_k or league_k)))
    L = max(0.10, min(0.40, float(league_k or 0.225)))
    num   = (b * p) / L
    denom = num + ((1 - b) * (1 - p)) / (1 - L)
    if denom <= 0:
        return league_k
    return max(0.04, min(0.55, num / denom))


# Times-Through-Order Penalty (TTOP) — well-documented effect:
# pitcher K% drops and batter wOBA rises each time through the order.
# Multipliers applied per PA index (1st PA, 2nd PA, 3rd PA vs SP).
_TTOP_K_MULT     = (1.00, 0.97, 0.92)   # pitcher K rate decay
_TTOP_BATTER_MULT = (1.00, 1.02, 1.06)   # batter wOBA boost


def _ttop_avg_k_mult(pa_count):
    """Average K-rate multiplier across pa_count PAs (TTOP-weighted)."""
    if pa_count <= 0:
        return 1.0
    n_full = int(pa_count)
    frac   = pa_count - n_full
    s = 0.0
    for i in range(n_full):
        s += _TTOP_K_MULT[min(i, len(_TTOP_K_MULT) - 1)]
    if frac > 0:
        s += frac * _TTOP_K_MULT[min(n_full, len(_TTOP_K_MULT) - 1)]
    return s / pa_count


def _ttop_avg_batter_mult(pa_count):
    """Average batter wOBA multiplier across pa_count PAs (TTOP-weighted)."""
    if pa_count <= 0:
        return 1.0
    n_full = int(pa_count)
    frac   = pa_count - n_full
    s = 0.0
    for i in range(n_full):
        s += _TTOP_BATTER_MULT[min(i, len(_TTOP_BATTER_MULT) - 1)]
    if frac > 0:
        s += frac * _TTOP_BATTER_MULT[min(n_full, len(_TTOP_BATTER_MULT) - 1)]
    return s / pa_count


def _pitcher_k_projection_vs_lineup(pitcher_id, pitcher_name, opposing_lineup,
                                     starter_tbf=22.0,
                                     lines=(4.5, 5.5, 6.5, 7.5, 8.5),
                                     pitcher_dict=None,
                                     ump_k_mult=1.0):
    """Project pitcher K total vs a specific opposing lineup.

    Method:
      * Per-batter Log5 K rate × slot-aware PAs vs SP, with TTOP penalty
        applied per PA (each subsequent trip the K rate falls).
      * Sum into expected K total, derive Poisson P(over line) for each line.
      * Blend with XGBoost xgb_k_prob() when its model is loaded for the line
        (60% XGB / 40% Poisson).
      * Optional umpire K-zone multiplier (`ump_k_mult`) scales total K.

    Returns dict with expectedK, expectedKLog5, expectedKXgb (raw), perBatter
    list, and per-line over/under verdicts.
    """
    if not opposing_lineup:
        return None

    fg_pit = fg_pitcher(pitcher_name) if pitcher_name else {}
    pit_kpct = _safe_f(fg_pit.get("fg_kpct"), _LEAGUE_KPCT)

    tbf = max(12.0, min(30.0, float(starter_tbf)))
    per_slot_pa = tbf / 9.0

    expected_k_log5 = 0.0
    per_batter = []
    for i, b in enumerate(opposing_lineup[:9]):
        name = b.get("name") or ""
        if not name:
            continue
        bat = fg_batter(name) or {}
        bat_kpct = _safe_f(bat.get("fg_kpct"), _LEAGUE_KPCT)
        slot = int(b.get("slot") or (i + 1))
        # Slight slot adjustment so leadoff sees ~+0.2 more PA than #9 vs SP.
        slot_pa = per_slot_pa + max(0.0, (5 - slot) * 0.04)
        # TTOP: K rate decays each subsequent PA. Use the average multiplier
        # across this slot's PAs vs SP.
        ttop_mult = _ttop_avg_k_mult(slot_pa)
        k_per_pa = _log5_k_rate(bat_kpct, pit_kpct) * ttop_mult * ump_k_mult
        k_per_pa = max(0.04, min(0.55, k_per_pa))
        k_exp    = k_per_pa * slot_pa
        expected_k_log5 += k_exp
        per_batter.append({
            "slot":   slot,
            "name":   name,
            "kPerPa": round(k_per_pa, 3),
            "paVsSp": round(slot_pa,  2),
            "expK":   round(k_exp,    2),
            "ttopMult": round(ttop_mult, 3),
        })

    expected_k_log5 = round(expected_k_log5, 2)

    # XGBoost K-prop ensemble: per-line probability when models loaded.
    xgb_avail = xgb_ready("k")
    if xgb_avail and pitcher_dict is None:
        # Build a minimal pitcher dict the K model can consume.
        sv_pit = sv_pitcher(pitcher_name) or {}
        pitcher_dict = {
            "name":         pitcher_name,
            "svxera":       _safe_f(sv_pit.get("sv_xera"),      None),
            "fgera":        _safe_f(fg_pit.get("fg_era"),        None),
            "fgkpct":       _safe_f(fg_pit.get("fg_kpct"),       None),
            "fgbbpct":      _safe_f(fg_pit.get("fg_bbpct"),      None),
            "svwhiffpct":   _safe_f(sv_pit.get("sv_whiff"),      None),
            "oppKPct":      _safe_f(fg_pit.get("opp_kpct_proxy"), 22.0),
            "oppWoba":      _safe_f(fg_pit.get("opp_woba_proxy"), 0.320),
        }
        # Fold in rolling form (l{3,5,10}Ks / l5KRate / l{3,5}IP / daysRest).
        # NOTE: the previous code read rf.get("l3"/"l5"/"l10"/"days_rest"), keys
        # _pitcher_recent_form never returns, so every rolling feature silently
        # fell back to its default. _pitcher_rolling_k_features returns the
        # correct keys, computed to match the model's training definitions.
        try:
            _kf = _pitcher_rolling_k_features(pitcher_id) if pitcher_id else None
            if _kf:
                pitcher_dict.update(_kf)
        except Exception:
            pass

    # Fold in arsenal pitch-mix (usage-weighted whiff%/putaway%) so the K model
    # can use the swing-and-miss signal the retrained models were trained on.
    if xgb_avail and pitcher_dict:
        try:
            _ars = _arsenal_whiff_summary(pitcher_id) if pitcher_id else None
            if _ars:
                pitcher_dict.setdefault("arsenalWhiff",   _ars.get("whiff"))
                pitcher_dict.setdefault("arsenalPutaway", _ars.get("putaway"))
        except Exception:
            pass
        _maybe_stuff_plus(pitcher_dict, pitcher_id)

    # Blend Log5 expected K with the average of XGB per-line implied means
    # (so the displayed expected K reflects the ensemble too). When XGB is
    # unavailable, expected_k = expected_k_log5.
    expected_k = expected_k_log5

    line_results = []
    for line in lines:
        p_over_log5 = _poisson_over_prob(expected_k_log5, line)
        p_over_xgb = None
        if xgb_avail:
            try:
                p_over_xgb = xgb_k_prob(pitcher_dict, line=float(line))
            except Exception:
                p_over_xgb = None
        if p_over_xgb is not None:
            p_over = 0.6 * p_over_xgb + 0.4 * p_over_log5
            method = "ensemble"
        else:
            p_over = p_over_log5
            method = "log5"
        p_over  = round(max(0.01, min(0.99, p_over)), 3)
        p_under = round(1.0 - p_over, 3)
        if p_over >= 0.62:
            side, verdict, cls = "over",  "BET OVER",   "v-bet"
        elif p_over >= 0.55:
            side, verdict, cls = "over",  "LEAN OVER",  "v-lean"
        elif p_under >= 0.62:
            side, verdict, cls = "under", "BET UNDER",  "v-bet"
        elif p_under >= 0.55:
            side, verdict, cls = "under", "LEAN UNDER", "v-lean"
        else:
            side, verdict, cls = "pass",  "PASS",       "v-pass"
        line_results.append({
            "line":       line,
            "pOver":      p_over,
            "pUnder":     p_under,
            "pOverLog5":  round(p_over_log5, 3),
            "pOverXgb":   round(p_over_xgb, 3) if p_over_xgb is not None else None,
            "method":     method,
            "side":       side,
            "verdict":    verdict,
            "verdictCls": cls,
        })

    return {
        "pitcher":      pitcher_name,
        "expectedK":    round(expected_k, 2),
        "expectedKLog5": round(expected_k_log5, 2),
        "expectedTBF":  round(tbf, 1),
        "umpKMult":     round(ump_k_mult, 3),
        "xgbAvailable": xgb_avail,
        "lineupSize":   len(per_batter),
        "perBatter":    per_batter,
        "lineProjections": line_results,
    }


def _umpire_k_multiplier(game_pk):
    """Return a K-rate multiplier in [0.88, 1.12] from cached umpire data.

    Uses zone_rating (0–100, higher = pitcher friendly). 50 = neutral.
    Returns (mult, ump_meta) where ump_meta is a small dict for surfacing.
    """
    if not game_pk:
        return 1.0, None
    try:
        for delta in (0, -1, 1):
            date_str = (datetime.now(ET) + timedelta(days=delta)).strftime("%Y-%m-%d")
            games = _fetch_schedule_with_officials(date_str, date_str) if "_fetch_schedule_with_officials" in globals() else []
            gdata = next((g for g in games if g.get("gamePk") == game_pk), None)
            if gdata:
                break
        if not gdata:
            return 1.0, None
        ump = _get_hp_umpire(gdata)
        ump_id = ump.get("id")
        if not ump_id:
            return 1.0, None
        with _ump_lock:
            cached = _ump_cache.get(ump_id)
        if not cached or "data" not in cached:
            return 1.0, {"name": ump.get("fullName"), "loaded": False}
        data = cached["data"]
        zone = float(data.get("zone_rating") or 50)
        # 50 zone = 1.0×; 65 = 1.075×; 35 = 0.925×; clamp.
        mult = 1.0 + (zone - 50) * 0.005
        mult = max(0.88, min(1.12, mult))
        return round(mult, 3), {
            "name":       ump.get("fullName"),
            "zone":       int(zone),
            "tendency":   data.get("tendency"),
            "loaded":     True,
        }
    except Exception:
        return 1.0, None


def _find_lineup_catcher(lineup):
    """Return (name, id) of the catcher in a lineup list, or (None, None)."""
    if not lineup:
        return None, None
    for b in lineup:
        pos = (b.get("pos") or "").upper().strip()
        if pos == "C":
            return b.get("name"), b.get("id")
    return None, None


def _framing_ump_k_mult(game_pk, catcher_name=None, catcher_id=None):
    """Combined catcher-framing × HP-umpire K multiplier in [0.85, 1.18].

    Multiplies the existing zone-rating-based umpire mult with a framing
    multiplier derived from the catcher's runs-extra-strikes. Returns
    (mult, meta dict) where meta surfaces both inputs for UI / debug.
    """
    ump_mult, ump_meta = _umpire_k_multiplier(game_pk)
    frame = framing_runs(name=catcher_name, player_id=catcher_id) if _FRAMING_AVAILABLE else {"framing_runs": 0.0}
    frame_mult = framing_k_multiplier(frame.get("framing_runs")) if _FRAMING_AVAILABLE else 1.0
    combined = max(0.85, min(1.18, round(ump_mult * frame_mult, 4)))
    meta = {
        "ump":           ump_meta,
        "ump_mult":      ump_mult,
        "catcher":       catcher_name,
        "framing_runs":  round(float(frame.get("framing_runs") or 0.0), 2),
        "framing_mult":  frame_mult,
        "combined_mult": combined,
    }
    return combined, meta


def _resolve_park_factor(home_team_abbr, home_team_id, hand="R", stat="HR", date_str=None):
    """Prefer Ballpark Pal microclimate factor; fall back to static PARK_FACTORS.

    Returns a float multiplier on the ratio scale (1.0 = neutral). The
    HR_PARK_FACTORS dict is on the 100-scale used elsewhere — we only consult
    it as a refined HR ratio (divided by 100) when BP misses.
    """
    if _BPP_AVAILABLE and home_team_abbr:
        bp = bp_park_factor(home_team_abbr, hand=hand, stat=stat, date_str=date_str)
        if bp is not None:
            return bp
    if stat == "HR" and home_team_id is not None and home_team_id in HR_PARK_FACTORS:
        # Handedness-split HR factor when the park has a known platoon skew,
        # else the symmetric HR index — both via _hr_park_factor_hand().
        return _hr_park_factor_hand(home_team_id, hand)
    return PARK_FACTORS.get(home_team_id, 1.0)


def _model_divergence(probs, gp, batx, exp_pa_total, *, bvp_pa=0, park_factor=1.0):
    """Surface XGB-vs-BATX divergence and a HIGH/MEDIUM/LOW UNCERTAINTY flag.

    For 1+ Hit specifically — the only market with an XGB model loaded today.
    Returns:
        xgb / batx       — each model's 1+ hit probability
        divergence       — raw absolute Δ (probability points)
        divergenceLogit  — variance-aware Δ on the logit scale
        flagKey/Label    — bucketed reliability category
        blended          — final shrink-to-prior reconciled probability
        reliability      — 0..1 confidence score combining coverage + divergence
        coverage         — XGB input coverage (0..1) when XGB is active
    """
    xgb_p     = gp.get("xgbHitProb")
    coverage  = float(gp.get("xgbHitCoverage") or 0.0)
    exp_pa    = max(1.0, float(exp_pa_total or 4.2))
    # BATX 1+ hit prob via binomial across expected PA — must match the route
    # so the bar isn't comparing apples to oranges.
    batx_hits = float(batx.get("hits", 0) or 0)
    batx_p    = round(_binomial_over_zero(batx_hits, exp_pa), 3)
    raw_blend = probs.get("hit1")

    if xgb_p is None:
        return {
            "available":      False,
            "blended":        raw_blend,
            "batx":           batx_p,
            "xgb":            None,
            "coverage":       round(coverage, 3),
            "divergence":     None,
            "divergenceLogit": None,
            "reliability":    round(0.30 + 0.30 * min(1.0, exp_pa / 4.5), 3),
            "flagKey":        "thin",
            "flagLabel":      "XGB UNAVAILABLE",
            "flagCls":        "v-pass",
        }

    div     = round(abs(xgb_p - batx_p), 3)
    div_lgt = round(_logit_divergence(xgb_p, batx_p), 3)

    # ── Stacked calibrator: replaces the "HIGH UNCERTAINTY" dual-bar UX with a
    #    single calibrated probability + 95% CI + decisive verdict tier.
    #    Falls back to the legacy shrink-to-prior path if the calibrator
    #    module isn't importable.
    stack = None
    if _STACK_AVAILABLE:
        # Pass the XGB prediction interval (when present) so the calibrator can
        # fuse an empirical, simulation-grounded CI rather than relying solely
        # on the heuristic analytic interval.
        _ci_lo = gp.get("xgbHitCiLo")
        _ci_hi = gp.get("xgbHitCiHi")
        _mc_ci = (_ci_lo, _ci_hi) if (_ci_lo is not None and _ci_hi is not None) else None
        try:
            stack = stacked_calibrate(
                xgb_p, batx_p,
                coverage=coverage,
                exp_pa=exp_pa,
                bvp_pa=bvp_pa,
                park_factor=park_factor,
                mc_ci=_mc_ci,
            )
        except Exception:
            stack = None

    if stack:
        # The stacked verdict is the single source of truth for the UI.
        return {
            "available":       True,
            "blended":         stack["probability"],
            "blendedRaw":      raw_blend,
            "batx":            batx_p,
            "xgb":             round(xgb_p, 3),
            "coverage":        round(coverage, 3),
            "divergence":      div,
            "divergenceLogit": div_lgt,
            "shrinkApplied":   0.0,
            "reliability":     stack["confidence"],
            "flagKey":         stack["verdict"].lower(),
            "flagLabel":       stack["verdict_label"],
            "flagCls":         _stack_color_to_class(stack["verdict_color"]),
            # Verdict-tier output (new): the single-glance decision.
            "verdict": {
                "tier":         stack["verdict"],
                "label":        stack["verdict_label"],
                "color":        stack["verdict_color"],
                "probability":  stack["probability"],
                "ci_lo":        stack["ci_lo"],
                "ci_hi":        stack["ci_hi"],
                "confidence":   stack["confidence"],
                "source":       stack["source"],
            },
        }

    # ── Legacy fallback (only when stacked_calibrator import failed) ────────
    if   div_lgt >= 1.10:
        flag = ("high",   "HIGH UNCERTAINTY", "v-fade")
    elif div_lgt >= 0.55:
        flag = ("medium", "MODELS SPLIT",     "v-lean")
    else:
        flag = ("low",    "MODELS AGREE",     "v-bet")

    LEAGUE_PRIOR_HIT1 = 0.66
    div_shrink   = max(0.0, min(0.50, (div_lgt - 0.55) * 0.40))
    cov_shrink   = max(0.0, 0.40 - coverage) * 0.50
    shrink_w     = max(0.0, min(0.60, div_shrink + cov_shrink))
    blended      = round(_shrink_to_prior(raw_blend, LEAGUE_PRIOR_HIT1, shrink_w), 3)

    rel = 1.0
    rel -= min(0.55, max(0.0, (div_lgt - 0.30) * 0.45))
    rel -= 0.30 * max(0.0, 1.0 - coverage)
    reliability = round(max(0.20, min(1.0, rel)), 3)

    return {
        "available":       True,
        "blended":         blended,
        "blendedRaw":      raw_blend,
        "batx":            batx_p,
        "xgb":             round(xgb_p, 3),
        "coverage":        round(coverage, 3),
        "divergence":      div,
        "divergenceLogit": div_lgt,
        "shrinkApplied":   round(shrink_w, 3),
        "reliability":     reliability,
        "flagKey":         flag[0],
        "flagLabel":       flag[1],
        "flagCls":         flag[2],
    }


def _stack_color_to_class(color: str) -> str:
    """Map stacked-calibrator verdict color → existing bvp.html CSS class."""
    return {
        "green": "v-bet",   # STRONG_BET
        "teal":  "v-bet",   # LEAN_OVER
        "gray":  "v-pass",  # PASS
        "amber": "v-lean",  # LEAN_UNDER
        "red":   "v-fade",  # STRONG_FADE
    }.get(color, "v-pass")


def _projection_drivers(batx_adjustments, top_n=4):
    """Pick the top-N BATX adjustment components by absolute magnitude.

    Returns ordered list of {component, contribution, direction, label}.
    `batx_adjustments` is the dict stored in batx['adjustments'] by
    _project_batter_batx — values are the per-component contributions to
    the composite multiplier (deltas around zero).
    """
    if not batx_adjustments or not isinstance(batx_adjustments, dict):
        return []
    pretty = {
        "contact_contrib":  "Contact (xBA + AVG)",
        "power_contrib":    "Power (ISO/Brl/EV)",
        "disc_contrib":     "Discipline (BB/K)",
        "platoon_contrib":  "Platoon edge",
        "park_contrib":     "Park factor",
        "wx_contrib":       "Weather",
        "pitcher_contrib":  "Pitcher resistance",
        "form_contrib":     "Recent form (L7)",
        "bvp_contrib":      "Career BvP",
        "pitch_mix":        "Pitch-mix matchup",
    }
    items = []
    for k, v in batx_adjustments.items():
        if not isinstance(v, (int, float)):
            continue
        magnitude = abs(float(v))
        if magnitude < 0.001:
            continue
        items.append({
            "component":    k,
            "label":        pretty.get(k, k.replace("_contrib", "").replace("_", " ").title()),
            "contribution": round(float(v), 4),
            "direction":    "+" if v > 0 else "-",
            "magnitude":    round(magnitude, 4),
        })
    items.sort(key=lambda r: r["magnitude"], reverse=True)
    return items[:top_n]


def _monte_carlo_vs_sp(per_pa_rates, pa_vs_sp, n_sims=4000, rng_seed=None):
    """Monte Carlo distribution of vs-SP outcomes over `pa_vs_sp` plate appearances.

    per_pa_rates: dict with keys 'k', 'bb', 'hbp', '1b', '2b', '3b', 'hr'.
    The remaining mass is distributed to outs.
    Returns percentile bands (P25/P50/P75/P90) for hits, TB, HR, RBI plus
    the probabilities of clearing standard prop lines.

    Vectorized: PA outcomes are i.i.d. draws, so one multinomial per simulated
    game is distributionally identical to drawing PA-by-PA at ~15x less CPU
    (~24ms -> ~1.7ms per batter; the projections build runs this for all 18
    starters). The seed feeds a local Generator — the old implementation
    seeded the GLOBAL `random` module from the 9-thread batter-enrich pool,
    which was neither reproducible under concurrency nor safe for other
    `random` users.
    """
    n_pa_int  = int(round(max(0.0, pa_vs_sp)))
    if n_pa_int <= 0:
        return None

    # Normalize rates and compute outs as residual.
    r = dict(per_pa_rates)
    r.setdefault("hbp", 0.005)
    used = sum(max(0.0, float(v)) for v in r.values())
    if used > 0.99:
        scale = 0.99 / used
        for k in r:
            r[k] = float(r[k]) * scale
        used = sum(r.values())
    out_rate = max(0.001, 1.0 - used)

    # Outcome distribution — columns: k, bb, hbp, 1b, 2b, 3b, hr, out.
    weights = np.array([
        max(0.0, float(r.get("k", 0) or 0)),  max(0.0, float(r.get("bb", 0) or 0)),
        max(0.0, float(r.get("hbp", 0) or 0)), max(0.0, float(r.get("1b", 0) or 0)),
        max(0.0, float(r.get("2b", 0) or 0)),  max(0.0, float(r.get("3b", 0) or 0)),
        max(0.0, float(r.get("hr", 0) or 0)),  out_rate,
    ], dtype=np.float64)
    weights /= weights.sum()

    if rng_seed is None:
        rng = np.random.default_rng()
    else:
        try:
            rng = np.random.default_rng(abs(int(rng_seed)))
        except (TypeError, ValueError):
            rng = np.random.default_rng(abs(hash(str(rng_seed))))

    counts = rng.multinomial(n_pa_int, weights, size=n_sims)
    n_1b, n_2b, n_3b = counts[:, 3], counts[:, 4], counts[:, 5]
    sim_k, sim_bb, sim_hr = counts[:, 0], counts[:, 1], counts[:, 6]
    sim_hits = n_1b + n_2b + n_3b + sim_hr
    sim_tb   = n_1b + 2 * n_2b + 3 * n_3b + 4 * sim_hr
    # RBI: per-hit Bernoulli runner-on chances (1B 18%, 2B 30%, 3B 45%);
    # HR always drives in the batter plus a 50% chance of one more.
    sim_rbi  = (rng.binomial(n_1b, 0.18) + rng.binomial(n_2b, 0.30)
                + rng.binomial(n_3b, 0.45) + sim_hr + rng.binomial(sim_hr, 0.50))

    def _pctiles(arr, ps=(25, 50, 75, 90)):
        s = np.sort(arr)
        n = len(s)
        return {f"p{p}": int(s[min(n - 1, int(round(p / 100.0 * (n - 1))))]) for p in ps}

    def _gte_prob(arr, threshold):
        return round(float(np.mean(arr >= threshold)), 3)

    return {
        "nSims":  n_sims,
        "nPa":    n_pa_int,
        "hits":   {"mean": round(float(sim_hits.mean()), 2), **_pctiles(sim_hits),
                   "p_ge_1": _gte_prob(sim_hits, 1), "p_ge_2": _gte_prob(sim_hits, 2)},
        "tb":     {"mean": round(float(sim_tb.mean()), 2), **_pctiles(sim_tb),
                   "p_ge_2": _gte_prob(sim_tb, 2),  "p_ge_3": _gte_prob(sim_tb, 3)},
        "hr":     {"mean": round(float(sim_hr.mean()), 3), "p_ge_1": _gte_prob(sim_hr, 1)},
        "rbi":    {"mean": round(float(sim_rbi.mean()), 2), "p_ge_1": _gte_prob(sim_rbi, 1),
                   "p_ge_2": _gte_prob(sim_rbi, 2)},
        "k":      {"mean": round(float(sim_k.mean()), 2), "p_ge_1": _gte_prob(sim_k, 1)},
        "bb":     {"mean": round(float(sim_bb.mean()), 2), "p_ge_1": _gte_prob(sim_bb, 1)},
    }


# Bullpen baseline adjustments vs starters (approximate league-wide diffs).
#  RP K% ~ +2.5pts, RP wOBA-against ~ -0.012, RP HR/9 ~ -0.10.
_BULLPEN_VS_SP = {
    "k_uplift":     +0.025,    # RP K% above SP
    "woba_offset":  -0.012,    # RP wOBA-against below SP
    "rate_mult":    0.94,      # batter offensive rate × this in bullpen PAs
}


def _vs_rp_projections(batx, exp_pa_total, exp_pa_vs_sp):
    """Project the slice of the game vs the BULLPEN (PAs after the SP exits).

    Uses league bullpen baseline adjustments (RP slightly more dominant than
    SP). When pa_vs_rp is small (≤ 0.5), returns None — projections become
    unreliable and the UI can simply hide the section.
    """
    pa_total = max(0.5, float(exp_pa_total or 4.35))
    pa_sp    = max(0.0, float(exp_pa_vs_sp or pa_total * 0.6))
    pa_rp    = max(0.0, pa_total - pa_sp)
    if pa_rp < 0.5:
        return None

    scale = pa_rp / pa_total
    rate_mult = _BULLPEN_VS_SP["rate_mult"]
    h_lam   = float(batx.get("hits", 0) or 0) * scale * rate_mult
    tb_lam  = float(batx.get("tb",   0) or 0) * scale * rate_mult
    hr_lam  = float(batx.get("hr",   0) or 0) * scale * rate_mult
    rbi_lam = float(batx.get("rbi",  0) or 0) * scale * rate_mult
    return {
        "paVsRp": round(pa_rp, 2),
        "probs": {
            "hit1": round(_poisson_over_prob(h_lam,   0.5), 3),
            "tb2":  round(_poisson_over_prob(tb_lam,  1.5), 3),
            "hr":   round(_poisson_over_prob(hr_lam,  0.5), 3),
            "rbi1": round(_poisson_over_prob(rbi_lam, 0.5), 3),
        },
        "expected": {
            "hits": round(h_lam,  3),
            "tb":   round(tb_lam, 3),
            "hr":   round(hr_lam, 4),
            "rbi":  round(rbi_lam, 3),
        },
        "note": f"~{round(pa_rp,1)} PAs vs RP · bullpen K% +{int(_BULLPEN_VS_SP['k_uplift']*1000)/10:.1f}pts vs SP",
    }


def _per_pa_rates_from_batx(batx, fg_bat, exp_pa_total, ttop_boost=1.0):
    """Derive per-PA outcome rates (k, bb, hbp, 1b, 2b, 3b, hr) for MC sim.

    Uses BATX expected hits/HR/RBI to anchor average rates and FG K%/BB% for
    walks/strikeouts. 1B/2B/3B inferred from total bases minus HR contribution.
    """
    pa = max(0.5, float(exp_pa_total or 4.35))
    h_per   = float(batx.get("hits", 0) or 0) / pa * ttop_boost
    tb_per  = float(batx.get("tb",   0) or 0) / pa * ttop_boost
    hr_per  = float(batx.get("hr",   0) or 0) / pa * ttop_boost
    k_per   = max(0.05, min(0.50, _safe_f(fg_bat.get("fg_kpct"),  _LEAGUE_KPCT)))
    bb_per  = max(0.02, min(0.20, _safe_f(fg_bat.get("fg_bbpct"), 0.082)))
    hbp_per = 0.011

    # Distribute hits into 1B / 2B / 3B / HR using TB constraint:
    #  TB = 1B + 2*2B + 3*3B + 4*HR
    #  H  = 1B + 2B + 3B + HR
    # Solve for 2B + 3B (extras), holding HR fixed; assume 3B ≈ 6% of XBH.
    h_remain = max(0.0, h_per - hr_per)
    tb_remain = max(0.0, tb_per - 4 * hr_per)
    extras = max(0.0, min(h_remain, tb_remain - h_remain))   # 2B + 3B + (extra TB above singles)
    # Cap and split
    extras = min(extras, h_remain * 0.55)
    triples = extras * 0.06
    doubles = max(0.0, extras - triples)
    singles = max(0.0, h_remain - extras)

    return {
        "k":   k_per,
        "bb":  bb_per,
        "hbp": hbp_per,
        "1b":  singles,
        "2b":  doubles,
        "3b":  triples,
        "hr":  hr_per,
    }


def _fetch_bvp(batter_id, pitcher_id):
    """
    Fetch career batter-vs-pitcher splits from the MLB Stats API.
    Returns Bayesian-shrunk rates + raw counts so the caller can decide
    how much weight to apply.
    """
    today = datetime.now().date()
    key = (batter_id, pitcher_id)
    with _bvp_lock:
        cached = _bvp_cache.get(key)
        if cached and cached[0] == today:
            return cached[1]

    result = {"success": False, "pa": 0, "note": "No H2H data"}
    try:
        r = requests.get(
            f"{MLB_API}/people/{batter_id}/stats",
            params={
                "stats": "vsPlayer",
                "group": "hitting",
                "opposingPlayerId": pitcher_id,
                "sportId": 1,
            },
            timeout=10,
        )
        r.raise_for_status()
        splits = (r.json().get("stats") or [{}])[0].get("splits", [])
        if not splits:
            # No career H2H — grade from platoon splits.
            # Primary: daily matchup CSV (pre-computed, no API call needed).
            # Fallback: MLB Stats API statSplits.
            platoon_grade = "C"
            platoon_ops = None
            pitcher_hand = "R"
            grade_basis = "platoon"

            # Try matchup cache first for pitcher hand + batter platoon stats
            mrow = _matchup_row(batter_id, pitcher_id)
            if mrow:
                bh = (mrow.get('batter_hand') or 'R').upper()
                # Infer pitcher hand from which split has more AB
                # (matchup file stores batter hand, not pitcher hand explicitly)
                # Use vsL vs vsR to determine which split is relevant
                # vsL = batter vs LHP, vsR = batter vs RHP
                pitcher_hand = "R"   # default; refined below
                # Use batter_hand to pick the right split key
                if bh == 'L':
                    # LHB: favorable split is vsR (vs RHP)
                    vs_ops = _safe_f(mrow.get('vsR_ops') or None, None)
                    if vs_ops:
                        platoon_ops = vs_ops
                        pitcher_hand = "R"
                    else:
                        vs_ops = _safe_f(mrow.get('vsL_ops') or None, None)
                        if vs_ops:
                            platoon_ops = vs_ops
                            pitcher_hand = "L"
                else:
                    # RHB/switch: use vsL (vs LHP)
                    vs_ops = _safe_f(mrow.get('vsL_ops') or None, None)
                    if vs_ops:
                        platoon_ops = vs_ops
                        pitcher_hand = "L"
                    else:
                        vs_ops = _safe_f(mrow.get('vsR_ops') or None, None)
                        if vs_ops:
                            platoon_ops = vs_ops
                            pitcher_hand = "R"

            if platoon_ops is None:
                # Fallback: MLB API for pitcher hand, then batter platoon split
                try:
                    pr = requests.get(f"{MLB_API}/people/{pitcher_id}", timeout=6)
                    if pr.ok:
                        ppeople = pr.json().get("people", [{}])
                        pitcher_hand = ((ppeople[0].get("pitchHand") or {}).get("code") or "R")
                except Exception:
                    pass
                try:
                    year_now = datetime.now().year
                    sit_code = "l" if pitcher_hand == "L" else "r"
                    sr = requests.get(
                        f"{MLB_API}/people/{batter_id}/stats",
                        params={"stats": "statSplits", "group": "hitting",
                                "sitCodes": sit_code, "season": year_now, "sportId": 1},
                        timeout=8,
                    )
                    if sr.ok:
                        for sg in sr.json().get("stats", []):
                            for sp in sg.get("splits", []):
                                if (sp.get("split") or {}).get("code") == sit_code:
                                    raw = sp.get("stat", {})
                                    platoon_ops = _safe_f(raw.get("ops"), None)
                                    break
                            if platoon_ops is not None:
                                break
                except Exception:
                    pass

            if platoon_ops is not None:
                if platoon_ops >= 0.950:
                    platoon_grade = "A+"
                elif platoon_ops >= 0.850:
                    platoon_grade = "A"
                elif platoon_ops >= 0.750:
                    platoon_grade = "B"
                elif platoon_ops >= 0.650:
                    platoon_grade = "C"
                else:
                    platoon_grade = "D"

            result = {
                "success": True,
                "pa": 0,
                "ab": 0,
                "h": 0,
                "hr": 0,
                "avg": None,
                "ops": None,
                "season_ops": None,
                "ops_ratio": None,
                "grade": platoon_grade,
                "grade_basis": grade_basis,
                "pitcher_hand": pitcher_hand,
                "platoon_ops": platoon_ops,
                "sample_note": f"No career H2H — grade reflects vs {'LHP' if pitcher_hand == 'L' else 'RHP'} splits",
                "note": "No career H2H on record",
                "tooltip": f"No career BvP sample | vs {'LHP' if pitcher_hand == 'L' else 'RHP'} OPS: {platoon_ops:.3f}" if platoon_ops else "No career BvP sample",
                "shrunk": {},
            }
        else:
            # MLB Stats API `stats=vsPlayer` returns one split per season the
            # batter faced this pitcher — aggregate across all seasons for true
            # career H2H. Also build a per-season breakdown for the UI.
            ab = h = bb = hbp = hr = dbl = tpl = so = sf = tb = 0
            seasons = []
            first_season = last_season = None
            for sp in splits:
                stat = sp.get("stat", {}) or {}
                season_yr = sp.get("season") or stat.get("season")
                s_ab  = int(stat.get("atBats", 0) or 0)
                s_h   = int(stat.get("hits", 0) or 0)
                s_bb  = int(stat.get("baseOnBalls", 0) or 0)
                s_hbp = int(stat.get("hitByPitch", 0) or 0)
                s_hr  = int(stat.get("homeRuns", 0) or 0)
                s_dbl = int(stat.get("doubles", 0) or 0)
                s_tpl = int(stat.get("triples", 0) or 0)
                s_so  = int(stat.get("strikeOuts", 0) or 0)
                s_sf  = int(stat.get("sacFlies", 0) or 0)
                s_tb  = int(stat.get("totalBases", 0) or 0)
                s_pa  = s_ab + s_bb + s_hbp + s_sf
                ab  += s_ab;  h  += s_h;   bb  += s_bb;  hbp += s_hbp
                hr  += s_hr;  dbl += s_dbl; tpl += s_tpl; so  += s_so
                sf  += s_sf;  tb += s_tb
                if s_pa > 0:
                    try:
                        yr_int = int(season_yr) if season_yr else None
                    except (TypeError, ValueError):
                        yr_int = None
                    seasons.append({
                        "season": yr_int,
                        "pa": s_pa, "ab": s_ab, "h": s_h, "hr": s_hr,
                        "bb": s_bb, "so": s_so,
                        "avg": round(s_h / s_ab, 3) if s_ab else 0.0,
                        "tb":  s_tb,
                    })
                    if yr_int is not None:
                        first_season = yr_int if first_season is None else min(first_season, yr_int)
                        last_season  = yr_int if last_season  is None else max(last_season,  yr_int)
            singles = max(0, h - dbl - tpl - hr)
            pa  = ab + bb + hbp + sf
            seasons.sort(key=lambda r: (r["season"] is None, r["season"] or 0), reverse=True)

            raw_avg  = round(h / ab, 3) if ab else 0.0
            raw_obp  = round((h + bb + hbp) / pa, 3) if pa else 0.0
            raw_slg  = round(tb / ab, 3) if ab else 0.0
            raw_ops  = round(raw_obp + raw_slg, 3) if pa and ab else None
            raw_woba = _woba_from_counts(bb, hbp, singles, dbl, tpl, hr, pa) or _LEAGUE_WOBA
            raw_kpct = round(so / pa, 4) if pa else _LEAGUE_KPCT
            raw_bbpct= round(bb / pa, 4) if pa else _LEAGUE_BBPCT

            season_ops = None
            try:
                year = datetime.now().year
                rs = requests.get(
                    f"{MLB_API}/people/{batter_id}/stats",
                    params={"stats": "season", "group": "hitting", "season": year, "sportId": 1},
                    timeout=8,
                )
                if rs.ok:
                    sp = (rs.json().get("stats") or [{}])[0].get("splits", [])
                    if sp:
                        season_ops = _safe_f((sp[0].get("stat") or {}).get("ops"), None)
            except Exception:
                season_ops = None

            ops_ratio = None
            if raw_ops is not None and season_ops is not None and season_ops > 0:
                ops_ratio = round(raw_ops / season_ops, 3)

            # Bayesian shrinkage — with < 5 PA the estimate is nearly pure league avg
            shrunk_woba  = _shrink(raw_woba,  pa, _LEAGUE_WOBA,  _SHRINK_PA_BVP)
            shrunk_avg   = _shrink(raw_avg,   ab, 0.250,         _SHRINK_PA_BVP)
            shrunk_kpct  = _shrink(raw_kpct,  pa, _LEAGUE_KPCT,  _SHRINK_PA_BVP)
            shrunk_bbpct = _shrink(raw_bbpct, pa, _LEAGUE_BBPCT, _SHRINK_PA_BVP)

            # Recency-based reliability: only recent seasons (last 2 full years) count.
            # A batter's performance against a pitcher 3+ years ago (with a different
            # arsenal) is unreliable; recency-weighted PA drives how much we trust the edge.
            _cur_yr = datetime.now().year
            recent_pa = sum(
                s["pa"] for s in seasons
                if (s.get("season") or 0) >= _cur_yr - 1
            )
            is_stale = (last_season is not None and last_season < _cur_yr - 2)
            # Hard floor at 5 recent PA; saturates at 50
            reliability = 0.0 if recent_pa < 5 else round(min(1.0, recent_pa / 50.0), 3)

            # Edge signal: how much does Bayesian wOBA deviate from league?
            woba_edge = round(shrunk_woba - _LEAGUE_WOBA, 4)
            if pa == 0:
                note = "No career H2H; league average assumed."
            elif recent_pa < 5 and pa >= 5:
                note = f"{pa} PA career H2H ({recent_pa} PA recent) — too stale to weight."
            elif pa < 10:
                note = f"Only {pa} PA — insufficient sample."
            elif pa < 20:
                note = f"{pa} PA career H2H — moderate sample."
            else:
                note = f"{pa} PA career H2H — strong sample."
            if is_stale:
                note += f" Data through {last_season} only."

            temp = {
                "success": True,
                "pa": pa,
                "ab": ab,
                "h": h,
                "hr": hr,
                "bb": bb,
                "so": so,
                "tb": tb,
                "avg": raw_avg,
                "ops": raw_ops,
                "season_ops": season_ops,
                "ops_ratio": ops_ratio,
                "first_season": first_season,
                "last_season":  last_season,
                "seasons":      seasons,
                "sample_note":  note,
                "raw": {
                    "avg": raw_avg,
                    "obp": raw_obp,
                    "slg": raw_slg,
                    "ops": raw_ops,
                    "woba": raw_woba,
                    "kpct": raw_kpct,
                    "bbpct": raw_bbpct,
                },
                "shrunk": {
                    "woba": shrunk_woba,
                    "avg": shrunk_avg,
                    "kpct": shrunk_kpct,
                    "bbpct": shrunk_bbpct,
                },
                "reliability": reliability,
                "recent_pa": recent_pa,
                "is_stale": is_stale,
                "woba_edge": woba_edge,
                "note": note,
            }
            grade = _compute_bvp_grade(temp)
            temp["grade"] = grade
            avg_txt = f"{raw_avg:.3f}" if raw_avg else ".000"
            ops_txt = f"{raw_ops:.3f}" if raw_ops is not None else "N/A"
            temp["tooltip"] = f"{h}-for-{ab} ({avg_txt}) vs this pitcher | {hr} HR | {ops_txt} OPS"

            result = temp
    except Exception as ex:
        print(f"[bvp] {batter_id} vs {pitcher_id}:", ex)
        result = {"success": False, "error": str(ex)}

    with _bvp_lock:
        _bvp_cache[key] = (today, result)
    return result


def _pitch_avg_from_events(events):
    """Compute batting AVG from statcast event strings."""
    if not events:
        return None
    ab_excluded = {
        "walk", "intent_walk", "hit_by_pitch", "sac_bunt", "sac_fly",
        "catcher_interf", "sac_fly_double_play", "sac_bunt_double_play",
    }
    hit_events = {"single", "double", "triple", "home_run"}
    ab = 0
    hits = 0
    for ev in events:
        if not ev:
            continue
        e = str(ev).strip().lower()
        if not e or e in ab_excluded:
            continue
        ab += 1
        if e in hit_events:
            hits += 1
    if ab <= 0:
        return None
    return round(hits / ab, 3)


def _batter_pitch_profile(batter_id):
    """Build per-batter AVG by pitch type from current-season Statcast."""
    if not batter_id:
        return None
    today = datetime.now().date()
    with _pitch_adv_lock:
        cached = _batter_pitch_perf_cache.get(batter_id)
        if cached and cached[0] == today:
            return cached[1]

    profile = None

    # Stability guard: pybaseball Statcast pulls are expensive and can timeout
    # request handlers under load. Enable only when explicitly requested.
    if not _PITCH_ADV_USE_PYBASEBALL:
        with _pitch_adv_lock:
            _batter_pitch_perf_cache[batter_id] = (today, None)
        return None

    try:
        import pybaseball as pb
        start_dt = f"{datetime.now().year}-03-01"
        end_dt = datetime.now().strftime("%Y-%m-%d")
        df = pb.statcast_batter(start_dt=start_dt, end_dt=end_dt, player_id=int(batter_id))
        if df is not None and len(df) > 0 and "events" in df.columns:
            events_all = [x for x in df["events"].tolist() if x is not None]
            overall_avg = _pitch_avg_from_events(events_all)
            by_pitch = {}
            if "pitch_type" in df.columns:
                for pt in sorted(set([str(x).upper() for x in df["pitch_type"].tolist() if x])):
                    sub = df[df["pitch_type"].astype(str).str.upper() == pt]
                    if len(sub) <= 0:
                        continue
                    p_avg = _pitch_avg_from_events([x for x in sub["events"].tolist() if x is not None])
                    if p_avg is not None:
                        by_pitch[pt] = p_avg
            profile = {
                "overall_avg": overall_avg,
                "by_pitch": by_pitch,
                "sample": int(len(df)),
            }
    except Exception as ex:
        print(f"[pitch_adv:batter_profile] {batter_id}: {ex}")
        profile = None

    with _pitch_adv_lock:
        _batter_pitch_perf_cache[batter_id] = (today, profile)
    return profile


_ARSENAL_MIN_USAGE    = 7.0    # ignore pitches thrown <7% of the time
_ARSENAL_MIN_COVERAGE = 35.0   # need batter data covering >=35% of the arsenal


def _arsenal_matchup_from_stats(pitcher_id, batter_id):
    """Real pitch-arsenal matchup: the batter's wOBA-by-pitch-type weighted by
    the pitcher's ACTUAL usage of each pitch. Returns a verdict dict, or None
    when arsenal data is too thin (caller falls back to the handedness proxy).

    Both Savant leaderboards (`_sv_pit_arsenal_stats`, `_sv_bat_arsenal_stats`)
    are keyed by MLBAM id and share the same `pitch_name` vocabulary, so the
    join needs no name matching."""
    try:
        with _sv_lock:
            pit_ars = _sv_pit_arsenal_stats.get(str(int(pitcher_id)))
            bat_ars = _sv_bat_arsenal_stats.get(str(int(batter_id)))
        if not pit_ars or not bat_ars:
            return None

        # Usage-weighted expected wOBA for this batter vs this exact arsenal.
        num = den = 0.0
        per_pitch = []
        for pitch, pstat in pit_ars.items():
            usage = _safe_f(pstat.get("usage"), 0.0)
            if usage < _ARSENAL_MIN_USAGE:
                continue
            b = bat_ars.get(pitch)
            if not b:
                continue
            bw = _safe_f(b.get("woba"), None)
            if bw is None:
                continue
            num += usage * bw
            den += usage
            per_pitch.append({
                "pitch": pitch,
                "usage": round(usage, 1),
                "batter_woba": round(bw, 3),
                "whiff_pct": _safe_f(b.get("whiff_pct"), None),
            })
        if den < _ARSENAL_MIN_COVERAGE or not per_pitch:
            return None

        matchup_woba = num / den
        # Baseline = the batter's own average wOBA across every pitch type they
        # have data on, so the verdict reflects whether THIS arsenal skews toward
        # the batter's strengths rather than just raw quality.
        baseline_vals = [_safe_f(v.get("woba"), None) for v in bat_ars.values()]
        baseline_vals = [x for x in baseline_vals if x is not None]
        baseline = (sum(baseline_vals) / len(baseline_vals)) if baseline_vals else _LEAGUE_WOBA

        driver = max(per_pitch, key=lambda r: r["usage"])         # most-thrown pitch w/ data
        signed = sorted(per_pitch, key=lambda r: r["batter_woba"])
        worst, best = signed[0], signed[-1]

        delta = matchup_woba - baseline
        if delta >= 0.020:
            status, d = "favorable", best
            note = (f"Strong vs this arsenal — {matchup_woba:.3f} xwOBA "
                    f"(thrives on {d['pitch']}: {d['batter_woba']:.3f} at {d['usage']:.0f}% usage)")
        elif delta <= -0.020:
            status, d = "unfavorable", worst
            note = (f"Weak vs this arsenal — {matchup_woba:.3f} xwOBA "
                    f"(struggles vs {d['pitch']}: {d['batter_woba']:.3f} at {d['usage']:.0f}% usage)")
        else:
            status = "neutral"
            note = f"Neutral arsenal matchup — {matchup_woba:.3f} xwOBA vs the mix"

        return {
            "status": status,
            "note": note,
            "primary_pitch": driver["pitch"],
            "primary_pitch_label": driver["pitch"],
            "usage_pct": round(driver["usage"], 1),
            "matchup_woba": round(matchup_woba, 3),
            "baseline_woba": round(baseline, 3),
            "source": "arsenal",
            "pitches": sorted(per_pitch, key=lambda r: r["usage"], reverse=True)[:5],
        }
    except Exception as ex:
        print(f"[arsenal_matchup] {batter_id} vs {pitcher_id}: {ex}")
        return None


def _pitch_type_advantage(batter_id, pitcher_id, batter_name='', pitcher_name=''):
    """Batter vs the pitcher's REAL arsenal (usage-weighted wOBA by pitch type),
    falling back to the handedness-split proxy when arsenal data is thin."""
    if not batter_id or not pitcher_id:
        return {"status": "neutral", "note": "Neutral matchup"}

    today = datetime.now().date()
    key = (int(batter_id), int(pitcher_id))
    with _pitch_adv_lock:
        cached = _pitch_adv_cache.get(key)
        if cached and cached[0] == today:
            return cached[1]

    out = _arsenal_matchup_from_stats(pitcher_id, batter_id) \
        or _pitch_type_advantage_proxy(batter_id, pitcher_id, batter_name, pitcher_name)

    with _pitch_adv_lock:
        _pitch_adv_cache[key] = (today, out)
    return out


def _pitch_type_advantage_proxy(batter_id, pitcher_id, batter_name='', pitcher_name=''):
    """Legacy fallback: the pitcher's single most-used pitch × the batter's AVG
    vs that pitch (or a handedness split when pitch-type Statcast is missing)."""
    out = {"status": "neutral", "note": "Neutral matchup"}
    try:
        p_name = (pitcher_name or '').strip()
        if not p_name:
            try:
                rp = requests.get(f"{MLB_API}/people/{pitcher_id}", timeout=8)
                if rp.ok:
                    p_name = ((rp.json().get("people") or [{}])[0].get("fullName") or "").strip()
            except Exception:
                p_name = ''

        svp = sv_pitcher(p_name) if p_name else {}
        arsenal = (svp.get("sv_arsenal_pct") or {}) if isinstance(svp, dict) else {}
        if not arsenal:
            out = {"status": "neutral", "note": "Neutral matchup"}
        else:
            primary_pitch, usage = max(arsenal.items(), key=lambda kv: _safe_f(kv[1], 0.0))
            pt_code = str(primary_pitch or '').upper()
            pt_label = PITCH_LABELS.get(str(primary_pitch or '').lower(), pt_code or 'pitch')

            prof = _batter_pitch_profile(int(batter_id))
            overall_avg = _safe_f((prof or {}).get("overall_avg"), None)
            pitch_avg = _safe_f(((prof or {}).get("by_pitch") or {}).get(pt_code), None)

            # Fast fallback when pitch-type Statcast isn't available:
            # proxy by handedness split vs pitcher's throwing hand.
            proxy_note = None
            if pitch_avg is None:
                phand = (player_profile(int(pitcher_id)).get("throws") or "R").upper()
                splits = hitter_split_profile(int(batter_id)) or {}
                skey = "vl" if phand == "L" else "vr"
                split_avg = _safe_f((splits.get(skey) or {}).get("avg"), None)
                if overall_avg is None:
                    fgb = fg_batter(batter_name or "") if batter_name else {}
                    overall_avg = _safe_f(fgb.get("fg_avg"), None)
                if split_avg is not None:
                    pitch_avg = split_avg
                    proxy_note = "(proxy: handedness split)"

            if pitch_avg is None:
                status = "neutral"
                note = "Neutral matchup"
            else:
                crush = (pitch_avg >= 0.280) or (overall_avg is not None and pitch_avg >= overall_avg + 0.030)
                struggle = (pitch_avg <= 0.200) or (overall_avg is not None and pitch_avg <= overall_avg - 0.030)
                if crush:
                    status = "favorable"
                    note = f"Crushes {pt_label.lower()}s ({pitch_avg:.3f}) — pitcher throws {_safe_f(usage, 0):.0f}% {pt_label.lower()}s"
                elif struggle:
                    status = "unfavorable"
                    note = f"Struggles vs {pt_label.lower()}s ({pitch_avg:.3f}) — pitcher throws {_safe_f(usage, 0):.0f}% {pt_label.lower()}s"
                else:
                    status = "neutral"
                    note = "Neutral matchup"
                if proxy_note and note != "Neutral matchup":
                    note = f"{note} {proxy_note}"

            out = {
                "status": status,
                "note": note,
                "primary_pitch": pt_code,
                "primary_pitch_label": pt_label,
                "usage_pct": round(_safe_f(usage, 0.0), 1),
                "pitch_avg": pitch_avg,
                "overall_avg": overall_avg,
            }
    except Exception as ex:
        print(f"[pitch_adv] {batter_id} vs {pitcher_id}: {ex}")
        out = {"status": "neutral", "note": "Neutral matchup"}

    return out



def _num(v, d=0.0):
    try:
        if v in (None, "", "N/A", "---", ".---", "-.--"):
            raise ValueError('empty numeric')
        f = float(v)
        if not math.isfinite(f):
            raise ValueError('non-finite numeric')
        return f
    except Exception:
        try:
            if d is None:
                return None
            fd = float(d)
            if not math.isfinite(fd):
                return 0.0
            return fd
        except Exception:
            return 0.0


def _clamp(v, lo, hi):
    return max(lo, min(hi, v))


def _pct(values, q):
    if not values:
        return 0
    arr = sorted(values)
    if len(arr) == 1:
        return arr[0]
    pos = (len(arr) - 1) * q
    lo = int(math.floor(pos))
    hi = int(math.ceil(pos))
    if lo == hi:
        return arr[lo]
    w = pos - lo
    return arr[lo] * (1 - w) + arr[hi] * w


def player_profile(player_id):
    if not player_id:
        return {'bats': 'S', 'throws': 'R'}
    if player_id in _bio_cache:
        return _bio_cache[player_id]
    try:
        r = requests.get(f"{MLB_API}/people/{player_id}", timeout=8)
        r.raise_for_status()
        p = (r.json().get('people') or [{}])[0]
        out = {
            'bats': p.get('batSide', {}).get('code', 'S') or 'S',
            'throws': p.get('pitchHand', {}).get('code', 'R') or 'R',
        }
    except Exception:
        out = {'bats': 'S', 'throws': 'R'}
    _evict_if_large(_bio_cache, 1000)
    _bio_cache[player_id] = out
    return out


def hitter_split_profile(player_id):
    if not player_id:
        return {}
    if player_id in _hit_split_cache:
        return _hit_split_cache[player_id]
    year = datetime.now().year
    out = {}
    try:
        r = requests.get(
            f"{MLB_API}/people/{player_id}/stats",
            params={"stats": "statSplits", "group": "hitting", "season": year, "sitCodes": "vl,vr"},
            timeout=8,
        )
        r.raise_for_status()
        splits = (r.json().get('stats') or [{}])[0].get('splits', [])
        for sp in splits:
            code = sp.get('split', {}).get('code', '')
            if code not in ('vl', 'vr'):
                continue
            s = sp.get('stat', {})
            out[code] = {
                'avg': _num(s.get('avg'), 0.0),
                'ops': _num(s.get('ops'), 0.0),
                'obp': _num(s.get('obp'), 0.0),
                'slg': _num(s.get('slg'), 0.0),
                'pa': int(s.get('plateAppearances', 0) or 0),
            }
    except Exception:
        out = {}
    _evict_if_large(_hit_split_cache, 1000)
    _hit_split_cache[player_id] = out
    return out


def team_pitching_context(team_id):
    if not team_id:
        return {}
    key = (team_id, datetime.now().date().isoformat())
    if key in _team_pitch_cache:
        return _team_pitch_cache[key]
    year = datetime.now().year
    try:
        r = requests.get(
            f"{MLB_API}/teams/{team_id}/stats",
            params={"stats": "season", "group": "pitching", "season": year},
            timeout=8,
        )
        r.raise_for_status()
        s = (r.json().get('stats') or [{}])[0].get('splits', [{}])[0].get('stat', {})
        out = {
            'era': _clamp(_num(s.get('era'), 4.10), 2.8, 6.2),
            'whip': _clamp(_num(s.get('whip'), 1.28), 1.05, 1.60),
            'k9': _clamp(_num(s.get('strikeoutsPer9Inn'), 8.6), 6.5, 11.5),
            'bb9': _clamp(_num(s.get('walksPer9Inn'), 3.2), 2.0, 4.8),
            'hr9': _clamp(_num(s.get('homeRunsPer9'), 1.10), 0.7, 1.7),
        }
    except Exception:
        out = dict(BULLPEN_BASE)
    _evict_if_large(_team_pitch_cache, 300)
    _team_pitch_cache[key] = out
    return out


def _rank_staff_badge(composite_rank):
    r = int(composite_rank or 0)
    if r and r <= 5:
        return {'rank': r, 'label': 'Top 5 Staff', 'tone': 'top5', 'icon': '🔴'}
    if r and r >= 21:
        return {'rank': r, 'label': 'Bottom 10 Staff', 'tone': 'bottom10', 'icon': '🟢'}
    return {'rank': r or None, 'label': 'Mid-Pack', 'tone': 'mid', 'icon': '⚪'}


_team_pitch_rank_cache = {'data': None, 'byId': {}, 'ts': 0.0}
_team_pitch_rank_lock = threading.Lock()
_TEAM_PITCH_RANK_TTL = 30 * 60


def _get_team_pitching_rankings(force=False):
    now = time.time()
    with _team_pitch_rank_lock:
        cached = _team_pitch_rank_cache.get('data')
        cached_by_id = _team_pitch_rank_cache.get('byId') or {}
        ts = float(_team_pitch_rank_cache.get('ts') or 0)
    if (not force) and cached and (now - ts) < _TEAM_PITCH_RANK_TTL:
        return cached, cached_by_id

    teams_resp = requests.get(f"{MLB_API}/teams?sportId=1&activeStatus=Y", timeout=12)
    teams_resp.raise_for_status()
    teams_raw = [t for t in (teams_resp.json().get('teams') or []) if (t.get('sport') or {}).get('id') == 1]

    rows = []
    for t in teams_raw:
        tid = t.get('id')
        if not tid:
            continue
        ctx = team_pitching_context(tid)
        rows.append({
            'teamId': tid,
            'abbr': t.get('abbreviation', '?'),
            'name': t.get('name', ''),
            'era': round(float(ctx.get('era') or 0), 2),
            'whip': round(float(ctx.get('whip') or 0), 3),
            'k9': round(float(ctx.get('k9') or 0), 2),
            'hr9': round(float(ctx.get('hr9') or 0), 2),
        })

    if not rows:
        return [], {}

    era_rank = {r['teamId']: i + 1 for i, r in enumerate(sorted(rows, key=lambda x: x.get('era', 99)))}
    whip_rank = {r['teamId']: i + 1 for i, r in enumerate(sorted(rows, key=lambda x: x.get('whip', 99)))}
    k9_rank = {r['teamId']: i + 1 for i, r in enumerate(sorted(rows, key=lambda x: x.get('k9', -1), reverse=True))}
    hr9_rank = {r['teamId']: i + 1 for i, r in enumerate(sorted(rows, key=lambda x: x.get('hr9', 99)))}

    for r in rows:
        tid = r['teamId']
        r['era_rank'] = era_rank.get(tid)
        r['whip_rank'] = whip_rank.get(tid)
        r['k9_rank'] = k9_rank.get(tid)
        r['hr9_rank'] = hr9_rank.get(tid)
        composite = (r['era_rank'] + r['whip_rank'] + r['k9_rank'] + r['hr9_rank']) / 4.0
        r['composite_score'] = round(composite, 2)

    rows.sort(key=lambda x: (x.get('composite_score', 99), x.get('era_rank', 99), x.get('abbr', '')))
    for i, r in enumerate(rows, start=1):
        r['composite_rank'] = i

    by_id = {r['teamId']: r for r in rows}
    with _team_pitch_rank_lock:
        _team_pitch_rank_cache['data'] = rows
        _team_pitch_rank_cache['byId'] = by_id
        _team_pitch_rank_cache['ts'] = now
    return rows, by_id


_pitcher_stats_mlb_cache: dict = {}
_pitcher_stats_mlb_lock = threading.Lock()

def pitcher_stats_mlb(player_id):
    today = datetime.now().date().isoformat()
    cache_key = (player_id, today)
    with _pitcher_stats_mlb_lock:
        if cache_key in _pitcher_stats_mlb_cache:
            return _pitcher_stats_mlb_cache[cache_key]
    try:
        r = requests.get(f"{MLB_API}/people/{player_id}/stats?stats=season&group=pitching&season={datetime.now().year}", timeout=8)
        r.raise_for_status()
        splits = r.json().get("stats", [{}])[0].get("splits", [])
        prof = player_profile(player_id)
        if not splits:
            result = {'pitchHand': prof.get('throws', 'R')}
        else:
            s = splits[0].get("stat", {})
            result = {
                "era": s.get("era", "N/A"), "whip": s.get("whip", "N/A"),
                "ip": s.get("inningsPitched", "N/A"),
                "wins": s.get("wins", 0), "losses": s.get("losses", 0),
                "g": s.get("gamesPlayed", 0), "gs": s.get("gamesStarted", 0),
                "k9": round(float(s.get("strikeoutsPer9Inn", 0) or 0), 2),
                "bb9": round(float(s.get("walksPer9Inn", 0) or 0), 2),
                "hr9": round(float(s.get("homeRunsPer9", 0) or 0), 2),
                "pitchHand": prof.get('throws', 'R'),
            }
    except Exception:
        prof = player_profile(player_id)
        result = {'pitchHand': prof.get('throws', 'R')}
    with _pitcher_stats_mlb_lock:
        _evict_if_large(_pitcher_stats_mlb_cache, 200)
        _pitcher_stats_mlb_cache[cache_key] = result
    return result


def _load_local_pitcher_arsenal():
    """Load pitch arsenal stats from local FanGraphs CSVs into module-level cache.

    Reads fg*_pit*.csv files that contain real pitch-type usage columns.
    Steamer projection files (which lack these columns) are skipped.
    Called once at startup via _preload_caches() so _pitcher_model() never
    has to pay the 20-60s CSV-parse cost on the first request.
    """
    PITCH_TYPE_COLS = {
        'FA%','SI%','FC%','SL%','CU%','CH%','KC%','KN%','EP%','SC%','FO%',
        'PO%','XX%','CT%','CB%','SF%',
    }
    arsenal = {}
    velo = {}
    seen: set = set()
    paths = (
        _glob.glob(os.path.join("data", "fg*_pit*.csv"))
        + _glob.glob(os.path.join("data", "fg_pitching_*.csv"))
    )
    for path in paths:
        abs_path = os.path.abspath(path)
        if abs_path in seen:
            continue
        seen.add(abs_path)
        try:
            df = pd.read_csv(path)
            has_arsenal = any(c in PITCH_TYPE_COLS or c.endswith("_Velo") for c in df.columns)
            if not has_arsenal:
                continue
            for _, row in df.iterrows():
                pname = str(row.get("Name") or row.get("PlayerName") or row.get("player_name") or "").strip()
                if not pname:
                    continue
                key = _sv_key(pname)
                pitch_pct = {
                    k.replace("%", "").lower(): float(row[k])
                    for k in row.keys()
                    if k in PITCH_TYPE_COLS and pd.notnull(row[k])
                }
                pitch_velo = {
                    k.replace("_Velo", "").lower(): float(row[k])
                    for k in row.keys()
                    if k.endswith("_Velo") and pd.notnull(row[k])
                }
                if pitch_pct:
                    arsenal[key] = pitch_pct
                if pitch_velo:
                    velo[key] = pitch_velo
        except Exception as ex:
            logging.warning(f"[LocalArsenal] Failed to load {path}: {ex}")
    return arsenal, velo


def _pitcher_model(name, pid=None, team_id=None):
    global _local_arsenal_cache
    mlb = pitcher_stats_mlb(pid) if pid else {}

    # Grab a snapshot of all sv caches under _sv_lock (fast — dicts are already built).
    # The local arsenal load is done OUTSIDE _sv_lock to avoid holding the global
    # stats lock for the 2+ seconds it takes to iterate the FanGraphs CSV files.
    with _sv_lock:
        xs = dict(_sv_pit_xstats)
        ap = dict(_sv_arsenal_pct)
        av = dict(_sv_arsenal_velo)
        lx = _fuzzy_lookup(name, xs)
        r = dict(lx) if lx else {}
        lap = _fuzzy_lookup(name, ap)
        lav = _fuzzy_lookup(name, av)
        r["sv_arsenal_pct"] = lap if lap else {}
        r["sv_arsenal_velo"] = lav if lav else {}

    # Supplement missing arsenal data from local FanGraphs CSVs — done outside
    # _sv_lock so that other stat-lookup threads are not blocked during CSV parsing.
    if not r["sv_arsenal_pct"] or not r["sv_arsenal_velo"]:
        with _local_arsenal_lock:
            if _local_arsenal_cache is None:
                _local_arsenal_cache = _load_local_pitcher_arsenal()
            local_pct, local_velo = _local_arsenal_cache
        key = _sv_key(name)
        if not r["sv_arsenal_pct"] and key in local_pct:
            r["sv_arsenal_pct"] = local_pct[key]
        if not r["sv_arsenal_velo"] and key in local_velo:
            r["sv_arsenal_velo"] = local_velo[key]

    try:
        from brain_merge_patch import _brain_fuzzy, _brain_pit_overlay as _bpo
        with _brain_overlay_lock:
            brain = _brain_fuzzy(name, _bpo)
        for k, v in brain.items():
            if k not in r or r[k] in (None, "", "NA", "N/A"):
                r[k] = v
    except Exception:
        pass
    # Always ensure 'name' is set; merge MLB API stats as fallbacks for missing fields.
    # Normalize numeric pitch-stat keys to float so callers (e.g. _starter_outs_target,
    # _tier_blend) can do arithmetic without TypeError on "N/A" strings from the MLB API.
    r['name'] = name
    _PITCH_FLOAT_KEYS = {'era', 'whip', 'k9', 'bb9', 'hr9'}
    for k, v in mlb.items():
        if k not in r or r[k] in (None, "", "NA", "N/A"):
            r[k] = _num(v, BULLPEN_BASE.get(k, 0.0)) if k in _PITCH_FLOAT_KEYS else v
    r.setdefault('pitchHand', 'R')
    return r
def _tier_blend(tm, starter, w_tm, w_base, w_sp, mods):
    out = {}
    for k in ('era', 'whip', 'k9', 'bb9', 'hr9'):
        out[k] = _clamp(
            w_tm * _num(tm.get(k), BULLPEN_BASE[k]) +
            w_base * BULLPEN_BASE[k] +
            w_sp * _num(starter.get(k), BULLPEN_BASE[k]) +
            mods.get(k, 0),
            0.55 if k == 'hr9' else 0.0,
            1.9 if k == 'hr9' else 20.0
        )
    return out



def _bullpen_tiers(starter, team_id=None):
    tm = team_pitching_context(team_id)
    closer = _tier_blend(tm, starter, 0.65, 0.20, 0.15, {'era': -0.28, 'whip': -0.06, 'k9': 0.80, 'bb9': -0.15, 'hr9': -0.08})
    setup = _tier_blend(tm, starter, 0.62, 0.23, 0.15, {'era': -0.12, 'whip': -0.03, 'k9': 0.35, 'bb9': -0.05, 'hr9': -0.03})
    middle = _tier_blend(tm, starter, 0.58, 0.25, 0.17, {'era': 0.18, 'whip': 0.04, 'k9': -0.25, 'bb9': 0.10, 'hr9': 0.08})
    for name, model in [('Closer', closer), ('Setup', setup), ('Middle', middle)]:
        model['name'] = name
        model['pitchHand'] = starter.get('pitchHand', 'R')
    return {'closer': closer, 'setup': setup, 'middle': middle}
# Alias for legacy code
_parse_ip = parse_ip


def _starter_outs_target(starter, rng):
    mean = 16.5 + (4.1 - _num(starter.get('era'), 4.1)) * 1.2 + (_num(starter.get('k9'), 8.2) - 8.2) * 0.20 - max(0, _num(starter.get('whip'), 1.25) - 1.25) * 2.8
    mean = _clamp(mean, 12.0, 21.0)
    return int(_clamp(round(rng.gauss(mean, 2.4)), 9, 24))


def _platoon_adjustments(b, pitch_hand):
    bats = (b.get('bats') or 'S').upper()
    base_avg = _num(b.get('sv_xba'), _num(b.get('avg'), 0.245))
    base_ops = _num(b.get('ops'), 0.720)
    split_avg = None
    split_ops = None
    if pitch_hand == 'L':
        split_avg = _num(b.get('vs_l_avg'), 0)
        split_ops = _num(b.get('vs_l_ops'), 0)
    elif pitch_hand == 'R':
        split_avg = _num(b.get('vs_r_avg'), 0)
        split_ops = _num(b.get('vs_r_ops'), 0)
    hit_adj = 0.0; hr_adj = 0.0; k_adj = 0.0
    if split_avg > 0 and split_ops > 0:
        hit_adj += (split_avg - base_avg) * 0.65
        hr_adj += (split_ops - base_ops) * 0.10
        k_adj -= (split_avg - base_avg) * 1.6
    else:
        if bats == 'S':
            hit_adj += 0.008; hr_adj += 0.0015; k_adj -= 0.008
        elif (bats == 'L' and pitch_hand == 'R') or (bats == 'R' and pitch_hand == 'L'):
            hit_adj += 0.010; hr_adj += 0.0020; k_adj -= 0.012
        else:
            hit_adj -= 0.008; hr_adj -= 0.0015; k_adj += 0.010
    return hit_adj, hr_adj, k_adj


# ── BAT X for Simulation ──────────────────────────────────────────────────────
# Lightweight wrapper: computes per-batter composite + component adjustments
# **once** before the simulation loop (not every PA) and returns a multiplier dict
# that _derive_probs_batx() applies to PA outcome probabilities.
def _batx_for_sim(batter, opp_pitcher, park, weather):
    """
    Returns a dict with:
      composite   float  overall multiplier (e.g. 1.08 = 8% above neutral)
      hit_mult    float  hit probability multiplier
      hr_mult     float  HR probability multiplier
      walk_mult   float  walk probability multiplier
      k_mult      float  strikeout probability multiplier
    All clamped conservatively so no single batter swings MC by more than ±25%.
    """
    try:
        opp_fg = fg_pitcher(opp_pitcher.get('name', ''))
        opp_sv = sv_pitcher(opp_pitcher.get('name', ''))
        pitcher_hand = (opp_pitcher.get('pitchHand') or 'R').upper()
        # Pull rolling form + head-to-head BvP so the BATX "form" (0.07) and
        # "bvp" (0.01) weights actually fire during simulation. Both helpers
        # are daily-cached, so this is one MLB Stats API call per batter on
        # cold start and free afterwards.
        bid = batter.get('id') or batter.get('mlb_id')
        opp_pid = opp_pitcher.get('id')
        try:
            form = _fetch_rolling_form(bid, False) if bid else None
        except Exception:
            form = None
        try:
            bvp = _fetch_bvp(bid, opp_pid) if (bid and opp_pid) else None
        except Exception:
            bvp = None
        proj = _project_batter_batx(
            batter, opp_pitcher.get('name', ''), opp_fg, opp_sv,
            park, weather or {}, pitcher_hand=pitcher_hand,
            opp_pitcher_id=opp_pid,
            form=form, bvp=bvp,
            def_factor=_def_factor_for_pitcher(opp_pid),
        )
        adj = proj.get('adjustments', {})
        comp = _clamp(proj.get('composite', 1.0), 0.70, 1.30)

        # Contact quality → hit rate
        contact  = adj.get('contact',    0.0)
        power    = adj.get('power',       0.0)
        disc     = adj.get('discipline',  0.0)
        platoon  = adj.get('platoon',     0.0)
        form     = adj.get('form',        0.0)
        bvp      = adj.get('bvp',         0.0)
        pitcher  = adj.get('pitcher',     0.0)

        hit_boost  = _clamp(1.0 + contact*3.5 + platoon*2.0 + form*2.5 + bvp*2.0 + pitcher*1.5, 0.75, 1.25)
        hr_boost   = _clamp(1.0 + power*4.0   + platoon*1.5 + form*2.0 + bvp*1.5,               0.60, 1.40)
        walk_boost = _clamp(1.0 + disc*4.0    + platoon*1.0,                                     0.75, 1.25)
        k_boost    = _clamp(1.0 - disc*3.0    - contact*2.0 - form*1.5,                          0.78, 1.22)

        return {
            'composite': comp,
            'hit_mult':  hit_boost,
            'hr_mult':   hr_boost,
            'walk_mult': walk_boost,
            'k_mult':    k_boost,
            'adjustments': dict(adj),
        }
    except Exception:
        return {'composite': 1.0, 'hit_mult': 1.0, 'hr_mult': 1.0, 'walk_mult': 1.0, 'k_mult': 1.0, 'adjustments': {}}


def _derive_probs(b, p, park=1.0, batx=None):
    avg = _num(b.get('sv_xba'), _num(b.get('avg'), 0.245))
    obp = _num(b.get('obp'), max(avg + 0.060, 0.290))
    slg = _num(b.get('sv_xslg'), _num(b.get('slg'), 0.400))
    xwoba = _num(b.get('sv_xwoba'), _num(b.get('fg_woba'), 0.320))
    ev = _num(b.get('sv_ev'), 87.5)
    hh = _num(b.get('sv_hh_pct'), 37.0)
    brl = _num(b.get('sv_brl_pct'), 5.5)
    wrc = _num(b.get('fg_wrc'), 100.0)
    sb_total = _num(b.get('fg_sb'), 6)

    era = _num(p.get('era'), 4.25)
    whip = _num(p.get('whip'), 1.28)
    k9 = _num(p.get('k9'), 8.4)
    bb9 = _num(p.get('bb9'), 3.2)
    hr9 = _num(p.get('hr9'), 1.10)
    pitch_hand = (p.get('pitchHand') or 'R').upper()

    hand_hit, hand_hr, hand_k = _platoon_adjustments(b, pitch_hand)

    hit_rate = avg + (xwoba - 0.320) * 0.30 + (ev - 87.5) * 0.003 + (hh - 37.0) * 0.0016 + (wrc - 100) * 0.00035
    hit_rate += (whip - 1.28) * 0.055 - (era - 4.25) * 0.010 + (park - 1.0) * 0.030 + hand_hit
    hit_rate = _clamp(hit_rate, 0.13, 0.35)

    walk_rate = max(obp - avg, 0.045) + (bb9 - 3.2) * 0.010
    if pitch_hand == 'L' and (b.get('bats') or 'S') == 'L':
        walk_rate += 0.002
    walk_rate = _clamp(walk_rate, 0.04, 0.15)

    hr_rate = 0.018 + max(0, brl - 6.0) * 0.0035 + max(0, ev - 89.0) * 0.0017 + max(0, slg - 0.420) * 0.060
    hr_rate += (hr9 - 1.10) * 0.020 + (park - 1.0) * 0.050 + hand_hr
    hr_rate = _clamp(hr_rate, 0.005, min(0.095, hit_rate * 0.45))

    dbl_rate = 0.040 + max(0, slg - avg - 0.150) * 0.12 + max(0, ev - 88.0) * 0.002
    dbl_rate = _clamp(dbl_rate, 0.020, min(0.110, hit_rate * 0.40))

    trp_rate = _clamp(0.004 + max(0, avg - 0.270) * 0.04 + (park - 1.0) * 0.005, 0.001, 0.020)
    trp_rate = min(trp_rate, max(0.001, hit_rate - hr_rate - dbl_rate - 0.02))

    single_rate = max(0.05, hit_rate - hr_rate - dbl_rate - trp_rate)
    k_rate = 0.175 + (k9 - 8.2) * 0.018 - (avg - 0.245) * 0.35 - (hh - 37) * 0.002 + hand_k
    k_rate = _clamp(k_rate, 0.09, 0.36)

    steal_rate = 0.010 + max(0, sb_total - 8) * 0.002 + max(0, wrc - 100) * 0.00015
    if (b.get('bats') or 'S') == 'L':
        steal_rate += 0.003
    steal_rate = _clamp(steal_rate, 0.003, 0.075)
    steal_success = _clamp(0.63 + max(0, sb_total - 8) * 0.01 + max(0, avg - 0.250) * 0.4, 0.58, 0.88)

    out_rate = 1.0 - (walk_rate + single_rate + dbl_rate + trp_rate + hr_rate)
    if out_rate < 0.28:
        scale = (1.0 - 0.28) / max(0.01, 1.0 - out_rate)
        walk_rate *= scale; single_rate *= scale; dbl_rate *= scale; trp_rate *= scale; hr_rate *= scale
        out_rate = 1.0 - (walk_rate + single_rate + dbl_rate + trp_rate + hr_rate)
    k_share = _clamp(k_rate / max(out_rate, 0.001), 0.18, 0.72)

    # ── BAT X Integration ─────────────────────────────────────────────────────
    # Apply matchup-aware multipliers computed once per batter from the BAT X engine.
    # This makes every simulated PA reflect platoon, park, form, BvP, and pitcher
    # resistance instead of only season averages.
    if batx:
        hit_m  = batx.get('hit_mult',  1.0)
        hr_m   = batx.get('hr_mult',   1.0)
        walk_m = batx.get('walk_mult', 1.0)
        k_m    = batx.get('k_mult',    1.0)
        # Scale hit types preserving internal ratios
        new_single = _clamp(single_rate * hit_m, 0.03, 0.30)
        new_dbl    = _clamp(dbl_rate    * hit_m, 0.01, 0.12)
        new_trp    = _clamp(trp_rate    * hit_m, 0.001, 0.022)
        new_hr     = _clamp(hr_rate     * hr_m,  0.003, 0.10)
        new_bb     = _clamp(walk_rate   * walk_m, 0.04, 0.16)
        new_out    = max(0.28, 1.0 - (new_single + new_dbl + new_trp + new_hr + new_bb))
        new_k_share = _clamp(k_share * k_m, 0.18, 0.75)
        return {
            'bb': new_bb, '1b': new_single, '2b': new_dbl, '3b': new_trp, 'hr': new_hr,
            'out': new_out, 'kshare': new_k_share, 'steal_rate': steal_rate, 'steal_success': steal_success
        }

    return {
        'bb': walk_rate, '1b': single_rate, '2b': dbl_rate, '3b': trp_rate, 'hr': hr_rate,
        'out': out_rate, 'kshare': k_share, 'steal_rate': steal_rate, 'steal_success': steal_success
    }


def _pick_event(probs, rng):
    r = rng.random(); acc = 0.0
    for ev in ['bb', '1b', '2b', '3b', 'hr', 'out']:
        acc += probs[ev]
        if r <= acc:
            if ev == 'out' and rng.random() < probs['kshare']:
                return 'k'
            return ev
    return 'out'


def _normalize_pa_probs(probs):
    normalized = dict(probs or {})
    non_out_total = (
        float(normalized.get('bb', 0.0) or 0.0)
        + float(normalized.get('1b', 0.0) or 0.0)
        + float(normalized.get('2b', 0.0) or 0.0)
        + float(normalized.get('3b', 0.0) or 0.0)
        + float(normalized.get('hr', 0.0) or 0.0)
    )
    normalized['out'] = max(0.28, 1.0 - non_out_total)
    normalized['kshare'] = _clamp(float(normalized.get('kshare', 0.18) or 0.18), 0.18, 0.78)
    return normalized


# ─────────────────────────────────────────────────────────────────────────────
# MC UPGRADES — inlined from mc_upgrades.py
# Phases 1-9: Weather, Umpire, Antithetic Variates, TTOP Decay,
#             Platoon Regression, BatX Pitcher Form, Cache Pre-warming,
#             Log-Odds Market Blending, Markov Runner Advancement.
# ─────────────────────────────────────────────────────────────────────────────

# Venues with humidors that suppress HR beyond altitude correction
HUMIDOR_VENUES = {19, 15}   # Coors (19), Chase (15)

_COMPASS_DEG = {"N":0,"NNE":22.5,"NE":45,"ENE":67.5,"E":90,"ESE":112.5,
                "SE":135,"SSE":157.5,"S":180,"SSW":202.5,"SW":225,"WSW":247.5,
                "W":270,"WNW":292.5,"NW":315,"NNW":337.5}


def _wind_along_spray(wind_spd: float, wind_dir: str, venue_id: int) -> float:
    """
    Returns signed wind speed (mph) along the home-plate → CF axis.
    Positive = out (boost), negative = in (suppress).

    `wind_dir` is the meteorological compass heading the wind blows FROM
    (Open-Meteo convention) — the ball is carried toward the OPPOSITE
    heading, so rotate 180° before projecting onto the park's CF bearing.
    Uses PARK_CF_BEARING (the same table `_wind_field_geometry` / the UI's
    `wind_out` are built from) so the model and the displayed wind arrow can
    never disagree about out vs in. Unmapped venue or unknown compass
    direction → 0.0: neutral, never a directional guess.
    """
    if not wind_dir or not wind_spd or wind_spd <= 0:
        return 0.0
    try:
        bearing = PARK_CF_BEARING.get(int(venue_id or 0))
    except (TypeError, ValueError):
        bearing = None
    if bearing is None:
        return 0.0
    wind_from = _COMPASS_DEG.get(wind_dir.strip().upper())
    if wind_from is None:
        return 0.0
    to_deg = (wind_from + 180.0) % 360.0
    return wind_spd * math.cos(math.radians(to_deg - bearing))


def build_weather_multipliers(wx: dict, venue_id: int, park_factor: float) -> dict:
    """
    Phase 1A: Physics-grade weather multipliers for Monte Carlo.

    Returns dict with keys:
        hr_mult   — multiply per-PA HR probability
        hit_mult  — multiply per-PA hit probability
        run_mult  — multiply projected runs (applied at team level)
        carry_ft  — additional carry in feet (informational)
        dome      — True if indoor, bypass all adjustments

    IMPORTANT: park_factor is the BASELINE (geometry/altitude).
    Weather adjustments are applied as DEVIATIONS — do not double-count
    by applying raw weather on top of weather-inclusive seasonal PF.
    The seasonal PF already reflects the park's average weather.
    We only apply the *delta* from average conditions.
    """
    if wx.get("dome"):
        return {"hr_mult": 1.0, "hit_mult": 1.0, "run_mult": 1.0,
                "carry_ft": 0.0, "dome": True}

    # ── Temperature (delta from 70°F park-average baseline) ────────────────────
    try:
        temp_f = float(wx.get("temp", 70))
    except (TypeError, ValueError):
        temp_f = 70.0
    temp_f = max(20.0, min(110.0, temp_f))
    temp_delta = temp_f - 70.0   # positive = warmer than average

    # Nathan 2017: +1.0%/°F for HR, empirical ~0.6%/°F (use 0.8% as compromise)
    hr_temp_mult = 1.0 + temp_delta * 0.008
    # Run scoring: more muted
    run_temp_mult = 1.0 + temp_delta * 0.004

    # ── Wind (along-spray component) ────────────────────────────────────────
    try:
        wind_spd = float(wx.get("wind_speed", 0) or 0)
    except (TypeError, ValueError):
        wind_spd = 0.0
    wind_dir = str(wx.get("wind_dir", "") or "")

    # Prefer the payload's precomputed signed out-component (`wind_out`, from
    # _wind_field_geometry): it uses the exact forecast degrees rather than
    # the 16-point compass string. Fall back to reconstructing from compass.
    try:
        along = float(wx["wind_out"]) if wx.get("wind_out") is not None else \
            _wind_along_spray(wind_spd, wind_dir, venue_id)
    except (TypeError, ValueError, KeyError):
        along = _wind_along_spray(wind_spd, wind_dir, venue_id)
    # +3.5 ft/mph along-spray → convert to HR prob multiplier
    # Typical HR margin ~5 ft → each 1.4 ft carry ≈ 1% more HR land
    carry_ft = along * 3.5
    hr_wind_mult = 1.0 + along * 0.004   # ~+0.4%/mph out, −0.4%/mph in
    hr_wind_mult = max(0.82, min(1.22, hr_wind_mult))

    # ── Humidor correction (suppresses HR ~20-25% beyond altitude) ───────────
    humidor_mult = 0.97 if venue_id in HUMIDOR_VENUES else 1.0

    # ── Combine ───────────────────────────────────────────────────────────────────
    hr_mult  = max(0.75, min(1.35, hr_temp_mult * hr_wind_mult * humidor_mult))
    hit_mult = max(0.92, min(1.08, 1.0 + temp_delta * 0.002))  # hits much less sensitive
    run_mult = max(0.88, min(1.12, run_temp_mult * (1.0 + along * 0.002)))

    return {
        "hr_mult":   round(hr_mult,  4),
        "hit_mult":  round(hit_mult, 4),
        "run_mult":  round(run_mult, 4),
        "carry_ft":  round(carry_ft, 1),
        "dome":      False,
        "temp_f":    round(temp_f, 1),
        "wind_spd":  round(wind_spd, 1),
        "wind_along": round(along, 1),
    }


# ─────────────────────────────────────────────────────────────────────────────
# PHASE 1B — UMPIRE K%/BB% ADJUSTMENTS
# Research basis (UmpScorecards / SABR / Berkeley):
#   Inter-umpire SD ≈ 0.20 R/game → K_mult SD ~0.04, BB_mult SD ~0.05
#   Regress 50% to 1.0 if games_sampled < 30
#   Elite framing catcher adds ~±3.9 pp K%, −3.9 pp BB% (interact multiplicatively)
# ─────────────────────────────────────────────────────────────────────────────

LG_K_PER_TEAM  = 8.5   # league-average K per team per game
LG_BB_PER_TEAM = 3.0   # league-average BB per team per game


def build_ump_sim_adjustments(zone_rating: float | None,
                               avg_k_per_team: float | None,
                               avg_bb_per_team: float | None,
                               games_sampled: int) -> dict:
    """
    Phase 1B: Convert umpire zone stats to K%/BB% multipliers for simulation.

    Args:
        zone_rating:     0-100 (from _ump_cache, 50=neutral, >65=pitcher-friendly)
        avg_k_per_team:  from ump history (or None)
        avg_bb_per_team: from ump history (or None)
        games_sampled:   number of games in ump sample

    Returns dict: {k_mult, bb_mult, run_mult, zone_rating}
    """
    if avg_k_per_team is None or games_sampled == 0:
        return {"k_mult": 1.0, "bb_mult": 1.0, "run_mult": 1.0, "zone_rating": 50}

    # Shrink toward 1.0 based on sample size
    # Full weight at 80+ games; 50% at 30 games; zero below 15
    confidence = min(1.0, max(0.0, (games_sampled - 15) / 65.0))

    raw_k_mult  = avg_k_per_team  / LG_K_PER_TEAM
    raw_bb_mult = avg_bb_per_team / LG_BB_PER_TEAM

    # Regress toward 1.0
    k_mult  = 1.0 + (raw_k_mult  - 1.0) * confidence
    bb_mult = 1.0 + (raw_bb_mult - 1.0) * confidence

    # Hard clamps: inter-umpire variation realistically ±12% K, ±15% BB
    k_mult  = max(0.88, min(1.12, k_mult))
    bb_mult = max(0.85, min(1.15, bb_mult))

    # Run environment shift: more K + fewer BB = fewer runs
    # Approx: each 1 BB ≈ 0.35 R; each 1 K ≈ -0.05 R (weak, already in outs)
    k_delta  = (avg_k_per_team  - LG_K_PER_TEAM)  * confidence
    bb_delta = (avg_bb_per_team - LG_BB_PER_TEAM) * confidence
    run_mult = max(0.92, min(1.08, 1.0 - k_delta * 0.008 + bb_delta * 0.035))

    return {
        "k_mult":      round(k_mult,  4),
        "bb_mult":     round(bb_mult, 4),
        "run_mult":    round(run_mult, 4),
        "zone_rating": zone_rating or 50,
        "confidence":  round(confidence, 3),
        "games":       games_sampled,
    }


# ─────────────────────────────────────────────────────────────────────────────
# PHASE 2 — TTOP CONTINUOUS DECAY
# Research basis (Tango/Lichtman, Brill JQAS 2023):
#   1st TTO baseline, +9 wOBA pts 2nd TTO, +8 more 3rd TTO (~+17 cumulative)
#   Brill: smooth function of batters faced, not discrete tiers
#   Arsenal scale: ×1.7 for 1-pitch SP, ×0.8 for 4+ pitch SP
#   Pitch count tail: +0.015 wOBA per pitch above 75
# ─────────────────────────────────────────────────────────────────────────────

def ttop_woba_penalty(batters_faced: int,
                      pitches_thrown: int,
                      arsenal_size: int = 3) -> float:
    """
    Continuous TTOP (Time Through Order Penalty) as wOBA-against delta.
    Returns positive value = batters hit better by this amount.

    arsenal_size: number of distinct pitch types (1=1-pitch, 4+=multi-arsenal)
    """
    # Smooth TTOP: quadratic in batters_faced
    # 0 BF=0, 9 BF≈10 pts, 18 BF≈17 pts, 27 BF≈25 pts
    ttop_base = min(0.030, (batters_faced / 27.0) ** 1.4 * 0.030)

    # Arsenal scale
    if arsenal_size <= 1:
        arsenal_scale = 1.7
    elif arsenal_size <= 2:
        arsenal_scale = 1.2
    elif arsenal_size >= 4:
        arsenal_scale = 0.8
    else:
        arsenal_scale = 1.0

    ttop = ttop_base * arsenal_scale

    # Pitch-count tail: fatigue beyond 75 pitches
    pitch_tail = max(0.0, (pitches_thrown - 75) * 0.00015)

    return round(min(0.050, ttop + pitch_tail), 4)


def relief_fatigue_penalty(days_pitched: list,
                           pitches_last: int = 20) -> float:
    """
    Reliever back-to-back penalty in wOBA-against delta.
    days_pitched: list of days ago (0=today, 1=yesterday, etc.)
    Research: B2B ≈ +10-15 wOBA pts; 3rd consecutive ≈ +20-30 pts
    """
    if not days_pitched:
        return 0.0
    min_rest = min(days_pitched) if days_pitched else 3
    if min_rest == 0:
        return 0.020 + min(0.015, pitches_last * 0.0003)
    if min_rest == 1 and len([d for d in days_pitched if d <= 2]) >= 2:
        return 0.015   # back-to-back appearances in last 2 days
    if min_rest == 1:
        return 0.010
    if min_rest == 2 and pitches_last >= 35:
        return 0.008
    return 0.0


# ─────────────────────────────────────────────────────────────────────────────
# PHASE 3 — PLATOON REGRESSION (canonical Tango constants)
# Research basis (The Book, FanGraphs Hardball Times):
#   LHB M=1000 PA, RHB M=2200 PA, Switch M=1620 PA
#   League splits (wOBA delta same vs opposite hand):
#     LHB: +35 pts, RHB: +23 pts, Switch: +27 pts (2008-2022 recalibration)
# ─────────────────────────────────────────────────────────────────────────────

PLATOON_M = {"L": 1000, "R": 2200, "S": 1620}

LEAGUE_PLATOON_SPLITS = {
    # wOBA delta: favorable vs unfavorable handedness matchup
    "L":  0.035,    # LHB vs RHP advantage (LHB hits .035 wOBA better vs RHP)
    "R":  0.023,    # RHB vs LHP advantage
    "S":  0.027,    # switch hitter advantage (use favorable side)
}

# League-average values used as the Bayesian shrinkage target in platoon_blend_v2.
# FIX: previously used the player's own season stat as the prior (season_val * M),
# which inflated split estimates for high-average batters and defeated the
# entire purpose of Tango's regression-to-league-mean constants.
_LEAGUE_AVG_PRIOR = {
    "avg":  0.248,
    "obp":  0.317,
    "slg":  0.397,
    "ops":  0.714,
    "woba": 0.320,
}

_STAT_DEFAULTS_V2 = {
    "avg": 0.245, "obp": 0.315, "slg": 0.390, "ops": 0.705, "woba": 0.320
}


def platoon_blend_v2(batter: dict, pitcher_hand: str, stat: str) -> float:
    """
    Phase 3: Proper Bayesian-regressed platoon blend.
    Replaces current _platoon_blend() in app.py.

    Uses canonical Tango regression constants — observed splits with small PA
    are shrunk toward LEAGUE-AVERAGE (not the player's own season stat).

    FIX: Prior was `season_val * M` — now correctly `lg_avg * M`.
    A .310 hitter with 30 vs-LHP PA previously had their split pulled toward
    .310 instead of .248, completely defeating the shrinkage purpose.
    """
    bats = (batter.get("bats") or "S").upper()
    hand = (pitcher_hand or "R").upper()
    if hand not in ("L", "R"):
        hand = "R"

    # Pick correct vs-hand split key
    split_key = f"vs_{'l' if hand == 'L' else 'r'}_{stat}"
    pa_key    = f"vs_{'l' if hand == 'L' else 'r'}_pa"

    obs_split = batter.get(split_key)
    split_pa  = int(batter.get(pa_key, 0) or 0)

    # Season (unhandedness-adjusted) value — used only for no-data fallback
    season_map = {
        "avg":  batter.get("avg")  or batter.get("fg_avg"),
        "obp":  batter.get("obp")  or batter.get("fg_obp"),
        "slg":  batter.get("slg")  or batter.get("fg_slg"),
        "ops":  batter.get("ops"),
        "woba": batter.get("fg_woba") or batter.get("sv_xwoba"),
    }
    season_val = float(season_map.get(stat) or _STAT_DEFAULTS_V2.get(stat, 0.0) or 0.0)

    # Helper to check if obs_split is a valid float
    def _is_valid_float(val):
        try:
            return float(val) > 0.0
        except (TypeError, ValueError):
            return False

    if obs_split is None or not _is_valid_float(obs_split):
        # No split data — apply theoretical league platoon advantage
        platoon_favorable = (
            (bats == "L" and hand == "R") or
            (bats == "R" and hand == "L") or
            bats == "S"
        )
        if stat in ("avg", "obp", "slg", "ops", "woba"):
            lg_edge = LEAGUE_PLATOON_SPLITS.get(bats, 0.025)
            # Season stat is a mix of both hands, so half the edge
            if platoon_favorable:
                return round(season_val + lg_edge * 0.5, 4)
            else:
                return round(season_val - lg_edge * 0.5, 4)
        return season_val

    obs_val = float(obs_split)
    M = PLATOON_M.get(bats, 1620)

    # Bayesian shrinkage: blend observed split with LEAGUE AVERAGE (correct prior).
    # FIX: was `(obs_val * split_pa + season_val * M) / (split_pa + M)`
    # which used the player's own season stat as the shrinkage target.
    lg_avg = _LEAGUE_AVG_PRIOR.get(stat, _STAT_DEFAULTS_V2.get(stat, 0.0))
    blended = (obs_val * split_pa + lg_avg * M) / (split_pa + M)
    return round(blended, 4)


# ─────────────────────────────────────────────────────────────────────────────
# PHASE 4 — UPDATED BATX WEIGHTS + PITCHER RECENT FORM WIRING
# Research: Barrel/EV most predictive for HR/TB (r²=0.382 brl vs future HR)
#           L7 wOBA is meaningful signal; BvP too noisy with small samples
# ─────────────────────────────────────────────────────────────────────────────

BATX_WEIGHTS_V2 = {
    "contact":    0.26,   # platoon-blended AVG + xBA  (unchanged)
    "power":      0.22,   # ISO, brl%, EV, xSLG        (unchanged — most predictive for HR/TB)
    "discipline": 0.12,   # BB%, K%, xwOBA             (unchanged)
    "platoon":    0.11,   # hand matchup edge           (+0.01 — most reliable split predictor)
    "park":       0.07,   # park factor                 (unchanged)
    "weather":    0.05,   # temp/wind                   (unchanged)
    "pitcher":    0.11,   # FIP/xERA/K% + recent form   (unchanged)
    "form":       0.07,   # L7 wOBA edge vs league      (unchanged)
    "bvp":        0.01,   # BvP shrunk wOBA × recency-reliability (-0.01 — small-sample H2H too noisy)
    "pitch_mix":  0.04,   # arsenal-weighted SLG matchup score (NEW — granular skill-based signal)
}


def pitcher_component_v2(opp_pitcher_fg: dict,
                          opp_pitcher_sv: dict,
                          recent_form: dict | None) -> tuple:
    """
    Phase 4: Blended pitcher resistance — 60% season + 40% recent form.
    Returns (pitcher_mult, k_resistance) where:
        pitcher_mult > 1 = pitcher is weaker than average (batter benefits)
        pitcher_mult < 1 = pitcher is stronger (batter penalized)
        k_resistance: fraction of season K% to apply (recent K% may differ)
    """
    def _f(v, d=0.0):
        try:
            f = float(v)
            return f if f == f else d
        except Exception:
            return d

    season_era  = _f(opp_pitcher_fg.get("fg_era")  or opp_pitcher_sv.get("sv_era_p"), 4.20)
    season_fip  = _f(opp_pitcher_fg.get("fg_fip"),  season_era)
    season_xera = _f(opp_pitcher_sv.get("sv_xera"), season_era)
    season_kpct = _f(opp_pitcher_fg.get("fg_kpct") or opp_pitcher_sv.get("sv_k_pct"), 0.22)

    if recent_form and isinstance(recent_form, dict) and recent_form.get("era_recent"):
        W_RECENT = 0.40
        era_blended  = 0.60 * season_era  + W_RECENT * recent_form["era_recent"]
        k9_recent    = recent_form.get("k9_recent", season_kpct * 9)
        kpct_recent  = min(0.40, k9_recent / 27.0)  # rough PA→k conversion
        kpct_blended = 0.60 * season_kpct + W_RECENT * kpct_recent
    else:
        era_blended  = (season_era + season_fip + season_xera) / 3.0
        kpct_blended = season_kpct

    pit_mult = min(1.30, max(0.72, era_blended / 4.20))
    return round(pit_mult, 4), round(kpct_blended, 4)


# ─────────────────────────────────────────────────────────────────────────────
# PHASE 6 — LOG-ODDS MARKET BLENDING
# Research (Trademate, Lopez/Matthews/Glickman arXiv:1701.05976):
#   Blend in log-odds space; weight table by market efficiency tier
#   Always de-vig (power method) before blending
# ─────────────────────────────────────────────────────────────────────────────

MARKET_MODEL_WEIGHTS = {
    # w = model weight (1-w = market weight)
    # Higher w = trust model more (less efficient market)
    "batter_hits":           0.35,
    "batter_total_bases":    0.35,
    "batter_home_runs":      0.30,
    "pitcher_strikeouts":    0.30,
    "batter_rbis":           0.40,
    "batter_runs_scored":    0.40,
    "batter_hits_runs_rbis": 0.40,
    "batter_stolen_bases":   0.45,
    "nrfi":                  0.35,
    "yrfi":                  0.40,
    # Full-game moneyline/totals markets are among the most efficient in all
    # of sports betting (deep, heavily-traded, closely watched by sharps) —
    # trust the market far more than the in-house sim here.
    "h2h":                   0.20,
    "totals":                0.20,
    # First-5 markets are thinner/less efficient than full-game.
    "f5_h2h":                0.30,
    "f5_totals":             0.30,
    # Alt-lines/micro-props — model dominates
    "default":               0.50,
}


def devig_power(over_implied: float, under_implied: float) -> tuple:
    """
    Power method de-vig (Shin 1993 style for asymmetric lines).
    Finds k such that over_implied^(1/k) + under_implied^(1/k) = 1.
    Returns (fair_over, fair_under).
    """
    if not over_implied or not under_implied or over_implied <= 0 or under_implied <= 0:
        return over_implied, under_implied
    # Binary search for k
    lo, hi = 0.5, 3.0
    for _ in range(50):
        k = (lo + hi) / 2.0
        s = over_implied ** (1.0 / k) + under_implied ** (1.0 / k)
        if s > 1.0:
            hi = k
        else:
            lo = k
    k = (lo + hi) / 2.0
    return round(over_implied ** (1.0 / k), 6), round(under_implied ** (1.0 / k), 6)


def logit_blend_prob(p_model: float,
                     p_market: float,
                     market_key: str,
                     over_implied: float | None = None,
                     under_implied: float | None = None) -> float:
    """
    Phase 6: Blend model probability with (de-vigged) market probability
    in log-odds space.

    If over_implied + under_implied provided, de-vigs first via power method.
    Returns blended probability.
    """
    def _safe_logit(p):
        p = max(0.001, min(0.999, p))
        return math.log(p / (1.0 - p))

    def _sigmoid(x):
        return 1.0 / (1.0 + math.exp(-x))

    # Learned per-market weight when enough graded history exists; the
    # hand-tuned MARKET_MODEL_WEIGHTS entry is the prior it shrinks toward.
    w = _blend_weight_for(market_key)

    # De-vig market probability if raw over/under implied given
    if over_implied and under_implied and over_implied > 0 and under_implied > 0:
        p_market_fair, _ = devig_power(over_implied, under_implied)
        p_market = p_market_fair if p_market_fair > 0 else p_market

    if not p_market or p_market <= 0:
        return round(max(0.01, min(0.99, p_model)), 4)

    blended_logit = w * _safe_logit(p_model) + (1.0 - w) * _safe_logit(p_market)
    return round(_sigmoid(blended_logit), 4)


# ─────────────────────────────────────────────────────────────────────────────
# PHASE 2B — ENHANCED _derive_probs WITH ALL PHASE 1/2/3 ADJUSTMENTS
# Drop-in replacement for app.py _derive_probs()
# New params: wx_mults, ump_adj, ttop_penalty_val, batx=None
# ─────────────────────────────────────────────────────────────────────────────

def derive_probs_v2(b: dict, p: dict, park: float = 1.0,
                    batx: dict | None = None,
                    wx_mults: dict | None = None,
                    ump_adj: dict | None = None,
                    ttop_penalty_val: float = 0.0) -> dict:
    """
    Phase 2B: Enhanced probability derivation.
    Extends existing _derive_probs() with:
      - wx_mults from build_weather_multipliers()  [Phase 1A]
      - ump_adj from build_ump_sim_adjustments()   [Phase 1B]
      - ttop_penalty_val from ttop_woba_penalty()  [Phase 2]

    All existing logic preserved; new multipliers applied on top.

    FIX (Bug 1): hit_mult now applied to singles, doubles, AND triples.
    Previously only single_rate was multiplied; doubles and triples were
    left at base rates, under-representing warm/wind-out conditions.
    """
    # ── Base probabilities (existing logic, inlined for portability) ───────────
    def _n(v, d=0.0):
        try:
            f = float(v)
            return f if f == f else d
        except Exception:
            return d

    def _cl(v, lo, hi):
        return max(lo, min(hi, v))

    avg  = _n(b.get("sv_xba"),    _n(b.get("avg"),    0.245))
    obp  = _n(b.get("obp"),       max(avg + 0.060, 0.290))
    slg  = _n(b.get("sv_xslg"),   _n(b.get("slg"),    0.400))
    xwoba = _n(b.get("sv_xwoba"), _n(b.get("fg_woba"), 0.320))
    ev   = _n(b.get("sv_ev"),     87.5)
    hh   = _n(b.get("sv_hh_pct"), 37.0)
    brl  = _n(b.get("sv_brl_pct"), 5.5)
    wrc  = _n(b.get("fg_wrc"),    100.0)
    sb   = _n(b.get("fg_sb"),     6)

    era  = _n(p.get("era"),  4.25)
    whip = _n(p.get("whip"), 1.28)
    k9   = _n(p.get("k9"),   8.4)
    bb9  = _n(p.get("bb9"),  3.2)
    hr9  = _n(p.get("hr9"),  1.10)
    pitch_hand = (p.get("pitchHand") or "R").upper()

    # Platoon (use v2 if possible)
    bats = (b.get("bats") or "S").upper()
    hand = pitch_hand
    if bats != "S":
        platoon_k = 0.97 if ((bats=="L" and hand=="R") or (bats=="R" and hand=="L")) else 1.03
        platoon_hit = 0.010 if ((bats=="L" and hand=="R") or (bats=="R" and hand=="L")) else -0.008
    else:
        platoon_k = 1.0; platoon_hit = 0.008

    # TTOP wOBA penalty → increases hit rate against fatigued pitcher
    ttop_boost = ttop_penalty_val  # wOBA units → directly boosts hit rate

    hit_rate = avg + (xwoba-0.320)*0.30 + (ev-87.5)*0.003 + (hh-37.0)*0.0016 \
             + (wrc-100)*0.00035 + (whip-1.28)*0.055 - (era-4.25)*0.010 \
             + (park-1.0)*0.030 + platoon_hit + ttop_boost * 0.6
    hit_rate = _cl(hit_rate, 0.13, 0.35)

    walk_rate = max(obp-avg, 0.045) + (bb9-3.2)*0.010
    walk_rate = _cl(walk_rate, 0.04, 0.15)

    hr_rate = 0.018 + max(0, brl-6.0)*0.0035 + max(0, ev-89.0)*0.0017 \
            + max(0, slg-0.420)*0.060 + (hr9-1.10)*0.020 + (park-1.0)*0.050
    hr_rate = _cl(hr_rate, 0.005, min(0.095, hit_rate*0.45))

    dbl_rate = _cl(0.040 + max(0,slg-avg-0.150)*0.12 + max(0,ev-88.0)*0.002,
                   0.020, min(0.110, hit_rate*0.40))
    trp_rate = _cl(0.004 + max(0,avg-0.270)*0.04 + (park-1.0)*0.005,
                   0.001, 0.020)
    trp_rate = min(trp_rate, max(0.001, hit_rate-hr_rate-dbl_rate-0.02))
    single_rate = max(0.05, hit_rate-hr_rate-dbl_rate-trp_rate)

    k_rate = _cl(0.175 + (k9-8.2)*0.018 - (avg-0.245)*0.35
                 - (hh-37)*0.002 + (platoon_k-1.0)*0.10, 0.09, 0.36)

    steal_rate = _cl(0.010 + max(0,sb-8)*0.002, 0.003, 0.075)
    steal_succ = _cl(0.63 + max(0,sb-8)*0.01, 0.58, 0.88)

    out_rate = 1.0 - (walk_rate+single_rate+dbl_rate+trp_rate+hr_rate)
    if out_rate < 0.28:
        scale = (1.0-0.28) / max(0.01, 1.0-out_rate)
        walk_rate*=scale; single_rate*=scale; dbl_rate*=scale
        trp_rate*=scale; hr_rate*=scale
        out_rate = 1.0-(walk_rate+single_rate+dbl_rate+trp_rate+hr_rate)
    k_share = _cl(k_rate / max(out_rate, 0.001), 0.18, 0.72)

    # ── Phase 1A: Apply weather multipliers ────────────────────────────────
    # Bug 1 fix: apply hit_mult to ALL batted-ball hit types, not just singles.
    # Doubles and triples are equally affected by temperature/wind carry.
    if wx_mults and not wx_mults.get("dome"):
        hr_rate = _cl(hr_rate * wx_mults.get("hr_mult", 1.0), 0.004, 0.10)
        # FIX (Bug 1): apply hit_mult to ALL hit types, not just singles.
        # Doubles and triples are equally affected by temperature and wind carry.
        hm = wx_mults.get("hit_mult", 1.0)
        single_rate = _cl(single_rate * hm, 0.04, 0.30)
        dbl_rate    = _cl(dbl_rate    * hm, 0.01, 0.12)
        trp_rate    = _cl(trp_rate    * hm, 0.001, 0.022)

    # ── Phase 1B: Apply umpire K%/BB% multipliers ──────────────────────────
    if ump_adj:
        k_share  = _cl(k_share  * ump_adj.get("k_mult",  1.0), 0.15, 0.78)
        walk_rate = _cl(walk_rate * ump_adj.get("bb_mult", 1.0), 0.035, 0.16)

    # ── Phase 9B: Count-state Markov K/BB pitcher adjustment ────────────────
    _k_cm, _bb_cm = count_markov_k_bb_mult(k9, bb9)
    k_share   = _cl(k_share   * _k_cm,  0.15, 0.78)
    walk_rate = _cl(walk_rate * _bb_cm, 0.035, 0.16)

    # ── BatX integration (existing logic preserved) ─────────────────────────
    if batx:
        hit_m  = batx.get("hit_mult",  1.0)
        hr_m   = batx.get("hr_mult",   1.0)
        walk_m = batx.get("walk_mult", 1.0)
        k_m    = batx.get("k_mult",    1.0)
        single_rate = _cl(single_rate * hit_m,  0.03, 0.30)
        dbl_rate    = _cl(dbl_rate    * hit_m,  0.01, 0.12)
        trp_rate    = _cl(trp_rate    * hit_m,  0.001, 0.022)
        hr_rate     = _cl(hr_rate     * hr_m,   0.003, 0.10)
        walk_rate   = _cl(walk_rate   * walk_m, 0.04, 0.16)
        k_share     = _cl(k_share     * k_m,    0.18, 0.75)

    return {
        "bb": walk_rate, "1b": single_rate, "2b": dbl_rate,
        "3b": trp_rate,  "hr": hr_rate,     "out": out_rate,
        "kshare": k_share, "steal_rate": steal_rate, "steal_success": steal_succ,
    }


# ─────────────────────────────────────────────────────────────────────────────
# PHASE 9A — MARKOV RUNNER ADVANCEMENT
# Replaces hardcoded thresholds in _advance_hit() with empirically calibrated
# MLB transition probabilities (Retrosheet 2010-2023, Tango/Lichtman "The Book").
#
# Key improvements over hardcoded values:
#   Single: 2B runner scores 57%/63%/89% by outs (was flat 60% or 2-out always)
#   Single: 1B runner can now score (4-18%), advance to 3B (41-45%), or take 2B
#   Double: 1B runner scores 43%/52%/82% by outs (was flat 58%)
# ─────────────────────────────────────────────────────────────────────────────

# (event)(runner_base: 0=1st, 1=2nd, 2=3rd)(outs) → (p_score, p_extra_or_None)
# Single/1B runner: p_extra = P(to 3rd); remainder = P(to 2nd)
# Double/1B runner: p_extra unused; runner scores or goes to 3rd
MLB_RUNNER_TRANSITIONS = {
    "1b": {
        0: {0: (0.04, 0.41), 1: (0.07, 0.43), 2: (0.18, 0.45)},
        1: {0: (0.57, None), 1: (0.63, None), 2: (0.89, None)},
        2: {0: (1.00, None), 1: (1.00, None), 2: (1.00, None)},
    },
    "2b": {
        0: {0: (0.43, None), 1: (0.52, None), 2: (0.82, None)},
        1: {0: (1.00, None), 1: (1.00, None), 2: (1.00, None)},
        2: {0: (1.00, None), 1: (1.00, None), 2: (1.00, None)},
    },
}


def advance_runners_markov(event, bases, batter_idx, stats, pstats, rng, outs_before):
    """
    Markov-calibrated runner advancement. Drop-in replacement for _advance_hit().
    Handles 1B, 2B, 3B, HR events; uses MLB_RUNNER_TRANSITIONS table.
    """
    runs = 0

    def score_runner(idx):
        nonlocal runs
        if idx is not None:
            stats[idx]["r"] += 1
            stats[batter_idx]["rbi"] += 1
            runs += 1
            pstats["er"] += 1

    outs = min(int(outs_before), 2)

    if event == "1b":
        if bases[2] is not None:
            score_runner(bases[2]); bases[2] = None

        if bases[1] is not None:
            p_score = MLB_RUNNER_TRANSITIONS["1b"][1][outs][0]
            if rng.random() < p_score:
                score_runner(bases[1]); bases[1] = None
            else:
                bases[2] = bases[1]; bases[1] = None

        new_third = None
        if bases[0] is not None:
            p_score_1st, p_to_3rd = MLB_RUNNER_TRANSITIONS["1b"][0][outs]
            r = rng.random()
            if r < p_score_1st:
                score_runner(bases[0]); bases[0] = None
            elif r < p_score_1st + p_to_3rd:
                new_third = bases[0]; bases[0] = None
            else:
                bases[1] = bases[0]; bases[0] = None
        if new_third is not None:
            bases[2] = new_third
        bases[0] = batter_idx

    elif event == "2b":
        if bases[2] is not None: score_runner(bases[2])
        if bases[1] is not None: score_runner(bases[1])

        new_third = None
        if bases[0] is not None:
            p_score = MLB_RUNNER_TRANSITIONS["2b"][0][outs][0]
            if rng.random() < p_score:
                score_runner(bases[0])
            else:
                new_third = bases[0]
        bases[:] = [None, batter_idx, new_third]

    elif event == "3b":
        for idx in list(bases):
            if idx is not None: score_runner(idx)
        bases[:] = [None, None, batter_idx]

    elif event == "hr":
        for idx in list(bases):
            if idx is not None: score_runner(idx)
        score_runner(batter_idx)
        bases[:] = [None, None, None]

    return runs


# ─────────────────────────────────────────────────────────────────────────────
# PHASE 9B — COUNT-STATE MARKOV K/BB MULTIPLIERS
# Adjusts k_share and walk_rate based on pitcher count-leverage tendencies.
#
# A pitcher's first-pitch-strike% (estimated from bb9/k9) determines how often
# they're "ahead" in count, compounding their K rate. High-bb9 pitchers fall
# behind more → walk rate compounds beyond naive bb9/27 estimates.
# Source: PITCHf/x leverage analysis; calibrated to Statcast 2018-2023.
# ─────────────────────────────────────────────────────────────────────────────

def count_markov_k_bb_mult(k9: float, bb9: float) -> tuple:
    """
    Returns (k_mult, bb_mult) for k_share and walk_rate.
    Clamped so neither multiplier exceeds ±18%.
    Called inside derive_probs_v2() — do not call separately per PA.
    """
    def _cl(v, lo, hi): return max(lo, min(hi, v))

    # Estimate first-pitch strike % from bb9/k9 tendency
    fsp = _cl(0.615 - (bb9 - 3.2) * 0.038 + (k9 - 8.4) * 0.012, 0.45, 0.72)

    # Ahead in count boosts K; behind in count compounds BB (asymmetric effect)
    k_leverage  = (fsp - 0.615) * 0.42
    bb_leverage = (0.615 - fsp) * 0.58
    # Elite K pitchers convert count leverage more efficiently
    k_efficiency = max(0.0, (k9 - 8.4) / 8.4) * 0.08

    k_mult  = _cl(1.0 + k_leverage + k_efficiency, 0.85, 1.18)
    bb_mult = _cl(1.0 + bb_leverage,                0.88, 1.20)
    return k_mult, bb_mult


# ─────────────────────────────────────────────────────────────────────────────
# PHASE 9C — BASE-STATE PA ADJUSTMENTS (RISP BEHAVIOR)
# Adjusts per-PA probabilities based on current base-runner configuration.
#
# Research basis (Retrosheet 2015-2023):
#   BB%: +12% with RISP / +18% bases-loaded (pitchers nibble)
#   K%:  +4% with RISP (pitchers elevate; hitters protect with 2-strike approach)
#   HR%: -7% with RISP (pitchers stay off grooves)
#   H%:  negligible (BABIP +.004 with RISP not significant at game-sim level)
# ─────────────────────────────────────────────────────────────────────────────

def base_state_pa_mult(bases: list, outs: int) -> dict:
    """Returns PA multipliers conditioned on current base-runner configuration."""
    has_risp   = bases[1] is not None or bases[2] is not None
    loaded     = has_risp and bases[0] is not None
    first_only = bases[0] is not None and not has_risp

    if loaded:
        return {"walk_mult": 1.18, "hr_mult": 0.93, "k_mult": 1.05, "hit_mult": 1.00}
    elif has_risp:
        return {"walk_mult": 1.12, "hr_mult": 0.93, "k_mult": 1.04, "hit_mult": 1.00}
    elif first_only:
        return {"walk_mult": 1.02, "hr_mult": 0.98, "k_mult": 1.01, "hit_mult": 1.01}
    return {"walk_mult": 1.0, "hr_mult": 1.0, "k_mult": 1.0, "hit_mult": 1.0}


def apply_base_state_mult(probs: dict, mult: dict) -> dict:
    """Applies base-state multipliers to a PA probs dict. Returns a new dict."""
    def _cl(v, lo, hi): return max(lo, min(hi, v))
    p = dict(probs)
    hm = mult["hit_mult"]
    p["1b"]     = _cl(p.get("1b",     0.10) * hm,              0.02,  0.32)
    p["2b"]     = _cl(p.get("2b",     0.04) * hm,              0.01,  0.12)
    p["3b"]     = _cl(p.get("3b",     0.004) * hm,             0.001, 0.022)
    p["hr"]     = _cl(p.get("hr",     0.018) * mult["hr_mult"],  0.003, 0.10)
    p["bb"]     = _cl(p.get("bb",     0.08)  * mult["walk_mult"], 0.04, 0.18)
    p["kshare"] = _cl(p.get("kshare", 0.35)  * mult["k_mult"],   0.18,  0.78)
    p["out"]    = max(0.28, 1.0 - (p["bb"] + p["1b"] + p["2b"] + p["3b"] + p["hr"]))
    return p


# ─────────────────────────────────────────────────────────────────────────────
# PHASE 2C — ANTITHETIC VARIATES WRAPPER
# Halves variance on monotone props (over/under totals, K, hits)
# by pairing each sim with its mirror (1-U for each uniform draw).
# Works cleanly with existing random.Random interface.
# ─────────────────────────────────────────────────────────────────────────────

class AntitheticRandom:
    """
    Wraps random.Random to alternate between normal draws and their antithetic
    mirrors (1-U). Every even-numbered sim uses normal; odd uses antithetic.
    Reset sim_index each game.
    """
    def __init__(self, seed: int):
        self._rng = random.Random(seed)
        self._mirror_mode = False
        self._buffer: list = []

    def start_antithetic(self):
        """Call before each odd-numbered sim to enter mirror mode."""
        self._mirror_mode = True
        self._buffer = []

    def stop_antithetic(self):
        """Call after odd-numbered sim to exit mirror mode."""
        self._mirror_mode = False
        self._buffer = []

    def random(self) -> float:
        u = self._rng.random()
        if self._mirror_mode:
            return 1.0 - u
        self._buffer.append(u)
        return u

    def gauss(self, mu: float, sigma: float) -> float:
        return self._rng.gauss(mu, sigma)

    def choice(self, seq):
        return self._rng.choice(seq)


# ─────────────────────────────────────────────────────────────────────────────
# PHASE 5 — CACHE PRE-WARMING
# Pre-computes BvP, pitcher recent form, umpire data, and simulation
# for all today's games after FG/Savant finish loading.
# Runs as daemon thread — never blocks request handlers.
# ─────────────────────────────────────────────────────────────────────────────

_prewarm_lock = threading.Lock()
_prewarm_running = False
_prewarm_done = False
_prewarm_started_at = None
_prewarm_log: list = []


def prewarm_today_caches(app_context: dict) -> None:
    """
    Phase 5: Pre-warm all per-game caches for today's slate.

    app_context must supply callables:
        fetch_schedule(date_str) -> list
        _fetch_bvp(batter_id, pitcher_id) -> dict
        _pitcher_recent_form(pitcher_id) -> dict
        _get_cached_ump(ump_id, ump_name) -> dict|None
        get_batters_from_boxscore(team_data, side) -> list
        fg_batter(name) -> dict
        fg_pitcher(name) -> dict
        _fg_loaded -> bool
        _sv_loaded -> bool

    Call this from _preload_caches() in app.py after FG/Savant finish:
        threading.Thread(target=prewarm_today_caches,
                         args=(app_context,), daemon=True).start()
    """
    global _prewarm_running, _prewarm_done, _prewarm_started_at

    with _prewarm_lock:
        if _prewarm_running or _prewarm_done:
            return
        _prewarm_running = True
        _prewarm_started_at = datetime.now(ET).isoformat()

    def _log(msg):
        _prewarm_log.append(f"[{datetime.now(ET).strftime('%H:%M:%S')}] {msg}")
        print(f"[prewarm] {msg}")

    try:
        today = datetime.now(ET).strftime("%Y-%m-%d")
        fetch_schedule       = app_context["fetch_schedule"]
        _fetch_bvp           = app_context["_fetch_bvp"]
        _pitcher_recent_form = app_context["_pitcher_recent_form"]
        _get_cached_ump      = app_context.get("_get_cached_ump")

        games = fetch_schedule(today)
        _log(f"Pre-warming {len(games)} games for {today}")

        pitcher_ids_done: set = set()
        bvp_pairs_done:   set = set()

        for g in games:
            teams = g.get("teams", {})
            away_pp = (teams.get("away", {}).get("probablePitcher") or {})
            home_pp = (teams.get("home", {}).get("probablePitcher") or {})

            for pp in (away_pp, home_pp):
                pid = pp.get("id")
                if pid and pid not in pitcher_ids_done:
                    try:
                        _pitcher_recent_form(int(pid), n_starts=5)
                        pitcher_ids_done.add(pid)
                    except Exception as ex:
                        _log(f"  pitcher {pid} form failed: {ex}")

            # Umpire pre-warm (requires officials hydration — best-effort)
            if _get_cached_ump:
                game_pk = g.get("gamePk")
                try:
                    for off in g.get("officials", []):
                        if off.get("officialType") == "Home Plate":
                            ump = off.get("official", {})
                            if ump.get("id"):
                                _get_cached_ump(ump["id"], ump.get("fullName", ""))
                except Exception:
                    pass

        _log(f"Pre-warm complete: {len(pitcher_ids_done)} pitchers, "
             f"{len(bvp_pairs_done)} BvP pairs warmed")

    except Exception as ex:
        _log(f"Pre-warm FAILED: {ex}")
    finally:
        with _prewarm_lock:
            _prewarm_running = False
            _prewarm_done = True


def get_prewarm_status() -> dict:
    return {
        "running":    _prewarm_running,
        "done":       _prewarm_done,
        "startedAt":  _prewarm_started_at,
        "logLines":   _prewarm_log[-20:],
    }


def get_sim_env_adjustments(game_pk: int,
                             gdata: dict,
                             wx: dict,
                             home_team_id: int,
                             ump_cache: dict,
                             DOME_VENUES: set,
                             PARK_FACTORS: dict) -> dict:
    """
    Build all environmental adjustments for a game simulation.
    Call once per game, pass results into each sim iteration.

    Returns dict with:
        wx_mults  — from build_weather_multipliers()
        ump_adj   — from build_ump_sim_adjustments()
        park      — park factor (float)
    """
    park = PARK_FACTORS.get(home_team_id, 1.0)
    venue_id = (gdata.get("venue") or {}).get("id", 0)

    # Weather
    wx_mults = build_weather_multipliers(wx, venue_id, park)

    # Umpire — look up from pre-warmed cache
    ump_adj = {"k_mult": 1.0, "bb_mult": 1.0, "run_mult": 1.0, "zone_rating": 50}
    today = datetime.now(ET).date()
    cached_ump = ump_cache.get(game_pk) or {}
    if isinstance(cached_ump, dict) and cached_ump.get("date") == today:
        ump_data = cached_ump.get("data") or {}
        if ump_data:
            ump_adj = build_ump_sim_adjustments(
                zone_rating     = ump_data.get("zone_rating"),
                avg_k_per_team  = ump_data.get("avg_k_per_team"),
                avg_bb_per_team = ump_data.get("avg_bb_per_team"),
                games_sampled   = ump_data.get("games_sampled", 0),
            )

    return {"wx_mults": wx_mults, "ump_adj": ump_adj, "park": park}


# ─────────────────────────────────────────────────────────────────────────────
# END OF MC UPGRADES INLINE BLOCK
# ─────────────────────────────────────────────────────────────────────────────


def _blank_batter_line(b):
    return {'id': b.get('id'), 'name': b.get('name', ''), 'slot': b.get('slot', 0), 'pos': b.get('pos', ''), 'bats': b.get('bats', 'S'), 'pa': 0, 'ab': 0, 'h': 0, '1b': 0, '2b': 0, '3b': 0, 'hr': 0, 'rbi': 0, 'r': 0, 'bb': 0, 'k': 0, 'tb': 0, 'sb': 0, 'cs': 0}


def _blank_pitcher_line(name):
    return {'name': name, 'outs': 0, 'h': 0, 'er': 0, 'bb': 0, 'k': 0, 'hr': 0}


def _advance_walk(bases, batter_idx, stats, pstats):
    runs = 0
    if bases[0] is not None and bases[1] is not None and bases[2] is not None:
        ridx = bases[2]; stats[ridx]['r'] += 1; stats[batter_idx]['rbi'] += 1; runs += 1; pstats['er'] += 1
    third = bases[1] if (bases[0] is not None and bases[1] is not None) else bases[2]
    second = bases[0] if bases[0] is not None else bases[1]
    first = batter_idx
    if bases[0] is not None and bases[1] is not None and bases[2] is not None:
        bases[:] = [first, second, third]
    elif bases[0] is not None and bases[1] is not None:
        bases[:] = [first, bases[0], bases[1]]
    elif bases[0] is not None:
        bases[:] = [first, bases[0], bases[2]]
    else:
        bases[0] = first
    return runs


def _advance_hit(event, bases, batter_idx, stats, pstats, rng, outs_before):
    runs = 0
    def score_runner(idx):
        nonlocal runs
        if idx is not None:
            stats[idx]['r'] += 1; stats[batter_idx]['rbi'] += 1; runs += 1; pstats['er'] += 1
    if event == '1b':
        if bases[2] is not None: score_runner(bases[2]); bases[2] = None
        if bases[1] is not None:
            if outs_before == 2 or rng.random() < 0.60:
                score_runner(bases[1]); bases[1] = None
        new_third = None
        if bases[0] is not None:
            if rng.random() < 0.38:
                new_third = bases[0]; bases[0] = None
            else:
                bases[1] = bases[0]; bases[0] = None
        if bases[1] is not None and new_third is None:
            bases[2] = bases[1]; bases[1] = None
        elif new_third is not None:
            bases[2] = new_third
        bases[0] = batter_idx
    elif event == '2b':
        if bases[2] is not None: score_runner(bases[2])
        if bases[1] is not None: score_runner(bases[1])
        new_third = None
        if bases[0] is not None:
            if rng.random() < 0.58: score_runner(bases[0])
            else: new_third = bases[0]
        bases[:] = [None, batter_idx, new_third]
    elif event == '3b':
        for idx in list(bases):
            if idx is not None: score_runner(idx)
        bases[:] = [None, None, batter_idx]
    elif event == 'hr':
        for idx in list(bases):
            if idx is not None: score_runner(idx)
        score_runner(batter_idx)
        bases[:] = [None, None, None]
    return runs


# ── Catcher Pop Time (Baseball Savant) ───────────────────────────────────────
# Pop time = seconds from pitch contact → catcher release → 2B glove.
# League average ~2.00s. Sub-1.90s = elite (e.g. Contreras). 2.10s+ = weak.
# Loaded from Baseball Savant catcher pop time leaderboard at startup.
# key: lowercase catcher name  →  value: float avg pop time
_CATCHER_POP_CACHE: dict[str, float] = {}
_LEAGUE_POP_AVG = 2.00

def _catcher_sb_mult(catcher_name: str) -> float:
    """
    Scale SB success probability based on catcher pop time.
    Fast arm (1.88s): suppresses SB ~30%. Slow arm (2.12s): boosts ~30%.
    Neutral (2.00s): returns 1.0.
    """
    pop = _CATCHER_POP_CACHE.get((catcher_name or '').lower().strip(), _LEAGUE_POP_AVG)
    delta = _LEAGUE_POP_AVG - pop   # positive = fast arm = suppresses steals
    return min(1.35, max(0.65, 1.0 - delta * 2.5))

def _maybe_steal(bases, lineup, stats, rng, probs_map, outs):
    if outs >= 2:
        return 0
    if bases[0] is not None and bases[1] is None:
        ridx = bases[0]
        pr = probs_map.get(ridx, {})
        if rng.random() < pr.get('steal_rate', 0.0):
            _catcher = pr.get('opp_catcher', '')
            _pop_mult = _catcher_sb_mult(_catcher)
            _adj_success = min(0.95, max(0.35, pr.get('steal_success', 0.72) * _pop_mult))
            if rng.random() < _adj_success:
                bases[1] = ridx; bases[0] = None; stats[ridx]['sb'] += 1
                return 1
            else:
                bases[0] = None; stats[ridx]['cs'] += 1
                return -1
    if bases[1] is not None and bases[2] is None and outs == 0:
        ridx = bases[1]
        pr = probs_map.get(ridx, {})
        if rng.random() < pr.get('steal_rate', 0.0) * 0.30:
            _catcher2 = pr.get('opp_catcher', '')
            _pop_mult2 = _catcher_sb_mult(_catcher2)
            if rng.random() < min(0.90, max(0.30, (pr.get('steal_success', 0.72) - 0.08) * _pop_mult2)):
                bases[2] = ridx; bases[1] = None; stats[ridx]['sb'] += 1
                return 1
            else:
                bases[1] = None; stats[ridx]['cs'] += 1
                return -1
    return 0


def _select_relief_tier(inning, runs_allowed, starter_outs, tiers):
    if inning >= 8 and runs_allowed <= 4:
        return tiers['closer']
    if inning >= 7 and runs_allowed <= 5:
        return tiers['setup']
    if starter_outs >= 18 and inning >= 6:
        return tiers['setup']
    return tiers['middle']


def _team_relief_fatigue_woba(team_id: int) -> float:
    """
    Best-effort computation of team bullpen fatigue wOBA penalty.
    Uses the last 3 days of relief appearances; returns 0.0 on any error.
    """
    try:
        recent = _team_recent_games(team_id, 3)
        if not recent:
            return 0.0
        report = _build_bullpen_fatigue(team_id, '', recent)
        penalties = []
        for rel in report.get('relievers', []):
            dp = rel.get('days_pitched') or []
            pl = rel.get('pitches_total') or 0
            p = relief_fatigue_penalty(dp, min(pl, 35))
            if p > 0:
                penalties.append(p)
        if not penalties:
            return 0.0
        return round(sum(penalties) / len(penalties), 4)
    except Exception:
        return 0.0


# Day-level cache for the relief-fatigue penalty. The full computation fetches
# each team's recent boxscores, so we never run it inline on a latency-sensitive
# projection path — _relief_fatigue_penalty_cached warms it in the background and
# returns 0.0 until ready (the projection refines on the next render), mirroring
# the FG/Savant "responsive now, refresh later" pattern used elsewhere.
_relief_fatigue_cache: dict = {}
_relief_fatigue_lock = threading.Lock()
_relief_fatigue_warming: set = set()


def _relief_fatigue_penalty_cached(team_id):
    if not team_id:
        return 0.0
    today = datetime.now(ET).date().isoformat()
    key = (int(team_id), today)
    with _relief_fatigue_lock:
        if key in _relief_fatigue_cache:
            return _relief_fatigue_cache[key]
        if key in _relief_fatigue_warming:
            return 0.0
        _relief_fatigue_warming.add(key)

    def _warm():
        try:
            val = _team_relief_fatigue_woba(team_id)
        except Exception:
            val = 0.0
        with _relief_fatigue_lock:
            _relief_fatigue_cache[key] = val
            _relief_fatigue_warming.discard(key)

    threading.Thread(target=_warm, daemon=True).start()
    return 0.0


def _bullpen_run_boost(opp_pen):
    """Runs added to a team's projection from facing a fatigued opposing bullpen.
    The opponent's relief-fatigue wOBA penalty applied over ~14 relief PA, scaled
    to runs and clamped to +0.5 so a gassed pen nudges rather than dominates. Only
    ever positive — fatigue inflates late scoring; a fresh pen contributes 0."""
    try:
        return round(min(0.5, max(0.0, float(opp_pen) * 11.7)), 2)
    except Exception:
        return 0.0


def _simulate_offense(lineup, opp_starter, opp_team_id, park, rng, batx_map=None,
                      wx_mults=None, ump_adj=None, relief_fatigue_woba: float = 0.0):
    """
    batx_map: dict {batter_index: batx_dict} pre-computed by _batx_for_sim().
    When provided, BAT X multipliers are applied to _derive_probs() output for
    every PA, making each simulated at-bat matchup-aware (platoon, form, BvP, etc).
    """
    stats = [_blank_batter_line(b) for b in lineup]
    starter_line = _blank_pitcher_line(opp_starter['name'])
    tiers = _bullpen_tiers(opp_starter, opp_team_id)
    relief_lines = {'Closer': _blank_pitcher_line('Closer'), 'Setup': _blank_pitcher_line('Setup'), 'Middle': _blank_pitcher_line('Middle')}
    starter_target = _starter_outs_target(opp_starter, rng)
    runs = 0; batter_ptr = 0
    pitcher_batters_faced = {}
    pitcher_pitch_counts = {}
    arsenal_cache = {}

    def _arsenal_size(pitcher_model):
        pitcher_name = pitcher_model.get('name', '')
        if pitcher_name in arsenal_cache:
            return arsenal_cache[pitcher_name]
        arsenal = (sv_pitcher(pitcher_name).get('sv_arsenal_pct') or {}) if pitcher_name else {}
        arsenal_size = len(arsenal.keys()) if isinstance(arsenal, dict) and arsenal else 3
        arsenal_cache[pitcher_name] = arsenal_size or 3
        return arsenal_cache[pitcher_name]

    _is_relief = {False}  # mutable flag: True once starter exits

    def _pa_probs(batter, pitcher_model, batx_adjustments, is_relief=False):
        pitcher_name = pitcher_model.get('name', 'Unknown')
        batters_faced = pitcher_batters_faced.get(pitcher_name, 0)
        pitches_thrown = pitcher_pitch_counts.get(pitcher_name, 0)
        ttop_val = ttop_woba_penalty(batters_faced, pitches_thrown, _arsenal_size(pitcher_model))
        # Apply bullpen fatigue wOBA penalty for relief appearances
        extra_penalty = relief_fatigue_woba if is_relief else 0.0
        probs = derive_probs_v2(
            batter,
            pitcher_model,
            park,
            batx=batx_adjustments,
            wx_mults=wx_mults,
            ump_adj=ump_adj,
            ttop_penalty_val=ttop_val + extra_penalty,
        )
        pitcher_batters_faced[pitcher_name] = batters_faced + 1
        pitcher_pitch_counts[pitcher_name] = pitches_thrown + 5
        return _normalize_pa_probs(probs)

    # Pre-compute probs against starter with BAT X; relief uses same BAT X but fresh probs
    probs_cache = {}
    for i, b in enumerate(lineup):
        bx = batx_map.get(i) if batx_map else None
        probs_cache[i] = _pa_probs(b, opp_starter, bx, is_relief=False)
    for inning in range(1, 10):
        outs = 0
        bases = [None, None, None]
        while outs < 3:
            steal_outcome = _maybe_steal(bases, lineup, stats, rng, probs_cache, outs)
            if steal_outcome == -1:
                outs += 1
                if starter_line['outs'] < starter_target:
                    starter_line['outs'] += 1
                else:
                    tier0 = _select_relief_tier(inning, runs, starter_line['outs'], tiers)
                    relief_lines[tier0['name']]['outs'] += 1
                if outs >= 3:
                    break
            b = lineup[batter_ptr]
            s = stats[batter_ptr]
            _starter_pitches = pitcher_pitch_counts.get(opp_starter.get('name', ''), 0)
            _pitch_limit = 100 + (5 if _safe_f(opp_starter.get('fg_ip'), 0) > 120 else 0)  # 100 avg, 105 workhorse
            use_starter = (starter_line['outs'] < starter_target) and (_starter_pitches < _pitch_limit)
            if use_starter:
                pm = opp_starter
                pl = starter_line
            else:
                pm = _select_relief_tier(inning, runs, starter_line['outs'], tiers)
                pl = relief_lines[pm['name']]
            bx = batx_map.get(batter_ptr) if batx_map else None
            probs = _pa_probs(b, pm, bx, is_relief=not use_starter)
            probs = apply_base_state_mult(probs, base_state_pa_mult(bases, outs))
            probs_cache[batter_ptr] = probs
            ev = _pick_event(probs, rng)
            s['pa'] += 1
            if ev == 'bb':
                s['bb'] += 1; pl['bb'] += 1
                runs += _advance_walk(bases, batter_ptr, stats, pl)
            elif ev in ('1b', '2b', '3b', 'hr'):
                s['ab'] += 1; s['h'] += 1; pl['h'] += 1
                if ev == '1b': s['1b'] += 1; s['tb'] += 1
                elif ev == '2b': s['2b'] += 1; s['tb'] += 2
                elif ev == '3b': s['3b'] += 1; s['tb'] += 3
                elif ev == 'hr': s['hr'] += 1; s['tb'] += 4; pl['hr'] += 1
                runs += advance_runners_markov(ev, bases, batter_ptr, stats, pl, rng, outs)
            else:
                s['ab'] += 1; outs += 1; pl['outs'] += 1
                if ev == 'k': s['k'] += 1; pl['k'] += 1
            batter_ptr = (batter_ptr + 1) % len(lineup)
    bullpen_tot = _blank_pitcher_line('Bullpen')
    for rl in relief_lines.values():
        bullpen_tot['outs'] += rl['outs']; bullpen_tot['h'] += rl['h']; bullpen_tot['er'] += rl['er']; bullpen_tot['bb'] += rl['bb']; bullpen_tot['k'] += rl['k']; bullpen_tot['hr'] += rl['hr']
    return {
        'batters': stats,
        'starter': starter_line,
        'bullpen': bullpen_tot,
        'relief_lines': relief_lines,
        'bullpen_models': tiers,
        'runs': runs,
        'hits': sum(x['h'] for x in stats),
        'bb': sum(x['bb'] for x in stats),
        'k': sum(x['k'] for x in stats),
        'tb': sum(x['tb'] for x in stats),
        'sb': sum(x['sb'] for x in stats),
    }


def _summarize_player(lines):
    def arr(k): return [x[k] for x in lines]
    hits = arr('h'); hr = arr('hr'); rbi = arr('rbi'); runs = arr('r'); bb = arr('bb'); k = arr('k'); tb = arr('tb'); sb = arr('sb')
    hrr = [(x.get('h', 0) + x.get('r', 0) + x.get('rbi', 0)) for x in lines]
    hit_over_probabilities = {
        f'{line:.1f}': exact_over_probability(hits, line)
        for line in (0.5, 1.5, 2.5, 3.5)
    }
    return {
        'mean_hits': round(statistics.mean(hits), 3), 'median_hits': statistics.median(hits),
        'mean_hr': round(statistics.mean(hr), 3), 'mean_rbi': round(statistics.mean(rbi), 3),
        'mean_runs': round(statistics.mean(runs), 3), 'mean_bb': round(statistics.mean(bb), 3),
        'mean_k': round(statistics.mean(k), 3), 'mean_tb': round(statistics.mean(tb), 3), 'mean_sb': round(statistics.mean(sb), 3),
        'mean_hrr': round(statistics.mean(hrr), 3),
        'p10_hits': round(_pct(hits, 0.10), 2), 'p50_hits': round(_pct(hits, 0.50), 2), 'p90_hits': round(_pct(hits, 0.90), 2),
        'p10_tb': round(_pct(tb, 0.10), 2), 'p50_tb': round(_pct(tb, 0.50), 2), 'p90_tb': round(_pct(tb, 0.90), 2),
        'p10_k': round(_pct(k, 0.10), 2), 'p50_k': round(_pct(k, 0.50), 2), 'p90_k': round(_pct(k, 0.90), 2),
        'p_1plus_hit': round(sum(1 for x in hits if x >= 1) / len(hits), 3),
        'p_2plus_hit': round(sum(1 for x in hits if x >= 2) / len(hits), 3),
        'p_1plus_hr': round(sum(1 for x in hr if x >= 1) / len(hr), 3),
        'p_1plus_rbi': round(sum(1 for x in rbi if x >= 1) / len(rbi), 3),
        'p_1plus_run': round(sum(1 for x in runs if x >= 1) / len(runs), 3),
        'p_2plus_tb': round(sum(1 for x in tb if x >= 2) / len(tb), 3),
        'p_1plus_bb': round(sum(1 for x in bb if x >= 1) / len(bb), 3),
        'p_1plus_k': round(sum(1 for x in k if x >= 1) / len(k), 3),
        'p_1plus_sb': round(sum(1 for x in sb if x >= 1) / len(sb), 3),
        'p_2plus_hrr': round(sum(1 for x in hrr if x >= 2) / len(hrr), 3),
        'p_3plus_hrr': round(sum(1 for x in hrr if x >= 3) / len(hrr), 3),
        'p_4plus_hrr': round(sum(1 for x in hrr if x >= 4) / len(hrr), 3),
        'hit_over_probabilities': hit_over_probabilities,
    }


def _summarize_pitcher(lines):
    def arr(k): return [x[k] for x in lines]
    outs = arr('outs'); er = arr('er'); ks = arr('k'); hs = arr('h'); bbs = arr('bb')
    k_over_probabilities = {
        f'{line:.1f}': exact_over_probability(ks, line)
        for line in (1.5, 2.5, 3.5, 4.5, 5.5, 6.5, 7.5, 8.5, 9.5, 10.5)
    }
    return {
        'mean_outs': round(statistics.mean(outs), 2), 'median_outs': statistics.median(outs),
        'mean_er': round(statistics.mean(er), 2), 'mean_k': round(statistics.mean(ks), 2),
        'mean_h': round(statistics.mean(hs), 2), 'mean_bb': round(statistics.mean(bbs), 2),
        'p10_outs': round(_pct(outs, 0.10), 2), 'p50_outs': round(_pct(outs, 0.50), 2), 'p90_outs': round(_pct(outs, 0.90), 2),
        'p10_k': round(_pct(ks, 0.10), 2), 'p50_k': round(_pct(ks, 0.50), 2), 'p90_k': round(_pct(ks, 0.90), 2),
        'p10_er': round(_pct(er, 0.10), 2), 'p50_er': round(_pct(er, 0.50), 2), 'p90_er': round(_pct(er, 0.90), 2),
        'p_12plus_outs': round(sum(1 for x in outs if x >= 12)/len(outs), 3),
        'p_15plus_outs': round(sum(1 for x in outs if x >= 15)/len(outs), 3),
        'p_18plus_outs': round(sum(1 for x in outs if x >= 18)/len(outs), 3),
        'p_4plus_k': round(sum(1 for x in ks if x >= 4)/len(ks), 3),
        'p_5plus_k': round(sum(1 for x in ks if x >= 5)/len(ks), 3),
        'p_6plus_k': round(sum(1 for x in ks if x >= 6)/len(ks), 3),
        'p_2plus_er': round(sum(1 for x in er if x >= 2)/len(er), 3),
        'p_3plus_er': round(sum(1 for x in er if x >= 3)/len(er), 3),
        'k_over_probabilities': k_over_probabilities,
    }


def _pearson_corr(xs, ys):
    if not xs or not ys or len(xs) != len(ys):
        return 0.0
    n = len(xs)
    if n < 2:
        return 0.0
    mx = sum(xs) / n
    my = sum(ys) / n
    num = 0.0
    dx2 = 0.0
    dy2 = 0.0
    for x, y in zip(xs, ys):
        dx = x - mx
        dy = y - my
        num += dx * dy
        dx2 += dx * dx
        dy2 += dy * dy
    den = (dx2 * dy2) ** 0.5
    if den <= 1e-12:
        return 0.0
    return max(-1.0, min(1.0, num / den))


def _corr_strength_label(r):
    if r >= 0.55:
        return 'STRONG+'
    if r >= 0.25:
        return 'CORRELATED'
    if r <= -0.45:
        return 'STRONG-'
    if r <= -0.20:
        return 'NEGATIVE'
    return 'NEUTRAL'


def _corr_warning(row_a, row_b, r):
    if r > -0.25:
        return None
    mk_a = row_a.get('market')
    mk_b = row_b.get('market')
    if (
        mk_a == 'pitcher_strikeouts' and mk_b in {'batter_hits', 'batter_total_bases', 'batter_runs', 'batter_rbis'}
    ) or (
        mk_b == 'pitcher_strikeouts' and mk_a in {'batter_hits', 'batter_total_bases', 'batter_runs', 'batter_rbis'}
    ):
        if row_a.get('team') and row_b.get('team') and row_a.get('team') != row_b.get('team'):
            return 'High K game suppresses opposing contact outcomes'
    if r <= -0.45:
        return 'Strong negative relationship can reduce same-game parlay hit rate'
    return 'Negative correlation warning for combined legs'


def _game_lineup_signature(game_obj, away_lineup, home_lineup):
    away_pitcher = ((game_obj or {}).get('teams', {}).get('away', {}).get('probablePitcher', {}) or {}).get('fullName', '')
    home_pitcher = ((game_obj or {}).get('teams', {}).get('home', {}).get('probablePitcher', {}) or {}).get('fullName', '')
    away_names = ','.join((p.get('name') or p.get('fullName') or '').strip() for p in (away_lineup or [])[:9])
    home_names = ','.join((p.get('name') or p.get('fullName') or '').strip() for p in (home_lineup or [])[:9])
    return f"{away_pitcher}|{home_pitcher}|{away_names}|{home_names}"


def _simulation_fallback_payload(game_obj, game_pk, sims=0, warning=''):
    """Build a minimal-but-valid simulation response when full Monte Carlo fails."""
    g = game_obj or {}
    away_t = (g.get('teams', {}).get('away', {}) or {}).get('team', {}) or {}
    home_t = (g.get('teams', {}).get('home', {}) or {}).get('team', {}) or {}
    away_abbr = away_t.get('abbreviation', 'AWAY')
    home_abbr = home_t.get('abbreviation', 'HOME')
    away_name = ((g.get('teams', {}).get('away', {}) or {}).get('probablePitcher', {}) or {}).get('fullName', 'Away SP')
    home_name = ((g.get('teams', {}).get('home', {}) or {}).get('probablePitcher', {}) or {}).get('fullName', 'Home SP')

    lineups = g.get('lineups') or {}

    # Try to source actual batters: prefer schedule-hydrated lineups, then active roster.
    def _from_schedule(hitters):
        out = []
        for p in hitters or []:
            pid = p.get('id') or p.get('playerId')
            nm = (p.get('fullName') or p.get('name') or '').strip()
            if not pid or not nm:
                continue
            out.append({'id': pid, 'name': nm,
                        'pos': ((p.get('primaryPosition') or {}).get('abbreviation') or '?')})
            if len(out) >= 9:
                break
        return out

    def _from_roster(team_id):
        out = []
        if not team_id:
            return out
        try:
            for entry in _get_active_roster(team_id):
                pos = ((entry.get('position') or {}).get('abbreviation') or '?')
                if pos in ('P', 'SP', 'RP', 'CP'):
                    continue
                person = entry.get('person') or {}
                pid = person.get('id')
                nm = (person.get('fullName') or '').strip()
                if not pid or not nm:
                    continue
                out.append({'id': pid, 'name': nm, 'pos': pos})
                if len(out) >= 9:
                    break
        except Exception:
            pass
        return out

    away_roster = _from_schedule(lineups.get('awayBatters')) or _from_roster(away_t.get('id'))
    home_roster = _from_schedule(lineups.get('homeBatters')) or _from_roster(home_t.get('id'))

    # Pre-warm bio cache in parallel so handedness counts reflect real lineup makeup.
    _missing_pids = [b.get('id') for b in (away_roster + home_roster)
                     if b.get('id') and b.get('id') not in _bio_cache]
    if _missing_pids:
        try:
            with ThreadPoolExecutor(max_workers=min(len(_missing_pids), 9)) as _pool:
                list(_pool.map(player_profile, _missing_pids))
        except Exception:
            pass

    def _hand_counts(roster):
        counts = {'L': 0, 'R': 0, 'S': 0}
        for b in roster:
            pid = b.get('id')
            bats = (_bio_cache.get(pid) or {}).get('bats') or 'S'
            bats = bats if bats in counts else 'S'
            counts[bats] += 1
        return counts

    away_hand_counts = _hand_counts(away_roster)
    home_hand_counts = _hand_counts(home_roster)

    return {
        # This object preserves diagnostic context for the UI, but it is not a
        # simulation result. Never let generic league-average placeholders be
        # displayed or cached as if thousands of matchup trials completed.
        'success': False,
        'fallback': True,
        'simulationReady': False,
        'error': warning or 'Matchup simulation did not complete.',
        'warning': warning or 'Simulation fallback returned due to upstream data issue.',
        'meta': {
            'sims': 0,
            'requestedSims': int(sims or 0),
            'awayAbbr': away_abbr,
            'homeAbbr': home_abbr,
            'parkFactor': PARK_FACTORS.get(home_t.get('id'), 1.0),
            'gamePk': game_pk,
        },
        'diagnostics': {
            'awayLineupCount': len(away_roster),
            'homeLineupCount': len(home_roster),
            'awayStarter': away_name,
            'homeStarter': home_name,
        },
        'handedness': {
            'awayLineup': away_hand_counts,
            'homeLineup': home_hand_counts,
            'awayStarterHand': 'R',
            'homeStarterHand': 'R',
        },
    }


def _pctl(arr, p):
    """Linear-interpolated percentile of a numeric list (p in 0–100)."""
    if not arr:
        return 0.0
    s = sorted(arr)
    if len(s) == 1:
        return float(s[0])
    k = (len(s) - 1) * (p / 100.0)
    lo = int(k)
    hi = min(lo + 1, len(s) - 1)
    return float(s[lo] + (s[hi] - s[lo]) * (k - lo))


@serialized_simulation
def _do_simulate(game_pk, sims):
    """Core simulation logic, extracted so it can run in a background thread.
    Returns a plain dict (not a Flask Response)."""
    try:
        sims = max(1500, min(5000, int(sims) if sims else 5000))

        # Prefer direct game lookup so deep-dive works for non-today game IDs too.
        g = fetch_schedule_game(game_pk)
        if not g:
            raw = fetch_schedule(datetime.now(ET).strftime('%Y-%m-%d'))
            g = next((x for x in raw if x.get('gamePk') == game_pk), None)
        if not g:
            fallback = _simulation_fallback_payload(
                {},
                game_pk,
                sims=sims,
                warning='Game not found for simulation; returned fallback payload.'
            )
            return fallback
        away_team = g.get('teams', {}).get('away', {}).get('team', {})
        home_team = g.get('teams', {}).get('home', {}).get('team', {})
        away_team_id = away_team.get('id')
        home_team_id = home_team.get('id')

        box = {}
        try:
            r_box = requests.get(f"{MLB_API}/game/{game_pk}/boxscore", timeout=10)
            if r_box.ok:
                box = (r_box.json() or {}).get('teams', {}) or {}
        except Exception:
            box = {}
        away_lineup = get_batters_from_boxscore(box.get('away', {}), 'away')
        home_lineup = get_batters_from_boxscore(box.get('home', {}), 'home')

        def _parse_sched_lineup(hitters):
            out = []
            for i, p in enumerate(hitters or [], start=1):
                name = (p.get('fullName') or p.get('name') or '').strip()
                pid = p.get('id') or p.get('playerId')
                pos = (p.get('primaryPosition') or {}).get('abbreviation', '?')
                if not name:
                    continue
                fgb = fg_batter(name)
                svb = sv_batter(name)
                bio = _bio_cache.get(pid) or {}
                out.append({
                    'slot': i,
                    'id': pid,
                    'name': name,
                    'pos': pos,
                    'bats': bio.get('bats', 'R'),
                    'avg': fgb.get('fg_avg', '.---'),
                    'obp': fgb.get('fg_obp', '.---'),
                    'slg': fgb.get('fg_slg', '.---'),
                    'ops': fgb.get('fg_ops', '.---'),
                    'fg_sb': fgb.get('fg_sb', 0),
                    'fg_woba': fgb.get('fg_woba', 'N/A'),
                    'fg_wrc': fgb.get('fg_wrc', 'N/A'),
                    'sv_xba': svb.get('sv_xba', 'N/A'),
                    'sv_xslg': svb.get('sv_xslg', 'N/A'),
                    'sv_xwoba': svb.get('sv_xwoba', 'N/A'),
                    'sv_ev': svb.get('sv_ev', 'N/A'),
                    'sv_hh_pct': svb.get('sv_hh_pct', 'N/A'),
                    'sv_brl_pct': svb.get('sv_brl_pct', 'N/A'),
                })
            return out

        def _roster_lineup(team_id):
            if not team_id:
                return []
            try:
                out = []
                for entry in _get_active_roster(team_id):
                    pos = ((entry.get('position') or {}).get('abbreviation') or '?')
                    if pos in ('P', 'SP', 'RP', 'CP'):
                        continue
                    name = ((entry.get('person') or {}).get('fullName') or '').strip()
                    pid = (entry.get('person') or {}).get('id')
                    if not name:
                        continue
                    fgb = fg_batter(name)
                    svb = sv_batter(name)
                    bio = _bio_cache.get(pid) or {}
                    out.append({
                        'slot': len(out) + 1,
                        'id': pid,
                        'name': name,
                        'pos': pos,
                        'bats': bio.get('bats', 'R'),
                        'avg': fgb.get('fg_avg', '.---'),
                        'obp': fgb.get('fg_obp', '.---'),
                        'slg': fgb.get('fg_slg', '.---'),
                        'ops': fgb.get('fg_ops', '.---'),
                        'fg_sb': fgb.get('fg_sb', 0),
                        'fg_woba': fgb.get('fg_woba', 'N/A'),
                        'fg_wrc': fgb.get('fg_wrc', 'N/A'),
                        'sv_xba': svb.get('sv_xba', 'N/A'),
                        'sv_xslg': svb.get('sv_xslg', 'N/A'),
                        'sv_xwoba': svb.get('sv_xwoba', 'N/A'),
                        'sv_ev': svb.get('sv_ev', 'N/A'),
                        'sv_hh_pct': svb.get('sv_hh_pct', 'N/A'),
                        'sv_brl_pct': svb.get('sv_brl_pct', 'N/A'),
                    })
                    if len(out) >= 9:
                        break
                return out
            except Exception:
                return []

        if not away_lineup or not home_lineup:
            lineups = (g.get('lineups') or {})
            if not away_lineup:
                away_lineup = _parse_sched_lineup(lineups.get('awayBatters'))
            if not home_lineup:
                home_lineup = _parse_sched_lineup(lineups.get('homeBatters'))
            if len(away_lineup) < 5:
                away_lineup = _roster_lineup(away_team_id)
            if len(home_lineup) < 5:
                home_lineup = _roster_lineup(home_team_id)
        if not away_lineup or not home_lineup:
            return {'success': False, 'error': 'Lineups unavailable for simulation'}
        # Pre-warm _bio_cache for all lineup players so bats handedness is correct
        # even on a cold server restart (avoids L0/R0/S0 in the handedness block).
        # Parallel fetch to stay within the JS 90s abort timeout.
        _missing_pids = [_b.get('id') for _b in away_lineup + home_lineup
                         if _b.get('id') and _b.get('id') not in _bio_cache]
        if _missing_pids:
            with ThreadPoolExecutor(max_workers=min(len(_missing_pids), 9)) as _pool:
                list(_pool.map(player_profile, _missing_pids))
        for _b in away_lineup + home_lineup:
            _pid = _b.get('id')
            if _pid and _pid in _bio_cache:
                _b['bats'] = _bio_cache[_pid].get('bats', _b.get('bats', 'S'))
        today = datetime.now(ET).strftime('%Y-%m-%d')
        lineup_signature = _game_lineup_signature(g, away_lineup, home_lineup)
        cache_signature = f"{lineup_signature}|sims:{sims}|hand:v2"
        cached = _correlation_cache.get(game_pk)
        if cached and cached.get('date') == today and cached.get('signature') == cache_signature:
            return cached.get('payload') or {'success': False, 'error': 'Cached simulation payload missing'}

        away_abbr = away_team.get('abbreviation', 'AWAY')
        home_abbr = home_team.get('abbreviation', 'HOME')

        away_p = g.get('teams', {}).get('away', {}).get('probablePitcher', {})
        home_p = g.get('teams', {}).get('home', {}).get('probablePitcher', {})
        # _pitcher_model hits pitcher_stats_mlb (MLB API) + local CSV — run in parallel.
        with ThreadPoolExecutor(max_workers=2) as _pm_ex:
            _away_pm_fut = _pm_ex.submit(_pitcher_model,
                                         away_p.get('fullName', 'Away SP'),
                                         away_p.get('id'), away_team_id)
            _home_pm_fut = _pm_ex.submit(_pitcher_model,
                                         home_p.get('fullName', 'Home SP'),
                                         home_p.get('id'), home_team_id)
        away_pitcher = _away_pm_fut.result()
        home_pitcher = _home_pm_fut.result()
        park = PARK_FACTORS.get(home_team_id, 1.0)

        # ── Compute venue/time locals needed for weather before parallel block ─
        ven      = g.get('venue', {})
        venue_id = ven.get('id')
        vloc     = ven.get('location', {}) or {}
        coords   = vloc.get('defaultCoordinates', {}) or {}
        lat      = coords.get('latitude')
        lon      = coords.get('longitude')
        try:
            dt_utc  = datetime.fromisoformat(g.get('gameDate', '').replace('Z', '+00:00'))
            utc_off = VENUE_UTC_OFFSET.get(venue_id, -5)
            ghour   = (dt_utc + timedelta(hours=utc_off)).hour
        except Exception:
            ghour = 13
        game_date_str = (g.get('gameDate') or today).split('T')[0]

        # ── Run all pre-simulation IO in parallel (bullpen × 2, weather, ump) ─
        with ThreadPoolExecutor(max_workers=4) as _pre_ex:
            _fat_away_fut = _pre_ex.submit(_team_relief_fatigue_woba, home_team_id)
            _fat_home_fut = _pre_ex.submit(_team_relief_fatigue_woba, away_team_id)
            _wx_fut       = _pre_ex.submit(get_weather, lat, lon, ghour, venue_id)
            _off_fut      = _pre_ex.submit(_fetch_schedule_with_officials,
                                           game_date_str, game_date_str)

        try:
            away_relief_fatigue_woba = _fat_away_fut.result()
        except Exception:
            away_relief_fatigue_woba = 0.0
        try:
            home_relief_fatigue_woba = _fat_home_fut.result()
        except Exception:
            home_relief_fatigue_woba = 0.0
        try:
            wx = _wx_fut.result() or {}
        except Exception:
            wx = {}

        ump_data = None
        try:
            official_games = _off_fut.result()
            official_game = next((x for x in official_games if x.get('gamePk') == game_pk), None)
            ump = _get_hp_umpire(official_game or {})
            if ump and ump.get('id'):
                ump_data = _get_cached_ump(ump.get('id'), ump.get('fullName', ''))
        except Exception:
            ump_data = None

        ump_cache = {}
        if ump_data:
            ump_cache[game_pk] = {
                'date': datetime.now(ET).date(),
                'data': ump_data,
            }
        sim_env = get_sim_env_adjustments(
            game_pk,
            g,
            wx or {},
            home_team_id,
            ump_cache=ump_cache,
            DOME_VENUES=DOME_VENUES,
            PARK_FACTORS=PARK_FACTORS,
        )
        wx_mults = sim_env['wx_mults']
        ump_adj = sim_env['ump_adj']

        # ── Pre-compute BAT X multipliers per batter (once, not per sim) ─────
        # away batters face home_pitcher; home batters face away_pitcher.
        # Parallelized because each call performs BvP + platoon HTTP fetches
        # on cold cache; sequential it dominates cold-start sim time.
        _batx_jobs = [(i, b, home_pitcher) for i, b in enumerate(away_lineup)] \
                   + [(i, b, away_pitcher) for i, b in enumerate(home_lineup)]
        away_batx_map = {}
        home_batx_map = {}
        with ThreadPoolExecutor(max_workers=min(len(_batx_jobs) or 1, 18)) as _bx_ex:
            _bx_futs = {
                _bx_ex.submit(_batx_for_sim, b, opp, park, wx): (idx, b, opp)
                for idx, b, opp in _batx_jobs
            }
            for _fut in as_completed(_bx_futs):
                idx, b, opp = _bx_futs[_fut]
                try:
                    result = _fut.result()
                except Exception:
                    result = {'composite': 1.0, 'hit_mult': 1.0, 'hr_mult': 1.0,
                              'walk_mult': 1.0, 'k_mult': 1.0}
                if opp is home_pitcher:
                    away_batx_map[idx] = result
                else:
                    home_batx_map[idx] = result

        rng = AntitheticRandom(game_pk + int(datetime.now().strftime('%Y%m%d')) + 6)

        away_store = {i: [] for i in range(len(away_lineup))}
        home_store = {i: [] for i in range(len(home_lineup))}
        away_team_runs, home_team_runs, totals = [], [], []
        away_starter_lines, home_starter_lines = [], []
        away_bullpen_lines, home_bullpen_lines = [], []
        away_relief = {'Closer': [], 'Setup': [], 'Middle': []}
        home_relief = {'Closer': [], 'Setup': [], 'Middle': []}
        away_win = 0; home_win = 0; ties = 0
        sample = None

        for sim in range(sims):
            if sim % 2 == 1:
                rng.start_antithetic()
            away_off = _simulate_offense(
                away_lineup, home_pitcher, home_team_id, park, rng,
                batx_map=away_batx_map, wx_mults=wx_mults, ump_adj=ump_adj,
                relief_fatigue_woba=away_relief_fatigue_woba,
            )
            home_off = _simulate_offense(
                home_lineup, away_pitcher, away_team_id, park, rng,
                batx_map=home_batx_map, wx_mults=wx_mults, ump_adj=ump_adj,
                relief_fatigue_woba=home_relief_fatigue_woba,
            )
            if sim % 2 == 1:
                rng.stop_antithetic()
            if sample is None:
                sample = {
                    'away': away_off, 'home': home_off,
                    'away_abbr': away_abbr, 'home_abbr': home_abbr,
                    'away_pitcher': away_pitcher['name'], 'home_pitcher': home_pitcher['name']
                }
            for i, line in enumerate(away_off['batters']): away_store[i].append(line)
            for i, line in enumerate(home_off['batters']): home_store[i].append(line)
            home_starter_lines.append(away_off['starter'])
            away_starter_lines.append(home_off['starter'])
            home_bullpen_lines.append(away_off['bullpen'])
            away_bullpen_lines.append(home_off['bullpen'])
            for k in away_relief.keys():
                away_relief[k].append(home_off['relief_lines'][k])
                home_relief[k].append(away_off['relief_lines'][k])
            away_team_runs.append(away_off['runs']); home_team_runs.append(home_off['runs']); totals.append(away_off['runs'] + home_off['runs'])
            if away_off['runs'] > home_off['runs']: away_win += 1
            elif home_off['runs'] > away_off['runs']: home_win += 1
            else: ties += 1

        away_props = []
        for i, b in enumerate(away_lineup):
            s = _summarize_player(away_store[i])
            s.update({'id': b.get('id'), 'name': b.get('name'), 'slot': b.get('slot'), 'pos': b.get('pos'), 'bats': b.get('bats', 'S')})
            bx = away_batx_map.get(i, {})
            s['batx_composite'] = round(bx.get('composite', 1.0), 4)
            s['batx_hit_mult']  = round(bx.get('hit_mult',  1.0), 4)
            s['batx_hr_mult']   = round(bx.get('hr_mult',   1.0), 4)
            away_props.append(s)
        home_props = []
        for i, b in enumerate(home_lineup):
            s = _summarize_player(home_store[i])
            s.update({'id': b.get('id'), 'name': b.get('name'), 'slot': b.get('slot'), 'pos': b.get('pos'), 'bats': b.get('bats', 'S')})
            bx = home_batx_map.get(i, {})
            s['batx_composite'] = round(bx.get('composite', 1.0), 4)
            s['batx_hit_mult']  = round(bx.get('hit_mult',  1.0), 4)
            s['batx_hr_mult']   = round(bx.get('hr_mult',   1.0), 4)
            home_props.append(s)

        away_pitch_summary = _summarize_pitcher(away_starter_lines)
        away_pitch_summary.update({'name': away_pitcher['name'], 'pitchHand': away_pitcher['pitchHand']})
        home_pitch_summary = _summarize_pitcher(home_starter_lines)
        home_pitch_summary.update({'name': home_pitcher['name'], 'pitchHand': home_pitcher['pitchHand']})
        away_bullpen_summary = _summarize_pitcher(away_bullpen_lines)
        away_bullpen_summary.update({'name': away_abbr + ' Bullpen'})
        home_bullpen_summary = _summarize_pitcher(home_bullpen_lines)
        home_bullpen_summary.update({'name': home_abbr + ' Bullpen'})

        away_tiers = {k.lower(): _summarize_pitcher(v) for k, v in away_relief.items()}
        home_tiers = {k.lower(): _summarize_pitcher(v) for k, v in home_relief.items()}

        away_l = sum(1 for b in away_lineup if (b.get('bats') or 'S') == 'L')
        away_r = sum(1 for b in away_lineup if (b.get('bats') or 'S') == 'R')
        away_s = sum(1 for b in away_lineup if (b.get('bats') or 'S') == 'S')
        home_l = sum(1 for b in home_lineup if (b.get('bats') or 'S') == 'L')
        home_r = sum(1 for b in home_lineup if (b.get('bats') or 'S') == 'R')
        home_s = sum(1 for b in home_lineup if (b.get('bats') or 'S') == 'S')

        # Phase 2.6: expose Monte Carlo correlation matrix + top SGP combos.
        market_vectors = []

        def _event_meta(market):
            if market == 'batter_hits':
                return {'line': 0.5, 'side': 'Over', 'short': 'H'}
            if market == 'batter_home_runs':
                return {'line': 0.5, 'side': 'Over', 'short': 'HR'}
            if market == 'batter_total_bases':
                return {'line': 1.5, 'side': 'Over', 'short': 'TB'}
            if market == 'batter_rbis':
                return {'line': 0.5, 'side': 'Over', 'short': 'RBI'}
            if market == 'batter_runs':
                return {'line': 0.5, 'side': 'Over', 'short': 'R'}
            if market == 'batter_hits_runs_rbis':
                return {'line': 1.5, 'side': 'Over', 'short': 'H+R+RBI'}
            if market == 'pitcher_strikeouts':
                return {'line': 4.5, 'side': 'Over', 'short': 'K'}
            return {'line': 0.5, 'side': 'Over', 'short': 'PROP'}

        def _add_batter_market_vectors(lineup, store, team_abbr):
            batter_markets = {
                'batter_hits': ('h', 1),
                'batter_home_runs': ('hr', 1),
                'batter_total_bases': ('tb', 2),
                'batter_rbis': ('rbi', 1),
                'batter_runs': ('r', 1),
                'batter_hits_runs_rbis': (lambda x: (x.get('h', 0) + x.get('r', 0) + x.get('rbi', 0)), 2),
            }
            for idx, batter in enumerate(lineup):
                lines = store.get(idx, [])
                if not lines:
                    continue
                for market, (stat_source, event_floor) in batter_markets.items():
                    if callable(stat_source):
                        values = [stat_source(x) for x in lines]
                    else:
                        values = [x.get(stat_source, 0) for x in lines]
                    if not values:
                        continue
                    meta = _event_meta(market)
                    event_prob = sum(1 for x in values if x >= event_floor) / len(values)
                    market_vectors.append({
                        'player': batter.get('name', ''),
                        'team': team_abbr,
                        'market': market,
                        'values': values,
                        'event_floor': event_floor,
                        'event_prob': round(event_prob, 4),
                        'line': meta['line'],
                        'side': meta['side'],
                        'leg_label': f"{batter.get('name', '')} {meta['short']}",
                    })

        _add_batter_market_vectors(away_lineup, away_store, away_abbr)
        _add_batter_market_vectors(home_lineup, home_store, home_abbr)

        for p_name, p_team, p_lines in (
            (away_pitcher['name'], away_abbr, away_starter_lines),
            (home_pitcher['name'], home_abbr, home_starter_lines),
        ):
            values = [x.get('k', 0) for x in p_lines]
            if values:
                meta = _event_meta('pitcher_strikeouts')
                floor = 5
                market_vectors.append({
                    'player': p_name,
                    'team': p_team,
                    'market': 'pitcher_strikeouts',
                    'values': values,
                    'event_floor': floor,
                    'event_prob': round(sum(1 for x in values if x >= floor) / len(values), 4),
                    'line': meta['line'],
                    'side': meta['side'],
                    'leg_label': f"{p_name} {meta['short']}",
                })

        correlations = []
        combo_candidates = []
        for i in range(len(market_vectors)):
            row_a = market_vectors[i]
            for j in range(i + 1, len(market_vectors)):
                row_b = market_vectors[j]
                r = _pearson_corr(row_a['values'], row_b['values'])
                if abs(r) < 0.10:
                    continue
                strength = _corr_strength_label(r)
                warning = _corr_warning(row_a, row_b, r)
                corr_item = {
                    'playerA': row_a['player'],
                    'marketA': row_a['market'],
                    'teamA': row_a['team'],
                    'playerB': row_b['player'],
                    'marketB': row_b['market'],
                    'teamB': row_b['team'],
                    'r': round(r, 3),
                    'strength': strength,
                }
                if warning:
                    corr_item['warning'] = warning
                correlations.append(corr_item)

                if r > 0:
                    event_a = [1 if x >= row_a['event_floor'] else 0 for x in row_a['values']]
                    event_b = [1 if x >= row_b['event_floor'] else 0 for x in row_b['values']]
                    joint_hits = sum(1 for a, b in zip(event_a, event_b) if a and b)
                    combined_prob = joint_hits / sims
                    indep_prob = row_a['event_prob'] * row_b['event_prob']
                    combo_candidates.append({
                        'legs': [row_a['leg_label'], row_b['leg_label']],
                        'legs_meta': [
                            {
                                'player': row_a['player'],
                                'market': row_a['market'],
                                'line': row_a['line'],
                                'side': row_a['side'],
                                'team': row_a['team'],
                            },
                            {
                                'player': row_b['player'],
                                'market': row_b['market'],
                                'line': row_b['line'],
                                'side': row_b['side'],
                                'team': row_b['team'],
                            },
                        ],
                        'combined_prob': round(combined_prob, 3),
                        'r': round(r, 3),
                        'strength': strength,
                        'combined_ev_pct': round((combined_prob - indep_prob) * 100, 2),
                        'score': (combined_prob * 0.65) + (r * 0.35),
                    })

        correlations = sorted(correlations, key=lambda x: abs(x['r']), reverse=True)[:240]
        top_sgp_combos = sorted(combo_candidates, key=lambda x: x['score'], reverse=True)[:5]
        for c in top_sgp_combos:
            c.pop('score', None)

        # Build a projected (expected-value) box score from MC means.
        # The legacy `sampleBoxscore` is a single random draw from sim #0 — useful
        # for visualizing one possible game, but misleading as a prediction. This
        # struct exposes mean H/HR/RBI/etc per batter so consumers can show the
        # model's actual expectation alongside p(1+H) / p(2+H) variance bands.
        def _projected_team_box(props, lineup, team_runs):
            rows = []
            for i, b in enumerate(lineup):
                p = props[i] if i < len(props) else {}
                # Expected PAs — matches the slot decay used in _project_batter_batx
                exp_pa = round(max(3.4, 4.35 - i * 0.095), 2)
                rows.append({
                    'slot':       i + 1,
                    'name':       b.get('name'),
                    'pos':        b.get('pos'),
                    'bats':       b.get('bats', 'S'),
                    'pa':         exp_pa,
                    'mean_h':     p.get('mean_hits', 0.0),
                    'p50_h':      p.get('p50_hits', 0),
                    'p90_h':      p.get('p90_hits', 0),
                    'p_1plus_h':  p.get('p_1plus_hit', 0.0),
                    'p_2plus_h':  p.get('p_2plus_hit', 0.0),
                    'mean_hr':    p.get('mean_hr', 0.0),
                    'mean_rbi':   p.get('mean_rbi', 0.0),
                    'mean_r':     p.get('mean_runs', 0.0),
                    'mean_bb':    p.get('mean_bb', 0.0),
                    'mean_k':     p.get('mean_k', 0.0),
                    'mean_tb':    p.get('mean_tb', 0.0),
                    'p_1plus_hr': p.get('p_1plus_hr', 0.0),
                })
            return {
                'batters':   rows,
                'mean_runs': round(statistics.mean(team_runs), 2) if team_runs else 0.0,
                'mean_hits': round(sum(r['mean_h']  for r in rows), 1),
                'mean_bb':   round(sum(r['mean_bb'] for r in rows), 1),
                'mean_k':    round(sum(r['mean_k']  for r in rows), 1),
                'mean_tb':   round(sum(r['mean_tb'] for r in rows), 1),
            }

        projected_box = {
            'away':         _projected_team_box(away_props, away_lineup, away_team_runs),
            'home':         _projected_team_box(home_props, home_lineup, home_team_runs),
            'away_abbr':    away_abbr,
            'home_abbr':    home_abbr,
            'away_pitcher': away_pitcher['name'],
            'home_pitcher': home_pitcher['name'],
            'sims':         sims,
        }

        payload = {
            'success': True,
            'meta': {'sims': sims, 'awayAbbr': away_abbr, 'homeAbbr': home_abbr, 'parkFactor': park},
            'team': {
                'away_mean_runs': round(statistics.mean(away_team_runs), 2),
                'home_mean_runs': round(statistics.mean(home_team_runs), 2),
                'mean_total': round(statistics.mean(totals), 2),
                'median_total': statistics.median(totals),
                'std_total': round(statistics.pstdev(totals), 2) if len(totals) > 1 else 0.0,
                'p25_total': round(_pctl(totals, 25), 1),
                'p75_total': round(_pctl(totals, 75), 1),
                'p_8plus_total': round(sum(1 for x in totals if x >= 8)/len(totals), 3),
                'p_9plus_total': round(sum(1 for x in totals if x >= 9)/len(totals), 3),
                'p_10plus_total': round(sum(1 for x in totals if x >= 10)/len(totals), 3),
                # P(over) at each common book total — the O/U ladder.
                'ou_ladder': {str(L): round(sum(1 for x in totals if x > L)/len(totals), 3)
                              for L in (6.5, 7.5, 8.5, 9.5, 10.5, 11.5)},
                'away_win_pct': round(away_win / sims, 3),
                'home_win_pct': round(home_win / sims, 3),
                'tie_pct': round(ties / sims, 3),
            },
            'handedness': {
                'awayLineup': {'L': away_l, 'R': away_r, 'S': away_s},
                'homeLineup': {'L': home_l, 'R': home_r, 'S': home_s},
                'awayStarterHand': away_pitcher['pitchHand'],
                'homeStarterHand': home_pitcher['pitchHand'],
            },
            'playerProps': {'away': away_props, 'home': home_props},
            'pitcherProps': {
                'awayStarter': away_pitch_summary, 'homeStarter': home_pitch_summary,
                'awayBullpen': away_bullpen_summary, 'homeBullpen': home_bullpen_summary,
                'awayBullpenTiers': away_tiers, 'homeBullpenTiers': home_tiers,
            },
            'correlations': correlations,
            'top_sgp_combos': top_sgp_combos,
            'sampleBoxscore': sample,
            'projectedBoxscore': projected_box,
        }
        _correlation_cache[game_pk] = {
            'date': today,
            'signature': cache_signature,
            'payload': payload,
        }
        return payload
    except Exception as ex:
        print('[api_simulate]', traceback.format_exc())
        try:
            g = fetch_schedule_game(game_pk) or {}
            fallback = _simulation_fallback_payload(
                g,
                game_pk,
                sims=sims,
                warning=f'Fallback mode: {str(ex) or "simulation error"}'
            )
            return fallback
        except Exception as fallback_ex:
            print('[api_simulate:fallback]', traceback.format_exc())
            emergency = _simulation_fallback_payload(
                {},
                game_pk,
                sims=sims,
                warning=f'Emergency fallback: {str(ex) or "simulation error"}; {str(fallback_ex) or "fallback error"}'
            )
            return emergency


# ── Durable simulation dispatcher ────────────────────────────────────────────
_SIMULATION_CACHE_TTL = int(os.getenv('SIMULATION_CACHE_TTL', '3600') or 3600)


def _simulation_snapshot_key(game_pk, sims, date_str=None):
    return normalize_cache_key(
        'linked_game_simulation_v436',
        int(game_pk),
        int(sims),
        date_str or datetime.now(ET).strftime('%Y-%m-%d'),
    )


def _read_simulation_snapshot(game_pk, sims, date_str=None):
    value = get_redis().get(_simulation_snapshot_key(game_pk, sims, date_str))
    if not isinstance(value, dict) or not isinstance(value.get('payload'), dict):
        return None
    return value


def _write_simulation_snapshot(game_pk, sims, payload, date_str=None):
    record = {'timestamp': time.time(), 'payload': dict(payload)}
    key = _simulation_snapshot_key(game_pk, sims, date_str)
    try:
        write_durable_json(key, record, ttl=_SIMULATION_CACHE_TTL)
    except JobQueueUnavailable:
        if settings.production:
            raise
        get_redis().set(key, record, ttl=_SIMULATION_CACHE_TTL)


@app.route('/api/simulate/<int:game_pk>')
def api_simulate(game_pk):
    try:
        sims = max(1500, min(5000, int(request.args.get('sims', 1500) or 1500)))
    except Exception:
        sims = 1500
    refresh = request.args.get('refresh') == '1'
    today = datetime.now(ET).strftime('%Y-%m-%d')
    cached = _read_simulation_snapshot(game_pk, sims, today)
    if cached and not refresh:
        return jsonify(dict(cached['payload'], cached=True))

    try:
        job = enqueue_job(
            'simulation',
            {'gamePk': game_pk, 'sims': sims, 'date': today},
            dedupe_key=f'simulation:{today}:{game_pk}:{sims}',
            timeout_seconds=360,
            max_attempts=2,
        )
        status = get_job_queue().snapshot(job) or {}
    except JobQueueUnavailable:
        return jsonify({
            'success': False,
            'simulationReady': False,
            'computing': False,
            'error': 'Simulation worker is unavailable. No estimate was substituted.',
            'retryable': True,
        }), 503

    if status.get('status') == 'error':
        return jsonify({
            'success': False,
            'simulationReady': False,
            'computing': False,
            'error': status.get('error') or 'Matchup simulation failed.',
            'retryable': True,
        }), 503
    return jsonify({
        'computing': True,
        'elapsed': status.get('elapsedSeconds', 0),
        'estimatedSeconds': max(15, 120 - int(status.get('elapsedSeconds') or 0)),
        'job': status,
    })


# ── Phase 7 Odds / Lineup / Edge Infrastructure ──────────────────────────────
ODDS_API_KEY = (os.getenv('ODDS_API_KEY') or '').strip()
ODDS_REGION = (os.getenv('ODDS_REGION') or 'us').strip()
ODDS_CACHE_STORE = os.path.join(DATA_DIR, 'odds_cache.json')


def _odds_ttl_seconds(env_key, default_seconds, min_seconds=30, max_seconds=24 * 60 * 60):
    """Read a TTL (seconds) from env with sane bounds and fallback."""
    raw = os.getenv(env_key)
    if raw is None or str(raw).strip() == '':
        return int(default_seconds)
    try:
        ttl = int(float(raw))
    except Exception:
        return int(default_seconds)
    return max(int(min_seconds), min(int(max_seconds), ttl))


def _odds_bool_env(env_key, default='1'):
    return str(os.getenv(env_key, default)).strip().lower() in ('1', 'true', 'yes')

# ── Odds API cache — prevents burning credits on every request ────────────────
# Events list: cache 6h (rarely changes intraday)
# Per-game odds snapshot: cache 24h by default (single fetch reused everywhere)
_ODDS_EVENTS_CACHE: dict = {}          # {'data': [...], 'ts': float}
_ODDS_GAME_CACHE:  dict = {}           # {event_id: {'all': [...], 'ts': float}}
# First-seen best over price today, keyed by (date_str, player, market_key, line).
# Populated on first call to _market_price_summary per key each calendar day.
_OPENING_PRICE_CACHE: dict = {}
_OPENING_PRICE_LOCK = threading.Lock()
# Timestamped price history for sparklines. Same key structure as _OPENING_PRICE_CACHE.
# Each value is a list of [iso_timestamp, american_price] tuples, oldest first.
_PRICE_HISTORY_CACHE: dict = {}
_PRICE_HISTORY_LOCK = threading.Lock()
_ODDS_EVENTS_TTL  = _odds_ttl_seconds('ODDS_EVENTS_TTL_SEC', 6 * 60 * 60)
_ODDS_GAME_TTL    = _odds_ttl_seconds('ODDS_GAME_TTL_SEC', 24 * 60 * 60)
_ODDS_NRFI_TTL    = _odds_ttl_seconds('ODDS_NRFI_TTL_SEC', 5 * 60)
_ODDS_DAILY_CACHE = _odds_bool_env('ODDS_DAILY_CACHE', '1')
_ODDS_SNAPSHOT_STRICT = _odds_bool_env('ODDS_SNAPSHOT_STRICT', '1')
_ODDS_SNAPSHOT_AUTOWARM = _odds_bool_env('ODDS_SNAPSHOT_AUTOWARM', '1')
_ODDS_SNAPSHOT_HEARTBEAT_SEC = _odds_ttl_seconds('ODDS_SNAPSHOT_HEARTBEAT_SEC', 5 * 60, min_seconds=60, max_seconds=60 * 60)
_ODDS_SNAPSHOT_RETRY_SEC = _odds_ttl_seconds('ODDS_SNAPSHOT_RETRY_SEC', 15 * 60, min_seconds=60, max_seconds=6 * 60 * 60)
_ODDS_CACHE_LOCK = threading.Lock()
_ODDS_SNAPSHOT_WORKER_LOCK = threading.Lock()
# Single-thread executor for non-blocking odds-cache file persistence.
_odds_io_executor = ThreadPoolExecutor(max_workers=1, thread_name_prefix="odds_io")
_ODDS_SNAPSHOT_WORKER_STARTED = False
_ODDS_SNAPSHOT_WORKER_LAST_ATTEMPT = 0.0
_ODDS_SNAPSHOT_META: dict = {
    'date': None,
    'complete': False,
    'running': False,
    'startedAt': None,
    'completedAt': None,
    'eventsCount': 0,
    'eventsFetched': 0,
    'errors': [],
    # The Odds API credit usage (from x-requests-* response headers), so we can
    # confirm caching is actually saving fetch usage.
    'creditsRemaining': None,
    'creditsUsed': None,
    'creditsLastCost': None,
    'creditsUsedToday': 0,
    'lastCreditAt': None,
}


def _record_odds_credits(resp):
    """Capture The Odds API credit headers after a live fetch. Cheap, best-effort."""
    try:
        h = resp.headers or {}
        rem = h.get('x-requests-remaining')
        used = h.get('x-requests-used')
        last = h.get('x-requests-last')
        with _ODDS_CACHE_LOCK:
            if rem is not None:
                _ODDS_SNAPSHOT_META['creditsRemaining'] = int(float(rem))
            if used is not None:
                _ODDS_SNAPSHOT_META['creditsUsed'] = int(float(used))
            if last is not None:
                cost = int(float(last))
                _ODDS_SNAPSHOT_META['creditsLastCost'] = cost
                if _ODDS_SNAPSHOT_META.get('date') == _odds_today_key():
                    _ODDS_SNAPSHOT_META['creditsUsedToday'] = int(_ODDS_SNAPSHOT_META.get('creditsUsedToday') or 0) + cost
            _ODDS_SNAPSHOT_META['lastCreditAt'] = datetime.now(timezone.utc).isoformat()
    except Exception:
        pass
_ODDS_PRIMARY_MARKETS = (
    'h2h,spreads,totals,h2h_1st_1_innings,'
    'batter_hits,batter_total_bases,batter_home_runs,batter_rbis,'
    'batter_runs_scored,batter_stolen_bases,batter_hits_runs_rbis,pitcher_strikeouts'
)
# Alternate-line ladders (e.g. K 1.5..9.5 per book) for the line-shopping matrix.
# Each key bills as one extra market per event request, so the daily snapshot
# costs ~5 more credits per game per day with these on; disable with
# ODDS_INCLUDE_ALT_MARKETS=0 to fall back to primary lines only.
_ODDS_ALT_MARKETS = (
    'batter_hits_alternate,batter_total_bases_alternate,'
    'batter_home_runs_alternate,batter_rbis_alternate,pitcher_strikeouts_alternate'
)
_ODDS_INCLUDE_ALT = _odds_bool_env('ODDS_INCLUDE_ALT_MARKETS', '1')
_ODDS_ALL_MARKETS = _ODDS_PRIMARY_MARKETS + (',' + _ODDS_ALT_MARKETS if _ODDS_INCLUDE_ALT else '')


def _odds_today_key():
    return datetime.now(ET).strftime('%Y-%m-%d')


def _odds_cache_entry_fresh(entry, data_key, ttl_sec):
    if not isinstance(entry, dict) or data_key not in entry:
        return False
    if _ODDS_DAILY_CACHE and entry.get('cache_date') == _odds_today_key():
        return True
    try:
        return (time.time() - float(entry.get('ts') or 0.0)) < float(ttl_sec)
    except Exception:
        return False


def _persist_odds_caches():
    payload = {
        'date': _odds_today_key(),
        'events': _ODDS_EVENTS_CACHE,
        'games': _ODDS_GAME_CACHE,
        'snapshot': _ODDS_SNAPSHOT_META,
        'savedAt': datetime.now(timezone.utc).isoformat(),
    }
    _save_json(ODDS_CACHE_STORE, payload)


def _restore_odds_caches():
    payload = _load_json(ODDS_CACHE_STORE, {})
    if not isinstance(payload, dict):
        return
    if payload.get('date') != _odds_today_key():
        return
    events = payload.get('events') or {}
    games = payload.get('games') or {}
    snapshot = payload.get('snapshot') or {}
    if isinstance(events, dict):
        _ODDS_EVENTS_CACHE.update(events)
    if isinstance(games, dict):
        _ODDS_GAME_CACHE.update(games)
    if isinstance(snapshot, dict):
        _ODDS_SNAPSHOT_META.update(snapshot)
        _ODDS_SNAPSHOT_META['running'] = False


def _ensure_daily_odds_snapshot():
    """Build one full odds snapshot for today, then serve cache-only for the rest of the day."""
    if not ODDS_API_KEY:
        return False

    with _ODDS_CACHE_LOCK:
        today = _odds_today_key()
        if _ODDS_SNAPSHOT_META.get('date') == today and _ODDS_SNAPSHOT_META.get('complete'):
            return True
        if _ODDS_SNAPSHOT_META.get('running'):
            return False
        _ODDS_SNAPSHOT_META.update({
            'date': today,
            'complete': False,
            'running': True,
            'startedAt': datetime.now(timezone.utc).isoformat(),
            'completedAt': None,
            'eventsCount': 0,
            'eventsFetched': 0,
            'errors': [],
            'creditsUsedToday': 0,
        })

    try:
        now = time.time()
        r = requests.get(
            'https://api.the-odds-api.com/v4/sports/baseball_mlb/events',
            params={'apiKey': ODDS_API_KEY, 'dateFormat': 'iso'},
            timeout=12,
        )
        r.raise_for_status()
        _record_odds_credits(r)
        events = r.json() or []

        with _ODDS_CACHE_LOCK:
            _ODDS_EVENTS_CACHE['data'] = events
            _ODDS_EVENTS_CACHE['ts'] = now
            _ODDS_EVENTS_CACHE['cache_date'] = _odds_today_key()
            _ODDS_SNAPSHOT_META['eventsCount'] = len(events)

        fetched = 0
        errors = []
        for ev in events:
            eid = ev.get('id')
            if not eid:
                continue
            try:
                now_ev = time.time()
                rr = requests.get(
                    f'https://api.the-odds-api.com/v4/sports/baseball_mlb/events/{eid}/odds',
                    params={
                        'apiKey': ODDS_API_KEY,
                        'regions': ODDS_REGION,
                        'markets': _ODDS_ALL_MARKETS,
                        'oddsFormat': 'american',
                        'dateFormat': 'iso',
                    },
                    timeout=15,
                )
                rr.raise_for_status()
                _record_odds_credits(rr)
                books = rr.json().get('bookmakers', []) or []
                with _ODDS_CACHE_LOCK:
                    _ODDS_GAME_CACHE[eid] = {
                        'all': books,
                        'ts': now_ev,
                        'cache_date': _odds_today_key(),
                    }
                fetched += 1
            except Exception as ex:
                errors.append(f'{eid}: {ex}')

        with _ODDS_CACHE_LOCK:
            _ODDS_SNAPSHOT_META['eventsFetched'] = fetched
            _ODDS_SNAPSHOT_META['errors'] = errors[:50]
            _ODDS_SNAPSHOT_META['completedAt'] = datetime.now(timezone.utc).isoformat()
            _ODDS_SNAPSHOT_META['complete'] = True
            _ODDS_SNAPSHOT_META['running'] = False
        # Persist to disk off the critical path so this thread isn't blocked by disk I/O.
        _odds_io_executor.submit(_persist_odds_caches)

        print(f'[Odds] Daily snapshot complete: events={len(events)} fetched={fetched} errors={len(errors)}')
        return True
    except Exception as ex:
        with _ODDS_CACHE_LOCK:
            _ODDS_SNAPSHOT_META['errors'] = [str(ex)]
            _ODDS_SNAPSHOT_META['completedAt'] = datetime.now(timezone.utc).isoformat()
            _ODDS_SNAPSHOT_META['complete'] = False
            _ODDS_SNAPSHOT_META['running'] = False
        _odds_io_executor.submit(_persist_odds_caches)
        print(f'[Odds] Daily snapshot failed: {ex}')
        return False


def _odds_snapshot_ready_today():
    with _ODDS_CACHE_LOCK:
        return (
            _ODDS_SNAPSHOT_META.get('date') == _odds_today_key()
            and bool(_ODDS_SNAPSHOT_META.get('complete'))
        )


def _start_odds_snapshot_worker():
    """Continuously ensure today's odds snapshot is built without manual priming."""
    global _ODDS_SNAPSHOT_WORKER_STARTED, _ODDS_SNAPSHOT_WORKER_LAST_ATTEMPT
    with _ODDS_SNAPSHOT_WORKER_LOCK:
        if _ODDS_SNAPSHOT_WORKER_STARTED:
            return
        _ODDS_SNAPSHOT_WORKER_STARTED = True

    def _runner():
        global _ODDS_SNAPSHOT_WORKER_LAST_ATTEMPT
        # Give startup loaders a short head start.
        time.sleep(8)
        while True:
            try:
                if not _ODDS_SNAPSHOT_AUTOWARM or not ODDS_API_KEY:
                    time.sleep(5 * 60)
                    continue

                if _odds_snapshot_ready_today():
                    time.sleep(_ODDS_SNAPSHOT_HEARTBEAT_SEC)
                    continue

                now = time.time()
                if (now - _ODDS_SNAPSHOT_WORKER_LAST_ATTEMPT) < _ODDS_SNAPSHOT_RETRY_SEC:
                    time.sleep(30)
                    continue

                _ODDS_SNAPSHOT_WORKER_LAST_ATTEMPT = now
                built = _ensure_daily_odds_snapshot()
                if built:
                    print('[ODDS_WORKER] Daily snapshot ready')
                else:
                    print('[ODDS_WORKER] Snapshot attempt incomplete; will retry')
            except Exception as ex:
                print(f'[ODDS_WORKER] Snapshot loop error: {ex}')
            time.sleep(30)

    threading.Thread(target=_runner, daemon=True).start()


_restore_odds_caches()


def _norm_name(s):
    return re.sub(r'[^a-z0-9]+', '', (s or '').lower())


def _american_to_implied(price):
    try:
        p = float(price)
        if p > 0:
            return round(100.0 / (p + 100.0), 4)
        if p < 0:
            return round((-p) / ((-p) + 100.0), 4)
        return None
    except Exception:
        return None


def _find_odds_event(away_name, home_name):
    if not ODDS_API_KEY:
        return None, []
    try:
        ok = _ensure_daily_odds_snapshot()
        if _ODDS_SNAPSHOT_STRICT and (not ok or not _odds_snapshot_ready_today()):
            return None, []
        with _ODDS_CACHE_LOCK:
            events = _ODDS_EVENTS_CACHE.get('data') or []
        na = _norm_name(away_name)
        nh = _norm_name(home_name)
        for ev in events:
            if _norm_name(ev.get('away_team')) == na and _norm_name(ev.get('home_team')) == nh:
                return ev, events
        return None, events
    except Exception as ex:
        print(f'[_find_odds_event] {ex}')
        return None, []


def _best_moneyline(bookmakers, away_name, home_name):
    best = {'away': None, 'home': None}
    for bk in bookmakers or []:
        for m in bk.get('markets', []) or []:
            if m.get('key') != 'h2h':
                continue
            for o in m.get('outcomes', []) or []:
                nm = o.get('name')
                item = {'bookmaker': bk.get('title'), 'price': o.get('price'), 'implied': _american_to_implied(o.get('price'))}
                if nm == away_name:
                    if best['away'] is None or float(o.get('price', -9999)) > float(best['away']['price']):
                        best['away'] = item
                elif nm == home_name:
                    if best['home'] is None or float(o.get('price', -9999)) > float(best['home']['price']):
                        best['home'] = item
    return best


def _best_total(bookmakers):
    best = None
    for bk in bookmakers or []:
        for m in bk.get('markets', []) or []:
            if m.get('key') != 'totals':
                continue
            outs = m.get('outcomes', []) or []
            over = next((x for x in outs if str(x.get('name')).lower() == 'over'), None)
            under = next((x for x in outs if str(x.get('name')).lower() == 'under'), None)
            if not over or not under:
                continue
            cand = {
                'bookmaker': bk.get('title'),
                'line': over.get('point'),
                'over_price': over.get('price'), 'under_price': under.get('price'),
                'over_implied': _american_to_implied(over.get('price')),
                'under_implied': _american_to_implied(under.get('price')),
            }
            if best is None:
                best = cand
            else:
                # prefer widely used standard line nearest consensus price
                if abs(float(cand['over_price'] or 0)) < abs(float(best['over_price'] or 0)):
                    best = cand
    return best


def _best_spread(bookmakers, away_name, home_name):
    """Return best run-line (spreads market) for each side."""
    best = {'away': None, 'home': None}
    for bk in bookmakers or []:
        for m in bk.get('markets', []) or []:
            if m.get('key') != 'spreads':
                continue
            for o in m.get('outcomes', []) or []:
                nm = o.get('name', '')
                point = o.get('point')  # e.g. -1.5 or +1.5
                price = o.get('price')
                item = {'bookmaker': bk.get('title'), 'price': price, 'point': point,
                        'implied': _american_to_implied(price)}
                if nm == away_name:
                    if best['away'] is None or abs(float(price or 0)) < abs(float(best['away']['price'] or 0)):
                        best['away'] = item
                elif nm == home_name:
                    if best['home'] is None or abs(float(price or 0)) < abs(float(best['home']['price'] or 0)):
                        best['home'] = item
    return best


def _load_event_odds(event_id, featured_only=False):
    if not ODDS_API_KEY or not event_id:
        return []
    try:
        ok = _ensure_daily_odds_snapshot()
        if _ODDS_SNAPSHOT_STRICT and (not ok or not _odds_snapshot_ready_today()):
            return []
        with _ODDS_CACHE_LOCK:
            cached = _ODDS_GAME_CACHE.get(event_id)
            return (cached or {}).get('all') or []
    except Exception as ex:
        print(f'[_load_event_odds] {ex}')
        with _ODDS_CACHE_LOCK:
            cached = _ODDS_GAME_CACHE.get(event_id)
        return (cached or {}).get('all', [])


def _load_event_market_odds(event_id, markets, cache_key, ttl_sec):
    # Keep signature for compatibility; serve subset from unified per-event cache.
    if not ODDS_API_KEY or not event_id or not markets:
        return []
    books = _load_event_odds(event_id)
    if not books:
        return []
    wanted = {m.strip() for m in str(markets).split(',') if m.strip()}
    if not wanted:
        return books
    filtered = []
    for bk in books:
        mkts = [m for m in (bk.get('markets') or []) if (m.get('key') or '') in wanted]
        if not mkts:
            continue
        b = dict(bk)
        b['markets'] = mkts
        filtered.append(b)
    return filtered


def _refresh_odds_events_cache():
    if not ODDS_API_KEY:
        return []
    ok = _ensure_daily_odds_snapshot()
    if _ODDS_SNAPSHOT_STRICT and (not ok or not _odds_snapshot_ready_today()):
        return []
    with _ODDS_CACHE_LOCK:
        return _ODDS_EVENTS_CACHE.get('data') or []


def _odds_cache_status_payload():
    now = time.time()
    with _ODDS_CACHE_LOCK:
        events_cached = int(len(_ODDS_EVENTS_CACHE.get('data') or []))
        events_ts = float(_ODDS_EVENTS_CACHE.get('ts') or 0.0)
        events_date = _ODDS_EVENTS_CACHE.get('cache_date')
        game_entries = _ODDS_GAME_CACHE
        game_cached = int(len(game_entries or {}))
        game_rows = []
        for eid, ent in (game_entries or {}).items():
            if not isinstance(ent, dict):
                continue
            game_rows.append({
                'eventId': eid,
                'bookmakers': len(ent.get('all') or []),
                'cacheDate': ent.get('cache_date'),
                'ageSec': round(max(0.0, now - float(ent.get('ts') or 0.0)), 1),
            })
        game_rows.sort(key=lambda x: x.get('ageSec', 0.0))

    file_exists = os.path.exists(ODDS_CACHE_STORE)
    file_meta = {
        'exists': file_exists,
        'path': ODDS_CACHE_STORE,
        'sizeBytes': os.path.getsize(ODDS_CACHE_STORE) if file_exists else 0,
        'modifiedAt': datetime.fromtimestamp(os.path.getmtime(ODDS_CACHE_STORE), tz=timezone.utc).isoformat() if file_exists else None,
    }
    return {
        'success': True,
        'keyConfigured': bool(ODDS_API_KEY),
        'dailyCacheEnabled': _ODDS_DAILY_CACHE,
        'snapshotStrict': _ODDS_SNAPSHOT_STRICT,
        'snapshotAutowarm': _ODDS_SNAPSHOT_AUTOWARM,
        'todayET': _odds_today_key(),
        'ttl': {
            'eventsSec': _ODDS_EVENTS_TTL,
            'gameSec': _ODDS_GAME_TTL,
            'nrfiSec': _ODDS_NRFI_TTL,
        },
        'eventsCache': {
            'count': events_cached,
            'cacheDate': events_date,
            'ageSec': round(max(0.0, now - events_ts), 1) if events_ts else None,
        },
        'gameCache': {
            'count': game_cached,
            'entries': game_rows[:30],
        },
        'snapshot': dict(_ODDS_SNAPSHOT_META),
        'snapshotWorker': {
            'started': _ODDS_SNAPSHOT_WORKER_STARTED,
            'retrySec': _ODDS_SNAPSHOT_RETRY_SEC,
            'heartbeatSec': _ODDS_SNAPSHOT_HEARTBEAT_SEC,
        },
        'file': file_meta,
    }


def _clear_odds_caches_locked():
    _ODDS_EVENTS_CACHE.clear()
    _ODDS_GAME_CACHE.clear()
    _ODDS_SNAPSHOT_META.update({
        'date': None,
        'complete': False,
        'running': False,
        'startedAt': None,
        'completedAt': None,
        'eventsCount': 0,
        'eventsFetched': 0,
        'errors': [],
    })
    _persist_odds_caches()


@app.route('/api/odds/cache/status')
def api_odds_cache_status():
    try:
        return jsonify(_odds_cache_status_payload())
    except Exception as ex:
        print(f'[api_odds_cache_status] {traceback.format_exc()}')
        return jsonify({'success': False, 'error': str(ex)}), 500


@app.route('/api/odds/cache/refresh', methods=['POST'])
def api_odds_cache_refresh():
    payload = request.get_json(silent=True) or {}
    mode = str(payload.get('mode') or request.args.get('mode') or 'snapshot').strip().lower()
    date_str = str(payload.get('date') or request.args.get('date') or datetime.now(ET).strftime('%Y-%m-%d')).strip()
    event_id = payload.get('eventId') or request.args.get('eventId')
    game_pk = payload.get('gamePk') or request.args.get('gamePk')
    clear_first = str(payload.get('clearFirst', request.args.get('clearFirst', '1'))).strip().lower() in ('1', 'true', 'yes')

    if settings.process_role != 'worker':
        try:
            job = enqueue_job(
                'odds_refresh',
                {
                    'mode': mode,
                    'date': date_str,
                    'eventId': event_id,
                    'gamePk': game_pk,
                    'clearFirst': clear_first,
                },
                dedupe_key=f'odds-refresh:{date_str}:{mode}:{event_id or game_pk or "all"}',
                timeout_seconds=600,
                max_attempts=2,
            )
            return jsonify({'success': True, 'queued': True, 'jobId': job['id']}), 202
        except JobQueueUnavailable:
            return jsonify({'success': False, 'error': 'Worker unavailable'}), 503

    if not ODDS_API_KEY:
        return jsonify({'success': False, 'error': 'ODDS_API_KEY is not configured'}), 400

    try:
        with _ODDS_CACHE_LOCK:
            if clear_first:
                _clear_odds_caches_locked()

        events = _refresh_odds_events_cache()
        result = {
            'success': True,
            'mode': mode,
            'date': date_str,
            'eventsRefreshed': len(events),
            'prefetchedEventIds': [],
            'prefetchedCount': 0,
            'clearFirst': clear_first,
        }

        if mode in ('snapshot', 'build'):
            snapshot_ok = _odds_snapshot_ready_today()
            result['snapshotBuilt'] = snapshot_ok
            result['prefetchedEventIds'] = list((_ODDS_GAME_CACHE or {}).keys())[:50]
            result['prefetchedCount'] = len(_ODDS_GAME_CACHE or {})
        elif mode in ('today', 'all'):
            sched = fetch_schedule(date_str)
            event_map = {
                (_norm_name(ev.get('away_team')), _norm_name(ev.get('home_team'))): ev
                for ev in events
            }
            seen = set()
            for g in sched or []:
                away_name = (((g.get('teams') or {}).get('away') or {}).get('team') or {}).get('name')
                home_name = (((g.get('teams') or {}).get('home') or {}).get('team') or {}).get('name')
                ev = event_map.get((_norm_name(away_name), _norm_name(home_name)))
                if not ev:
                    continue
                eid = ev.get('id')
                if not eid or eid in seen:
                    continue
                seen.add(eid)
                _load_event_odds(eid)
                result['prefetchedEventIds'].append(eid)
            result['prefetchedCount'] = len(result['prefetchedEventIds'])
        elif mode in ('event', 'single'):
            target_event_id = event_id
            if not target_event_id and game_pk:
                try:
                    gpk = int(game_pk)
                except Exception:
                    return jsonify({'success': False, 'error': 'gamePk must be an integer'}), 400
                sched = fetch_schedule(date_str)
                g = next((x for x in (sched or []) if x.get('gamePk') == gpk), None)
                if not g:
                    return jsonify({'success': False, 'error': f'gamePk {gpk} not found for {date_str}'}), 404
                away_name = (((g.get('teams') or {}).get('away') or {}).get('team') or {}).get('name')
                home_name = (((g.get('teams') or {}).get('home') or {}).get('team') or {}).get('name')
                ev, _ = _find_odds_event(away_name, home_name)
                target_event_id = (ev or {}).get('id') if ev else None
            if not target_event_id:
                return jsonify({'success': False, 'error': 'event mode requires eventId or gamePk'}), 400
            _load_event_odds(target_event_id)
            result['prefetchedEventIds'] = [target_event_id]
            result['prefetchedCount'] = 1

        result['status'] = _odds_cache_status_payload()
        return jsonify(result)
    except Exception as ex:
        print(f'[api_odds_cache_refresh] {traceback.format_exc()}')
        return jsonify({'success': False, 'error': str(ex)}), 500


def _poisson_over_prob(mean, line):
    """P(X > line) = P(X >= floor(line)+1) via Poisson(mean). Works for any half-integer line."""
    k = int(line) + 1
    if mean <= 0 or k < 1:
        return 0.0
    lam = float(mean)
    log_p = -lam
    cdf = math.exp(log_p)
    for x in range(1, k):
        log_p += math.log(lam) - math.log(x)
        cdf += math.exp(log_p)
    return max(0.0, min(1.0, 1.0 - cdf))


# Binomial 1+ probability for low-count, low-trial outcomes (hit/PA).
# Removes the structural bias of Poisson(λ=expected_count) for 1+ hit, where
# events aren't rare and the trial count (PA) is small.
def _binomial_over_zero(mean_count, expected_n):
    try:
        m = float(mean_count or 0)
        n = float(expected_n or 0)
    except (TypeError, ValueError):
        return 0.0
    if m <= 0 or n <= 0:
        return 0.0
    p = max(0.0, min(0.95, m / n))
    return max(0.0, min(1.0, 1.0 - (1.0 - p) ** n))


def _logit(p):
    p = max(1e-4, min(1 - 1e-4, float(p)))
    return math.log(p / (1.0 - p))


def _logit_divergence(p_a, p_b):
    """Absolute divergence on the logit scale — variance-aware: a 22pt gap near
    p=0.5 yields ~0.9 nats, while the same gap near p=0.9 yields ~1.6 nats.
    """
    return abs(_logit(p_a) - _logit(p_b))


def _shrink_to_prior(p, prior, weight):
    """Linear blend p toward prior. weight=0 → no shrinkage, weight=1 → prior."""
    w = max(0.0, min(1.0, float(weight)))
    return (1.0 - w) * float(p) + w * float(prior)


# Per-projection coverage score for the XGB hit model. Returns 0..1 — 1 means
# all key Statcast + FanGraphs inputs are populated, 0 means inputs are too
# thin to trust the XGB output. Drives both blend weight and reliability flag.
_XGB_HIT_COVERAGE_KEYS = (
    # batter
    ("b", "sv_xba",     0.200, 0.310),   # wider band - catches more real values
    ("b", "sv_xwoba",   0.280, 0.380),
    ("b", "sv_brl_pct", 1.0,   15.0),
    ("b", "fg_pa",      10,    None),     # lower PA threshold
    ("b", "l7Hits",     0.0,   7.0),    # recent form counts too
    # pitcher
    ("p", "fg_kpct",    0.10,  0.40),
    ("p", "fg_era",     2.00,  7.00),   # use ERA if FIP missing
)


def _xgb_hit_coverage(batter_stats, pitcher_stats):
    """Score 0..1 for how well-populated the XGB hit-model inputs are.

    Each key contributes 1/N if present and inside a plausible band, 0.5/N if
    present but at a default fallback (i.e. signal-less), 0 if missing.
    """
    if not batter_stats and not pitcher_stats:
        return 0.0
    b = batter_stats or {}
    p = pitcher_stats or {}
    total = len(_XGB_HIT_COVERAGE_KEYS)
    score = 0.0
    for side, key, lo, hi in _XGB_HIT_COVERAGE_KEYS:
        src = b if side == "b" else p
        v = src.get(key)
        if v is None:
            continue
        try:
            f = float(v)
        except (TypeError, ValueError):
            continue
        if f == 0:
            continue
        if hi is None:
            # one-sided threshold (e.g. minimum PA)
            if f >= lo:
                score += 1.0
            else:
                score += 0.5 * (f / lo)
            continue
        mid = (lo + hi) / 2.0
        # Penalise values that look like the default fallback (mid of the band).
        if abs(f - mid) < (hi - lo) * 0.05:
            score += 0.5
        else:
            score += 1.0
    return max(0.0, min(1.0, score / total))


def _market_lines_for_player(market_props, player, mk):
    """Sorted list of distinct lines actually offered in the market for a player/market combo."""
    seen = set()
    for item in market_props:
        if item.get('player') == player and item.get('market_key') == mk:
            try:
                seen.add(round(float(item.get('line')), 2))
            except (TypeError, ValueError):
                pass
    return sorted(seen)


