@app.route('/api/tracker/model-record')
def api_tracker_model_record():
    today = datetime.now(ET).strftime('%Y-%m-%d')
    entries = _collect_window_entries(today, 30)
    graded  = [e for e in entries if e.get('grade') in ('win', 'loss')]
    _MK_MAP = {
        'batter_hits': 'hits',
        'batter_home_runs': 'hr',
        'batter_total_bases': 'tb',
        'batter_rbis': 'rbi',
        'batter_runs_scored': 'runs',
        'batter_hits_runs_rbis': 'hrr',
        'pitcher_strikeouts': 'pitcher_strikeouts',
        'nrfi': 'nrfi',
        'yrfi': 'yrfi',
        'parlay': 'parlay',
    }
    by_mkt = {}
    for e in graded:
        mk  = e.get('marketKey', '')
        key = _MK_MAP.get(mk, mk)
        by_mkt.setdefault(key, {'wins': 0, 'losses': 0})
        if e.get('grade') == 'win':  by_mkt[key]['wins']   += 1
        else:                         by_mkt[key]['losses'] += 1
    record = {}
    for key, v in by_mkt.items():
        total = v['wins'] + v['losses']
        record[key] = {'wins': v['wins'], 'losses': v['losses'],
                       'graded': total,
                       'hit_rate': round(v['wins'] / total, 3) if total else 0.0}

    # Flat summary fields for UI consumers that only need hit rates.
    summary = {
        'hits': record.get('hits', {}).get('hit_rate', 0.0),
        'hr': record.get('hr', {}).get('hit_rate', 0.0),
        'pitcher_strikeouts': record.get('pitcher_strikeouts', {}).get('hit_rate', 0.0),
        'batter_total_bases': record.get('tb', {}).get('hit_rate', 0.0),
        'batter_rbis': record.get('rbi', {}).get('hit_rate', 0.0),
        'batter_runs_scored': record.get('runs', {}).get('hit_rate', 0.0),
        'batter_hits_runs_rbis': record.get('hrr', {}).get('hit_rate', 0.0),
        'parlay': record.get('parlay', {}).get('hit_rate', 0.0),
        'nrfi': record.get('nrfi', {}).get('hit_rate', 0.0),
        'yrfi': record.get('yrfi', {}).get('hit_rate', 0.0),
    }

    # Back-compat alias for prior frontend key.
    if 'pitcher_strikeouts' in record and 'k' not in record:
        record['k'] = record['pitcher_strikeouts']

    # Hit rate by stacked-calibrator verdict tier — does STRONG_BET actually
    # outperform LEAN_OVER in production? Only stacked rows carry a verdict;
    # picks are graded on the Over side, so the FADE tiers hitting *less* often
    # than the BET tiers is the model working.
    by_verdict = {}
    for e in graded:
        v = e.get('stackVerdict')
        if not v:
            continue
        c = by_verdict.setdefault(v, {'wins': 0, 'losses': 0,
                                      'profit_units': 0.0, 'priced': 0})
        if e.get('grade') == 'win':
            c['wins'] += 1
        else:
            c['losses'] += 1
        # Units P&L at the taken price — hit rate alone can't tell a profitable
        # tier from an unprofitable one (40% at +150 beats 55% at -200).
        pu = e.get('profitUnits')
        if pu is not None:
            try:
                c['profit_units'] += float(pu)
                c['priced'] += 1
            except (TypeError, ValueError):
                pass
    verdict_record = {}
    for v, c in by_verdict.items():
        total = c['wins'] + c['losses']
        verdict_record[v] = {
            'wins': c['wins'], 'losses': c['losses'], 'graded': total,
            'hit_rate': round(c['wins'] / total, 3) if total else 0.0,
            'profit_units': round(c['profit_units'], 2),
            'roi': round(c['profit_units'] / c['priced'], 3) if c['priced'] else None,
        }

    return jsonify({
        'success': True,
        'record': record,
        'summary': summary,
        'by_verdict': verdict_record,
        'window': 30,
        'total_graded': len(graded),
    })


