from concurrent.futures import ThreadPoolExecutor, as_completed

# ── League averages (2025 baseline) ──────────────────────────────────────────
LG_K_PER_TEAM_PER_GAME  = 8.5   # strikeouts per team per game
LG_BB_PER_TEAM_PER_GAME = 3.0
LG_R_PER_TEAM_PER_GAME  = 4.5
LG_TOTAL_K_PER_GAME     = 17.0  # both teams combined

# ── Umpire cache ──────────────────────────────────────────────────────────────
_ump_lock  = threading.Lock()
_ump_cache = {}   # ump_id (int) → {"data": {...}, "date": date}

# Common prop lines to score trends against
BATTER_LINES = {
    "hits":  [0.5, 1.5, 2.5],
    "hr":    [0.5],
    "tb":    [1.5, 2.5, 3.5],
    "rbi":   [0.5, 1.5],
}
PITCHER_LINES = {
    "k":   [3.5, 4.5, 5.5, 6.5, 7.5],
    "bb":  [1.5, 2.5],
}


# ── Helper: fetch schedule with officials hydration ───────────────────────────
def _fetch_schedule_with_officials(start_date, end_date):
    """Returns all regular-season games in a date range with umpire data."""
    try:
        r = requests.get(f"{MLB_API}/schedule", params={
            "sportId": 1,
            "startDate": start_date,
            "endDate": end_date,
            "hydrate": "officials,linescore",
            "gameType": "R",
        }, timeout=20)
        r.raise_for_status()
        games = []
        for d in r.json().get("dates", []):
            games.extend(d.get("games", []))
        return games
    except Exception as ex:
        print(f"[ump_schedule] {ex}")
        return []


def _get_hp_umpire(game):
    """Extract home plate umpire from a game dict (needs officials hydration)."""
    for off in game.get("officials", []):
        if off.get("officialType") == "Home Plate":
            return off.get("official", {})
    return {}


def _fetch_boxscore_ump_stats(game_pk):
    """Fetch K/BB totals from a single boxscore."""
    try:
        r = requests.get(f"{MLB_API}/game/{game_pk}/boxscore", timeout=8)
        r.raise_for_status()
        teams = r.json().get("teams", {})
        total_k = 0; total_bb = 0; total_r = 0
        for side in ("away", "home"):
            t = teams.get(side, {})
            ts = t.get("teamStats", {})
            bat = ts.get("batting", {})
            pit = ts.get("pitching", {})
            total_k  += int(pit.get("strikeOuts", 0))
            total_bb += int(pit.get("baseOnBalls", 0))
            total_r  += int(bat.get("runs", 0))
        return {"pk": game_pk, "k": total_k, "bb": total_bb, "r": total_r, "ok": True}
    except Exception as ex:
        return {"pk": game_pk, "ok": False, "error": str(ex)}


def _build_ump_stats(ump_id, game_pks):
    """
    Given a list of gamePks where this umpire was HP, fetch boxscores concurrently
    and compute K/BB/run averages + zone rating.
    """
    pks = game_pks[-20:]   # limit to last 20 for performance
    results = []
    with ThreadPoolExecutor(max_workers=8) as ex:
        futs = {ex.submit(_fetch_boxscore_ump_stats, pk): pk for pk in pks}
        for fut in as_completed(futs):
            res = fut.result()
            if res.get("ok"):
                results.append(res)

    if not results:
        return None

    n          = len(results)
    avg_k      = round(sum(r["k"] for r in results) / n, 1)
    avg_bb     = round(sum(r["bb"] for r in results) / n, 1)
    avg_r      = round(sum(r["r"] for r in results) / n, 1)

    # Per-team averages
    avg_k_per_team  = round(avg_k / 2, 1)
    avg_bb_per_team = round(avg_bb / 2, 1)
    avg_r_per_team  = round(avg_r / 2, 1)

    # vs league average (delta)
    k_vs_avg  = round(avg_k_per_team  - LG_K_PER_TEAM_PER_GAME,  1)
    bb_vs_avg = round(avg_bb_per_team - LG_BB_PER_TEAM_PER_GAME, 1)
    r_vs_avg  = round(avg_r_per_team  - LG_R_PER_TEAM_PER_GAME,  1)

    # Zone rating: 0–100.  Higher = more pitcher-friendly (more K, fewer runs)
    # Formula: 50 baseline + k bonus (up to +25) + run penalty (up to -25)
    k_score  = min(25, max(-25, k_vs_avg  *  4.0))
    r_score  = min(25, max(-25, r_vs_avg  * -3.0))
    bb_score = min(10, max(-10, bb_vs_avg * -2.5))
    zone_raw = 50 + k_score + r_score + bb_score
    zone     = int(min(100, max(0, round(zone_raw))))

    if zone >= 65:
        tendency = "PITCHER FRIENDLY"
        tendency_color = "var(--m)"
    elif zone <= 35:
        tendency = "HITTER FRIENDLY"
        tendency_color = "var(--g)"
    else:
        tendency = "NEUTRAL ZONE"
        tendency_color = "var(--mu)"

    return {
        "games_sampled":    n,
        "avg_total_k":      avg_k,
        "avg_k_per_team":   avg_k_per_team,
        "avg_total_bb":     avg_bb,
        "avg_bb_per_team":  avg_bb_per_team,
        "avg_total_r":      avg_r,
        "avg_r_per_team":   avg_r_per_team,
        "k_vs_avg":         f"+{k_vs_avg}" if k_vs_avg >= 0 else str(k_vs_avg),
        "bb_vs_avg":        f"+{bb_vs_avg}" if bb_vs_avg >= 0 else str(bb_vs_avg),
        "r_vs_avg":         f"+{r_vs_avg}"  if r_vs_avg  >= 0 else str(r_vs_avg),
        "zone_rating":      zone,
        "tendency":         tendency,
        "tendency_color":   tendency_color,
    }


def _load_ump_data(ump_id, ump_name):
    """Full umpire history load — called once per ump per day, cached."""
    today     = datetime.now(ET).date()
    season    = today.year
    start     = f"{season}-03-01"
    end_dt    = today - timedelta(days=1)
    end       = end_dt.strftime("%Y-%m-%d")

    games = _fetch_schedule_with_officials(start, end)

    # Filter games where this ump was HP
    hp_pks = []
    for g in games:
        u = _get_hp_umpire(g)
        if u.get("id") == ump_id:
            hp_pks.append(g["gamePk"])

    if not hp_pks:
        return None

    stats = _build_ump_stats(ump_id, hp_pks)
    if stats:
        stats["name"]     = ump_name
        stats["id"]       = ump_id
        stats["games_hp"] = len(hp_pks)
    return stats


def _get_cached_ump(ump_id, ump_name):
    today = datetime.now(ET).date()
    with _ump_lock:
        cached = _ump_cache.get(ump_id)
    if cached and cached.get("date") == today:
        return cached["data"]
    # Load in background — return None if not ready yet (caller handles gracefully)
    def _loader():
        data = _load_ump_data(ump_id, ump_name)
        if data:
            with _ump_lock:
                _evict_if_large(_ump_cache, 200)
                _ump_cache[ump_id] = {"data": data, "date": today}
        print(f"[ump_cache] loaded {ump_name} id={ump_id}: {data}")
    threading.Thread(target=_loader, daemon=True).start()
    return None


# ── Route: Umpire data for a game ─────────────────────────────────────────────
@app.route("/api/umpire/<int:game_pk>")
def api_umpire(game_pk):
    """
    Returns home plate umpire assignment + historical K/BB/run tendencies.
    On first call the cache is being built — returns loading=True so the
    frontend can poll once more after 3 seconds.
    """
    try:
        # Search today ± 1 day
        for delta in (0, -1, 1):
            date_str = (datetime.now(ET) + timedelta(days=delta)).strftime("%Y-%m-%d")
            games = _fetch_schedule_with_officials(date_str, date_str)
            gdata = next((g for g in games if g.get("gamePk") == game_pk), None)
            if gdata:
                break

        if not gdata:
            return jsonify({"success": False, "error": "Game not found"}), 404

        ump = _get_hp_umpire(gdata)
        if not ump or not ump.get("id"):
            return jsonify({
                "success": True,
                "umpire": None,
                "message": "Umpire assignment not yet posted",
            })

        ump_id   = ump["id"]
        ump_name = ump.get("fullName", "Unknown")

        # Try cache first — kick off load if needed
        today = datetime.now(ET).date()
        with _ump_lock:
            cached = _ump_cache.get(ump_id)

        if cached and cached.get("date") == today:
            stats = cached["data"]
            return jsonify({
                "success": True,
                "loading": False,
                "umpire": {
                    "id":       ump_id,
                    "name":     ump_name,
                    **stats,
                },
            })

        # Not cached — start background load, return partial response
        _get_cached_ump(ump_id, ump_name)
        return jsonify({
            "success": True,
            "loading": True,
            "umpire": {
                "id":   ump_id,
                "name": ump_name,
                "zone_rating": None,
                "tendency": "LOADING",
                "games_sampled": 0,
            },
        })

    except Exception as ex:
        print(f"[api_umpire] {traceback.format_exc()}")
        return jsonify({"success": False, "error": str(ex)}), 500


# ── L5/L10 helpers ────────────────────────────────────────────────────────────
_TEAM_ABBR_CACHE = {"date": None, "map": {}}
_TEAM_ABBR_LOCK = threading.Lock()


def _team_abbr_by_id():
    """teamId -> abbreviation for all MLB teams, daily-cached. The gameLog
    splits' `opponent` object carries only id + name (no abbreviation), so
    game-log consumers need this map for short opponent labels."""
    today = datetime.now().date()
    with _TEAM_ABBR_LOCK:
        if _TEAM_ABBR_CACHE["date"] == today and _TEAM_ABBR_CACHE["map"]:
            return _TEAM_ABBR_CACHE["map"]
    m = {}
    try:
        r = requests.get(f"{MLB_API}/teams", params={"sportId": 1}, timeout=8)
        for t in r.json().get("teams", []):
            if t.get("id") and t.get("abbreviation"):
                m[int(t["id"])] = t["abbreviation"]
    except Exception:
        with _TEAM_ABBR_LOCK:
            return dict(_TEAM_ABBR_CACHE["map"])
    with _TEAM_ABBR_LOCK:
        _TEAM_ABBR_CACHE["date"] = today
        _TEAM_ABBR_CACHE["map"] = m
        return dict(m)


def _gamelog_opp_abbr(split):
    opp = split.get("opponent", {}) or {}
    return (opp.get("abbreviation")
            or _team_abbr_by_id().get(opp.get("id"))
            or opp.get("name", ""))


_DAYNIGHT_MAP_CACHE = {"date": None, "season": None, "map": {}}
_DAYNIGHT_MAP_LOCK = threading.Lock()


def _gamepk_daynight_map(season):
    """gamePk -> 'day'/'night' for a season, daily-cached (one schedule call).

    The gameLog splits' nested `game.dayNight` is unreliable — it reads 'day'
    for every game — so the hit-history day/night split derives from the
    schedule endpoint, which carries the real value."""
    today = datetime.now().date()
    with _DAYNIGHT_MAP_LOCK:
        c = _DAYNIGHT_MAP_CACHE
        if c["date"] == today and c["season"] == season and c["map"]:
            return c["map"]
    m = {}
    try:
        r = requests.get(f"{MLB_API}/schedule", params={
            "sportId": 1,
            "startDate": f"{season}-03-01", "endDate": f"{season}-11-30",
            "gameType": "R",
            "fields": "dates,games,gamePk,dayNight",
        }, timeout=12)
        for d in r.json().get("dates", []):
            for g in d.get("games", []):
                if g.get("gamePk") and g.get("dayNight"):
                    m[int(g["gamePk"])] = g["dayNight"]
    except Exception:
        with _DAYNIGHT_MAP_LOCK:
            return dict(_DAYNIGHT_MAP_CACHE["map"])
    with _DAYNIGHT_MAP_LOCK:
        _DAYNIGHT_MAP_CACHE.update({"date": today, "season": season, "map": m})
        return dict(m)


def _gamelog_day_flag(split, dn_map):
    gpk = (split.get("game") or {}).get("gamePk")
    dn = dn_map.get(gpk) if gpk else None
    return (dn == "day") if dn else None


def _fetch_batter_gamelog(player_id, season=None, limit=10):
    """Returns recent game log entries for a batter, newest-last order."""
    try:
        splits = _gamelog_splits_cached(player_id, "hitting", season)
        dn_map = _gamepk_daynight_map(int(season or datetime.now().year))
        out = []
        chosen = splits if limit is None else splits[-int(limit):]
        for s in chosen:
            st = s.get("stat", {})
            out.append({
                "date": s.get("date", ""),
                "opp":  _gamelog_opp_abbr(s),
                "home": bool(s.get("isHome")),
                "day":  _gamelog_day_flag(s, dn_map),
                "ab":   int(st.get("atBats", 0)),
                "h":    int(st.get("hits", 0)),
                "hr":   int(st.get("homeRuns", 0)),
                "rbi":  int(st.get("rbi", 0)),
                "bb":   int(st.get("baseOnBalls", 0)),
                "tb":   int(st.get("totalBases", 0)),
                "r":    int(st.get("runs", 0)),
                "sb":   int(st.get("stolenBases", 0)),
            })
        return out
    except Exception as ex:
        print(f"[batter_gamelog] pid={player_id} {ex}")
        return []


def _fetch_pitcher_gamelog(player_id, season=None, limit=10):
    """Returns recent game log entries for a pitcher, newest-last order."""
    try:
        splits = _gamelog_splits_cached(player_id, "pitching", season)
        dn_map = _gamepk_daynight_map(int(season or datetime.now().year))
        out = []
        chosen = splits if limit is None else splits[-int(limit):]
        for s in chosen:
            st = s.get("stat", {})
            ip_raw = st.get("inningsPitched", "0.0")
            try:
                whole, third = str(ip_raw).split(".")
                ip_dec = int(whole) + int(third) / 3
            except Exception:
                ip_dec = _safe_f(ip_raw, 0)
            out.append({
                "date": s.get("date", ""),
                "opp":  _gamelog_opp_abbr(s),
                "home": bool(s.get("isHome")),
                "day":  _gamelog_day_flag(s, dn_map),
                "ip":   round(ip_dec, 2),
                "k":    int(st.get("strikeOuts", 0)),
                "bb":   int(st.get("baseOnBalls", 0)),
                "h":    int(st.get("hits", 0)),
                "er":   int(st.get("earnedRuns", 0)),
            })
        return out
    except Exception as ex:
        print(f"[pitcher_gamelog] pid={player_id} {ex}")
        return []


def _compute_over_rates(game_log, stat_key, lines):
    """
    For a list of game log dicts and a stat key (e.g. 'h', 'hr', 'k'),
    compute over% for each line across L5 and L10.
    Returns dict: { line (str) -> {"l5": {"over":n,"total":n,"pct":f}, "l10": {...}} }
    """
    vals = [g[stat_key] for g in game_log if stat_key in g]
    result = {}
    for line in lines:
        l10_vals = vals[-10:]
        l5_vals  = vals[-5:]
        def _rate(vs):
            over = sum(1 for v in vs if v > line)
            return {"over": over, "total": len(vs), "pct": round(over / len(vs), 3) if vs else None}
        result[str(line)] = {"l5": _rate(l5_vals), "l10": _rate(l10_vals)}
    return result


def _consistency_stat_value(row, market_key):
    if market_key == 'batter_hits':
        return int(row.get('h', 0) or 0)
    if market_key == 'batter_total_bases':
        return int(row.get('tb', 0) or 0)
    if market_key == 'batter_home_runs':
        return int(row.get('hr', 0) or 0)
    if market_key == 'batter_rbis':
        return int(row.get('rbi', 0) or 0)
    if market_key == 'batter_runs_scored':
        return int(row.get('r', 0) or 0)
    if market_key == 'batter_hits_runs_rbis':
        return int(row.get('h', 0) or 0) + int(row.get('r', 0) or 0) + int(row.get('rbi', 0) or 0)
    if market_key == 'batter_stolen_bases':
        return int(row.get('sb', 0) or 0)
    if market_key == 'pitcher_strikeouts':
        return int(row.get('k', 0) or 0)
    return None


def _consistency_window_summary(values, line, limit=None):
    sample = values if limit is None else values[-int(limit):]
    sample = [v for v in sample if v is not None]
    total = len(sample)
    if total == 0:
        return {'over': 0, 'total': 0, 'pct': None}
    over = sum(1 for v in sample if float(v) > float(line))
    return {'over': over, 'total': total, 'pct': round(over / total, 3)}


def _consistency_recent_form(values, line, limit=10):
    """Per-game recent-form detail for L5/L10 sparklines + current over streak.

    `values` are ordered oldest -> newest (most recent last), matching the
    game-log order used elsewhere in the consistency path. Returns the last
    `limit` games as [{v, over}] (chronological, most recent last) plus the
    current consecutive over-streak counted back from the most recent game.
    This is the recent-form visualization Bobby's Bets surfaces as L5
    sparklines, and the streak that powers the "hot hand" ranking.
    """
    clean = [v for v in values if v is not None]
    if not clean:
        return {'spark': [], 'streakOver': 0}
    tail = clean[-int(limit):]
    spark = [{'v': float(v), 'over': bool(float(v) > float(line))} for v in tail]
    streak = 0
    for v in reversed(clean):
        if float(v) > float(line):
            streak += 1
        else:
            break
    return {'spark': spark, 'streakOver': streak}


# ── Prop hit history (per-game bars vs line, with recorded closing lines) ─────
# Markets the hit-history chart supports → which game-log group feeds them.
_HIT_HISTORY_MARKETS = {
    'batter_hits': 'hitting',
    'batter_total_bases': 'hitting',
    'batter_home_runs': 'hitting',
    'batter_rbis': 'hitting',
    'batter_runs_scored': 'hitting',
    'batter_hits_runs_rbis': 'hitting',
    'batter_stolen_bases': 'hitting',
    'pitcher_strikeouts': 'pitching',
}

_HIT_HISTORY_DEFAULT_LINE = {
    'batter_hits': 0.5, 'batter_total_bases': 1.5, 'batter_home_runs': 0.5,
    'batter_rbis': 0.5, 'batter_runs_scored': 0.5, 'batter_hits_runs_rbis': 1.5,
    'batter_stolen_bases': 0.5, 'pitcher_strikeouts': 4.5,
}


def _hit_history_recorded_rows(player_id, player_name, market_key, dates):
    """date -> that day's tracker-capture row for (player, market).

    The daily tracker capture snapshots every slate prop at its offered line,
    and the closing-capture worker refreshes the price at first pitch — so a
    row here IS the line/price that was actually bettable that day. Matched by
    playerId when the row carries one, by normalized name otherwise. When a
    date has several rows (e.g. re-capture), prefer one with a closing price.
    """
    out = {}
    if not dates:
        return out
    try:
        store = _tracker_store_for_dates(dates)
    except Exception:
        return out
    name_l = (player_name or '').strip().lower()
    for ds in set(dates):
        day = _normalize_tracker_day(store.get(ds)) if store.get(ds) else None
        if not day:
            continue
        best = None
        for row in day.get('entries', []):
            if row.get('marketKey') != market_key:
                continue
            rid = row.get('playerId')
            matched = False
            if rid is not None and player_id is not None:
                try:
                    matched = int(rid) == int(player_id)
                except (TypeError, ValueError):
                    matched = False
            if not matched:
                matched = bool(name_l) and (row.get('player') or '').strip().lower() == name_l
            if not matched or row.get('line') is None:
                continue
            if best is None or (row.get('closingPrice') is not None and best.get('closingPrice') is None):
                best = row
        if best:
            out[ds] = best
    return out


def _hit_history_result(value, line):
    if value is None or line is None:
        return None
    if float(value) > float(line):
        return 'over'
    if float(value) < float(line):
        return 'under'
    return 'push'


def _hit_history_rate(results):
    """Hit-rate summary over a list of over/under/push results (None = excluded)."""
    decided = [r for r in results if r in ('over', 'under')]
    pushes = sum(1 for r in results if r == 'push')
    overs = sum(1 for r in decided if r == 'over')
    return {
        'overs': overs,
        'decided': len(decided),
        'pushes': pushes,
        'rate': round(overs / len(decided), 3) if decided else None,
    }


@app.route('/api/props/hit-history/<int:player_id>')
def api_props_hit_history(player_id):
    """Per-game prop values vs a line, graded two ways (PropsMadness-style chart).

    `?market=` tracker market key, `?line=` the line to grade against (defaults
    per market), `?n=` games window (default 20), `?season=`, `?player=` name
    fallback for tracker matching. Each game carries the stat value, its result
    vs the CURRENT line (applied retroactively), and — where the daily tracker
    capture recorded that day's offered line — the RECORDED line + closing
    price with its own result. `summary.closing.coverage` says how many games
    have a recorded line, so the UI can show an honest closing-mode sample
    instead of silently falling back.
    """
    market = (request.args.get('market') or 'batter_hits').strip()
    group = _HIT_HISTORY_MARKETS.get(market)
    if not group:
        return jsonify({'success': False, 'error': f'unsupported market: {market}'}), 400
    try:
        line = float(request.args.get('line'))
    except (TypeError, ValueError):
        line = _HIT_HISTORY_DEFAULT_LINE[market]
    try:
        n = max(1, min(int(request.args.get('n', 20)), 162))
    except (TypeError, ValueError):
        n = 20
    try:
        season = int(request.args.get('season', datetime.now().year))
    except (TypeError, ValueError):
        season = datetime.now().year
    player_name = (request.args.get('player') or '').strip()
    try:
        teammate_id = int(request.args.get('teammate'))
    except (TypeError, ValueError):
        teammate_id = None

    try:
        if group == 'pitching':
            log = _fetch_pitcher_gamelog(player_id, season=season, limit=n)
        else:
            log = _fetch_batter_gamelog(player_id, season=season, limit=n)
        season_total = len(_gamelog_splits_cached(player_id, group, season))
        recorded = _hit_history_recorded_rows(
            player_id, player_name, market, [g.get('date') for g in log if g.get('date')])

        # Teammate-in-lineup flag: the teammate appeared that day iff their own
        # game log has a split on the same date (same team, so same game).
        teammate_dates = None
        if teammate_id and teammate_id != player_id:
            teammate_dates = {s.get('date') for s in _gamelog_splits_cached(teammate_id, 'hitting', season)}

        games = []
        for g in log:
            value = _consistency_stat_value(g, market)
            row = {
                'date': g.get('date', ''),
                'opp': g.get('opp', ''),
                'home': bool(g.get('home')),
                'day': g.get('day'),
                'tm': (g.get('date') in teammate_dates) if teammate_dates is not None else None,
                'value': value,
                'result': _hit_history_result(value, line),
                'recorded': None,
            }
            rec = recorded.get(g.get('date'))
            if rec is not None:
                row['recorded'] = {
                    'line': rec.get('line'),
                    'result': _hit_history_result(value, rec.get('line')),
                    'closingPrice': rec.get('closingPrice'),
                    'closingBook': rec.get('closingBookmaker'),
                    'openingPrice': rec.get('openingPrice'),
                }
            games.append(row)

        closing_results = [
            (g['recorded'] or {}).get('result') for g in games if g.get('recorded')]
        closing_summary = _hit_history_rate(closing_results)
        closing_summary['coverage'] = len(closing_results)

        return jsonify({
            'success': True,
            'playerId': player_id,
            'player': player_name,
            'market': market,
            'line': line,
            'season': season,
            'n': n,
            'seasonGames': season_total,
            'teammate': teammate_id,
            'games': games,
            'summary': {
                'line': _hit_history_rate([g['result'] for g in games]),
                'closing': closing_summary,
            },
        })
    except Exception as ex:
        print(f"[api_props_hit_history] pid={player_id} {traceback.format_exc()}")
        return jsonify({'success': False, 'error': str(ex)}), 500


def _empty_consistency_payload(date_str):
    return {
        'success': True,
        'date': date_str,
        'generatedAt': datetime.now(timezone.utc).isoformat(),
        'cached': False,
        'cacheAgeSec': 0,
        'games': [],
        'teams': [],
        'slots': [],
        'markets': [],
    }


_prior_season_log_cache = {}      # player_id -> 2025 game-log list (static → session-cached)
_prior_season_log_lock = threading.Lock()
_PRIOR_CONSISTENCY_YEAR = 2026 - 1  # prior full season for season-over-season context


def _compute_consistency_payload(date_str):
    now = time.time()
    raw_games = fetch_schedule(date_str)
    parsed_games = [parse_game(g) for g in raw_games]
    parsed_games = [g for g in parsed_games if g]
    game_meta = {g.get('gamePk'): g for g in parsed_games}
    adjustments = _get_adjustments()
    rows = []

    def _consistency_game_rows(game):
        game_pk = game.get('gamePk')
        if not game_pk:
            return []
        try:
            return _build_tracker_rows_for_game(int(game_pk), date_str, adjustments, _sched=raw_games, include_odds=False) or []
        except Exception:
            print(f'[consistency_rows {game_pk}] {traceback.format_exc()}')
            return []

    with ThreadPoolExecutor(max_workers=min(6, max(1, len(raw_games)))) as _cex:
        for _game_rows in _cex.map(_consistency_game_rows, raw_games):
            rows.extend(_game_rows)

    supported_markets = {
        'batter_hits', 'batter_total_bases', 'batter_home_runs', 'batter_rbis',
        'batter_runs_scored', 'batter_hits_runs_rbis', 'batter_stolen_bases', 'pitcher_strikeouts'
    }
    deduped = {}
    for row in rows:
        market_key = row.get('marketKey')
        if market_key not in supported_markets:
            continue
        key = (row.get('playerId'), market_key, float(row.get('line') or 0))
        current = deduped.get(key)
        if current is None or float(row.get('hubRating') or 0) > float(current.get('hubRating') or 0):
            deduped[key] = dict(row)
    base_rows = list(deduped.values())

    player_tasks = {}
    for row in base_rows:
        player_id = row.get('playerId')
        if not player_id:
            continue
        player_tasks[player_id] = (row.get('marketKey') == 'pitcher_strikeouts')

    logs_by_player = {}
    prior_logs_by_player = {}
    # Prior season (2025) is static — reuse the session cache and only fetch misses.
    with _prior_season_log_lock:
        for pid in player_tasks:
            if pid in _prior_season_log_cache:
                prior_logs_by_player[pid] = _prior_season_log_cache[pid]
    with ThreadPoolExecutor(max_workers=12) as ex:
        fut_map = {}          # current season (2026)
        prior_fut_map = {}    # prior season (2025) — only uncached players
        for player_id, is_pitcher in player_tasks.items():
            fn = _fetch_pitcher_gamelog if is_pitcher else _fetch_batter_gamelog
            fut_map[ex.submit(fn, int(player_id), None, None)] = player_id
            if player_id not in prior_logs_by_player:
                prior_fut_map[ex.submit(fn, int(player_id), _PRIOR_CONSISTENCY_YEAR, None)] = player_id
        for fut in as_completed(fut_map):
            player_id = fut_map[fut]
            try:
                logs_by_player[player_id] = fut.result() or []
            except Exception:
                logs_by_player[player_id] = []
        for fut in as_completed(prior_fut_map):
            player_id = prior_fut_map[fut]
            try:
                plog = fut.result() or []
            except Exception:
                plog = []
            prior_logs_by_player[player_id] = plog
            with _prior_season_log_lock:
                _prior_season_log_cache[player_id] = plog

    market_labels = {
        'batter_hits': 'Hits', 'batter_total_bases': 'Total Bases', 'batter_home_runs': 'Home Runs',
        'batter_rbis': 'RBIs', 'batter_runs_scored': 'Runs', 'batter_hits_runs_rbis': 'H+R+RBI',
        'batter_stolen_bases': 'Stolen Bases', 'pitcher_strikeouts': 'Pitcher Strikeouts'
    }
    sheets = {mk: {'marketKey': mk, 'marketLabel': label, 'rows': []} for mk, label in market_labels.items()}
    teams = set()
    slots = set()
    game_filters = []
    for g in parsed_games:
        game_filters.append({'gamePk': g.get('gamePk'), 'label': f"{g.get('awayAbbr')} @ {g.get('homeAbbr')}"})

    for row in base_rows:
        player_id = row.get('playerId')
        market_key = row.get('marketKey')
        logs = logs_by_player.get(player_id, [])
        values = [_consistency_stat_value(log_row, market_key) for log_row in logs]
        values = [v for v in values if v is not None]
        game = game_meta.get(row.get('gamePk')) or {}
        slot = row.get('slot')
        teams.add(row.get('team') or '')
        if slot is not None:
            slots.add(int(slot))
        sheet_row = {
            'player': row.get('player'),
            'playerId': player_id,
            'team': row.get('team'),
            'opp': row.get('opp') or ((game.get('homeAbbr') if row.get('team') == game.get('awayAbbr') else game.get('awayAbbr')) if game else ''),
            'slot': slot,
            'gamePk': row.get('gamePk'),
            'gameLabel': f"{game.get('awayAbbr')} @ {game.get('homeAbbr')}" if game else '',
            'line': row.get('line'),
            'hubRating': row.get('hubRating'),
            'evPct': row.get('evPct'),
            'l5': _consistency_window_summary(values, row.get('line'), 5),
            'l10': _consistency_window_summary(values, row.get('line'), 10),
            'l20': _consistency_window_summary(values, row.get('line'), 20),
            'season': _consistency_window_summary(values, row.get('line'), None),
            'sampleSize': len(values),
            'actionable': row.get('actionable') is True,
            'canonicalCandidateId': row.get('canonicalCandidateId'),
            'candidateIntegrityVersion': row.get('integrityVersion'),
            'integrityReasons': row.get('integrityReasons') or [],
        }
        # Season-over-season context: the same over-rate computed on the player's
        # full PRIOR season (real 2025 game logs), plus the year-over-year delta —
        # so a hot current line can be read against last year's established level.
        prior_logs = prior_logs_by_player.get(player_id, [])
        prior_values = [_consistency_stat_value(lr, market_key) for lr in prior_logs]
        prior_values = [v for v in prior_values if v is not None]
        prior_summary = _consistency_window_summary(prior_values, row.get('line'), None)
        sheet_row['priorSeason'] = {
            'year': _PRIOR_CONSISTENCY_YEAR,
            'pct': prior_summary['pct'],
            'over': prior_summary['over'],
            'total': prior_summary['total'],
        }
        _cur_season_pct = sheet_row['season'].get('pct')
        sheet_row['yoyDelta'] = (
            round(_cur_season_pct - prior_summary['pct'], 3)
            if (_cur_season_pct is not None and prior_summary['pct'] is not None) else None
        )
        _form = _consistency_recent_form(values, row.get('line'), 10)
        sheet_row['sparkline'] = _form['spark']
        sheet_row['streakOver'] = _form['streakOver']
        sheets[market_key]['rows'].append(sheet_row)

    for market_key, sheet in sheets.items():
        sheet['rows'].sort(key=lambda x: (
            -(x.get('l10', {}).get('pct') if x.get('l10', {}).get('pct') is not None else -1),
            -(x.get('l5', {}).get('pct') if x.get('l5', {}).get('pct') is not None else -1),
            -(float(x.get('hubRating') or 0)),
            x.get('player') or ''
        ))

    payload = {
        'success': True,
        'date': date_str,
        'generatedAt': datetime.now(timezone.utc).isoformat(),
        'cached': False,
        'cacheAgeSec': 0,
        'games': game_filters,
        'teams': sorted(t for t in teams if t),
        'slots': sorted(slots),
        'markets': list(sheets.values()),
    }
    with _consistency_cache_lock:
        _evict_if_large(_CONSISTENCY_CACHE, 14)
        _CONSISTENCY_CACHE[date_str] = {'ts': now, 'payload': payload}
    return payload


def _trigger_consistency_refresh_async(date_str, reason='auto'):
    global _consistency_refreshing
    with _consistency_cache_lock:
        if _consistency_refreshing:
            return False
        _consistency_refreshing = True

    def _runner():
        global _consistency_refreshing
        try:
            _compute_consistency_payload(date_str)
            print(f'[consistency] refreshed ({reason})')
        except Exception:
            print(f'[consistency] refresh failed {traceback.format_exc()}')
        finally:
            with _consistency_cache_lock:
                _consistency_refreshing = False

    threading.Thread(target=_runner, daemon=True).start()
    return True


def _consistency_payload(date_str, refresh=False):
    now = time.time()
    with _consistency_cache_lock:
        cached = _CONSISTENCY_CACHE.get(date_str)
        refreshing = _consistency_refreshing
    ts = float((cached or {}).get('ts') or 0)
    age = int(now - ts) if ts else 0

    if cached and not refresh and (now - ts) < _CONSISTENCY_TTL:
        payload = dict(cached.get('payload') or {})
        payload['cacheAgeSec'] = age
        payload['cached'] = True
        payload['computing'] = False
        return payload

    if refresh:
        return _compute_consistency_payload(date_str)

    if cached:
        if not refreshing:
            _trigger_consistency_refresh_async(date_str, reason='stale_cache')
        payload = dict(cached.get('payload') or {})
        payload['cacheAgeSec'] = age
        payload['cached'] = True
        payload['computing'] = True
        payload['message'] = 'Refreshing in background'
        return payload

    if not refreshing:
        _trigger_consistency_refresh_async(date_str, reason='cold_start')
    payload = _empty_consistency_payload(date_str)
    payload['computing'] = True
    payload['message'] = 'Computing... auto-refresh in 20s'
    return payload


_HOT_HAND_FIELDS = (
    'player', 'playerId', 'team', 'opp', 'slot', 'gamePk', 'gameLabel',
    'line', 'hubRating', 'evPct', 'l5', 'l10', 'l20', 'season',
    'sparkline', 'streakOver', 'sampleSize', 'actionable',
    'canonicalCandidateId', 'candidateIntegrityVersion', 'integrityReasons',
)


def _hot_hand_payload(date_str, window='l5', min_pct=1.0, min_total=5, limit=250):
    """The "100% Club" / hot-hand board.

    Flattens the per-market consistency sheets into a single slate-wide list of
    players clearing their current prop line in at least `min_pct` of their last
    `window` games (default: 100% of the last 5 — the "100% Club"), then ranks by
    recent hit-rate, current over-streak, and model edge. Reuses the cached
    consistency payload so it adds no extra game-log fetching.
    """
    base = _consistency_payload(date_str)
    window = window if window in ('l5', 'l10', 'l20', 'season') else 'l5'
    try:
        min_pct = max(0.0, min(1.0, float(min_pct)))
    except (TypeError, ValueError):
        min_pct = 1.0
    try:
        min_total = max(1, int(min_total))
    except (TypeError, ValueError):
        min_total = 5

    rows = []
    for sheet in base.get('markets', []) or []:
        mk = sheet.get('marketKey')
        label = sheet.get('marketLabel')
        for r in sheet.get('rows', []) or []:
            win = r.get(window) or {}
            pct = win.get('pct')
            total = win.get('total') or 0
            if pct is None or total < min_total or pct < min_pct:
                continue
            entry = {k: r.get(k) for k in _HOT_HAND_FIELDS}
            entry['marketKey'] = mk
            entry['marketLabel'] = label
            entry['windowPct'] = pct
            entry['windowOver'] = win.get('over')
            entry['windowTotal'] = total
            rows.append(entry)

    rows.sort(key=lambda x: (
        -(x.get('windowPct') or 0),
        -(x.get('streakOver') or 0),
        -((x.get('l10') or {}).get('pct') or 0),
        -(x.get('windowTotal') or 0),
        -(float(x.get('hubRating') or 0)),
        x.get('player') or '',
    ))
    rows = rows[:int(limit)]

    return {
        'success': True,
        'date': date_str,
        'generatedAt': datetime.now(timezone.utc).isoformat(),
        'window': window,
        'minPct': min_pct,
        'minTotal': min_total,
        'count': len(rows),
        'cached': base.get('cached', False),
        'computing': base.get('computing', False),
        'message': base.get('message'),
        'players': rows,
    }


def _build_player_trends(player_id, is_pitcher):
    """Build the full trend dict for one player."""
    if is_pitcher:
        log  = _fetch_pitcher_gamelog(player_id)
        if not log:
            return {"log": [], "over_rates": {}, "streak": None}
        over_rates = {}
        for stat, lines in PITCHER_LINES.items():
            over_rates[stat] = _compute_over_rates(log, stat, lines)
        # Streak: consecutive games over/under 4.5 Ks
        streak = _compute_streak(log, "k", 4.5)
    else:
        log  = _fetch_batter_gamelog(player_id)
        if not log:
            return {"log": [], "over_rates": {}, "streak": None}
        over_rates = {}
        for stat, lines in BATTER_LINES.items():
            stat_key = {"hits": "h", "hr": "hr", "tb": "tb", "rbi": "rbi"}[stat]
            over_rates[stat] = _compute_over_rates(log, stat_key, lines)
        streak = _compute_streak(log, "h", 0.5)

    return {
        "log":        log,
        "over_rates": over_rates,
        "streak":     streak,
        "games":      len(log),
    }


def _compute_streak(log, stat_key, line):
    """
    Returns current consecutive over/under streak for the stat vs line.
    e.g. {"direction": "over", "length": 5}
    """
    if not log:
        return None
    vals   = [g.get(stat_key, 0) for g in log]
    if not vals:
        return None
    last_dir = "over" if vals[-1] > line else "under"
    length   = 0
    for v in reversed(vals):
        d = "over" if v > line else "under"
        if d == last_dir:
            length += 1
        else:
            break
    return {"direction": last_dir, "length": length}


def _confident_hits_exp_pa(slot):
    """Expected plate appearances for a lineup slot — the dominant volume driver
    of P(1+ hit) (leadoff ≈4.6 PA / 67% hit-game rate vs the 9-hole ≈3.9 PA /
    ~51%). Mirrors `_LINEUP_PA_WEIGHTS` used everywhere else."""
    try:
        s = int(slot)
    except Exception:
        s = 0
    if 1 <= s <= len(_LINEUP_PA_WEIGHTS):
        return float(_LINEUP_PA_WEIGHTS[s - 1])
    return 4.2


def _confident_hits_analytic_prob(b, opp_fg, opp_hand, exp_pa):
    """Structural 'book model' second estimate of P(1+ hit), independent of XGB.

    This is the same math sportsbooks/sharp models use: a per-PA hit rate
    compounded over expected plate appearances via 1−(1−p)^PA. The per-PA rate is
    the batter's platoon-blended AVG converted to per-PA (×AB/PA≈1−BB%), then
    tilted by the opposing starter's strikeout + BABIP-against profile (more Ks /
    weaker contact allowed ⇒ fewer hits). Giving the stacked calibrator a genuine
    SECOND model (not a re-expression of XGB) is what lets the fusion add skill.
    Returns None when inputs are too thin to trust (so we fall back to XGB-only).
    """
    try:
        avg_vs = platoon_blend_v2(b, opp_hand, 'avg')
        avg_vs = float(avg_vs or 0)
        if avg_vs <= 0:
            return None
        fgb = fg_batter(b.get("name", "")) or {}
        bb = _safe_f(fgb.get("fg_bbpct"), 0.08)
        if bb > 1:
            bb /= 100.0
        # AVG is per-AB; (1−BB%) approximates AB/PA (HBP/SF are minor) → hits/PA.
        hit_pa = avg_vs * max(0.80, 1.0 - bb)
        # Opposing starter tilt — league hits/PA in play ≈ (1−.22)·.295 ≈ .230.
        opp_k = _safe_f((opp_fg or {}).get("fg_kpct"), 0.22)
        if opp_k > 1:
            opp_k /= 100.0
        opp_babip = _safe_f((opp_fg or {}).get("fg_babip"), 0.295)
        opp_hit_pa = max(0.0, 1.0 - opp_k) * opp_babip
        tilt = _clamp((opp_hit_pa / 0.230) if opp_hit_pa else 1.0, 0.82, 1.18)
        hit_pa = max(0.0, min(0.60, hit_pa * tilt))
        p = _binomial_over_zero(hit_pa * exp_pa, exp_pa)
        return p if p and p > 0 else None
    except Exception:
        return None


def _arsenal_hit_tilt(adv):
    """Convert the batter-vs-this-pitcher's-arsenal matchup into a bounded
    logit-scale nudge on the hit probability. Only REAL arsenal data moves the
    number (source=='arsenal' — the usage-weighted wOBA join); the handedness
    proxy is too weak to tilt a hit prob, so it returns 0. A batter who hits this
    exact pitch mix better than their own baseline gets a positive nudge; worse,
    negative. Capped at ±0.24 logits (≈ ±5 points near a 0.65 prob) so the
    matchup sharpens the ranking without overwhelming the model."""
    if not adv or adv.get("source") != "arsenal":
        return 0.0
    mw = adv.get("matchup_woba")
    bw = adv.get("baseline_woba")
    if mw is None or bw is None:
        return 0.0
    try:
        delta = float(mw) - float(bw)
    except (TypeError, ValueError):
        return 0.0
    delta = max(-0.060, min(0.060, delta))
    return 4.0 * delta


_PIT_PLATOON_CACHE = {}      # pitcher_id -> (date, {vsL_avg, vsR_avg, vsL_ops, ...})
_PIT_PLATOON_LOCK = threading.Lock()
_LEAGUE_BAA = 0.245          # league batting-average-against (the hit baseline)


def _pitcher_platoon_splits(pitcher_id):
    """Season vs-LHB / vs-RHB splits for a pitcher (AVG-against + OPS-against +
    sample), daily-cached. This is the 'pitcher weak spot' signal: a starter who
    yields a high average to one handedness is a prime hit target for batters of
    that side. One MLB Stats API call per starter per day."""
    if not pitcher_id:
        return {}
    try:
        pid = int(pitcher_id)
    except (TypeError, ValueError):
        return {}
    today = datetime.now().date()
    with _PIT_PLATOON_LOCK:
        c = _PIT_PLATOON_CACHE.get(pid)
        if c and c[0] == today:
            return c[1]
    out = {}
    try:
        year = datetime.now().year
        r = requests.get(
            f"{MLB_API}/people/{pid}/stats",
            params={"stats": "statSplits", "group": "pitching",
                    "sitCodes": "l,r", "season": year}, timeout=8)
        if r.ok:
            for sg in (r.json().get("stats") or []):
                for sp in sg.get("splits", []):
                    code = ((sp.get("split") or {}).get("code") or "").lower()
                    st = sp.get("stat") or {}
                    avg = _safe_f(st.get("avg"), None)
                    ops = _safe_f(st.get("ops"), None)
                    ab = int(st.get("atBats", 0) or 0)
                    if code == "l":
                        out.update({"vsL_avg": avg, "vsL_ops": ops, "vsL_ab": ab})
                    elif code == "r":
                        out.update({"vsR_avg": avg, "vsR_ops": ops, "vsR_ab": ab})
    except Exception:
        out = {}
    with _PIT_PLATOON_LOCK:
        _PIT_PLATOON_CACHE[pid] = (today, out)
    return out


def _confident_hits_matchup_tilt(bats, opp_hand, opp_fg, opp_sv, pit_splits, adv):
    """Combine the DECISIVE matchup factors into one bounded logit tilt on the
    hit probability, plus reasoning clauses. Three independent levers:

      • ARSENAL — how the batter hits this pitcher's actual pitch mix (`adv`).
      • PLATOON + PITCHER WEAK SPOT — the batter's handedness edge AND how badly
        this pitcher actually pitches to that side (vs-hand AVG-against split).
        A lefty vs a RHP who yields .300 to LHB is a prime hit target.
      • GENERAL HITTABILITY — WHIP / BABIP-against / xERA vs league (a soft SP
        lifts everyone's hit odds; an ace suppresses them).

    Total capped at ±0.40 logits so the matchup sharpens the ranking decisively
    without overriding the calibrated model. Returns (tilt, info)."""
    info = {"clauses": []}
    tilt = 0.0

    # 1) Arsenal (real data only).
    a_tilt = _arsenal_hit_tilt(adv)
    tilt += a_tilt
    info["arsenalTilt"] = round(a_tilt, 3)

    # 2) Platoon direction + pitcher vs-hand vulnerability.
    bh = (bats or "S").upper()
    ph = (opp_hand or "R").upper()
    if ph not in ("L", "R"):
        ph = "R"
    eff = bh if bh in ("L", "R") else ("L" if ph == "R" else "R")  # switch bats opposite
    platoon_adv = (eff != ph)
    info["platoonAdv"] = "favorable" if platoon_adv else "unfavorable"
    info["batSide"] = eff
    base = 0.05 if platoon_adv else -0.05
    vs_avg = vs_ab = None
    if pit_splits:
        if eff == "L":
            vs_avg, vs_ab = pit_splits.get("vsL_avg"), (pit_splits.get("vsL_ab") or 0)
        else:
            vs_avg, vs_ab = pit_splits.get("vsR_avg"), (pit_splits.get("vsR_ab") or 0)
    vuln_tilt = 0.0
    if vs_avg is not None and (vs_ab or 0) >= 30:
        vuln_tilt = _clamp((float(vs_avg) - _LEAGUE_BAA) / 0.060, -1.2, 1.2) * 0.12
        info["vsHandAvg"] = round(float(vs_avg), 3)
        if float(vs_avg) >= 0.270:
            info["clauses"].append(("weak", f"{ph}HP yields .{int(round(float(vs_avg) * 1000)):03d} to {eff}HB"))
    platoon_tilt = _clamp(base + vuln_tilt, -0.16, 0.16)
    tilt += platoon_tilt
    info["platoonTilt"] = round(platoon_tilt, 3)
    if platoon_adv and not any(c[0] == "weak" for c in info["clauses"]):
        info["clauses"].append(("platoon", f"platoon edge ({eff}HB vs {ph}HP)"))

    # 3) General hittability (pitcher weak spot, season-wide).
    whip = _safe_f((opp_fg or {}).get("fg_whip"), None)
    babip = _safe_f((opp_fg or {}).get("fg_babip"), None)
    xera = _safe_f((opp_sv or {}).get("sv_xera"), None)
    hz, n = 0.0, 0
    if whip is not None:
        hz += _clamp((whip - 1.27) / 0.30, -1, 1); n += 1
    if babip is not None:
        hz += _clamp((babip - 0.295) / 0.040, -1, 1); n += 1
    if xera is not None:
        hz += _clamp((xera - 4.20) / 1.20, -1, 1); n += 1
    weak_tilt = 0.0
    if n:
        weak_tilt = _clamp((hz / n) * 0.10, -0.10, 0.10)
        tilt += weak_tilt
        if (hz / n) >= 0.5 and not any(c[0] == "weak" for c in info["clauses"]):
            wbits = []
            if whip and whip >= 1.35:
                wbits.append(f"{whip:.2f} WHIP")
            if xera and xera >= 4.6:
                wbits.append(f"{xera:.2f} xERA")
            if wbits:
                info["clauses"].append(("weak", "hittable SP — " + ", ".join(wbits)))
    info["weakTilt"] = round(weak_tilt, 3)

    tilt = _clamp(tilt, -0.40, 0.40)
    info["totalTilt"] = round(tilt, 3)
    return tilt, info


def _confident_hit_reason(name, batter, cal_p, rf, mu, opp_name, opp_hand, slot,
                          exp_pa=None, confirmed=True, adv=None, minfo=None):
    """Plain-English 'why this player' for a Confident Hit pick.

    Every clause is a REAL driver pulled from the same data the model scores on
    (recent game-log form, season/Statcast contact quality, the platoon-blended
    matchup score, lineup role + expected PA volume) — nothing is fabricated.
    Appends a lineup-confirmation caveat when the lineup is only projected, which
    is the single biggest real-world edge sharp bettors apply (never bet a
    volume prop on an unconfirmed lineup — late scratches kill it)."""
    bits = []
    # 1) Recent form — hits per game / hit rate over the last 7 completed games.
    l7  = rf.get("l7Hits")
    l7r = rf.get("l7HitRate")
    if l7 is not None and l7 >= 1.0:
        bits.append(f"{l7:.1f} H/G last 7")
    elif l7r is not None and l7r >= 0.30:
        bits.append(f".{int(round(l7r * 1000)):03d} L7 hit rate")
    # 2) Arsenal matchup — how well the batter hits THIS pitcher's actual pitch
    #    mix (usage-weighted wOBA join). Lead with it when favorable: it is the
    #    other half of what makes a hit likely besides current form.
    if adv and adv.get("source") == "arsenal":
        st = adv.get("status")
        mw = adv.get("matchup_woba")
        pp = adv.get("primary_pitch")
        if st == "favorable" and mw is not None:
            extra = f" ({mw:.3f} xwOBA vs the mix)" if mw else ""
            bits.append(f"crushes this arsenal{extra}")
        elif st == "favorable":
            bits.append("strong vs this arsenal")
        elif st == "neutral" and pp and len(bits) < 1:
            bits.append(f"handles the {pp}")
    # 2.5) Pitcher weak spot + platoon edge — decisive matchup factors. Lead with
    #      a concrete vulnerability ('RHP yields .305 to LHB' / 'hittable SP') over
    #      the bare platoon-direction note.
    if minfo and minfo.get("clauses") and len(bits) < 3:
        weak_c = next((c[1] for c in minfo["clauses"] if c[0] == "weak"), None)
        plat_c = next((c[1] for c in minfo["clauses"] if c[0] == "platoon"), None)
        if weak_c:
            bits.append(weak_c)
        if plat_c and len(bits) < 3 and weak_c is None:
            bits.append(plat_c)
    # 3) Contact quality — prefer Statcast xBA (skill, de-luck'd) then season AVG.
    sv  = sv_batter(name) or {}
    fgb = fg_batter(name) or {}
    xba = _safe_f(sv.get("sv_xba"), None)
    avg = _safe_f(fgb.get("fg_avg"), None)
    if len(bits) < 3 and xba is not None and xba >= 0.255:
        bits.append(f".{int(round(xba * 1000)):03d} xBA")
    elif len(bits) < 3 and avg is not None and avg >= 0.260:
        bits.append(f".{int(round(avg * 1000)):03d} AVG")
    # 4) Matchup grade vs the listed starter (platoon-blended, pitcher-adjusted).
    tier  = mu.get("tier")
    score = mu.get("score")
    if tier in ("A", "B") and score and len(bits) < 3:
        last = (opp_name or "").split()[-1] if opp_name and opp_name != "TBD" else ""
        vs = f" vs {opp_hand}HP {last}" if last else ""
        bits.append(f"{tier}-tier matchup{vs}")
    # 5) Lineup role + expected PA volume — the dominant driver of 1+ hit.
    if slot and 1 <= int(slot) <= 5 and len(bits) < 3:
        _ord = {1: "1st", 2: "2nd", 3: "3rd", 4: "4th", 5: "5th"}.get(int(slot), f"{slot}th")
        pa_txt = f" (~{exp_pa:.1f} PA)" if exp_pa else ""
        bits.append(f"bats {_ord}{pa_txt}")
    # Guarantee at least one substantive clause: the model still favors this hit.
    if not bits or (len(bits) == 1 and bits[0].startswith("bats")):
        bits.append(f"model favors contact ({int(round(cal_p * 100))}%)")
    out = " · ".join(bits[:3])
    if not confirmed:
        out += " · ⚠ proj. lineup — confirm before betting"
    return out


def _compute_confident_hits(game_pk, limit=4, date_hint=None, prefetch=None):
    """High-confidence 'take for a hit' picks for the dashboard quick-props strip.

    THIS IS THE MONEY MAKER. It ranks batters purely by their PROBABILITY OF
    GETTING A HIT (not by EV/odds — those are attached afterward as info only).
    That probability is driven by the two things that decide a hit:

      • RECENT FORM — the calibrated XGB hits model is fed the same serve-parity
        `_batter_recent_hit_form` features (L7/L14 hits per game, L7 hit rate) the
        tracker uses, so a hot bat is reflected in the live number.
      • ARSENAL MATCHUP — the hit prob is then tilted by how well the batter hits
        THIS pitcher's actual pitch mix: a usage-weighted wOBA join of the
        batter's wOBA-by-pitch-type against the pitcher's real per-pitch usage
        (`_pitch_type_advantage` → `_arsenal_matchup_from_stats`). A batter who
        crushes the exact pitches this guy throws rises; one who can't, falls.

    Supporting structure (so the number is honest, not a recency mirage):
      1. ENSEMBLE — the XGB model is fused with a structural PA model (per-PA hit
         rate compounded over expected plate appearances, 1−(1−p)^PA) via the same
         `stacked_calibrate` the prop board uses (park-factor adjusted).
      2. CALIBRATION — fused prob run through the live realized-accuracy
         recalibration so confidence reflects graded results, not model optimism.
      3. VOLUME — expected PA (lineup slot) is a dominant driver; top-of-order
         hitters record a hit far more often purely on plate-appearance count.
      4. LINEUP DISCIPLINE — each pick tagged confirmed vs projected.

    Picks are gated above a confidence floor, ranked by the (form + arsenal)
    hit probability, and capped at `limit` (≤4). Each carries a plain-English
    reason that leads with recent form and the arsenal verdict.
    """
    if not (_XGB_AVAILABLE and xgb_ready("hits")):
        return []
    gdata, away_bats, home_bats, away_t, home_t, pitchers = (
        prefetch if prefetch is not None
        else _props_fetch_game(game_pk, date_hint=date_hint))
    if not gdata:
        return []

    ap_info = (pitchers or {}).get("ap") or {}
    hp_info = (pitchers or {}).get("hp") or {}
    ap_name = ap_info.get("fullName", "TBD")
    hp_name = hp_info.get("fullName", "TBD")
    ap_id   = ap_info.get("id"); hp_id = hp_info.get("id")
    ap_hand = ((pitcher_stats_mlb(ap_id) if ap_id else {}).get("pitchHand") or "R").upper()
    hp_hand = ((pitcher_stats_mlb(hp_id) if hp_id else {}).get("pitchHand") or "R").upper()
    hp_fg = fg_pitcher(hp_name) or {}; hp_sv = sv_pitcher(hp_name) or {}
    ap_fg = fg_pitcher(ap_name) or {}; ap_sv = sv_pitcher(ap_name) or {}
    # Pitcher weak-spot splits (vs-LHB / vs-RHB AVG-against) — fetched ONCE per
    # starter (concurrently), daily-cached, shared across every batter facing them.
    with ThreadPoolExecutor(max_workers=2) as _sx:
        _hpf = _sx.submit(_pitcher_platoon_splits, hp_id)
        _apf = _sx.submit(_pitcher_platoon_splits, ap_id)
        try: hp_splits = _hpf.result()
        except Exception: hp_splits = {}
        try: ap_splits = _apf.result()
        except Exception: ap_splits = {}

    away_abbr = away_t.get("team", {}).get("abbreviation", "AWAY")
    home_abbr = home_t.get("team", {}).get("abbreviation", "HOME")
    home_id   = (home_t.get("team") or {}).get("id")
    # Hit-environment park factor (BABIP/hits). BPP microclimate when available,
    # else the static park index — passed into the stacked fusion.
    try:
        park_factor = float(_resolve_park_factor(home_abbr, home_id, hand="R", stat="H") or 1.0)
    except Exception:
        park_factor = 1.0

    # Confirmed-lineup status per side: a side is "confirmed" only once the
    # official batting order is posted (≥9 batters, none flagged pending).
    def _side_confirmed(bats):
        return bool(bats) and len(bats) >= 9 and all(
            (x.get("lineup_status") or "confirmed") == "confirmed" for x in bats[:9])
    away_conf = _side_confirmed(away_bats)
    home_conf = _side_confirmed(home_bats)

    # Confidence floor: clearly above a coin flip. Hits base rate (1+ hit) ≈ 0.66,
    # so we only surface batters the calibrated model likes meaningfully.
    CONF_FLOOR = 0.60

    def _score_batter(b, opp_name, opp_hand, opp_fg, opp_sv, opp_pid, opp_splits, team_abbr, confirmed):
        name = (b.get("name") or "").strip()
        pid  = b.get("id")
        slot = b.get("slot") or 0
        if not name:
            return None
        exp_pa = _confident_hits_exp_pa(slot)
        # Serve-parity recent form (also powers the reason). Daily-cached per id.
        rf = _batter_recent_hit_form(pid) if pid else {}
        bdict = {"name": name, "bats": b.get("bats") or "S", "slot": slot, "id": pid}
        if rf:
            bdict.update(rf)
        pdict = {"name": opp_name, "pitchHand": opp_hand}
        # Model 1: calibrated XGB hits probability.
        try:
            xgb_p = xgb_hit_prob(bdict, pdict)
        except Exception:
            xgb_p = None
        if xgb_p is None:
            return None
        xgb_p = float(xgb_p)
        # Model 2: structural per-PA × expected-PA "book model".
        batx_p = _confident_hits_analytic_prob(b, opp_fg, opp_hand, exp_pa)
        # Fuse the two via the same stacked calibrator the prop board uses.
        fused = xgb_p
        model_source = "xgb"
        if batx_p is not None:
            if _STACK_AVAILABLE:
                try:
                    stk = stacked_calibrate(
                        xgb_p, float(batx_p), coverage=0.6, exp_pa=exp_pa,
                        bvp_pa=0, park_factor=park_factor, market_key="batter_hits")
                except Exception:
                    stk = None
                if stk and stk.get("probability") is not None:
                    fused = float(stk["probability"]); model_source = "stacked"
                else:
                    fused = 0.5 * xgb_p + 0.5 * float(batx_p); model_source = "blend"
            else:
                fused = 0.5 * xgb_p + 0.5 * float(batx_p); model_source = "blend"
        # Live realized-accuracy recalibration on the fused probability.
        cal_p = _calibrate_prop_prob("batter_hits", fused)
        try:
            cal_p = float(cal_p)
        except Exception:
            cal_p = fused
        # ── Decisive matchup factors: arsenal + platoon advantage + pitcher weak
        #    spots, combined into one bounded logit tilt. With recent form (in the
        #    model) these are what the ranking is built to reflect.
        adv = None
        if pid and opp_pid:
            try:
                adv = _pitch_type_advantage(int(pid), int(opp_pid), name, opp_name)
            except Exception:
                adv = None
        tilt, minfo = _confident_hits_matchup_tilt(
            b.get("bats"), opp_hand, opp_fg, opp_sv, opp_splits, adv)
        if tilt:
            try:
                cal_p = 1.0 / (1.0 + math.exp(-(_logit(cal_p) + tilt)))
            except Exception:
                pass
        cal_p = max(0.03, min(0.97, cal_p))
        if cal_p < CONF_FLOOR:
            return None
        _ars_status = adv.get("status") if (adv and adv.get("source") == "arsenal") else None
        return {
            "player": name, "playerId": pid, "team": team_abbr, "slot": slot,
            "market": "hits", "marketKey": "batter_hits", "marketLabel": "Hits",
            "line": 0.5, "side": "Over", "recommendedSide": "Over",
            "hitProb": round(cal_p, 4),
            "xgbProb": round(xgb_p, 4),
            "analyticProb": round(float(batx_p), 4) if batx_p is not None else None,
            "modelSource": model_source,
            "expPa": round(exp_pa, 1),
            "confidencePct": int(round(cal_p * 100)),
            "lineupConfirmed": bool(confirmed),
            "arsenalStatus": _ars_status,
            "arsenalApplied": bool(_ars_status),
            "arsenalWoba": adv.get("matchup_woba") if _ars_status else None,
            "arsenalBaseline": adv.get("baseline_woba") if _ars_status else None,
            "arsenalPrimaryPitch": adv.get("primary_pitch") if _ars_status else None,
            # Decisive matchup signals (recent form is inside the model probability).
            "matchupTilt": round(tilt, 3) if tilt else 0,
            "arsenalTilt": minfo.get("arsenalTilt", 0),
            "platoonAdv": minfo.get("platoonAdv"),
            "platoonTilt": minfo.get("platoonTilt", 0),
            "batSide": minfo.get("batSide"),
            "pitcherVsHandAvg": minfo.get("vsHandAvg"),
            "pitcherWeakTilt": minfo.get("weakTilt", 0),
            "oppPitcher": opp_name, "oppHand": opp_hand,
            "l7Hits": rf.get("l7Hits"), "l7HitRate": rf.get("l7HitRate"),
            "hubRating": max(0, min(100, int(round(cal_p * 100)))),
            # Stash inputs so the (expensive) matchup score + reason are built only
            # for the final top-N picks, not every batter in the lineup.
            "_fin": {"b": b, "rf": rf, "adv": adv, "minfo": minfo, "opp_fg": opp_fg,
                     "opp_sv": opp_sv, "opp_hand": opp_hand, "opp_name": opp_name,
                     "exp_pa": exp_pa, "confirmed": confirmed, "cal_p": cal_p,
                     "slot": slot, "name": name},
        }

    # Only the top of each order are realistic 'best hit' candidates (volume +
    # quality); 8–9 hitters rarely clear the floor and just add latency.
    tasks = ([(b, hp_name, hp_hand, hp_fg, hp_sv, hp_id, hp_splits, away_abbr, away_conf) for b in (away_bats or [])[:7]]
             + [(b, ap_name, ap_hand, ap_fg, ap_sv, ap_id, ap_splits, home_abbr, home_conf) for b in (home_bats or [])[:7]])
    picks = []
    with ThreadPoolExecutor(max_workers=8) as ex:
        futs = [ex.submit(_score_batter, *t) for t in tasks]
        for fut in as_completed(futs):
            try:
                r = fut.result()
                if r:
                    picks.append(r)
            except Exception:
                pass

    # Rank by calibrated probability; confirmed lineups break ties (sharper bet).
    picks.sort(key=lambda x: (x["hitProb"], x.get("lineupConfirmed", False)), reverse=True)
    top = picks[:limit]

    # Finalize ONLY the shown picks: the matchup score + plain-English reason are
    # the expensive per-batter extras, so we build them for ≤4 picks, not all 14.
    for p in top:
        fin = p.pop("_fin", None)
        if not fin:
            p.setdefault("matchupScore", None); p.setdefault("matchupTier", None)
            p.setdefault("reason", "model-projected contact edge")
            continue
        try:
            mu = _matchup_score(fin["b"], fin["opp_fg"], fin["opp_sv"],
                                pitcher_hand=fin["opp_hand"]) or {}
        except Exception:
            mu = {}
        p["matchupScore"] = round(float(mu.get("score") or 0), 1) or None
        p["matchupTier"] = mu.get("tier")
        p["reason"] = _confident_hit_reason(
            fin["name"], fin["b"], fin["cal_p"], fin["rf"], mu, fin["opp_name"],
            fin["opp_hand"], fin["slot"], exp_pa=fin["exp_pa"],
            confirmed=fin["confirmed"], adv=fin["adv"], minfo=fin.get("minfo"))
    # Drop any stashed inputs from non-shown picks (defensive; top already popped).
    for p in picks:
        p.pop("_fin", None)

    # ── Odds / EV layer (best-effort) ────────────────────────────────────────
    # Price each shown pick against the live 'to record a hit' market, de-vig it,
    # and compute true EV + a Quarter-Kelly stake. This turns a confident pick
    # into an actionable bet: a 70% model prob at -300 (75% implied) is a FADE,
    # while the same prob at -130 is +EV. Degrades silently with no odds/key.
    try:
        _enrich_confident_hits_with_odds(top, away_t, home_t)
    except Exception:
        print(f"[confident_hits] odds enrich {traceback.format_exc()}")
    return top


def _enrich_confident_hits_with_odds(picks, away_t, home_t):
    """Attach market price, de-vig'd fair prob, true EV, edge, value grade and a
    Quarter-Kelly stake to each Confident Hit (market_key=batter_hits, line 0.5).

    All betting math goes through `value_engine` — the single source of truth —
    so the numbers agree with /api/v1/edges and the tracker. Best-effort: any
    pick without a posted price simply keeps its model fields (no fabricated
    odds), and the whole step is a no-op when ODDS_API_KEY is unset."""
    if not picks or not ODDS_API_KEY:
        return
    away_full = (away_t.get("team") or {}).get("name", "")
    home_full = (home_t.get("team") or {}).get("name", "")
    event, _ = _find_odds_event(away_full, home_full)
    if not event:
        return
    books = _load_event_odds(event.get("id"), featured_only=False) or []
    if not books:
        return
    valid_names = {p["player"] for p in picks if p.get("player")}
    market_props = _parse_prop_markets(books, valid_names)
    if not market_props:
        return

    adj         = _get_adjustments()
    bankroll    = float(adj.get('bankroll', 1000.0) or 1000.0)
    kelly_frac  = float(adj.get('kelly_fraction', 0.25) or 0.25)
    max_bet_pct = float(adj.get('max_bet_pct', 0.05) or 0.05)
    unit_pct    = float(adj.get('unit_size_pct', 0.01) or 0.01)

    for p in picks:
        msum = _market_price_summary(market_props, p["player"], "batter_hits", 0.5)
        over_price = msum.get("best_over_price")
        if over_price is None:
            continue
        under_price    = msum.get("best_under_price")
        market_implied = msum.get("market_implied")
        model_prob     = float(p["hitProb"])

        fairp = ev = edge = None
        stake = None
        if _VALUE_ENGINE_AVAILABLE:
            fairp = value_engine.fair_prob(over_price, under_price, method='multiplicative')
            ev    = value_engine.expected_value(model_prob, over_price)
            stake = value_engine.kelly_stake(
                model_prob, over_price, bankroll=bankroll, fraction=kelly_frac,
                max_pct=max_bet_pct, unit_pct=unit_pct)
        else:
            fairp = _american_to_implied(over_price)
        # Edge vs the de-vig'd fair line (true edge, not vs the juiced implied).
        if fairp is not None:
            edge = model_prob - float(fairp)

        p["bestPrice"]      = over_price
        p["bestBook"]       = msum.get("best_over_book")
        p["bestUnderPrice"] = under_price
        p["bookCount"]      = msum.get("book_count")
        p["marketImplied"]  = round(float(market_implied), 4) if market_implied is not None else None
        p["fairProb"]       = round(float(fairp), 4) if fairp is not None else None
        p["edge"]           = round(edge, 4) if edge is not None else None
        p["valueGrade"]     = (value_engine.edge_grade(edge)
                               if (edge is not None and _VALUE_ENGINE_AVAILABLE) else None)
        p["evPct"]          = round(float(ev), 4) if ev is not None else None
        p["isPlusEv"]       = bool(ev is not None and ev > 0)
        if ev is not None:
            p["conviction"] = ('gold' if ev >= 0.10 else 'green' if ev >= 0.05
                               else 'lean' if ev > 0 else 'fade')
        if stake:
            p["fullKellyPct"]  = stake["full_kelly_pct"]
            p["stakePct"]      = stake["stake_pct"]
            p["stakeDollars"]  = stake["stake_dollars"]
            p["stakeUnits"]    = stake["stake_units"]


def _compute_dashboard_quick_props(game_pk, limit=3, date_hint=None, prefetch=None):
    """Compute top quick-prop picks for a game card strip.

    Accuracy stack — the same fused pipeline the tracker capture / props board
    runs, per candidate (batter, market, line), replacing the old L10-hit-rate
    heuristic (0.55·L10% + 0.45·matchup) which carried no model probability:

      1. ANALYTIC LEG — full BATX projection (`_project_batter_batx`: platoon
         blend, hand-aware park factor, weather, rolling form, BvP, opposing
         defense) → Poisson P(over) at each line.
      2. XGB LEG — line-exact calibrated model (`xgb_batter_prob_full`) with
         serve-parity features: recent hit form for hits, hand-aware park HR /
         park factor (+ scorer-side momentum) for hr/tb/rbi.
      3. FUSION — `stacked_calibrate` (market/line-aware, real BvP PA count).
      4. MARKET BLEND — when the prop is priced, the fused prob is blended with
         the de-vig'd market in logit space (`logit_blend_prob`, learned
         per-market weights) exactly like the tracker rows.
      5. LIVE RECALIBRATION — `_calibrate_prop_prob` corrects the displayed
         probability to realized graded accuracy.

    Ranking: true edge vs the market when priced, else calibrated lift over the
    line-aware base rate (so hits 0.5 and HR 0.5 compare fairly). The L10
    over-rate and matchup score remain displayed confirmation signals, computed
    only for the shown picks — they no longer drive selection.
    """
    gdata, away_bats, home_bats, away_t, home_t, _pitchers = (
        prefetch if prefetch is not None
        else _props_fetch_game(game_pk, date_hint=date_hint))
    if not gdata:
        return None, []

    away_abbr = away_t.get("team", {}).get("abbreviation", "AWAY")
    home_abbr = home_t.get("team", {}).get("abbreviation", "HOME")
    home_id   = (home_t.get("team") or {}).get("id")

    # Opposing-starter context: away batters face the home starter (hp) and
    # home batters face the away starter (ap).
    _ap = (_pitchers or {}).get('ap', {}) if isinstance(_pitchers, dict) else {}
    _hp = (_pitchers or {}).get('hp', {}) if isinstance(_pitchers, dict) else {}

    def _opp_ctx(opp):
        nm = (opp or {}).get('fullName') or ''
        opid = (opp or {}).get('id')
        hand = 'R'
        try:
            if opid:
                hand = (pitcher_stats_mlb(opid).get('pitchHand') or 'R')
        except Exception:
            hand = 'R'
        return {
            'name': nm, 'id': opid, 'hand': (hand or 'R').upper(),
            'fg': fg_pitcher(nm) or {}, 'sv': sv_pitcher(nm) or {},
            'def_factor': _def_factor_for_pitcher(opid),
        }

    _home_opp = _opp_ctx(_hp)   # away batters face the home starter
    _away_opp = _opp_ctx(_ap)   # home batters face the away starter

    # Game context shared by every batter: hand-aware HR park factors + weather
    # (both feed the BATX projection; the power models get park via features).
    pf_rhb = _resolve_park_factor(home_abbr, home_id, hand="R", stat="HR")
    pf_lhb = _resolve_park_factor(home_abbr, home_id, hand="L", stat="HR")
    try:
        ven   = gdata.get("venue", {}) or {}
        coord = ((ven.get("location") or {}).get("defaultCoordinates")) or {}
        try:
            dt_utc = datetime.fromisoformat((gdata.get("gameDate") or "").replace("Z", "+00:00"))
            ghour  = dt_utc.astimezone(ET).hour
        except Exception:
            ghour = 13
        wx = get_weather(coord.get("latitude"), coord.get("longitude"), ghour, venue_id=ven.get("id"))
    except Exception:
        wx = {}
    adjustments = _get_adjustments()

    # Live prices (best-effort; cached snapshot). Lets the strip rank by TRUE
    # edge and lets the fused prob absorb market information via the blend.
    market_props = []
    try:
        if ODDS_API_KEY:
            event, _ = _find_odds_event((away_t.get('team') or {}).get('name', ''),
                                        (home_t.get('team') or {}).get('name', ''))
            books = _load_event_odds(event.get('id'), featured_only=False) if event else []
            valid_names = {b.get('name') for b in (away_bats or []) + (home_bats or []) if b.get('name')}
            market_props = _parse_prop_markets(books, valid_names) if books else []
    except Exception:
        market_props = []

    market_config = [
        ("hits", "batter_hits",        "Hits",        [0.5, 1.5]),
        ("hr",   "batter_home_runs",   "Home Runs",   [0.5]),
        ("tb",   "batter_total_bases", "Total Bases", [1.5, 2.5]),
        ("rbi",  "batter_rbis",        "RBIs",        [0.5, 1.5]),
    ]
    # Physical ceilings on the ANALYTIC leg: roughly the best hitter in baseball
    # vs the softest matchup. An unshrunk small-sample projection (a call-up
    # slugging .900 over 15 PA) can post P(2+ hits)≈0.99 through the Poisson —
    # no real hitter clears these, so anything above is sample noise.
    _QP_ANALYTIC_CEILING = {
        ("batter_hits", 0.5): 0.88, ("batter_hits", 1.5): 0.42,
        ("batter_home_runs", 0.5): 0.30,
        ("batter_total_bases", 1.5): 0.68, ("batter_total_bases", 2.5): 0.45,
        ("batter_rbis", 0.5): 0.58, ("batter_rbis", 1.5): 0.25,
    }
    _QP_SHRINK_PRIOR_PA = 100.0   # PA pseudo-count pulling thin samples to base rate

    tagged = ([(b, away_abbr, 'away') for b in (away_bats or [])[:6]]
              + [(b, home_abbr, 'home') for b in (home_bats or [])[:6]])

    def _score_batter(batter, team, side):
        pid  = batter.get("id")
        name = (batter.get("name") or "").strip()
        if not pid or not name:
            return []
        opp = _home_opp if side == 'away' else _away_opp
        slot = int(batter.get("slot") or 9)
        exp_pa = _LINEUP_PA_WEIGHTS[slot - 1] if 1 <= slot <= 9 else 4.2

        # Day-cached per-player context (same inputs the props board uses).
        form = None
        try:
            form = _fetch_rolling_form(pid, False)
        except Exception:
            pass
        bvp = None
        if opp.get('id'):
            try:
                bvp = _fetch_bvp(pid, opp['id'])
            except Exception:
                pass
        bvp_pa = int((bvp or {}).get('pa') or 0)

        # Hand-aware park factor: a switch hitter bats opposite the starter.
        bhand = (batter.get("bats") or "R").upper()
        if bhand == "S":
            bhand = "L" if opp['hand'] == "R" else "R"
        bpf = pf_lhb if bhand == "L" else pf_rhb

        try:
            proj = _project_batter_batx(
                batter, opp['name'], opp['fg'], opp['sv'], bpf, wx,
                pitcher_hand=opp['hand'], opp_pitcher_id=opp.get('id'),
                form=form, bvp=bvp, def_factor=opp.get('def_factor', 1.0)) or {}
        except Exception:
            proj = {}
        if not proj:
            return []

        pdict = {"name": opp['name'], "pitchHand": opp['hand']}
        # Opposing-starter Stuff+ for the power models (day-cached; no-op
        # until a retrained HR/TB/RBI model consumes it).
        _maybe_opp_stuff(pdict, opp.get('id'))
        # Season sample size for the shrink below (brain-patched FG lookup).
        try:
            fg_pa = float((fg_batter(name) or {}).get('fg_pa') or 0)
        except (TypeError, ValueError):
            fg_pa = 0.0
        rf = None   # recent hit form, fetched lazily for the hits models
        best = {}
        for market, mk, mlabel, lines in market_config:
            mean = float(proj.get(market) or 0)
            family = _XGB_FAMILY_FOR_MK.get(mk)
            for line in lines:
                analytic_p = _poisson_over_prob(mean, line)
                # Small-sample discipline: shrink toward the line's base rate by
                # season PA (a 15-PA call-up collapses to ~league average; a
                # full-season regular keeps most of his signal), then clamp to
                # the physical ceiling — an unshrunk hot streak can't post a
                # 99% two-hit probability and top the strip.
                _br = float(_market_base_rate_for(mk, line) or 0.5)
                analytic_p = ((fg_pa * analytic_p + _QP_SHRINK_PRIOR_PA * _br)
                              / (fg_pa + _QP_SHRINK_PRIOR_PA))
                _ceil = _QP_ANALYTIC_CEILING.get((mk, line))
                if _ceil is not None:
                    analytic_p = min(analytic_p, _ceil)
                if analytic_p < 0.02:
                    continue
                # Line-exact XGB with serve-parity features (mirrors the
                # tracker capture path — see _build_tracker_rows_for_game).
                _full = {}
                if _XGB_AVAILABLE and family and xgb_line_ready(family, line):
                    bdict = dict(batter)
                    if family == 'hits':
                        if rf is None:
                            try:
                                rf = _batter_recent_hit_form(pid) or {}
                            except Exception:
                                rf = {}
                        bdict.update(rf)
                    else:
                        bdict['parkFactor'] = _park_factor_for(home_id)
                        bdict['parkHr']     = _hr_park_factor_hand(home_id, bhand)
                    try:
                        _full = xgb_batter_prob_full(family, line, bdict, pdict) or {}
                    except Exception:
                        _full = {}
                xgb_p = _full.get('prob') if _full else None
                base_prob = analytic_p
                model_source = 'batx'
                stk = None
                if xgb_p is not None:
                    if _STACK_AVAILABLE:
                        mc_ci = ((_full.get('p_lo'), _full.get('p_hi'))
                                 if _full.get('p_lo') is not None and _full.get('p_hi') is not None else None)
                        try:
                            stk = stacked_calibrate(float(xgb_p), float(analytic_p),
                                                    coverage=0.5, exp_pa=exp_pa, bvp_pa=bvp_pa,
                                                    market_key=mk, line=line, mc_ci=mc_ci)
                        except Exception:
                            stk = None
                    if stk and stk.get('probability') is not None:
                        base_prob = float(stk['probability']); model_source = 'stacked'
                    else:
                        base_prob = 0.5 * float(xgb_p) + 0.5 * analytic_p; model_source = 'xgb_blend'
                raw_mult_prob = _clamp01(base_prob * _market_mult(mk, adjustments))

                # Market blend + live recalibration — identical to tracker rows.
                msum = _market_price_summary(market_props, name, mk, line) if market_props else {}
                market_implied = msum.get('market_implied')
                if market_implied and market_implied > 0:
                    under_imp = _american_to_implied(msum.get('best_under_price')) or (1 - market_implied)
                    adj_prob = logit_blend_prob(raw_mult_prob, market_implied, mk, market_implied, under_imp)
                else:
                    adj_prob = raw_mult_prob
                precal_prob = adj_prob
                adj_prob = _calibrate_prop_prob(mk, precal_prob)

                base_rate = _br
                lift = adj_prob - base_rate
                if lift <= 0:
                    continue   # model doesn't beat a typical starter at this line
                edge = _capped_edge(adj_prob, market_implied)
                ev_pct = round(adj_prob / market_implied - 1, 4) if market_implied and market_implied > 0 else None
                # Rank by true edge when priced, else by base-rate lift (both in
                # probability points, so a slate mixing priced/unpriced stays sane).
                rank = edge if edge is not None else lift
                cand = {
                    "player": name, "playerId": pid, "team": team, "slot": slot,
                    "market": market, "marketKey": mk, "marketLabel": mlabel,
                    "line": float(line), "side": "Over", "recommendedSide": "Over",
                    "adjProb": round(adj_prob, 4),
                    "preCalProb": round(precal_prob, 4),
                    "modelSource": model_source,
                    "xgbProb": round(float(xgb_p), 4) if xgb_p is not None else None,
                    "analyticProb": round(analytic_p, 4),
                    "stackedProb": stk.get('probability') if stk else None,
                    "stackVerdict": stk.get('verdict') if stk else None,
                    "calStatus": _prop_cal_status(mk),
                    "modelMean": round(mean, 3),
                    "baseRate": base_rate, "lift": round(lift, 4),
                    "edge": round(edge, 4) if edge is not None else None,
                    "evPct": ev_pct,
                    "isPlusEv": bool(ev_pct is not None and ev_pct > 0),
                    "bestPrice": msum.get('best_over_price'),
                    "bestBook": msum.get('best_over_book'),
                    "bookCount": msum.get('book_count'),
                    "marketImplied": round(float(market_implied), 4) if market_implied else None,
                    "_rank": rank,
                }
                if market not in best or cand["_rank"] > best[market]["_rank"]:
                    best[market] = cand
        return list(best.values())

    all_picks = []
    with ThreadPoolExecutor(max_workers=8) as ex:
        futs = [ex.submit(_score_batter, b, t, s) for b, t, s in tagged]
        for fut in as_completed(futs):
            try:
                all_picks.extend(fut.result())
            except Exception:
                pass

    # preCalProb tiebreak: the live recalibration is a coarse step function
    # until graded volume accumulates, so equal adjProb/lift picks are ordered
    # by the un-recalibrated fused probability (preserves model discrimination).
    all_picks.sort(key=lambda x: (x.get("_rank", 0), x.get("adjProb", 0),
                                  x.get("preCalProb", 0)), reverse=True)
    top = all_picks[:limit]

    # Finalize ONLY the shown picks: L10 over-rate + matchup score are heavy
    # per-player extras that are now display/confirmation signals, so they're
    # built for ≤`limit` picks instead of every batter in both lineups.
    for p in top:
        p.pop("_rank", None)
        l10_pct = l10_tot = None
        try:
            rates = (_build_player_trends(int(p["playerId"]), False) or {}).get("over_rates", {})
            l10 = rates.get(p["market"], {}).get(str(p["line"]), {}).get("l10", {})
            l10_pct = l10.get("pct"); l10_tot = l10.get("total")
        except Exception:
            pass
        p["l10_pct"]   = round(l10_pct, 3) if l10_pct is not None else None
        p["l10_total"] = l10_tot
        opp = _home_opp if p["team"] == away_abbr else _away_opp
        try:
            batter = next((b for b, _t, _s in tagged if b.get("id") == p["playerId"]), None)
            mu = _matchup_score(batter, opp['fg'], opp['sv'], pitcher_hand=opp['hand']) if batter else None
            p["matchupScore"] = round(float((mu or {}).get("score") or 0), 1) or None
        except Exception:
            p["matchupScore"] = None
        p["hubRating"] = _hub_rating(p["adjProb"], p.get("edge") or 0,
                                     l10_pct if l10_pct is not None else 0.5)
        p["quality"] = p["adjProb"]   # legacy field: kept for older clients
        p["reason"] = _projection_reason_short(p["player"], p["marketKey"],
                                               p["adjProb"], p.get("edge"), opp['name'])
    return gdata, top


# ── Route: L5/L10 trends for all players in a game ───────────────────────────
_TRENDS_RESP_CACHE = {}
_TRENDS_RESP_LOCK = threading.Lock()
_TRENDS_RESP_TTL = 300  # gamelog-derived; changes at most once per game day


@app.route("/api/props/trends/<int:game_pk>")
def api_props_trends(game_pk):
    """
    Returns L5/L10 over rates for every batter and both starting pitchers in a game.
    Uses concurrent fetching to keep response time under ~4s.
    """
    try:
        date_hint = request.args.get('date')
        _resp_ck = (int(game_pk), date_hint or '')
        with _TRENDS_RESP_LOCK:
            _hit = _TRENDS_RESP_CACHE.get(_resp_ck)
        if _hit and time.time() - _hit[0] < _TRENDS_RESP_TTL:
            return jsonify(_hit[1])
        # Get lineups + pitchers
        gdata, away_bats, home_bats, away_t, home_t, pitchers = _props_fetch_game(game_pk, date_hint=date_hint)
        if not gdata:
            return jsonify({"success": False, "error": "Game not found"}), 404

        all_batters  = away_bats + home_bats
        ap_info      = pitchers["ap"]
        hp_info      = pitchers["hp"]

        # Build task list: (player_id, is_pitcher, name)
        tasks = []
        for b in all_batters:
            pid = b.get("id")
            if pid:
                tasks.append((int(pid), False, b.get("name", "")))
        for pi in [ap_info, hp_info]:
            pid = pi.get("id")
            if pid:
                tasks.append((int(pid), True, pi.get("fullName", "")))

        results = {}
        with ThreadPoolExecutor(max_workers=10) as ex:
            fut_map = {
                ex.submit(_build_player_trends, pid, is_pit): (pid, name)
                for pid, is_pit, name in tasks
            }
            for fut in as_completed(fut_map):
                pid, name = fut_map[fut]
                try:
                    data = fut.result()
                    results[str(pid)] = {"name": name, **data}
                except Exception as fe:
                    results[str(pid)] = {"name": name, "error": str(fe)}
        _gdata2, quick_props = _compute_dashboard_quick_props(game_pk, limit=3, date_hint=date_hint)

        _payload = {
            "success":  True,
            "gamePk":   game_pk,
            "players":  results,
            "quickProps": quick_props,
            "timestamp": datetime.now(timezone.utc).isoformat(),
        }
        with _TRENDS_RESP_LOCK:
            _evict_if_large(_TRENDS_RESP_CACHE, 40)
            _TRENDS_RESP_CACHE[_resp_ck] = (time.time(), _payload)
        return jsonify(_payload)

    except Exception as ex:
        print(f"[api_props_trends] {traceback.format_exc()}")
        return jsonify({"success": False, "error": str(ex)}), 500


# ── Quick-props response cache (stale-while-revalidate) ───────────────────────
# The strip got heavy (legacy multi-market picks + the XGB/arsenal Confident Hits
# + live odds), so we cache the whole payload per (game, date) and serve it
# instantly. Within FRESH_TTL we return as-is; within STALE_TTL we return the
# cached copy immediately AND refresh in the background so the next open is
# current — the user never waits on a cold recompute and never misses a window.
_QUICK_PROPS_CACHE = {}            # (game_pk, date) -> {"ts": float, "payload": {...}}
_QUICK_PROPS_REFRESHING = set()    # keys with an in-flight background refresh
_QUICK_PROPS_LOCK = threading.Lock()
_QUICK_PROPS_FRESH_TTL = 90        # serve cached without refreshing
_QUICK_PROPS_STALE_TTL = 600       # serve cached + refresh in background


def _build_quick_props_payload(game_pk, date_hint):
    """Fetch the game ONCE, then compute the legacy picks and the Confident Hits
    CONCURRENTLY (they previously ran serially and each re-fetched the game)."""
    bundle = _props_fetch_game(game_pk, date_hint=date_hint)
    if not bundle or not bundle[0]:
        return None
    picks, confident_hits = [], []
    with ThreadPoolExecutor(max_workers=2) as ex:
        f_qp = ex.submit(_compute_dashboard_quick_props, game_pk, 3, date_hint, bundle)
        f_ch = ex.submit(_compute_confident_hits, game_pk, 4, date_hint, bundle)
        try:
            _g, picks = f_qp.result()
        except Exception:
            print(f"[api_props_quick] quick_props {traceback.format_exc()}")
            picks = []
        try:
            confident_hits = f_ch.result()
        except Exception:
            print(f"[api_props_quick] confident_hits {traceback.format_exc()}")
            confident_hits = []
    return {
        "success": True,
        "gamePk": game_pk,
        "picks": picks or [],
        "confidentHits": confident_hits or [],
        "generatedAt": datetime.now(timezone.utc).isoformat(),
    }


def _schedule_quick_props_refresh(game_pk, date_hint, ck):
    """Kick a single background recompute for a stale cache entry (deduped)."""
    with _QUICK_PROPS_LOCK:
        if ck in _QUICK_PROPS_REFRESHING:
            return
        _QUICK_PROPS_REFRESHING.add(ck)

    def _run():
        try:
            payload = _build_quick_props_payload(game_pk, date_hint)
            if payload:
                with _QUICK_PROPS_LOCK:
                    _QUICK_PROPS_CACHE[ck] = {"ts": time.time(), "payload": payload}
        except Exception:
            print(f"[quick_props_refresh] {traceback.format_exc()}")
        finally:
            with _QUICK_PROPS_LOCK:
                _QUICK_PROPS_REFRESHING.discard(ck)

    threading.Thread(target=_run, daemon=True).start()


# ── Route: Quick props for dashboard inline strip ─────────────────────────────
@app.route("/api/props/quick/<int:game_pk>")
def api_props_quick(game_pk):
    """Top batter prop edges + Confident Hits for a game card strip.

    Cached per (game, date) with stale-while-revalidate so repeat opens are
    instant and a cold recompute never blocks the user."""
    try:
        date_hint = request.args.get('date')
        ck = (game_pk, date_hint or '')
        now = time.time()
        with _QUICK_PROPS_LOCK:
            ent = _QUICK_PROPS_CACHE.get(ck)
        if ent:
            age = now - ent["ts"]
            if age < _QUICK_PROPS_FRESH_TTL:
                return jsonify(ent["payload"])
            if age < _QUICK_PROPS_STALE_TTL:
                # Serve stale instantly; refresh in the background.
                _schedule_quick_props_refresh(game_pk, date_hint, ck)
                stale = dict(ent["payload"]); stale["cached"] = True
                return jsonify(stale)

        payload = _build_quick_props_payload(game_pk, date_hint)
        if payload is None:
            return jsonify({"success": False, "error": "Game not found"}), 404
        with _QUICK_PROPS_LOCK:
            _QUICK_PROPS_CACHE[ck] = {"ts": time.time(), "payload": payload}
        return jsonify(payload)

    except Exception as ex:
        print(f"[api_props_quick] {traceback.format_exc()}")
        return jsonify({"success": False, "error": str(ex)}), 500


